INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('trmte8s', '밴드 슈러그', 'https://static.exercisedb.dev/media/trmte8s.gif', '승모근', '목', '밴드', '어깨', 'Step:1 발을 어깨너비로 벌리고 밴드를 발 아래에 두고 양손으로 끝을 잡는다.,Step:2 팔을 곧게 편 채로 밴드를 허벅지 앞에 자연스럽게 둔다.,Step:3 승모근을 사용해 어깨를 위로 으쓱하며 밴드를 최대한 들어올린다.,Step:4 동작 정점에서 잠시 멈췄다가 천천히 어깨를 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LMGXZn8', '바벨 디클라인 클로즈 그립 투 스컬 프레스', 'https://static.exercisedb.dev/media/LMGXZn8.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 디클라인 벤치에 누워 클로즈 그립으로 바벨을 잡는다.,Step:2 상완을 고정한 채 팔꿈치를 굽혀 바벨을 이마 쪽으로 내린다.,Step:3 잠시 멈춘 후 팔을 펴서 원래 위치로 바벨을 밀어 올린다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('27NNGFr', '케이블 인클라인 플라이(스태빌리티 볼)', 'https://static.exercisedb.dev/media/27NNGFr.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 스태빌리티 볼을 인클라인 각도로 세팅한다.,Step:2 케이블 머신의 높은 풀리에 핸들을 연결한다.,Step:3 머신을 등진 상태로 볼에 앉아 양발을 단단히 고정한다.,Step:4 오버핸드 그립으로 핸들을 잡고 손바닥이 앞으로 향하게 한다.,Step:5 등을 곧게 펴고 가슴을 열며 약간 앞으로 기울인다.,Step:6 팔꿈치를 살짝 굽힌 채 양팔을 천천히 옆으로 벌린다.,Step:7 팔이 지면과 평행해질 때까지 벌린다.,Step:8 정점에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:9 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('a4F9Oyc', '케틀벨 더블 크로스 행 클린', 'https://static.exercisedb.dev/media/a4F9Oyc.gif', '이두근', '상완이두근', '케틀벨', '전완근,어깨', 'Step:1 발을 어깨너비로 벌리고 양손에 케틀벨을 잡는다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 전방으로 기울인다.,Step:3 케틀벨을 몸 앞에 자연스럽게 늘어뜨린다.,Step:4 엉덩이·무릎·어깨를 폭발적으로 신전하며 케틀벨을 들어 올린다.,Step:5 케틀벨이 올라올 때 팔꿈치를 높게 유지하며 어깨 쪽으로 끌어올린다.,Step:6 어깨 높이에서 케틀벨을 받으며 손바닥이 안쪽을 향하게 한다.,Step:7 다시 시작 자세로 내려가고 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ecl28tP', '덤벨 리버스 포워드 런지', 'https://static.exercisedb.dev/media/ecl28tP.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 양손에 덤벨을 들고 어깨너비로 선다.,Step:2 오른발을 앞으로 내딛으며 등을 곧게 펴고 코어에 힘을 준다.,Step:3 양 무릎을 굽혀 오른쪽 허벅지가 지면과 평행할 때까지 내려간다.,Step:4 오른발 뒤꿈치에 힘을 주어 다시 일어선다.,Step:5 반대 다리도 동일하게 수행한다.,Step:6 원하는 횟수만큼 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wnEscH8', '바벨 프레스 윗몸일으키기', 'https://static.exercisedb.dev/media/wnEscH8.gif', '복근', '허리', '바벨', '어깨,가슴', 'Step:1 매트에 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 오버핸드 그립으로 바벨을 가슴 위에 올려잡는다.,Step:3 복근을 수축하며 상체를 천천히 들어 올린다.,Step:4 정점에서 잠시 멈춘 뒤 천천히 내려간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gVlnLIJ', '케이블 리버스 원 암 컬', 'https://static.exercisedb.dev/media/gVlnLIJ.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신 앞에서 어깨너비로 선다.,Step:2 언더핸드 그립으로 핸들을 잡되 손바닥은 아래로 향하게 한다.,Step:3 팔꿈치를 몸 가까이에 유지하며 전완을 들어 올린다.,Step:4 정점에서 잠시 멈췄다가 천천히 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mtXengz', '덤벨 핑거 컬', 'https://static.exercisedb.dev/media/mtXengz.gif', '전완근', '팔 아래', '덤벨', '손목 굴근,손목 신근', 'Step:1 벤치나 의자에 앉아 등을 곧게 편다.,Step:2 덤벨을 한 손에 잡고 전완을 허벅지 위에 올려 손바닥을 위로 향하게 한다.,Step:3 덤벨이 손가락 끝으로 굴러가게 한 후 손가락 힘으로 말아 올린다.,Step:4 원하는 횟수만큼 반복 후 반대 손도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kuMiR2T', '밴드 스티프 레그 데드리프트', 'https://static.exercisedb.dev/media/kuMiR2T.gif', '둔근', '허벅지', '밴드', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 밴드를 발목에 걸친다.,Step:2 양손으로 밴드를 잡고 손바닥이 몸쪽을 향하게 한다.,Step:3 등을 곧게 유지한 채 엉덩이를 접으며 상체를 숙인다.,Step:4 무릎은 살짝 굽힌 채 햄스트링이 늘어나는 지점을 찾는다.,Step:5 정점에서 잠시 멈춘 뒤 엉덩이와 햄스트링 힘으로 상체를 들어 올린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZA8b5hc', '케틀벨 고블릿 스쿼트', 'https://static.exercisedb.dev/media/ZA8b5hc.gif', '둔근', '허벅지', '케틀벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 양손으로 케틀벨을 가슴 가까이 붙잡고 선다.,Step:2 가슴을 펴고 코어에 힘을 준 채 무릎과 엉덩이를 굽혀 내려간다.,Step:3 허벅지가 지면과 평행해질 때까지 내려간다.,Step:4 정점에서 잠시 멈춘 뒤 뒤꿈치를 밀며 일어선다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DOoWcnA', '레버 체스트 프레스', 'https://static.exercisedb.dev/media/DOoWcnA.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 좌석 높이를 조절한 뒤 기계에 앉아 등은 패드에 평평하게 밀착한다.,Step:2 오버핸드 그립으로 손잡이를 잡고, 팔꿈치를 90도 각도로 맞춘다.,Step:3 손잡이를 앞으로 밀어 팔을 완전히 펴며, 동작 중 숨을 내쉰다.,Step:4 끝 지점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아오며 숨을 들이쉰다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('F3xgbjF', '덤벨 인클라인 바이셉스 컬', 'https://static.exercisedb.dev/media/F3xgbjF.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 인클라인 벤치에 앉아 각 손에 덤벨을 들고, 손바닥은 정면을 향한 채 팔을 완전히 편다.,Step:2 상완은 고정한 채, 숨을 내쉬며 이두근을 수축하면서 덤벨을 들어 올린다.,Step:3 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 강하게 쥐어짜듯 수축한다.,Step:5 숨을 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('x6KpKpq', '클로즈 그립 푸쉬업', 'https://static.exercisedb.dev/media/x6KpKpq.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 손을 서로 가깝게 두고 어깨 바로 아래에 위치시킨 하이 플랭크 자세로 시작한다.,Step:2 코어에 힘을 주고, 팔꿈치를 몸통 가까이 유지한 채 몸을 바닥 쪽으로 내린다.,Step:3 손바닥으로 바닥을 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('84RyJf8', '덤벨 원 암 숄더 프레스', 'https://static.exercisedb.dev/media/84RyJf8.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 어깨 높이에서 들고, 손바닥은 정면을 향하게 한다.,Step:2 덤벨을 위로 밀어 올려 팔을 머리 위에서 완전히 편다.,Step:3 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한 뒤, 반대쪽도 동일하게 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UKWTJWR', '케이블 스탠딩 스트레이트 크로스오버', 'https://static.exercisedb.dev/media/UKWTJWR.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 머신 중앙에 서서 발을 어깨너비로 벌린다.,Step:2 손바닥이 아래를 보도록 케이블 손잡이를 잡고, 팔을 양옆으로 곧게 뻗는다.,Step:3 팔을 곧게 편 상태를 유지하며, 손을 몸 앞에서 서로 만나게 하며 교차시킨다.,Step:4 정점에서 잠깐 멈춘 뒤, 팔을 곧게 유지한 채 천천히 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IpONWYv', '덤벨 사이드 벤드', 'https://static.exercisedb.dev/media/IpONWYv.gif', '복근', '허리', '덤벨', '복사근', 'Step:1 발을 어깨너비로 벌리고 곧게 서서 한 손에 덤벨을 들고 옆으로 늘어뜨린다.,Step:2 등을 곧게 유지하고 코어에 힘을 준 채, 덤벨 반대쪽으로 허리를 천천히 측면 굽혀 가능한 범위까지 내린다.,Step:3 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한 뒤, 반대쪽도 동일하게 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('H6ybluc', '덤벨 싱글 레그 스쿼트', 'https://static.exercisedb.dev/media/H6ybluc.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 한쪽 다리를 앞으로 뻗어 운동 내내 바닥에 닿지 않게 유지한다.,Step:3 지지하는 다리의 무릎을 굽히며 의자에 앉듯이 몸을 아래로 내린다.,Step:4 가슴을 세우고 등을 곧게 유지한다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤, 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤, 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DhMl549', '바벨 풀 스쿼트(백 POV)', 'https://static.exercisedb.dev/media/DhMl549.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 발끝은 약간 바깥쪽으로 둔다.,Step:2 바벨을 상부 등(승모근 또는 후면 삼각근)에 올려 지지한다.,Step:3 코어에 힘을 주고 가슴을 세운 채, 몸을 내리기 시작한다.,Step:4 무릎과 엉덩이를 굽히며 엉덩이를 뒤로 빼고 아래로 내려 의자에 앉는 느낌으로 수행한다.,Step:5 허벅지가 바닥과 평행하거나 약간 더 낮아질 때까지 내려간다.,Step:6 무릎은 발끝 방향과 일직선으로 유지하고, 체중은 뒤꿈치에 둔다.,Step:7 뒤꿈치로 바닥을 밀어 일어나며 엉덩이와 무릎을 편다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('72BC5Za', '아처 풀업', 'https://static.exercisedb.dev/media/72BC5Za.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 풀업 바에 어깨너비보다 약간 넓게 오버핸드 그립으로 매달린다.,Step:2 코어에 힘을 주고 견갑을 아래로 내리며 뒤로 모은다.,Step:3 몸을 끌어올릴 때 한쪽 팔은 굽혀 팔꿈치를 옆구리 쪽으로 당기고, 반대쪽 팔은 곧게 유지한다.,Step:4 턱이 바 위로 올라오고 굽힌 팔이 완전히 수축될 때까지 당긴다.,Step:5 컨트롤하며 내려오면서 굽혔던 팔을 펴고, 다음 반복에서 반대쪽으로 수행한다.,Step:6 반복마다 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qRZ5S1N', '케이블 원 암 트라이셉스 푸시다운', 'https://static.exercisedb.dev/media/qRZ5S1N.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 가슴 높이에 직선 바(또는 손잡이) 어태치먼트를 장착한 케이블 머신을 마주 보고 선다.,Step:2 오버핸드 그립으로 바를 잡고, 케이블에 장력이 생기도록 한 걸음 뒤로 선다.,Step:3 발을 어깨너비로 두고 무릎을 약간 굽힌다.,Step:4 운동 내내 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 팔은 바닥에 수직이 되도록 하여 시작한다.,Step:6 상완을 고정한 채, 숨을 내쉬며 바를 아래로 밀어 팔을 완전히 편다.,Step:7 정점에서 잠깐 멈춘 뒤, 숨을 들이쉬며 천천히 시작 자세로 돌아간다.,Step:8 원하는 반복 횟수만큼 반복한 뒤, 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PnZJIrk', '보조 와이드 그립 가슴 딥(무릎 꿇기)', 'https://static.exercisedb.dev/media/PnZJIrk.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 기계 높이를 원하는 설정으로 맞춘 뒤, 무릎을 패드에 고정한다.,Step:2 넓은 그립으로 손잡이를 잡고 팔꿈치는 약간 굽힌다.,Step:3 팔꿈치를 굽혀 몸을 내리며, 상완이 바닥과 평행해질 때까지 내려간다.,Step:4 팔을 펴며 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KXyoEtA', '덤벨 시트 내부 바이셉스 컬', 'https://static.exercisedb.dev/media/KXyoEtA.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 평평하게 두고, 양손에 덤벨을 들어 손바닥이 위를 보게 한다.,Step:2 상완을 허벅지 위에 올려 고정하고, 덤벨이 아래로 늘어지게 둔다.,Step:3 상완을 고정한 채, 이두근을 수축하며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CHpahtl', '레버에 앉은 엉덩이 외전', 'https://static.exercisedb.dev/media/CHpahtl.gif', '외전근', '허벅지', '레버리지 머신', '둔근,햄스트링', 'Step:1 좌석 높이를 조절해 무릎이 90도가 되도록 맞춘다.,Step:2 등받이에 등을 대고 앉아 발을 발판에 올린다.,Step:3 안정적으로 고정하기 위해 옆 손잡이를 잡는다.,Step:4 외전근에 힘을 주고, 다리를 몸의 정중선에서 바깥쪽으로 천천히 벌린다.,Step:5 끝 지점에서 잠깐 멈춘 뒤, 다리를 천천히 모아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LQFOrMn', '직선 바에서 가슴 딥스', 'https://static.exercisedb.dev/media/LQFOrMn.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 평행봉(딥스 바)을 손바닥이 아래를 보게 잡고 팔을 완전히 편다.,Step:2 무릎을 굽혀 발목을 교차한다.,Step:3 팔을 굽혀 몸을 내리며, 어깨가 팔꿈치보다 낮아질 때까지 내려간다.,Step:4 팔을 펴며 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('33AzZeV', '바벨 프론트 레이즈 및 풀오버', 'https://static.exercisedb.dev/media/33AzZeV.gif', '가슴근육', '가슴', '바벨', '삼각근,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서, 오버핸드 그립(손바닥 아래)으로 바벨을 잡는다.,Step:2 팔을 곧게 편 채 바벨을 전방으로 들어 올려 어깨 높이까지 올린다.,Step:3 정점에서 잠깐 멈춘 뒤, 바벨을 천천히 시작 자세로 내린다.,Step:4 이어서 팔을 곧게 유지한 채 바벨을 머리 뒤쪽으로 내려간다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤, 바벨을 다시 시작 자세로 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SGY8Zui', '바벨 클린 앤 프레스', 'https://static.exercisedb.dev/media/SGY8Zui.gif', '대퇴사두근', '허벅지', '바벨', '햄스트링,둔근,어깨,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 몸 앞 바닥에 둔다.,Step:2 무릎을 굽히고 엉덩이를 접어 내려가 오버핸드 그립으로 바벨을 잡는데, 손은 어깨너비보다 약간 넓게 둔다.,Step:3 뒤꿈치로 밀어 엉덩이와 무릎을 펴며 바벨을 바닥에서 들어 올리고, 바벨은 몸에 가깝게 유지한다.,Step:4 바벨이 허벅지 높이에 오면, 엉덩이를 폭발적으로 펴고 어깨를 으쓱하며 바벨을 가슴 쪽으로 끌어올린다.,Step:5 바벨이 가슴 높이에 오면, 재빨리 몸을 낮춰 어깨 높이에서 캐치하고 팔꿈치는 앞을 향하게 하며 손바닥은 위를 보게 한다.,Step:6 캐치 자세에서 바벨을 머리 위로 곧게 밀어 올려 팔을 완전히 편다.,Step:7 바벨을 천천히 시작 자세로 내리고 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('82LxxkW', '바벨 리스트 컬', 'https://static.exercisedb.dev/media/82LxxkW.gif', '전완근', '팔 아래', '바벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 평평하게 두고, 전완을 허벅지 위에 올린 채 언더핸드 그립으로 바벨을 잡는다.,Step:2 손목을 곧게 유지한 채 바벨이 손끝 쪽으로 굴러 내려가게 한다.,Step:3 손목을 굽혀 바벨을 전완 쪽으로 천천히 말아 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 바벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GNhAeJ0', '덤벨 해머 컬(암 블래스터 포함)', 'https://static.exercisedb.dev/media/GNhAeJ0.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 덤벨을 양손에 들고 곧게 서서 손바닥이 몸통을 향하게 한다.,Step:2 팔꿈치를 몸통 가까이 붙이고, 손바닥이 정면을 향하도록 회전시킨다.,Step:3 이 자세가 시작 자세다.,Step:4 상완을 고정한 채, 숨을 내쉬며 이두근을 수축하면서 덤벨을 말아 올린다.,Step:5 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다.,Step:6 정점에서 잠깐 멈추며 이두근을 강하게 수축한다.,Step:7 숨을 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:8 권장 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8d8qJQI', '바벨 리버스 그립 인클라인 벤치 로우', 'https://static.exercisedb.dev/media/8d8qJQI.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 인클라인 벤치를 45도 각도로 세팅한다.,Step:2 벤치에 앉아 등받이를 마주 보고, 가슴을 등받이에 붙인다.,Step:3 리버스 그립(손바닥 아래)으로 바벨을 잡고, 손은 어깨너비보다 약간 넓게 둔다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 바벨을 상복부 쪽으로 당기며 견갑을 모아 수축한다.,Step:6 정점에서 잠깐 멈춘다.,Step:7 바벨을 천천히 시작 자세로 내린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YUYAMEj', '엎드린 자세로 누워서 대퇴사두근 스트레칭', 'https://static.exercisedb.dev/media/YUYAMEj.gif', '대퇴사두근', '허벅지', '도움을 준', '햄스트링,둔근', 'Step:1 다리를 뻗은 채로 바닥에 엎드린다.,Step:2 왼쪽 무릎을 굽히고 왼손을 뒤로 뻗어 왼발이나 발목을 잡는다.,Step:3 왼쪽 발을 엉덩이 쪽으로 천천히 당겨 왼쪽 대퇴근이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한 뒤 풀어준다.,Step:5 오른쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ye84CTU', '레버 프리처 컬 v. 2', 'https://static.exercisedb.dev/media/ye84CTU.gif', '이두근', '상완이두근', '레버리지 머신', '전완근', 'Step:1 좌석 높이를 조절한 뒤 상완을 패드에 올리고 가슴을 지지대에 밀착한 상태로 앉는다.,Step:2 언더핸드 그립으로 손잡이를 잡되, 어깨너비보다 약간 넓게 잡는다.,Step:3 상완을 고정한 채, 숨을 내쉬며 손잡이를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈추며 이두근을 강하게 수축한다.,Step:5 숨을 들이쉬며 손잡이를 천천히 내려 팔을 완전히 펴서 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VW88JNd', '덤벨 앉아서 한쪽 다리 종아리 들어올리기 - 손바닥 위로', 'https://static.exercisedb.dev/media/VW88JNd.gif', '종아리근', '종아리', '덤벨', '햄스트링,둔근', 'Step:1 벤치나 의자에 앉아 등을 곧게 세우고 발을 바닥에 평평하게 둔다.,Step:2 한 손에 덤벨을 들고 손바닥이 위를 보게 하여 허벅지 위에 올린다.,Step:3 한쪽 다리를 바닥에서 들어 앞쪽으로 뻗되, 무릎은 약간 굽힌다.,Step:4 발 앞꿈치로 밀어 뒤꿈치를 가능한 높이까지 들어 올린다.,Step:5 정점에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤, 다리를 바꿔 동일하게 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FWdVhcW', '케이블 스탠딩 어깨 외회전', 'https://static.exercisedb.dev/media/FWdVhcW.gif', '삼각근', '어깨', '케이블', '회전근개,승모근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 약간 굽힌다.,Step:2 팔을 앞쪽으로 뻗어 지면과 평행하게 만든 상태에서 케이블 손잡이를 잡는다.,Step:3 팔꿈치를 약간 굽히고, 견갑을 뒤로 당겨 안정화한다.,Step:4 팔꿈치 위치는 유지한 채, 팔을 바깥쪽으로 천천히 회전시킨다.,Step:5 끝 지점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XooAdhl', '물구나무서기', 'https://static.exercisedb.dev/media/XooAdhl.gif', '삼두근', '상완이두근', '맨몸', '어깨,코어', 'Step:1 물구나무서기를 할 수 있을 만큼 충분히 넓은 공간을 확보한다.,Step:2 손을 어깨너비로 바닥에 짚고 손가락은 정면을 향하게 한다.,Step:3 코어와 어깨 힘으로 균형을 잡으며 다리를 차올려 벽 쪽으로 올린다.,Step:4 삼두근에 힘을 줘 체중을 지탱하며 자세를 유지한다.,Step:5 균형을 유지할 수 있는 만큼 자세를 버틴다.,Step:6 내려올 때는 다리를 천천히 바닥으로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gw9PqGk', '풀 플란체 푸쉬업', 'https://static.exercisedb.dev/media/gw9PqGk.gif', '가슴근육', '가슴', '맨몸', '어깨,삼두근,코어', 'Step:1 손을 어깨너비보다 약간 넓게 두고 푸쉬업 시작 자세를 잡는다.,Step:2 코어에 힘을 주고, 팔꿈치를 몸통 가까이 유지한 채 몸을 바닥 쪽으로 내린다.,Step:3 내려가면서 몸을 앞으로 기울이고 발을 바닥에서 띄워 손으로 균형을 잡는다.,Step:4 가슴이 바닥 바로 위에 올 때까지 계속 내려간다.,Step:5 손으로 바닥을 밀어 팔을 펴며 몸을 다시 들어 올려 시작 자세로 돌아온다.,Step:6 머리부터 발끝까지 일직선을 유지한다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iaapw0g', 'ez 바벨 시티드 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/iaapw0g.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 세우고 발을 바닥에 평평하게 둔다.,Step:2 오버핸드 그립으로 EZ 바를 어깨너비로 잡는다.,Step:3 바를 머리 위로 들어 올려 팔을 완전히 편다.,Step:4 상완을 고정한 채 팔꿈치를 굽혀 바를 머리 뒤로 천천히 내린다.,Step:5 잠깐 멈춘 뒤, 팔꿈치를 펴며 바를 다시 시작 자세로 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Kzg30R7', '밴드 스탠딩 크런치', 'https://static.exercisedb.dev/media/Kzg30R7.gif', '복근', '허리', '밴드', '복사근', 'Step:1 밴드를 허리 높이의 단단한 고정 지점에 연결한다.,Step:2 고정 지점을 등지고 서서 발을 어깨너비로 벌린다.,Step:3 양손으로 밴드를 잡아 가슴 높이로 올리고, 팔꿈치는 굽힌 채 몸통 가까이 붙인다.,Step:4 복근에 힘을 주고 상체를 천천히 앞으로 말아 가슴을 무릎 쪽으로 가져간다.,Step:5 수축 지점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oom75KC', '덤벨 스트레이트 레그 데드리프트', 'https://static.exercisedb.dev/media/oom75KC.gif', '둔근', '허벅지', '덤벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 서서, 오버핸드 그립으로 각 손에 덤벨을 든다.,Step:2 등을 곧게 유지하고 코어에 힘을 준 상태에서, 엉덩이를 접어 힙 힌지를 만들며 덤벨을 바닥 쪽으로 내리고 상체를 앞으로 기울인다.,Step:3 무릎을 약간 굽힌 채 햄스트링이 늘어나는 느낌이 들 때까지 덤벨을 계속 내린다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤, 둔근과 햄스트링에 힘을 주어 상체를 다시 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WcHl7ru', '스미스 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/WcHl7ru.gif', '삼두근', '상완이두근', '스미스 머신', '가슴,어깨', 'Step:1 좌석 높이를 조절한 뒤 벤치에 앉아 발을 바닥에 평평하게 둔다.,Step:2 어깨너비보다 약간 좁게 클로즈 그립으로 바를 잡는다.,Step:3 팔꿈치를 몸통 가까이 유지한 채 바를 가슴 쪽으로 내린다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤, 바를 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8xUv4J7', '케이블 시티드 크런치', 'https://static.exercisedb.dev/media/8xUv4J7.gif', '복근', '허리', '케이블', '복사근', 'Step:1 케이블 머신에 앉아 발을 바닥에 평평하게 두고 무릎을 굽힌다.,Step:2 양손으로 케이블 손잡이를 잡고 머리 뒤쪽에 위치시킨다.,Step:3 복근에 힘을 주고 상체를 천천히 앞으로 말아 가슴을 무릎 쪽으로 가져간다.,Step:4 수축 지점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IaGQCrC', '고립 푸시업', 'https://static.exercisedb.dev/media/IaGQCrC.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 서스펜션 트레이너를 준비하고 적절한 높이로 조절한다.,Step:2 고정 지점을 등지고 서서 오버핸드 그립으로 손잡이를 잡는다.,Step:3 발을 앞으로 내딛어 몸을 기울여 체중이 서스펜션 트레이너에 실리게 한다.,Step:4 머리부터 발뒤꿈치까지 몸을 일직선으로 유지하고 코어에 힘을 준 뒤, 가슴을 손잡이 쪽으로 내린다.,Step:5 가슴과 팔로 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qFpAkpP', '케이블 스탠딩 리프트', 'https://static.exercisedb.dev/media/qFpAkpP.gif', '복근', '허리', '케이블', '복사근,허리', 'Step:1 케이블 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:2 양손으로 케이블 손잡이를 잡고 허리 높이에 위치시킨다.,Step:3 코어에 힘을 주고 운동 내내 등을 곧게 유지한다.,Step:4 팔을 곧게 편 채, 숨을 내쉬며 손잡이를 반대쪽 어깨 방향으로 들어 올리면서 상체를 회전한다.,Step:5 정점에서 잠깐 멈춘 뒤, 숨을 들이쉬며 손잡이를 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤, 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bWxq4op', '덤벨 원 암 리버스 프리처 컬', 'https://static.exercisedb.dev/media/bWxq4op.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 벤치에 앉아 가슴을 패드에 대고, 한 팔을 벤치 가장자리 위로 뻗은 상태에서 언더핸드 그립으로 덤벨을 잡는다.,Step:2 팔이 완전히 펴질 때까지 덤벨을 천천히 내린다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 다시 말아 올린다.,Step:4 정점에서 이두근을 강하게 수축한 뒤, 덤벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한 뒤, 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('F1KxjBa', '덤벨 피처 해머 컬', 'https://static.exercisedb.dev/media/F1KxjBa.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 덤벨을 양손에 들고 곧게 서서 손바닥이 몸통을 향하게 한다.,Step:2 팔꿈치를 몸통 가까이 붙이고, 손바닥이 정면을 향하도록 회전시킨다.,Step:3 이 자세가 시작 자세다.,Step:4 상완을 고정한 채, 숨을 내쉬며 이두근을 수축하면서 덤벨을 말아 올린다.,Step:5 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다.,Step:6 정점에서 잠깐 멈추며 이두근을 강하게 수축한다.,Step:7 숨을 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:8 권장 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('u2X71Np', '케이블 프론트 레이즈', 'https://static.exercisedb.dev/media/u2X71Np.gif', '삼각근', '어깨', '케이블', '삼두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 케이블 손잡이를 잡는다.,Step:2 등을 곧게 유지하고 코어에 힘을 준다.,Step:3 팔을 곧게 편 채 손바닥이 아래를 보도록 유지하면서 손잡이를 몸 앞쪽으로 들어 올린다.,Step:4 팔이 바닥과 평행해질 때까지 계속 올린다.,Step:5 정점에서 잠깐 멈춘 뒤, 손잡이를 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uxJcFUU', '케이블 라이닝 삼두근 익스텐션 v. 2', 'https://static.exercisedb.dev/media/uxJcFUU.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 로프 손잡이를 로우 풀리 케이블 머신에 연결한다.,Step:2 평평한 벤치에 등을 대고 눕되, 머리는 케이블 머신 쪽을 향하게 한다.,Step:3 로프 손잡이를 양손으로 잡고 손바닥이 서로 마주 보게 한 뒤, 팔을 가슴 위로 곧게 뻗는다.,Step:4 상완을 고정한 채 팔꿈치를 굽혀 로프 손잡이를 이마 쪽으로 천천히 내린다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤, 팔을 다시 펴서 시작 자세로 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5KLbZWx', '케틀벨 얼터네이팅 프레스', 'https://static.exercisedb.dev/media/5KLbZWx.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 각 손에 케틀벨을 어깨 높이로 든다.,Step:2 한쪽 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:3 케틀벨을 다시 어깨 높이로 내린다.,Step:4 반대쪽 팔로 반복한다.,Step:5 원하는 반복 횟수만큼 팔을 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('U3ffHlY', '삼두근 익스텐션 바닥에 누워 케이블 로프', 'https://static.exercisedb.dev/media/U3ffHlY.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 로프를 케이블 머신에 연결하고 최하단 위치로 설정한다.,Step:2 바닥에 등을 대고 누워 머리가 케이블 머신 쪽을 향하게 한다.,Step:3 로프를 양손으로 잡고 손바닥이 서로 마주 보게 한 뒤, 팔을 천장 쪽으로 곧게 뻗는다.,Step:4 상완을 고정한 채 팔꿈치를 굽혀 로프를 이마 쪽으로 천천히 내린다.,Step:5 잠깐 멈춘 뒤, 팔을 다시 펴서 시작 자세로 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CI6baTY', '레이즈', 'https://static.exercisedb.dev/media/CI6baTY.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔은 몸 옆에 둔다.,Step:2 무릎을 굽혀 가슴 쪽으로 당기되, 발은 바닥에서 띄운다.,Step:3 복근에 힘을 주어 엉덩이를 바닥에서 들어 올리며 무릎을 머리 쪽으로 가져간다.,Step:4 정점에서 잠깐 멈춘 뒤, 엉덩이를 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('d5bTEPV', '밴드 스텝업', 'https://static.exercisedb.dev/media/d5bTEPV.gif', '둔근', '허벅지', '밴드', '대퇴사두근,햄스트링,종아리근', 'Step:1 밴드를 허벅지에 감되, 무릎 바로 위에 위치시킨다.,Step:2 스텝 또는 플랫폼을 마주 보고 서서 발을 엉덩이너비로 둔다.,Step:3 오른발을 플랫폼 위에 올리고 뒤꿈치로 밀어 올라선다.,Step:4 왼쪽 다리를 뒤로 곧게 뻗는다.,Step:5 왼발을 다시 바닥으로 내린다.,Step:6 왼발로 플랫폼에 올라서는 동작을 수행한다.,Step:7 원하는 반복 횟수만큼 다리를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gchi5Tr', '케이블 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/Gchi5Tr.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 케이블 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:2 오른손으로 케이블 손잡이를 잡고, 상완이 바닥과 평행이 되도록 팔을 들어 올린 뒤 팔꿈치를 90도로 굽힌다.,Step:3 상완을 고정한 채 전완을 뒤로 뻗어 팔을 완전히 편다.,Step:4 정점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아간다.,Step:5 왼팔로도 반복한다.,Step:6 원하는 반복 횟수만큼 양팔을 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('REGM1dE', '덤벨 원 암 디클라인 체스트 프레스', 'https://static.exercisedb.dev/media/REGM1dE.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 한 손에 든 덤벨을 가슴 위에 둔다.,Step:2 발을 바닥에 평평하게 두고 등을 벤치에 밀착한다.,Step:3 덤벨을 천장 쪽으로 밀어 올려 팔꿈치를 완전히 편다.,Step:4 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한 뒤, 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dmgMp3n', '바벨 인클라인 로우', 'https://static.exercisedb.dev/media/dmgMp3n.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 엎드려 가슴을 패드에 대고, 발은 바닥에 평평하게 둔다.,Step:3 오버핸드 그립으로 바벨을 잡고 손은 어깨너비보다 약간 넓게 둔다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 바벨을 가슴 쪽으로 당기며 견갑을 모아 수축한다.,Step:6 정점에서 잠깐 멈춘다.,Step:7 바벨을 천천히 시작 자세로 내린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1jXLYEw', '서서 옆으로 스트레칭', 'https://static.exercisedb.dev/media/1jXLYEw.gif', '광배근', '등', '맨몸', '어깨,복사근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 양팔을 바닥과 평행하게 옆으로 곧게 뻗는다.,Step:3 상체를 천천히 한쪽으로 기울여 옆구리와 광배근이 늘어나는 것을 느낀다.,Step:4 15–30초 동안 유지한다.,Step:5 시작 자세로 돌아와 반대쪽도 반복한다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PQcUlDi', '케이블 수핀 리버스 플라이', 'https://static.exercisedb.dev/media/PQcUlDi.gif', '삼각근', '어깨', '케이블', '승모근,능형근', 'Step:1 D-핸들을 로우 풀리 케이블 머신에 연결하고 평평한 벤치에 엎드린다.,Step:2 양손으로 D-핸들을 잡고 손바닥이 아래를 보게 한 뒤, 팔을 몸 앞쪽으로 곧게 뻗는다.,Step:3 팔을 곧게 편 채, 팔을 양옆으로 들어 올려 바닥과 평행해질 때까지 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 팔을 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gKozT8X', '덤벨 싱글 레그 데드리프트', 'https://static.exercisedb.dev/media/gKozT8X.gif', '둔근', '허벅지', '덤벨', '햄스트링,허리', 'Step:1 발을 엉덩이너비로 두고 서서 오른손에 덤벨을 든다.,Step:2 체중을 왼다리에 싣고 오른발을 바닥에서 살짝 들어 올린다.,Step:3 등을 곧게 유지한 채 엉덩이를 접어 앞으로 힌지하며 덤벨을 바닥 쪽으로 내린다.,Step:4 동시에 오른다리를 뒤로 곧게 뻗고, 왼무릎은 약간 굽힌 상태를 유지한다.,Step:5 상체와 오른다리가 바닥과 평행해질 때까지 덤벨을 내린다.,Step:6 바닥 지점에서 잠깐 멈춘 뒤, 둔근과 햄스트링에 힘을 주어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤, 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lyKCLmK', '덤벨 시티드 리버스 그립 컨센트레이션 컬', 'https://static.exercisedb.dev/media/lyKCLmK.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 평평하게 두고 한 손에 덤벨을 든다(손바닥은 위를 향함).,Step:2 팔꿈치를 허벅지 안쪽(무릎 바로 위)에 댄다.,Step:3 상완을 고정한 채, 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 강하게 수축한다.,Step:5 숨을 들이쉬며 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한 뒤, 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4dUn2iv', '바벨 스탠딩 클로즈 그립 컬', 'https://static.exercisedb.dev/media/4dUn2iv.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 서서, 언더핸드 그립으로 손을 가까이 모아 바벨을 잡는다.,Step:2 팔꿈치를 몸통 가까이 붙이고 상완은 움직이지 않도록 고정한다.,Step:3 숨을 내쉬며 이두근을 수축하면서 바를 말아 올리고, 이두근이 완전히 수축되어 바가 어깨 높이에 올 때까지 계속 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 강하게 수축한다.,Step:5 숨을 들이쉬며 바벨을 천천히 내려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vM5YS2g', '리버스 하이퍼 익스텐션(스태빌리티 볼)', 'https://static.exercisedb.dev/media/vM5YS2g.gif', '둔근', '허벅지', '스태빌리티 볼', '햄스트링,허리', 'Step:1 스태빌리티 볼 위에 엎드려 누워 엉덩이는 볼에 얹고 다리는 뒤로 곧게 뻗는다.,Step:2 안정성을 위해 양손을 몸 앞 바닥에 짚는다.,Step:3 둔근과 햄스트링에 힘을 주어 다리를 가능한 높이 천장 쪽으로 들어 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 다리를 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7F1DVzn', '레버 전면 풀다운', 'https://static.exercisedb.dev/media/7F1DVzn.gif', '광배근', '등', '레버리지 머신', '이두근,능형근,후면 삼각근', 'Step:1 좌석 높이를 조절한 뒤 무릎을 패드 아래에 두고 발을 바닥에 평평하게 둔 상태로 기계에 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡되, 어깨너비보다 약간 넓게 잡는다.,Step:3 가슴을 들어 올리고 어깨를 뒤로 젖혀, 허리에 약간의 아치를 유지한 채 상체를 곧게 세운다.,Step:4 광배근에 힘을 주고 손잡이를 가슴 쪽으로 당기며 견갑을 모아 수축한다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤, 손잡이를 천천히 풀어 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('03lzqwk', '보조 매달린 무릎 올리기', 'https://static.exercisedb.dev/media/03lzqwk.gif', '복근', '허리', '도움을 준', '고관절 굴근', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥이 정면(몸 바깥쪽)을 향하게 둔다.,Step:2 코어에 힘을 주고 엉덩이와 무릎을 굽혀 무릎을 가슴 쪽으로 들어 올린다.,Step:3 정점에서 잠깐 멈추며 복근을 강하게 수축한다.,Step:4 다리를 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ayAHcEm', '스미스 인클라인 숄더 레이즈', 'https://static.exercisedb.dev/media/ayAHcEm.gif', '전거근', '가슴', '스미스 머신', '삼각근,승모근', 'Step:1 스미스 머신을 인클라인(기울어진) 각도로 설정한다.,Step:2 기계를 마주 보고 서서 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 바를 잡되, 손은 어깨너비보다 약간 넓게 둔다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 팔꿈치가 리드하도록 바를 천장 방향으로 들어 올린다.,Step:6 정점에서 잠깐 멈춘 뒤, 바를 천천히 내려 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('isAAZWA', '좌우 풀 업', 'https://static.exercisedb.dev/media/isAAZWA.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 약간 굽힌다.,Step:2 오버핸드 그립으로 풀업 바를 잡되, 손은 어깨너비보다 약간 넓게 둔다.,Step:3 팔을 완전히 편 채 바에 매달려 몸의 힘을 뺀다.,Step:4 팔꿈치를 굽혀 몸을 끌어올리며 턱을 바 쪽으로 가져가되, 몸은 곧게 유지한다.,Step:5 턱이 바 위로 올라오면, 몸을 천천히 내려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('W9pFVv1', '바벨 벤치 스쿼트', 'https://static.exercisedb.dev/media/W9pFVv1.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 스쿼트 랙에 가슴 높이로 바벨을 세팅한다.,Step:2 랙을 등지고 서서 발을 어깨너비로 둔다.,Step:3 무릎을 굽혀 스쿼트 자세로 내려가되, 등을 곧게 하고 가슴을 든다.,Step:4 어깨너비보다 약간 넓게 오버핸드 그립으로 바벨을 잡는다.,Step:5 바벨을 랙에서 들어 올린 뒤 뒤로 걸음을 옮기며 자세를 잡는다.,Step:6 무릎이 발끝 방향과 일직선이 되도록 유지하며 스쿼트로 내려간다.,Step:7 바닥에서 잠시 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gAwDzB3', '케이블 트라이셉스 푸시다운(v-bar)', 'https://static.exercisedb.dev/media/gAwDzB3.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신의 가장 높은 위치에 V-바 어태치먼트를 연결한다.,Step:2 케이블 머신을 마주 보고 발을 어깨너비로 선다.,Step:3 손바닥이 아래로 향하도록 오버핸드 그립으로 V-바를 어깨너비로 잡는다.,Step:4 팔꿈치를 몸통 옆에 붙이고 운동 내내 상완은 고정한다.,Step:5 삼두근에 힘을 주며 숨을 내쉬면서 V-바를 아래로 눌러 팔을 완전히 편다.,Step:6 아래 지점에서 잠시 멈추며 삼두근을 강하게 수축한다.,Step:7 숨을 들이마시며 천천히 시작 위치로 되돌리되, 컨트롤을 유지한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xLYSdtg', '케이블 미들 플라이', 'https://static.exercisedb.dev/media/xLYSdtg.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 머신 양쪽에 케이블을 가슴 높이로 맞춘다.,Step:2 머신 중앙에 서서 한 발을 약간 앞으로 둔다.,Step:3 손잡이를 오버핸드 그립으로 잡고 팔을 옆으로 펼친다.,Step:4 팔꿈치를 살짝 굽힌 채 상체를 약간 앞으로 기울인다.,Step:5 가슴에 힘을 주고 팔을 앞으로 쓸어 모으듯 가져온다.,Step:6 가운데에서 잠시 멈춘 뒤 천천히 시작 자세로 되돌린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('17lJ1kr', '레버 라이딩 레그 컬', 'https://static.exercisedb.dev/media/17lJ1kr.gif', '햄스트링', '허벅지', '레버리지 머신', '종아리근', 'Step:1 머신을 몸에 맞게 조절하고 원하는 중량을 선택한다.,Step:2 머신에 엎드려 다리를 곧게 펴고 뒤꿈치를 패드 레버에 댄다.,Step:3 손잡이나 머신 측면을 잡아 몸을 고정한다.,Step:4 상체는 고정한 채 숨을 내쉬며 엉덩이가 들리지 않도록 하면서 다리를 가능한 만큼 컬한다.,Step:5 수축 지점에서 잠시 멈추며 햄스트링을 조인다.,Step:6 숨을 들이마시며 천천히 시작 위치로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JrOHAZc', '바벨 뻣뻣한 다리 좋은 아침', 'https://static.exercisedb.dev/media/JrOHAZc.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 두고 무릎을 살짝 굽힌 채 선다.,Step:2 바벨을 승모근 위쪽에 올려 상부 등에 얹는다.,Step:3 등을 곧게 유지한 채 엉덩이를 뒤로 빼며 힙 힌지로 상체를 앞으로 숙인다.,Step:4 상체가 바닥과 평행해질 때까지 내려가며 햄스트링 스트레치를 느낀다.,Step:5 둔근과 햄스트링에 힘을 주어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('s8nrDXF', '중량 크런치', 'https://static.exercisedb.dev/media/s8nrDXF.gif', '복근', '허리', '가중', '복사근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 원판이나 덤벨을 가슴 위에 든다.,Step:3 복근에 힘을 주고 상체를 말아 올려 견갑골이 바닥에서 뜨게 한다.,Step:4 꼭대기에서 잠시 멈춘 뒤 천천히 시작 자세로 내려온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('r1XNRYB', '밴드 서포트 풀업', 'https://static.exercisedb.dev/media/r1XNRYB.gif', '광배근', '등', '밴드', '이두근,전완근', 'Step:1 밴드를 풀업 바나 튼튼한 고정 지점에 걸어 고정한다.,Step:2 밴드 위에 발을 올리고 손바닥이 앞을 향하도록 바를 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 편 채 매달리고 코어에 힘을 주며 어깨를 아래/뒤로 고정한다.,Step:4 견갑골을 모으며 팔꿈치를 엉덩이 쪽으로 내리듯 당겨 몸을 끌어올린다.,Step:5 턱이 바 위로 올라갈 때까지 당긴 뒤 천천히 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wQ2c4XD', '바벨 루마니안 데드리프트', 'https://static.exercisedb.dev/media/wQ2c4XD.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 두고 발끝은 정면으로 향하게 선다.,Step:2 어깨너비보다 약간 넓게 오버핸드 그립으로 바벨을 잡는다.,Step:3 등을 곧게 유지하며 무릎을 살짝 굽힌 채 힙 힌지로 상체를 숙인다.,Step:4 바벨을 몸에 가깝게 유지하며 바닥 쪽으로 내린다.,Step:5 내려가며 햄스트링의 당김을 느낀다.,Step:6 햄스트링 스트레치가 충분히 느껴지는 지점에서 엉덩이를 앞으로 밀며 일어선다.,Step:7 동작 상단에서 둔근을 조인다.,Step:8 바벨을 천천히 다시 내리며 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ezpnw9d', '밴드 리버스 리스트 컬', 'https://static.exercisedb.dev/media/Ezpnw9d.gif', '전완근', '팔 아래', '밴드', '전완근', 'Step:1 벤치나 의자에 앉고 발을 바닥에 둔다.,Step:2 손바닥이 아래를 보게 오버핸드 그립으로 밴드를 잡고 손가락에 밴드를 건다.,Step:3 전완을 허벅지 위에 올리고 손목은 가장자리 밖으로 나오게 둔다.,Step:4 손목을 위로 말아 올리며 전완에 힘을 준다.,Step:5 꼭대기에서 잠시 멈춘 뒤 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ha7SZ3y', '케틀벨 터키쉬 겟업(스쿼트 스타일)', 'https://static.exercisedb.dev/media/Ha7SZ3y.gif', '둔근', '허벅지', '케틀벨', '대퇴사두근,햄스트링,코어', 'Step:1 등을 대고 누워 오른손에 케틀벨을 들고 팔을 어깨 위로 곧게 편다.,Step:2 오른쪽 무릎을 굽혀 오른발을 바닥에 두고 왼쪽 다리는 편다.,Step:3 오른발로 지면을 밀어 엉덩이를 들어 브릿지 자세를 만든다.,Step:4 왼쪽 다리를 몸 아래로 넣어 무릎을 굽혀 왼발을 바닥에 둔다.,Step:5 몸통을 왼쪽으로 회전하며 왼손을 바닥에 짚어 지지한다.,Step:6 오른발과 왼손으로 밀어 상체를 들어 무릎을 꿇은 자세로 올라온다.,Step:7 무릎 꿇은 자세에서 일어나되 케틀벨은 머리 위로 고정한다.,Step:8 동작을 역순으로 수행해 시작 자세로 돌아간다.,Step:9 반대쪽도 동일하게 반복한다(이번엔 왼손에 케틀벨).');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('prbWx1D', '덤벨 로테이션 리버스 플라이', 'https://static.exercisedb.dev/media/prbWx1D.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 두고 서서 덤벨을 양손에 들고 손바닥은 서로 마주 보게 한다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 하고 가슴을 편다.,Step:3 팔꿈치를 살짝 굽힌 채 팔을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 팔을 회전시켜 손바닥이 바닥을 향하게 만든다.,Step:5 팔을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BMMolZ3', '크런치', 'https://static.exercisedb.dev/media/BMMolZ3.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥쪽으로 벌린다.,Step:3 복근에 힘을 주고 어깨뼈가 바닥에서 뜨도록 상체를 말아 올리며 동시에 무릎을 가슴 쪽으로 당긴다.,Step:4 꼭대기에서 잠시 멈춘 뒤 어깨뼈를 천천히 내리고 다리를 시작 자세로 뻗는다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ecpY0rH', '리버스 그립 머신 랫 풀다운', 'https://static.exercisedb.dev/media/ecpY0rH.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이를 조절하고 무릎을 패드 아래에 넣고 발은 바닥에 둔다.,Step:2 손바닥이 위를 향하는 언더핸드 그립으로 손잡이를 어깨너비보다 약간 넓게 잡는다.,Step:3 가슴을 펴고 어깨를 뒤로 당긴 채 앉아 허리에 약간의 아치를 유지한다.,Step:4 손잡이를 가슴 쪽으로 당기며 견갑골을 모아준다.,Step:5 아래 지점에서 잠시 멈춘 뒤 천천히 시작 자세로 되돌린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jgbvVJ0', '덤벨 인클라인 티레이즈', 'https://static.exercisedb.dev/media/jgbvVJ0.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 인클라인 벤치를 45도로 맞추고 앉아 양손에 덤벨을 들되 손바닥은 서로 마주 보게 한다.,Step:2 상체를 앞으로 기울여 팔이 바닥을 향해 곧게 늘어지게 한다.,Step:3 팔을 곧게 편 채 옆으로 들어 올려 바닥과 평행이 되게 하여 몸과 함께 \'T\'자 형태를 만든다.,Step:4 꼭대기에서 잠시 멈춘 뒤 천천히 팔을 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HEJ6DIX', '케이블 리베이트', 'https://static.exercisedb.dev/media/HEJ6DIX.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 케이블 머신을 마주 보고 발을 어깨너비로 선다.,Step:2 오른손으로 케이블 손잡이를 잡고 뒤로 한 발 물러나 장력을 만든다.,Step:3 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 한다.,Step:4 상완을 몸통에 붙인 채 팔꿈치를 90도로 굽혀 시작한다.,Step:5 전완을 뒤로 펴며 팔을 완전히 곧게 만든다.,Step:6 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gnfo4FM', '바벨 하이바 스쿼트', 'https://static.exercisedb.dev/media/Gnfo4FM.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 두고 발끝은 약간 바깥으로 돌린다.,Step:2 바벨을 승모근 위쪽(상부 등)에 올려 둔다.,Step:3 코어에 힘을 주고 가슴을 든 채 엉덩이를 뒤로 빼며 무릎을 굽혀 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:5 뒤꿈치로 밀어 일어서며 엉덩이와 무릎을 편다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OVTZ65k', 'ez-barbell 스탠딩 와이드 그립 바이셉스 컬', 'https://static.exercisedb.dev/media/OVTZ65k.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 두고 곧게 선 채 EZ 바를 언더핸드 그립으로 어깨너비보다 넓게 잡는다.,Step:2 팔꿈치를 몸통에 붙이고 상완이 움직이지 않도록 고정한다.,Step:3 이두근을 수축하며 바를 어깨 쪽으로 말아 올린다.,Step:4 꼭대기에서 잠시 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ipvgBnC', '바벨 시트 카프 레이즈', 'https://static.exercisedb.dev/media/ipvgBnC.gif', '종아리근', '종아리', '바벨', '햄스트링', 'Step:1 벤치에 앉아 발을 바닥에 두고 바벨을 허벅지 위에 올린다.,Step:2 발볼을 블록이나 스텝 같은 받침 위에 두고 뒤꿈치는 아래로 떨어지게 한다.,Step:3 뒤꿈치를 가능한 한 아래로 내려 종아리 스트레치를 느낀다.,Step:4 뒤꿈치를 최대한 들어 올려 종아리를 수축한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5VXmnV5', '체중 인클라인 사이드 플랭크', 'https://static.exercisedb.dev/media/5VXmnV5.gif', '복근', '허리', '맨몸', '복사근,어깨', 'Step:1 옆으로 누워 다리를 곧게 펴고 포개어 둔다.,Step:2 어깨 바로 아래에 전완을 두고 팔꿈치를 90도로 굽힌다.,Step:3 코어에 힘을 주고 엉덩이를 들어 머리부터 발끝까지 일직선이 되게 한다.,Step:4 원하는 시간 동안 자세를 유지한다.,Step:5 엉덩이를 내려 휴식한 뒤 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6kSxYnw', '바벨 리스트 컬 v. 2', 'https://static.exercisedb.dev/media/6kSxYnw.gif', '전완근', '팔 아래', '바벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 무릎을 굽힌다.,Step:2 언더핸드 그립(손바닥 위)으로 어깨너비로 바벨을 잡는다.,Step:3 전완을 허벅지 위에 두고 손목이 가장자리 밖으로 나오게 한다.,Step:4 손목을 위로 말아 올려 바벨을 전완 쪽으로 당긴다.,Step:5 꼭대기에서 잠시 멈춘 뒤 천천히 바벨을 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2Ryn564', '엎드린 자세로 대퇴직근 스트레칭', 'https://static.exercisedb.dev/media/2Ryn564.gif', '복근', '허리', '도움을 준', '대퇴사두근', 'Step:1 다리를 곧게 펴고 바닥에 엎드린다.,Step:2 오른쪽 무릎을 굽히고 오른손을 뒤로 뻗어 오른발이나 발목을 잡는다.,Step:3 오른발이나 발목을 엉덩이 쪽으로 천천히 당겨 오른쪽 허벅지 앞쪽이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 풀어준 뒤 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1PLE8e9', '덤벨 인클라인 트위스트 플라이', 'https://static.exercisedb.dev/media/1PLE8e9.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 인클라인 벤치를 45도로 맞추고 앉아 양손에 덤벨을 들되 손바닥은 서로 마주 보게 한다.,Step:2 벤치에 누워 덤벨을 가슴 위로 밀어 올려 팔을 편다.,Step:3 덤벨을 넓은 호를 그리며 옆으로 내려 가슴이 늘어나는 지점을 찾는다.,Step:4 내릴 때 손목을 회전시켜 동작 하단에서 손바닥이 앞으로 향하게 한다.,Step:5 동작을 역으로 수행해 덤벨을 다시 올리며 상단에서 가슴을 조인다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CB8WET1', '인클라인 푸시업 깊이 점프', 'https://static.exercisedb.dev/media/CB8WET1.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 벤치나 스텝처럼 손을 올릴 수 있는 높은 지지면을 찾고, 가장자리에 손을 어깨너비로 둔다.,Step:2 발을 뒤로 보내 머리부터 발끝까지 일직선을 만든다.,Step:3 팔꿈치를 굽혀 가슴을 지지면 가장자리 쪽으로 내리며 몸의 정렬을 유지한다.,Step:4 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:5 지지면에서 점프해 내려오고, 무릎을 살짝 굽혀 부드럽게 착지한다.,Step:6 원하는 반복 횟수만큼 푸시업과 점프를 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mWBtgmb', '덤벨 싱글 암 오버헤드 캐리', 'https://static.exercisedb.dev/media/mWBtgmb.gif', '삼각근', '어깨', '덤벨', '승모근,코어', 'Step:1 발을 어깨너비로 두고 곧게 선 채 한 손에 덤벨을 든다.,Step:2 덤벨을 머리 위로 들어 팔을 완전히 편다.,Step:3 코어에 힘을 주고 등을 곧게 유지한 채 앞으로 걸으며 덤벨을 머리 위로 고정한다.,Step:4 원하는 거리 또는 시간만큼 걷는다.,Step:5 손을 바꿔 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PAgTVaK', '가슴 딥스(무릎 꿇기)', 'https://static.exercisedb.dev/media/PAgTVaK.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 머신 높이를 맞추고 무릎을 패드에 고정한다.,Step:2 손바닥이 아래로 향하게 손잡이를 잡고 팔을 완전히 편다.,Step:3 팔꿈치를 굽혀 상완이 바닥과 평행해질 때까지 몸을 내린다.,Step:4 잠시 멈춘 뒤 팔을 펴며 시작 자세로 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AQ0mC4Y', '덤벨 풀 캔 래터럴 레이즈', 'https://static.exercisedb.dev/media/AQ0mC4Y.gif', '삼각근', '어깨', '덤벨', '승모근,회전근개', 'Step:1 발을 어깨너비로 두고 서서 덤벨을 양손에 들고 손바닥은 몸을 향하게 한다.,Step:2 등을 곧게 하고 코어에 힘을 준다.,Step:3 팔꿈치를 살짝 굽힌 채 팔을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 꼭대기에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OaE7CpD', '케틀벨 더블 윈드밀', 'https://static.exercisedb.dev/media/OaE7CpD.gif', '복근', '허리', '케틀벨', '어깨,햄스트링', 'Step:1 발을 어깨너비로 두고 서서 오른손에 케틀벨을 든다.,Step:2 오른팔을 머리 위로 곧게 펴고 시선은 케틀벨을 본다.,Step:3 왼발은 왼쪽으로 45도, 오른발은 오른쪽으로 90도 돌린다.,Step:4 허리를 왼쪽으로 접어 오른팔은 머리 위로 고정한 채 상체를 기울인다.,Step:5 케틀벨을 바닥 쪽으로 내리며 왼발 쪽으로 손을 뻗는다.,Step:6 잠시 멈춘 뒤 코어에 힘을 주고 오른발로 밀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G61cXLk', '케이블 레이즈 백 트라이셉스(로프)(남성)', 'https://static.exercisedb.dev/media/G61cXLk.gif', '삼각근', '어깨', '케이블', '승모근,능형근,이두근', 'Step:1 로프 손잡이를 낮은 풀리에 연결하고 머신을 마주 보며 무릎을 꿇는다.,Step:2 로프를 중립 그립(손바닥 서로 마주)으로 잡고 팔을 앞쪽으로 완전히 편다.,Step:3 등을 곧게 하고 코어에 힘을 준 채, 견갑골을 뒤로 모으며 로프를 몸 쪽으로 당긴다.,Step:4 끝 지점에서 견갑골을 조이며 잠시 멈춘다.,Step:5 천천히 긴장을 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Wgaz7pm', '레버 시트 크런치', 'https://static.exercisedb.dev/media/Wgaz7pm.gif', '복근', '허리', '레버리지 머신', '복사근', 'Step:1 레버리지 머신에 앉아 등을 패드에 붙이고 발은 바닥에 둔다.,Step:2 손잡이를 잡거나 측면 패드에 손을 두어 몸을 고정한다.,Step:3 복근에 힘을 주고 천천히 상체를 뒤로 젖혀 패드가 함께 움직이게 한다.,Step:4 상체가 약 45도 정도로 기울면 복근을 수축해 앞으로 크런치하며 가슴을 무릎 쪽으로 가져온다.,Step:5 꼭대기에서 잠시 멈춘 뒤 천천히 풀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9pa4H5m', '밴드 수평 팔로프 프레스', 'https://static.exercisedb.dev/media/9pa4H5m.gif', '복근', '허리', '밴드', '복사근,둔근', 'Step:1 밴드를 허리 높이의 튼튼한 고정 지점에 연결한다.,Step:2 고정 지점을 옆으로 두고 몸을 수직으로 선다(밴드와 직각).,Step:3 양손으로 손잡이를 잡고 옆으로 이동해 밴드에 장력을 만든다.,Step:4 팔꿈치를 굽혀 손을 가슴 앞에 두고 몸통에 가깝게 유지한다.,Step:5 코어에 힘을 주고 자세를 안정적으로 고정한다.,Step:6 팔을 정면으로 곧게 펴며 밴드를 밀어낸다.,Step:7 몇 초간 유지하며 코어 긴장을 유지한다.,Step:8 밴드의 당김을 버티며 천천히 손을 다시 가슴 앞으로 가져온다.,Step:9 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZqNOWQ6', '레버 리버스 그립 수직 행', 'https://static.exercisedb.dev/media/ZqNOWQ6.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이와 발판 위치를 조절해 정렬이 맞도록 한다.,Step:2 가슴을 패드에 대고 앉아 발은 발판에 둔다.,Step:3 손바닥이 위를 향하게 언더핸드 그립으로 손잡이를 잡는다.,Step:4 등을 곧게 하고 코어에 힘을 준다.,Step:5 손잡이를 가슴 쪽으로 당기며 견갑골을 모은다.,Step:6 상단에서 잠시 멈춘 뒤 천천히 팔을 펴며 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EyLrNC2', '짐 볼 크로스 암 레이즈', 'https://static.exercisedb.dev/media/EyLrNC2.gif', '광배근', '등', '스태빌리티 볼', '어깨,코어', 'Step:1 스태빌리티 볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥은 서로 마주 보게 하며 팔은 몸 옆으로 늘어뜨린다.,Step:3 코어에 힘을 주고 한쪽 팔을 어깨 쪽으로 들어 올린다(팔꿈치는 약간 굽힘).,Step:4 꼭대기에서 잠시 멈춘 뒤 천천히 팔을 내린다.,Step:5 반대쪽 팔로 동일하게 반복한다.,Step:6 원하는 반복 횟수만큼 교대로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DB0n8AG', '케틀벨 프론트 스쿼트', 'https://static.exercisedb.dev/media/DB0n8AG.gif', '둔근', '허벅지', '케틀벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 두고 발끝은 약간 바깥으로 돌린다.,Step:2 케틀벨을 양손으로 가슴 앞에 바짝 붙여 든다.,Step:3 코어에 힘을 주고 가슴을 든 채, 의자에 앉듯 엉덩이를 뒤로 빼며 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:5 뒤꿈치로 밀어 일어서며 상단에서 둔근을 조인다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('w2oRpuH', '레버 교대 좁은 그립 좌석 행', 'https://static.exercisedb.dev/media/w2oRpuH.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이와 발판 위치를 조절해 정렬이 맞도록 한다.,Step:2 등을 곧게 하고 앉아 발은 발판에 둔다.,Step:3 손바닥이 서로 마주 보게 좁은 그립으로 손잡이를 잡는다.,Step:4 운동 내내 가슴을 들고 어깨를 뒤로 유지한다.,Step:5 한쪽 손잡이를 몸통 쪽으로 당기고 다른 쪽은 고정한 채 유지한다.,Step:6 끝 지점에서 견갑골을 모아 조인다.,Step:7 천천히 시작 자세로 되돌리고 반대쪽도 반복한다.,Step:8 원하는 반복 횟수만큼 교대로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zYmNaoY', '엘리베이터', 'https://static.exercisedb.dev/media/zYmNaoY.gif', '등 위쪽', '등', '맨몸', '어깨,승모근', 'Step:1 발을 어깨너비로 두고 서서 무릎을 살짝 굽힌다.,Step:2 손을 허리에 두거나 가슴 앞에서 교차한다.,Step:3 등을 곧게 유지한 채 허리에서 천천히 상체를 앞으로 숙여 바닥 쪽으로 내린다.,Step:4 바닥 지점에서 잠시 멈춘 뒤 천천히 상체를 다시 들어 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NKJ8o6x', '골반 기울기', 'https://static.exercisedb.dev/media/NKJ8o6x.gif', '복근', '허리', '맨몸', '허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손은 몸 옆에 둔다.,Step:3 복근에 힘을 주고 골반을 말아 올려 허리가 바닥에 눌리게 한다.,Step:4 복근 수축을 느끼며 몇 초간 유지한다.,Step:5 힘을 풀고 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cAvTaSg', '짐 볼 덤벨 리베이트', 'https://static.exercisedb.dev/media/cAvTaSg.gif', '삼두근', '상완이두근', '덤벨', '어깨,등', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥은 서로 마주 보게 하며 팔꿈치는 90도로 굽힌다.,Step:3 팔을 뒤로 곧게 펴며 삼두근을 수축한다.,Step:4 꼭대기에서 잠시 멈춘 뒤 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kXaIn5A', '덤벨 조트만 컬', 'https://static.exercisedb.dev/media/kXaIn5A.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 곧게 서며 손바닥은 몸을 향하게 한다.,Step:2 팔꿈치를 몸통에 붙이고 상완을 고정한 채 손바닥을 앞으로 회전시킨다.,Step:3 상완을 고정하고 덤벨을 어깨까지 컬한다.,Step:4 상단에서 손목을 회전해 손바닥이 몸 바깥쪽을 향하게 한다.,Step:5 천천히 덤벨을 내리며 손바닥을 다시 몸 쪽으로 회전시킨다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wDN97Ca', '머신 이너 체스트 프레스', 'https://static.exercisedb.dev/media/wDN97Ca.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 좌석 높이를 조절하고 등에 패드를 밀착해 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔꿈치를 90도 정도로 맞춘다.,Step:3 숨을 내쉬며 손잡이를 앞으로 밀어 팔을 완전히 편다.,Step:4 끝 지점에서 잠시 멈춘 뒤 천천히 시작 자세로 되돌리며 숨을 들이마신다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nCU1Ekp', '리버스 크런치', 'https://static.exercisedb.dev/media/nCU1Ekp.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 팔을 몸 옆으로 뻗는다.,Step:2 무릎을 굽혀 발을 바닥에서 들어 허벅지가 바닥과 수직이 되게 한다.,Step:3 복근을 수축해 골반을 말아 올리며 무릎을 가슴 쪽으로 당긴다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 골반을 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zZlORz6', '덤벨 누워 한쪽 팔 외전 삼두근 익스텐션', 'https://static.exercisedb.dev/media/zZlORz6.gif', '삼두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 누워 머리와 등을 지지하고 발은 바닥에 둔다.,Step:2 한 손에 덤벨을 언더핸드 그립으로 잡고 어깨 위로 팔을 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:4 하단에서 잠시 멈춘 뒤 삼두근 힘으로 팔을 펴 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qLpO4vV', '짐 볼의 등 익스텐션', 'https://static.exercisedb.dev/media/qLpO4vV.gif', '척추', '등', '스태빌리티 볼', '둔근,햄스트링', 'Step:1 스태빌리티 볼을 바닥에 두고 그 위에 엎드려 골반이 볼에 얹히게 하고 발은 벽이나 안정된 지지면에 둔다.,Step:2 손을 머리 뒤에 두거나 가슴 위로 교차한다.,Step:3 코어에 힘을 주고 상체를 천천히 들어 올려 등이 펴지며 머리부터 발끝까지 일직선이 되게 한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 상체를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8K0w2yA', '던지기와 함께 매달린 무릎 올리기 지원', 'https://static.exercisedb.dev/media/8K0w2yA.gif', '복근', '허리', '도움을 준', '고관절 굴근,허리', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥은 정면을 향하게 한다.,Step:2 코어에 힘을 주고 무릎을 가슴 쪽으로 끌어올리며 다리는 붙인다.,Step:3 무릎이 가슴 높이에 오면 다리를 아래로 강하게 던지듯 뻗어 내린다.,Step:4 다리가 다시 앞으로 스윙되도록 두고 같은 동작을 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nUwVh7b', '덤벨 데드리프트', 'https://static.exercisedb.dev/media/nUwVh7b.gif', '둔근', '허벅지', '덤벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 두고 발끝은 정면을 향하게 선다.,Step:2 양손에 덤벨을 들고 손바닥은 몸을 향하게 하며 팔은 아래로 늘어뜨린다.,Step:3 등을 곧게 유지한 채 엉덩이와 무릎을 굽혀 덤벨을 바닥 쪽으로 내린다.,Step:4 뒤꿈치로 밀어 엉덩이와 무릎을 펴며 덤벨을 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2JCuFTU', '덤벨 무릎 꿇기 바이셉스 짐 볼', 'https://static.exercisedb.dev/media/2JCuFTU.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 바닥에 무릎을 꿇고 앞에 짐 볼을 둔다.,Step:2 팔꿈치를 짐 볼 위에 올리고 손바닥이 위를 향하게 덤벨을 양손에 든다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 컬해 이두근을 수축한다.,Step:4 덤벨이 어깨 높이에 오고 이두근이 완전히 수축될 때까지 들어 올린다.,Step:5 상단에서 잠시 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UFGF6gk', '케이블 로프 크로스오버 좌석 행', 'https://static.exercisedb.dev/media/UFGF6gk.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 로잉 머신(좌석)에서 발을 고정하고 무릎을 살짝 굽힌 채 앉는다.,Step:2 케이블 로프를 오버핸드 그립으로 잡고 손바닥이 서로 마주 보게 한다.,Step:3 등을 곧게 하고 코어에 힘을 주며 상체를 약간 뒤로 기울인다.,Step:4 로프를 가슴 쪽으로 당기며 견갑골을 모아 등을 수축한다.,Step:5 수축 지점에서 잠시 멈춘 뒤 천천히 긴장을 풀고 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('c8oybX6', '케이블 로프 높은 좌석 행', 'https://static.exercisedb.dev/media/c8oybX6.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 높게 세팅된 좌석에 앉아 케이블 머신을 마주 본다.,Step:2 로프 손잡이를 오버핸드 그립으로 잡고 손바닥이 서로 마주 보게 한다.,Step:3 등을 곧게 하고 무릎을 살짝 굽힌 채 상체를 약간 뒤로 기울인다.,Step:4 견갑골을 뒤로 모으며 케이블을 몸 쪽으로 당겨 등 근육을 수축한다.,Step:5 완전히 수축된 지점에서 잠시 멈춘다.,Step:6 천천히 긴장을 풀며 팔을 펴 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QLRmNeT', '짐 볼 덤벨 해머 컬', 'https://static.exercisedb.dev/media/QLRmNeT.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥은 몸을 향하게 하며 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 한쪽 덤벨을 어깨까지 컬한다(손바닥 방향 유지).,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오면 잠시 멈춘다.,Step:5 숨을 들이마시며 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:6 반대쪽 팔로 반복한다.,Step:7 원하는 반복 횟수만큼 교대로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('f9lVSSI', '스트라이드 점프(남자)', 'https://static.exercisedb.dev/media/f9lVSSI.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 두고 선다.,Step:2 무릎을 굽혀 스쿼트 자세로 내려간다.,Step:3 폭발적으로 점프하며 다리와 팔을 뻗어 올린다.,Step:4 공중에서 다리를 벌리고 팔을 옆으로 펼친다.,Step:5 발을 어깨너비로 부드럽게 착지하며 무릎을 굽혀 충격을 흡수한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wXvUZC8', '체중을 밀고 당기기', 'https://static.exercisedb.dev/media/wXvUZC8.gif', '가슴근육', '가슴', '맨몸', '삼두근,삼각근', 'Step:1 손을 어깨너비보다 약간 넓게 둔 푸시업 자세로 시작하고 몸은 일직선을 유지한다.,Step:2 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리며 몸의 정렬을 유지한다.,Step:3 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:4 푸시업 자세에서 팔꿈치를 굽혀 가슴을 바닥 쪽으로 ‘당기듯’ 내려가되, 몸 정렬을 유지한다.,Step:5 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('z6TAHoT', '덤벨 트위스트 벤치 프레스', 'https://static.exercisedb.dev/media/z6TAHoT.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 벤치에 누워 발을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 손바닥이 앞을 향하도록 오버핸드 그립으로 덤벨을 양손에 든다.,Step:3 팔꿈치를 살짝 굽힌 채 덤벨을 가슴 위로 곧게 들어 올린다.,Step:4 팔꿈치를 몸통에 가깝게 유지하며 덤벨을 가슴 쪽으로 천천히 내린다.,Step:5 내릴 때 손목을 비틀어 하단에서 손바닥이 서로 마주 보게 한다.,Step:6 하단에서 잠시 멈춘 뒤 덤벨을 밀어 올려 시작 자세로 돌아온다.,Step:7 올릴 때 손목을 다시 비틀어 시작 자세처럼 손바닥이 바깥을 향하게 한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CjETvlw', '롤러 장착 단일 다리 어깨 굴근 감압근 견인기', 'https://static.exercisedb.dev/media/CjETvlw.gif', '가슴근육', '가슴', '롤러', '삼각근,삼두근', 'Step:1 평평한 바닥에 앉아 다리를 앞으로 곧게 뻗는다.,Step:2 롤러를 양손으로 잡고 손바닥이 아래를 향하게 하여 허벅지 위에 둔다.,Step:3 상체를 약간 뒤로 기울이고 코어에 힘을 준다.,Step:4 롤러를 어깨 높이까지 들어 올리되 팔은 곧게 유지한다.,Step:5 롤러를 천천히 다시 허벅지 쪽으로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jK2hZ6n', '덤벨 한쪽 팔 장착 해머 컬', 'https://static.exercisedb.dev/media/jK2hZ6n.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 등을 곧게 하고 발을 바닥에 둔다.,Step:2 한 손에 덤벨을 중립 그립(손바닥 서로 마주)으로 잡는다.,Step:3 팔꿈치를 허벅지 안쪽(무릎 위쪽)에 고정해 지지한다.,Step:4 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 컬한다.,Step:5 상단에서 잠시 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 천천히 덤벨을 내린다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9sgNE2O', '바벨 디클라인 풀오버', 'https://static.exercisedb.dev/media/9sgNE2O.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 머리가 엉덩이보다 낮게 위치하도록 하고 발을 고정한다.,Step:2 손바닥이 바깥을 향하는 프로네이티드 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 팔꿈치를 살짝 굽힌 채 바벨을 가슴 위로 들어 올린다.,Step:4 바벨을 호를 그리며 머리 뒤로 천천히 내려 가슴과 어깨가 늘어나는 느낌을 받는다.,Step:5 잠시 멈춘 뒤 같은 궤도로 바벨을 다시 시작 위치로 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KOpzGBL', '덤벨 웨이터 바이셉스 컬', 'https://static.exercisedb.dev/media/KOpzGBL.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 양손에 덤벨을 들고 곧게 서며 손바닥이 앞을 향하게 한다.,Step:2 상완을 몸에 붙이고 팔꿈치를 안쪽으로 모아 고정한다.,Step:3 손목을 꺾지 말고 천천히 덤벨을 어깨까지 컬한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UGhRD1A', '옆으로 던지는 자세로 누워서 다리 올리기 보조', 'https://static.exercisedb.dev/media/UGhRD1A.gif', '복근', '허리', '도움을 준', '고관절 굴근,복사근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔은 몸 옆에 둔다.,Step:2 손을 엉덩이 아래에 넣어 지지한다.,Step:3 복근에 힘을 주고 다리를 곧게 유지한 채 바닥에서 들어 올린다.,Step:4 다리를 붙인 채 한쪽으로 내려 바닥에서 몇 cm 위에서 멈춘다.,Step:5 잠시 멈춘 뒤 다리를 다시 중앙으로 올려 시작 자세로 돌아온다.,Step:6 반대쪽으로도 같은 동작을 한다.,Step:7 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZNgOYQU', '레그 레이즈 (평행봉)', 'https://static.exercisedb.dev/media/ZNgOYQU.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 평행봉을 잡고 팔을 완전히 편 채 몸을 곧게 늘어뜨린다.,Step:2 코어에 힘을 주고 다리를 곧게 편 채 앞쪽으로 들어 올린다.,Step:3 다리가 바닥과 평행(또는 그 이상)해질 때까지 들어 올린다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 다리를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Q2Eu1Ax', '케이블 라이딩 익스텐션 풀오버(로프 포함)', 'https://static.exercisedb.dev/media/Q2Eu1Ax.gif', '광배근', '등', '케이블', '삼두근,어깨', 'Step:1 로프를 케이블 머신에 연결하고 풀리를 가장 높은 위치로 맞춘다.,Step:2 벤치에 누워 머리가 케이블 머신 쪽을 향하게 한다.,Step:3 로프를 양손으로 잡고 팔을 가슴 위로 곧게 편다(손바닥 서로 마주).,Step:4 팔을 곧게 유지한 채 로프를 머리 뒤로 천천히 내리며 컨트롤한다.,Step:5 하단에서 잠시 멈춘 뒤 천천히 로프를 다시 시작 위치로 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('b9kqlBy', '케틀벨 교대 레니게이드 로우', 'https://static.exercisedb.dev/media/b9kqlBy.gif', '등 위쪽', '등', '케틀벨', '코어,어깨', 'Step:1 케틀벨을 잡고 하이 플랭크 자세를 만든다(발은 골반 너비).,Step:2 코어에 힘을 주고 머리부터 발끝까지 일직선을 유지한다.,Step:3 한쪽 케틀벨을 가슴 쪽으로 당기며 팔꿈치를 몸에 가깝게 유지한다.,Step:4 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 반대쪽 팔로 반복하며 교대로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6pTkI99', '덤벨 원 암 스내치', 'https://static.exercisedb.dev/media/6pTkI99.gif', '둔근', '허벅지', '덤벨', '햄스트링,대퇴사두근,코어', 'Step:1 발을 어깨너비로 두고 한 손에 덤벨을 오버핸드 그립으로 잡는다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 하고 가슴을 편다.,Step:3 덤벨을 몸에 가깝게 유지하며 바닥 쪽으로 내린다.,Step:4 엉덩이, 무릎, 발목을 폭발적으로 펴며 덤벨을 수직으로 끌어올린다.,Step:5 덤벨이 어깨 높이에 오면 빠르게 손을 회전시키며 머리 위로 ‘펀치’하듯 올려 팔을 완전히 편다.,Step:6 머리 위에서 덤벨을 받되 무릎과 엉덩이를 살짝 굽혀 충격을 흡수한다.,Step:7 덤벨을 컨트롤하며 다시 시작 자세로 내린다.,Step:8 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8coXSYU', '롤러 어깨 굴곡근 풀어주기', 'https://static.exercisedb.dev/media/8coXSYU.gif', '가슴근육', '가슴', '롤러', '삼각근,삼두근', 'Step:1 평평한 바닥에 앉아 다리를 앞으로 곧게 뻗는다.,Step:2 롤러를 양손으로 잡고 손바닥이 아래를 향하게 하여 허벅지 위에 둔다.,Step:3 상체를 약간 앞으로 기울이고 롤러를 몸에서 멀어지게 굴리며 팔을 정면으로 곧게 편다.,Step:4 잠시 멈춘 뒤 롤러를 다시 몸 쪽으로 굴리며 팔을 굽혀 허벅지로 되돌린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hxyTtWj', '덤벨 시티드 레터럴 레이즈', 'https://static.exercisedb.dev/media/hxyTtWj.gif', '삼각근', '어깨', '덤벨', '승모근,등 위쪽', 'Step:1 벤치에 앉아 발을 바닥에 두고 덤벨을 양손에 들고 허벅지 위에 둔다.,Step:2 등을 곧게 하고 코어에 힘을 준다.,Step:3 팔꿈치를 살짝 굽힌 채 덤벨을 옆으로 들어 올려 팔이 바닥과 평행이 되게 한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sVvXT5J', '짐 볼 파이크 푸시 업', 'https://static.exercisedb.dev/media/sVvXT5J.gif', '가슴근육', '가슴', '스태빌리티 볼', '어깨,삼두근,코어', 'Step:1 손은 바닥에 두고 정강이를 스태빌리티 볼 위에 둔 푸시업 자세로 시작한다.,Step:2 코어에 힘을 주고 엉덩이를 들어 올리며 볼을 손 쪽으로 굴린다.,Step:3 다리를 곧게 유지해 몸이 역V자(파이크) 형태가 되게 한다.,Step:4 팔꿈치를 굽혀 상체를 바닥 쪽으로 내리되 머리는 손 사이에 오게 한다.,Step:5 손으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Wgbn9qo', '삼두근 딥스(벤치)', 'https://static.exercisedb.dev/media/Wgbn9qo.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치에 앉아 손을 벤치 가장자리에 두고 손가락은 앞을 향하게 한다.,Step:2 엉덩이를 벤치 밖으로 빼고 손으로 체중을 지지한다.,Step:3 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 등을 벤치에 가깝게 유지한다.,Step:4 하단에서 잠시 멈춘 뒤 손으로 밀어 팔을 펴며 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('q6y3OhV', '레버 바이셉 컬', 'https://static.exercisedb.dev/media/q6y3OhV.gif', '이두근', '상완이두근', '레버리지 머신', '전완근', 'Step:1 좌석 높이를 조절하고 등에 패드를 붙여 머신에 앉는다.,Step:2 손바닥이 위를 향하게 언더핸드 그립으로 손잡이를 잡고 팔꿈치는 몸 옆에 붙인다.,Step:3 숨을 내쉬며 손잡이를 위로 컬해 이두근을 수축한다.,Step:4 상단에서 잠시 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 천천히 손잡이를 내려 팔을 완전히 펴 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IvV6C9M', '벤치 덤벨 원 암 손목 컬', 'https://static.exercisedb.dev/media/IvV6C9M.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 한 손에 덤벨을 들고 팔을 벤치 위로 뻗어 손바닥이 위를 향하게 한다.,Step:2 상완을 고정한 채 손목을 중립으로 유지하며 덤벨을 어깨 쪽으로 컬한다.,Step:3 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wdRZISl', '바벨 스탠딩 클로즈 그립 밀리터리 프레스', 'https://static.exercisedb.dev/media/wdRZISl.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 두고 서서 바벨을 오버핸드 그립으로 어깨너비보다 약간 좁게 잡는다.,Step:2 바벨을 어깨 높이로 들어 올리며 팔꿈치를 몸에 가깝게 둔다.,Step:3 바벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 바벨을 다시 어깨 높이로 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hacCyUv', 'ez 바벨 클로즈 그립 프리처 컬', 'https://static.exercisedb.dev/media/hacCyUv.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 프리처 컬 벤치에 앉아 상완을 패드에 올리고 EZ 바를 언더핸드 그립으로 잡는다.,Step:2 삼두가 패드에 닿게 두고 팔을 완전히 편다(등은 곧게).,Step:3 바를 천천히 컬해 어깨 쪽으로 올리며 이두근을 수축한다.,Step:4 상단에서 잠시 멈추며 이두근을 조인다.,Step:5 바를 천천히 내려 팔을 완전히 펴 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3TZduzM', '바벨 인클라인 벤치 프레스', 'https://static.exercisedb.dev/media/3TZduzM.gif', '가슴근육', '가슴', '바벨', '어깨,삼두근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 누워 발을 바닥에 둔다.,Step:3 바벨을 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 바벨을 언랙하고 팔꿈치를 컨트롤하며 가슴 쪽으로 천천히 내린다.,Step:5 하단에서 잠시 멈춘 뒤 바벨을 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('O2K9Vb5', '높은 평행봉에서 와이드 그립 가슴 딥', 'https://static.exercisedb.dev/media/O2K9Vb5.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 평행봉 위에 올라 팔을 완전히 펴고 몸을 공중에 띄운다.,Step:2 상체를 약간 앞으로 기울인다.,Step:3 팔꿈치를 굽혀 가슴이 봉 바로 위에 올 때까지 몸을 내린다.,Step:4 잠시 멈춘 뒤 팔을 펴며 시작 자세로 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RxayqAZ', '덤벨 클로즈 그립 프레스', 'https://static.exercisedb.dev/media/RxayqAZ.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 평벤치에 앉아 양손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 허벅지로 덤벨을 보조해 한 쪽씩 들어 올려 어깨너비로 가슴 앞에 위치시킨다.,Step:3 손목을 회전해 손바닥이 바깥(정면)을 향하게 하여 시작 자세를 만든다.,Step:4 숨을 들이마시며 덤벨을 천천히 내려 가슴 옆(가슴 높이)까지 내린다.,Step:5 숨을 내쉬며 삼두근을 사용해 덤벨을 다시 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LkoAWAE', '팔꿈치 딥스', 'https://static.exercisedb.dev/media/LkoAWAE.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 의자 가장자리에 앉아 손을 엉덩이 옆 벤치 가장자리에 둔다.,Step:2 엉덩이를 앞으로 빼고 다리를 펴 뒤꿈치는 바닥에 둔다.,Step:3 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 등을 벤치에 가깝게 유지한다.,Step:4 하단에서 잠시 멈춘 뒤 손으로 밀어 팔을 펴며 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('reFHapa', '덤벨 디클라인 트위스트 플라이', 'https://static.exercisedb.dev/media/reFHapa.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 디클라인 벤치에 누워 머리가 엉덩이보다 낮게 위치하도록 한다.,Step:2 양손에 덤벨을 들고 손바닥이 서로 마주 보게 한 채 가슴 위로 팔을 곧게 편다.,Step:3 덤벨을 넓은 호로 옆으로 내려 가슴이 늘어나는 지점을 찾는다.,Step:4 내릴 때 손목을 비틀어 하단에서 손바닥이 앞으로 향하게 한다.,Step:5 동작을 역으로 수행해 덤벨을 다시 시작 위치로 올리며 상단에서 가슴을 조인다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QpXqiq8', '서스펜디드 스플릿 스쿼트', 'https://static.exercisedb.dev/media/QpXqiq8.gif', '대퇴사두근', '허벅지', '맨몸', '둔근,햄스트링,종아리근', 'Step:1 서스펜션 트레이너를 등지고 서서 발을 어깨너비로 둔다.,Step:2 한쪽 다리를 앞으로 뻗어 발등을 서스펜션 발걸이에 올린다.,Step:3 서 있는 쪽 다리 무릎을 굽혀 런지로 내려가되 가슴을 들고 무릎이 발끝 방향과 일직선이 되게 한다.,Step:4 앞발 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('da4cXST', 'ez바 클로즈그립 벤치프레스', 'https://static.exercisedb.dev/media/da4cXST.gif', '삼두근', '상완이두근', 'EZ 바벨', '가슴,어깨', 'Step:1 벤치에 누워 발을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 EZ 바를 클로즈 그립(어깨너비)으로 잡고 손바닥이 정면을 향하게 한다.,Step:3 바벨을 언랙해 가슴 위에서 팔을 완전히 편다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 바벨을 천천히 가슴 쪽으로 내린다.,Step:5 바벨이 가슴에 닿을 때 잠시 멈춘다.,Step:6 바벨을 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tj41Nu6', '슬레이 45в° 레그 와이드 프레스', 'https://static.exercisedb.dev/media/tj41Nu6.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신 각도를 45도로 맞춘다.,Step:2 등 패드에 등을 대고 앉아 발을 발판에 둔다.,Step:3 발을 어깨너비보다 넓게 벌린다.,Step:4 발판을 밀어 다리를 펴고 무릎을 곧게 한다.,Step:5 끝 지점에서 잠시 멈춘 뒤 무릎을 굽혀 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tc5dYrf', '밴드 스탠딩 리어 델트 로우', 'https://static.exercisedb.dev/media/tc5dYrf.gif', '삼각근', '어깨', '밴드', '승모근,능형근,이두근', 'Step:1 발을 어깨너비로 두고 밴드를 발 아래에 고정한다.,Step:2 손바닥이 서로 마주 보게 밴드 손잡이를 잡고 팔을 정면으로 뻗는다.,Step:3 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 한다.,Step:4 밴드를 가슴 쪽으로 당기며 견갑골을 모아준다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 긴장을 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rmEukuS', '다리를 쭉 뻗은 외다리 브릿지', 'https://static.exercisedb.dev/media/rmEukuS.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 한쪽 다리를 앞으로 곧게 뻗는다.,Step:3 둔근에 힘을 주고 엉덩이를 들어 무릎부터 어깨까지 일직선이 되게 한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 엉덩이를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KgI0tqW', '바벨 스모 데드리프트', 'https://static.exercisedb.dev/media/KgI0tqW.gif', '둔근', '허벅지', '바벨', '햄스트링,대퇴사두근,허리', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝은 바깥쪽을 향하게 선다.,Step:2 바벨을 발 사이 중앙, 몸 앞에 둔다.,Step:3 무릎을 굽히고 엉덩이를 낮추되 등을 곧게 하고 가슴을 들어 바벨을 오버핸드 그립으로 잡는다.,Step:4 코어에 힘을 주고 뒤꿈치로 밀어 엉덩이와 무릎을 동시에 펴며 바벨을 들어 올린다.,Step:5 들어 올릴 때 가슴을 들고 등을 곧게 유지하며 엉덩이를 앞으로 밀어 둔근을 완전히 수축한다.,Step:6 상단에서 잠시 멈춘 뒤 컨트롤하며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('17bqEXD', '앉아서 하는 종아리 스트레칭(남성)', 'https://static.exercisedb.dev/media/17bqEXD.gif', '종아리근', '종아리', '맨몸', '햄스트링', 'Step:1 의자나 벤치 끝에 앉고 양발을 바닥에 둔다.,Step:2 한쪽 다리를 앞으로 곧게 뻗어 뒤꿈치를 바닥에 둔다.,Step:3 상체를 조금 앞으로 기울여 종아리가 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JzQbv7J', '덤벨 앉아서 구부린 팔 옆으로 올리기', 'https://static.exercisedb.dev/media/JzQbv7J.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 벤치에 앉아 등을 곧게 하고 발을 바닥에 둔다.,Step:2 양손에 덤벨을 들고 손바닥은 몸을 향하게 하며 팔꿈치는 90도로 굽힌다.,Step:3 팔꿈치를 굽힌 채 팔을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('c16nYGA', '원 암 밴드 트위스트 체스트 프레스', 'https://static.exercisedb.dev/media/c16nYGA.gif', '가슴근육', '가슴', '밴드', '어깨,삼두근', 'Step:1 밴드를 가슴 높이의 튼튼한 고정 지점에 연결한다.,Step:2 고정 지점을 옆에 두고 서서 한 손으로 밴드를 잡는다.,Step:3 고정 지점에서 멀어져 밴드에 장력을 만든다.,Step:4 발을 어깨너비로 두고 무릎을 살짝 굽힌다.,Step:5 밴드를 잡은 손을 몸 앞을 가로질러 반대쪽 어깨 쪽으로 가져온다.,Step:6 밴드 장력을 유지한 채 손을 정면으로 밀어 팔을 편다.,Step:7 천천히 시작 자세로 돌아와 반복한다.,Step:8 반대쪽도 동일하게 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PSlvNMs', '가중 드롭 푸시업', 'https://static.exercisedb.dev/media/PSlvNMs.gif', '가슴근육', '가슴', '가중', '삼두근,어깨', 'Step:1 손을 어깨너비보다 약간 넓게, 발은 모은 하이 플랭크 자세로 시작한다.,Step:2 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리되 팔꿈치는 몸에 가깝게 둔다.,Step:3 가슴이 바닥 바로 위에 오면 폭발적으로 밀어 올려 손이 바닥에서 떨어지게 한다.,Step:4 올라오면서 손을 옆(그리고 약간 앞으로)으로 빠르게 옮겨 몸이 아래로 ‘떨어지듯’ 내려오게 한다.,Step:5 넓어진 손 위치로 몸을 받아 즉시 다시 가슴을 내린다.,Step:6 다시 폭발적으로 밀어 올리며 손을 더 좁은 위치로 옮겨 받아준다.,Step:7 넓게/좁게 손 위치를 번갈아가며 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WCAvOfC', '좌우 발가락 터치(남성)', 'https://static.exercisedb.dev/media/WCAvOfC.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 발을 어깨너비로 두고 서서 팔을 옆으로 뻗는다.,Step:2 허리를 오른쪽으로 굽혀 오른손으로 오른발 쪽을 터치하고 왼손은 옆으로 뻗어 둔다.,Step:3 시작 자세로 돌아온 뒤 왼쪽으로 굽혀 왼손으로 왼발 쪽을 터치하고 오른손은 옆으로 뻗어 둔다.,Step:4 원하는 반복 횟수만큼 좌우로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bndCa3Q', '바벨 핀 프레스', 'https://static.exercisedb.dev/media/bndCa3Q.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 파워랙에 바벨을 가슴 높이로 세팅한다.,Step:2 바벨을 마주 보고 서서 바 아래로 몸을 위치시킨다(발은 어깨너비).,Step:3 바벨을 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 바벨을 랙에서 들어 올려 가슴 위에서 팔을 완전히 편다.,Step:5 팔꿈치를 몸에 가깝게 두며 바벨을 가슴 쪽으로 내린다.,Step:6 바벨이 가슴에 닿으면 잠시 멈춘다.,Step:7 바벨을 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xMjBKwn', '덤벨 옆에서 앞으로 올리기', 'https://static.exercisedb.dev/media/xMjBKwn.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 발을 어깨너비로 두고 서서 덤벨을 양손에 들고 손바닥은 몸을 향하게 한다.,Step:2 등을 곧게 하고 코어에 힘을 준다.,Step:3 팔꿈치를 살짝 굽힌 채 덤벨을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:5 이어서 덤벨을 정면으로 들어 올려 바닥과 평행이 되게 한다(팔꿈치 살짝 굽힘 유지).,Step:6 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aTNKZiC', '덤벨 인클라인 원 암 사이드 들어올리기', 'https://static.exercisedb.dev/media/aTNKZiC.gif', '삼각근', '어깨', '덤벨', '승모근,삼두근', 'Step:1 인클라인 벤치에 앉아 한 손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 상체를 앞으로 기울여 상완을 허벅지 안쪽에 대고 고정한다.,Step:3 팔을 살짝 굽히고 손바닥이 아래를 향하게 한 채 덤벨을 옆으로 들어 올린다.,Step:4 팔이 바닥과 평행해질 때까지 들어 올린다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('k5IpyHg', '덤벨 원암 컨센트레이션 컬(스태빌리티 볼 위)', 'https://static.exercisedb.dev/media/k5IpyHg.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 스태빌리티 볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 한 손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔을 바닥 쪽으로 늘어뜨린다.,Step:3 팔꿈치를 허벅지 안쪽(무릎 위)에 고정해 지지한다.,Step:4 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨까지 컬한다.,Step:5 상단에서 잠시 멈춘 뒤 숨을 들이마시며 천천히 덤벨을 내린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ys97II0', '덤벨 시티드 프론트 레이즈', 'https://static.exercisedb.dev/media/Ys97II0.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 벤치에 앉아 발을 바닥에 두고 덤벨을 양손에 들고 허벅지 위에 둔다.,Step:2 등을 곧게 하고 코어에 힘을 준다.,Step:3 손바닥이 아래를 향하게 하여 덤벨을 정면으로 들어 올려 어깨 높이에 맞춘다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('S37C94C', '케틀벨 원암 저크', 'https://static.exercisedb.dev/media/S37C94C.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 두고 서서 한 손에 케틀벨을 어깨 높이에 든다.,Step:2 무릎을 살짝 굽히고 코어에 힘을 준다.,Step:3 케틀벨을 머리 위로 밀어 올리며 팔을 곧게 편다.,Step:4 밀어 올리는 동시에 무릎을 살짝 더 굽혔다가 빠르게 펴며 추진력을 만든다.,Step:5 케틀벨이 최고점에 도달할 때 빠르게 몸을 아래로 넣듯 무릎과 엉덩이를 굽힌다.,Step:6 무릎과 엉덩이를 살짝 굽힌 상태에서 케틀벨을 머리 위로 받아 팔을 완전히 편다.,Step:7 일어서며 무릎과 엉덩이를 완전히 펴고 케틀벨을 안정적으로 고정한다.,Step:8 무릎과 엉덩이를 굽히며 케틀벨을 천천히 어깨 높이로 내리고 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VO2qeJg', '사이드 플랭크 힙 내전', 'https://static.exercisedb.dev/media/VO2qeJg.gif', '내전근', '허벅지', '맨몸', '복사근,둔근', 'Step:1 옆으로 누워 다리를 곧게 펴고 포개어 둔다.,Step:2 전완으로 지지해 팔꿈치가 어깨 아래에 오게 한다.,Step:3 코어에 힘을 주고 엉덩이를 들어 머리부터 발끝까지 일직선을 만든다.,Step:4 사이드 플랭크를 유지한 채 위쪽 다리를 천장 쪽으로 들어 올린다(다리는 곧게).,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('J74XlNf', '짐 볼에 덤벨 교대 앉아 이두근 컬', 'https://static.exercisedb.dev/media/J74XlNf.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥이 앞을 향하게 하며 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 한쪽 덤벨을 컬하면서 전완을 회전시켜 손바닥이 어깨를 향하게 한다.,Step:4 숨을 들이마시며 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:5 반대쪽 팔로 동일하게 반복한다.,Step:6 원하는 반복 횟수만큼 교대로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2IxROQ1', '케이블 오버헤드 삼두근 익스텐션(로프 부착)', 'https://static.exercisedb.dev/media/2IxROQ1.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 케이블 머신의 높은 위치에 로프를 연결한다.,Step:2 머신을 등지고 서서 발을 어깨너비로 둔다.,Step:3 로프를 중립 그립(손바닥 서로 마주)으로 잡고 손을 머리 위로 가져간다.,Step:4 상완을 머리 옆에 붙이고 팔꿈치는 앞을 향하게 둔다.,Step:5 팔꿈치를 굽혀 로프를 머리 뒤로 천천히 내린다.,Step:6 하단에서 잠시 멈춘 뒤 팔을 펴 로프를 다시 위로 올린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lBDjFxJ', '풀업', 'https://static.exercisedb.dev/media/lBDjFxJ.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 손바닥이 바깥(정면)을 향하게 바를 잡고 팔을 완전히 편 채 매달린다.,Step:2 코어에 힘을 주고 견갑골을 모아 어깨를 안정화한다.,Step:3 팔꿈치를 굽혀 가슴을 바 쪽으로 끌어올린다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SYJ4Bkt', '바벨 라이딩 프리처 컬', 'https://static.exercisedb.dev/media/SYJ4Bkt.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 프리처 벤치에 앉아 가슴을 패드에 대고 팔을 패드 가장자리 밖으로 뻗은 채 바벨을 언더핸드 그립으로 잡는다.,Step:2 상완을 고정한 채 숨을 내쉬며 바벨을 컬해 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 상단에서 잠시 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 천천히 바벨을 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WME869U', '무릎을 땅에서 떼고 짐 볼 등 익스텐션', 'https://static.exercisedb.dev/media/WME869U.gif', '척추', '등', '스태빌리티 볼', '둔근,햄스트링', 'Step:1 스태빌리티 볼 위에 엎드려 골반을 볼에 올리고, 발은 벽에 대어 안정화한다.,Step:2 손을 머리 뒤에 두거나 가슴 위로 교차한다.,Step:3 코어에 힘을 주고 상체를 천천히 들어 올려 몸이 머리부터 발끝까지 일직선이 되게 한다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 상체를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QFmz6ch', '앉아서 허리 스트레칭', 'https://static.exercisedb.dev/media/QFmz6ch.gif', '광배근', '등', '맨몸', '둔근,햄스트링', 'Step:1 의자 끝에 앉고 양발을 바닥에 둔다.,Step:2 손을 허벅지나 의자 옆에 두어 몸을 지지한다.,Step:3 등을 곧게 편 상태에서 엉덩이 관절을 기준으로 천천히 상체를 앞으로 기울인다.,Step:4 허리 아래쪽이 늘어나는 것을 느끼며 20–30초 동안 유지한다.,Step:5 천천히 시작 자세로 돌아가 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wOLmCXc', '덤벨 삼두근 킥백', 'https://static.exercisedb.dev/media/wOLmCXc.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 발을 어깨너비로 두고 서서 오른손에 덤벨을 든다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 한다.,Step:3 오른팔꿈치를 옆구리로 들어 올리고 90도로 굽힌다.,Step:4 오른팔을 뒤로 곧게 펴며 삼두근을 수축한다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oLrKqDH', '오래 달리기', 'https://static.exercisedb.dev/media/oLrKqDH.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 골반 너비로 두고 곧게 선다.,Step:2 코어에 힘을 주고 상체는 긴장을 풀어 편안하게 둔다.,Step:3 제자리에서 조깅을 시작하며 무릎을 들어 올리고 발볼로 부드럽게 착지한다.,Step:4 일정한 페이스를 유지하며 원하는 시간/거리만큼 지속한다.,Step:5 호흡을 깊게 하며 좋은 자세를 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gUjqdei', '커트시 스쿼트', 'https://static.exercisedb.dev/media/gUjqdei.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 두고 선다.,Step:2 오른발을 대각선 뒤로, 왼발 뒤로 교차시키듯 내딛는다.,Step:3 양쪽 무릎을 굽혀 커트시(인사)하듯 몸을 낮춘다.,Step:4 상체는 세우고 체중은 앞발에 둔다.,Step:5 앞발 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 왼발로 교차해 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WrYPP2g', '케이블 한쪽 팔 똑바로 뒤로 높은 줄 (무릎 꿇기)', 'https://static.exercisedb.dev/media/WrYPP2g.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 케이블 머신의 허리 높이에 손잡이를 연결한다.,Step:2 머신을 마주 보고 무릎을 꿇고 한 손으로 손잡이를 잡는다.,Step:3 등을 곧게 하고 코어에 힘을 준다.,Step:4 손잡이를 가슴 쪽으로 당기며 견갑골을 모아준다.,Step:5 상단에서 잠시 멈춘다.,Step:6 천천히 손잡이를 풀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.,Step:8 반대쪽도 동일하게 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qdRxqCj', '케이블 풀다운(Pro Lat Bar)', 'https://static.exercisedb.dev/media/qdRxqCj.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 좌석 높이를 맞춰 허벅지가 바닥과 평행해지게 하고 발은 바닥에 둔다.,Step:2 랫 바를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:3 앉아 상체를 약간 뒤로 기울이되 가슴을 들고 등을 곧게 유지한다.,Step:4 바를 가슴 쪽으로 당기며 견갑골을 모아준다.,Step:5 하단에서 잠시 멈춘 뒤 바를 천천히 위로 되돌린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Qoujh3Q', '스프린트(전력질주)', 'https://static.exercisedb.dev/media/Qoujh3Q.gif', '복근', '허리', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 넓은 공간이나 트랙을 확보한다.,Step:2 발을 어깨너비로 두고 선다.,Step:3 팔을 힘차게 휘두르며 무릎을 끌어올려 전력 질주한다.,Step:4 정해진 거리 또는 시간 동안 스프린트를 유지한다.,Step:5 휴식 후 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('13TpY4H', '한쪽 팔 올리기 푸쉬업', 'https://static.exercisedb.dev/media/13TpY4H.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 손을 어깨너비보다 약간 넓게 두고 발은 모은 푸시업 자세로 시작한다.,Step:2 한쪽 팔을 옆으로 곧게 뻗어 바닥과 평행하게 든다.,Step:3 팔꿈치를 굽혀 몸을 내리되 등을 곧게 하고 코어에 힘을 준다.,Step:4 가슴 근육으로 몸을 밀어 올려 시작 자세로 돌아온다.,Step:5 반대쪽 팔을 뻗어 동일하게 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MCkqdKE', '기계체조(바 위에서)', 'https://static.exercisedb.dev/media/MCkqdKE.gif', '광배근', '등', '가중', '이두근,삼두근,어깨,전완근', 'Step:1 풀업 바에 매달려 손바닥이 바깥을 향하게 하고 손은 어깨너비보다 약간 넓게 잡는다.,Step:2 코어에 힘을 주고 견갑골을 아래/뒤로 당긴다.,Step:3 팔꿈치를 굽혀 가슴을 바 쪽으로 당기며 몸을 곧게 유지한다.,Step:4 가슴이 바에 닿으면 손으로 바를 아래로 누르고 팔꿈치를 뒤로 보내 몸을 바 위로 끌어올린다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yJUHKTn', '기계체조', 'https://static.exercisedb.dev/media/yJUHKTn.gif', '광배근', '등', '맨몸', '이두근,삼두근,어깨,가슴', 'Step:1 풀업 바에 매달려 손바닥이 바깥을 향하게 하고 팔을 완전히 편다.,Step:2 코어에 힘을 주고 몸을 바 쪽으로 끌어올리되 가슴이 먼저 올라가게 한다.,Step:3 동작 상단에 가까워지면 그립을 전환해 손바닥이 몸 쪽을 향하게 한다.,Step:4 가슴이 바 위로 올라오고 팔이 굽혀진 상태까지 계속 끌어올린다.,Step:5 천천히 역순으로 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fhZQPlV', '케이블 트위스트(위-아래)', 'https://static.exercisedb.dev/media/fhZQPlV.gif', '복근', '허리', '케이블', '복사근,허리', 'Step:1 발을 어깨너비로 두고 케이블 머신을 마주 보고 선다.,Step:2 케이블 손잡이를 양손으로 잡아 가슴 앞에 두고 팔은 살짝 굽힌다.,Step:3 코어에 힘을 주고 엉덩이와 다리는 고정한 채 몸통을 한쪽으로 천천히 회전한다.,Step:4 회전 끝 지점에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 반대쪽으로도 동일하게 회전한다.,Step:6 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Zg3XY7P', '레버 시트 레그 컬', 'https://static.exercisedb.dev/media/Zg3XY7P.gif', '햄스트링', '허벅지', '레버리지 머신', '종아리근', 'Step:1 머신을 몸에 맞게 조절하고 앉아 등을 등받이에 붙인다.,Step:2 종아리를 패드 레버 아래(발목 위쪽)에 위치시킨다.,Step:3 손잡이를 잡아 몸을 고정한다.,Step:4 허벅지는 고정한 채 숨을 내쉬며 다리를 가능한 만큼 컬한다.,Step:5 수축 지점에서 잠시 멈추며 햄스트링을 조인다.,Step:6 숨을 들이마시며 천천히 시작 자세로 되돌린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NCmbLCw', '푸시업(벽) v. 2', 'https://static.exercisedb.dev/media/NCmbLCw.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 벽을 마주 보고 팔 길이 정도 떨어져 선다.,Step:2 손을 어깨 높이로 벽에 대고 어깨너비보다 약간 넓게 둔다.,Step:3 발을 뒤로 빼 골반 너비로 두고 자세를 만든다.,Step:4 코어에 힘을 주고 머리부터 발끝까지 일직선을 유지한다.,Step:5 팔꿈치를 굽혀 가슴을 벽 쪽으로 내리되 몸의 정렬을 유지한다.,Step:6 잠시 멈춘 뒤 벽을 밀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('E4R8Hz1', '밴드 엉덩이 리프트', 'https://static.exercisedb.dev/media/E4R8Hz1.gif', '둔근', '허벅지', '밴드', '햄스트링,대퇴사두근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 저항 밴드를 무릎 바로 위에 건다.,Step:3 둔근과 코어에 힘을 준다.,Step:4 뒤꿈치로 바닥을 밀어 엉덩이를 들어 올리며 상단에서 둔근을 조인다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 엉덩이를 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WW95auq', '케이블 무릎을 꿇고 크런치', 'https://static.exercisedb.dev/media/WW95auq.gif', '복근', '허리', '케이블', '복사근', 'Step:1 로프 손잡이를 하이 풀리에 연결하고 머신을 등지고 무릎을 꿇는다.,Step:2 로프를 양손으로 잡고 머리 뒤에 두되 팔꿈치는 옆으로 벌린다.,Step:3 엉덩이는 고정한 채 허리를 굽혀 상체를 허벅지 쪽으로 크런치한다.,Step:4 하단에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mKwcrHn', '레버 그립 핸즈', 'https://static.exercisedb.dev/media/mKwcrHn.gif', '전완근', '팔 아래', '레버리지 머신', '이두근,삼두근', 'Step:1 좌석 높이를 조절하고 레버리지 머신 손잡이를 잡는다.,Step:2 등을 곧게 하고 발을 바닥에 둔다.,Step:3 숨을 내쉬며 손잡이를 쥐어 전완을 수축한다.,Step:4 1초간 수축을 유지한 뒤 천천히 풀어 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vqsbmL0', '레버 숄더 프레스 v. 2', 'https://static.exercisedb.dev/media/vqsbmL0.gif', '삼각근', '어깨', '레버리지 머신', '삼두근,가슴', 'Step:1 좌석 높이와 등받이를 편한 위치로 조절한다.,Step:2 등에 등받이를 붙이고 앉아 발은 바닥에 둔다.,Step:3 손잡이를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 손잡이를 위/앞으로 밀어 팔을 펴되 완전 잠금은 피한다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 손잡이를 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZOuKWir', '무릎꿇고 푸쉬업(남자)', 'https://static.exercisedb.dev/media/ZOuKWir.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 바닥에 무릎을 꿇고 손을 어깨너비로 둔다(손가락은 정면).,Step:2 다리를 뒤로 뻗어 발볼로 지지해 머리부터 발끝까지 일직선을 만든다.,Step:3 코어에 힘을 주고 팔꿈치를 굽혀 몸을 내리되 팔꿈치는 몸에 가깝게 둔다.,Step:4 가슴이 바닥 바로 위에 오면 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wkgnGfb', '짐 볼에 덤벨 인클라인 해머 프레스', 'https://static.exercisedb.dev/media/wkgnGfb.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 짐 볼에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주 보게 한다.,Step:2 발을 앞으로 걸으며 몸을 굴려 머리/목/상부 등이 볼에 지지되게 한다.,Step:3 덤벨을 어깨 높이에 두고 팔꿈치를 굽혀 옆으로 벌린다.,Step:4 손바닥이 서로 마주 보게 유지하며 덤벨을 위로, 약간 안쪽으로 밀어 올린다.,Step:5 팔을 완전히 펴며 상단에서 삼두근을 조인다.,Step:6 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HbSG1Pw', '아이소메트릭 가슴 압박', 'https://static.exercisedb.dev/media/HbSG1Pw.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 발을 어깨너비로 두고 서서 무릎을 살짝 굽힌다.,Step:2 팔을 정면으로 뻗어 바닥과 평행하게 하고 손바닥이 서로 마주 보게 한다.,Step:3 팔을 곧게 유지한 채 가슴을 최대한 강하게 수축해 모아준다.,Step:4 몇 초간 유지하며 가슴 수축을 느낀다.,Step:5 힘을 풀고 가슴을 이완한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DU7I633', '바벨 리버스 그립 인클라인 벤치 프레스', 'https://static.exercisedb.dev/media/DU7I633.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 인클라인 벤치를 45도로 맞춘다.,Step:2 벤치에 누워 발을 바닥에 둔다.,Step:3 리버스 그립(손바닥이 얼굴 쪽)을 사용해 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:4 바벨을 언랙하고 천천히 가슴 쪽으로 내리되 팔꿈치를 몸에 가깝게 둔다.,Step:5 바벨이 가슴에 닿으면 잠시 멈춘다.,Step:6 바벨을 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EAs3xL9', '덤벨 리버스 플라이', 'https://static.exercisedb.dev/media/EAs3xL9.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 두고 서서 덤벨을 양손에 든다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 하고 가슴을 편다.,Step:3 팔을 정면 아래로 늘어뜨리고 손바닥이 서로 마주 보게 한다.,Step:4 팔꿈치를 살짝 굽힌 채 팔을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('x69MAlq', '케이블 스트레이트 암 풀다운', 'https://static.exercisedb.dev/media/x69MAlq.gif', '광배근', '등', '케이블', '어깨,이두근', 'Step:1 하이 풀리에 스트레이트 바를 연결한다.,Step:2 머신을 마주 보고 발을 어깨너비로 선다.,Step:3 오버핸드 그립으로 바를 잡고 팔을 곧게 편 채 손바닥이 아래를 향하게 한다.,Step:4 광배근에 힘을 주고 팔을 곧게 유지한 채 바를 허벅지 쪽으로 당겨 내린다.,Step:5 하단에서 잠시 멈춘 뒤 천천히 바를 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cuKYxhu', '서있는 골반 기울기', 'https://static.exercisedb.dev/media/cuKYxhu.gif', '척추', '등', '맨몸', '복부', 'Step:1 발을 어깨너비로 두고 서서 무릎을 살짝 굽힌다.,Step:2 손을 허리에 두거나 몸 옆에 자연스럽게 둔다.,Step:3 코어에 힘을 주고 골반을 앞으로 기울여 허리가 뒤쪽으로 밀리듯 만들었다가 정렬한다.,Step:4 몇 초간 유지한 뒤 힘을 풀고 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8ozhUIZ', '바벨 스탠딩 카프 레이즈', 'https://static.exercisedb.dev/media/8ozhUIZ.gif', '종아리근', '종아리', '바벨', '햄스트링,둔근', 'Step:1 발을 어깨너비로 두고 서서 바벨을 상부 등에 올린다.,Step:2 발끝으로만 지면을 밀어 뒤꿈치를 최대한 들어 올린다.,Step:3 상단에서 잠시 멈춘 뒤 천천히 뒤꿈치를 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Eg98Ft9', '케이블 슈러그', 'https://static.exercisedb.dev/media/Eg98Ft9.gif', '승모근', '등', '케이블', '어깨', 'Step:1 케이블 머신을 마주 보고 발을 어깨너비로 선다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔을 아래로 늘어뜨린다.,Step:3 팔을 곧게 유지한 채 어깨를 귀 쪽으로 들어 올려 슈러그한다.,Step:4 수축을 잠시 유지한 뒤 천천히 어깨를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2IHEa2T', '바벨 플로어 카프 레이즈', 'https://static.exercisedb.dev/media/2IHEa2T.gif', '종아리근', '종아리', '바벨', '햄스트링', 'Step:1 바벨을 바닥에 앞쪽으로 둔다.,Step:2 발볼을 바벨 가장자리에 두고 뒤꿈치는 아래로 떨어지게 선다.,Step:3 필요하면 균형을 위해 안정된 물체를 잡는다.,Step:4 종아리 힘으로 뒤꿈치를 최대한 들어 올린다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 뒤꿈치를 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BWnJR72', '대퇴사두근 스트레칭', 'https://static.exercisedb.dev/media/BWnJR72.gif', '대퇴사두근', '허벅지', '맨몸', '햄스트링', 'Step:1 다리를 곧게 편 상태로 옆으로 눕는다.,Step:2 위쪽 다리를 굽히고 손으로 발목이나 발을 잡는다.,Step:3 발목이나 발을 엉덩이 쪽으로 천천히 당겨 대퇴근이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 스트레치를 풀고 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hC6oYY5', '옆으로 누워서 내전근 스트레칭', 'https://static.exercisedb.dev/media/hC6oYY5.gif', '내전근', '허벅지', '도움을 준', '햄스트링,둔근', 'Step:1 다리를 곧게 펴고 포개진 상태로 옆으로 눕는다.,Step:2 아래쪽 다리는 안정성을 위해 살짝 굽힌다.,Step:3 위쪽 발을 벤치나 스텝처럼 안정된 지지면에 올린다.,Step:4 위쪽 다리를 곧게 유지한 채 천천히 바닥 쪽으로 내리며 안쪽 허벅지가 늘어나는 것을 느낀다.,Step:5 20–30초 동안 유지한다.,Step:6 시작 자세로 돌아가 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jl6uxZV', '밴드 두 다리 종아리 올리기 - (양 다리 아래 밴드) v. 2', 'https://static.exercisedb.dev/media/jl6uxZV.gif', '종아리근', '종아리', '밴드', '발목,피트', 'Step:1 발을 어깨너비로 두고 서서 저항 밴드를 양발 아래에 둔다.,Step:2 밴드 끝을 손으로 잡아 안정적으로 지지한다.,Step:3 종아리 힘으로 뒤꿈치를 최대한 들어 올린다.,Step:4 상단에서 잠시 멈춘 뒤 천천히 뒤꿈치를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CcWEoWV', '짧은 보폭 달리기', 'https://static.exercisedb.dev/media/CcWEoWV.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 넓은 공간이나 트레드밀을 준비한다.,Step:2 발을 골반 너비로 두고 곧게 선다.,Step:3 제자리 조깅을 시작하며 무릎을 높게 들고 팔을 빠르게 흔든다.,Step:4 몇 초 후 짧은 보폭으로 앞으로 이동하며 빠른 페이스를 유지한다.,Step:5 원하는 시간/거리만큼 짧은 보폭 달리기를 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ca76jUE', '케틀벨 교대 행', 'https://static.exercisedb.dev/media/Ca76jUE.gif', '등 위쪽', '등', '케틀벨', '이두근,전완근', 'Step:1 발을 어깨너비로 두고 무릎을 살짝 굽힌 채 양손에 케틀벨을 들고 손바닥은 몸을 향하게 한다.,Step:2 힙 힌지로 상체를 숙이되 등을 곧게 하고 코어에 힘을 준다.,Step:3 한쪽 케틀벨을 가슴 쪽으로 당기며 팔꿈치를 몸에 가깝게 두고 견갑골을 모은다.,Step:4 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 반대쪽도 동일하게 수행하며 교대로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uOV3Itw', '삼두근 스트레칭', 'https://static.exercisedb.dev/media/uOV3Itw.gif', '삼두근', '상완이두근', '맨몸', '어깨', 'Step:1 등을 곧게 편 상태로 서거나 앉는다.,Step:2 한쪽 팔을 머리 위로 들어 올린 뒤 팔꿈치를 굽힌다.,Step:3 반대쪽 손으로 굽힌 팔꿈치를 잡고 머리 쪽으로 부드럽게 당긴다.,Step:4 삼두근이 늘어나는 것을 느끼며 15–30초 동안 유지한다.,Step:5 풀어준 뒤 반대쪽 팔도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DptumMx', '밴드 클로즈 그립 풀다운', 'https://static.exercisedb.dev/media/DptumMx.gif', '광배근', '등', '밴드', '이두근,전완근', 'Step:1 밴드를 풀업 바나 튼튼한 보에 고정해 높은 지점에 걸어 둔다.,Step:2 고정 지점을 마주 보고 서서 밴드를 언더핸드 그립으로 어깨너비로 잡는다.,Step:3 뒤로 물러나 밴드에 장력을 만든다(발은 골반 너비).,Step:4 코어에 힘을 주고 등을 곧게 유지하며 밴드를 가슴 쪽으로 당겨 견갑골을 모은다.,Step:5 하단에서 잠시 멈춘 뒤 천천히 밴드를 풀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5BZHW9s', '트위스트를 사용하여 머리 위로 손을 뻗을 수 있도록 스쿼트', 'https://static.exercisedb.dev/media/5BZHW9s.gif', '대퇴사두근', '허벅지', '맨몸', '둔근,햄스트링,코어', 'Step:1 발을 어깨너비로 두고 발끝을 약간 바깥으로 돌린다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트로 내려간다.,Step:3 스쿼트에서 올라오며 팔을 머리 위로 올리고 몸통을 한쪽으로 회전한다.,Step:4 시작 자세로 돌아온다.,Step:5 다음 스쿼트에서는 반대쪽으로 몸통을 회전하며 팔을 머리 위로 뻗는다.,Step:6 스쿼트마다 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cbuFJrn', '레버 그립리스 슈러그 v. 2', 'https://static.exercisedb.dev/media/cbuFJrn.gif', '승모근', '등', '레버리지 머신', '어깨,전완근', 'Step:1 좌석 높이와 자세를 조절해 등에 패드를 붙이고 앉는다.,Step:2 손잡이나 바를 오버핸드로 잡고 팔을 곧게 둔다.,Step:3 등을 곧게 유지한 채 어깨를 귀 쪽으로 최대한 들어 올린다.,Step:4 수축을 잠시 유지한 뒤 천천히 어깨를 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ktf3nvW', '케틀벨 플라이오 푸쉬업', 'https://static.exercisedb.dev/media/ktf3nvW.gif', '가슴근육', '가슴', '케틀벨', '삼두근,어깨,코어', 'Step:1 케틀벨 위에 손을 올려 하이 플랭크 자세를 만든다(손은 어깨너비).,Step:2 팔꿈치를 굽혀 가슴을 내리되 팔꿈치는 몸에 가깝게 둔다.,Step:3 폭발적으로 밀어 올려 손이 케틀벨에서 떨어지도록 한다.,Step:4 부드럽게 케틀벨 위에 다시 착지하고 즉시 다음 반복을 위해 다시 내려간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QT5Q0nK', '덤벨 시티드 얼터너티브 프레스', 'https://static.exercisedb.dev/media/QT5Q0nK.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 벤치에 앉아 양손에 덤벨을 들고 손바닥이 앞을 향하게 한다.,Step:2 덤벨을 어깨 높이로 들어 올려 팔꿈치를 굽히고 손바닥은 정면을 향하게 한다.,Step:3 한쪽 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 덤벨을 다시 어깨 높이로 내린다.,Step:5 반대쪽 덤벨로 같은 동작을 한다.,Step:6 원하는 반복 횟수만큼 교대로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('L2V5Nan', '덤벨 라이딩 익스텐션(얼굴 건너기)', 'https://static.exercisedb.dev/media/L2V5Nan.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 누워 발을 바닥에 두고 머리는 벤치 끝 쪽에 둔다.,Step:2 양손으로 덤벨을 잡고 가슴 위로 팔을 곧게 편다(손바닥 서로 마주).,Step:3 상완을 고정한 채 팔꿈치를 굽혀 덤벨을 호를 그리며 머리 뒤로 천천히 내린다.,Step:4 하단에서 잠시 멈춘 뒤 삼두근을 수축해 덤벨을 다시 시작 위치로 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wWFspEi', '스미스 싱글 레그 스플릿 스쿼트', 'https://static.exercisedb.dev/media/wWFspEi.gif', '대퇴사두근', '허벅지', '스미스 머신', '둔근,햄스트링', 'Step:1 스미스 머신 앞에 발을 어깨너비로 두고 선다.,Step:2 한쪽 발을 벤치나 스텝 위에 뒤로 올려 발끝이 정면을 향하게 한다.,Step:3 균형을 위해 스미스 머신 바를 잡는다.,Step:4 앞쪽 무릎을 굽혀 런지로 내려가되 등을 곧게 유지한다.,Step:5 하단에서 잠시 멈춘 뒤 앞발 뒤꿈치로 밀어 올라온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UgDm3oy', '무릎꿇고 점프스쿼트', 'https://static.exercisedb.dev/media/UgDm3oy.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 바닥에 무릎을 꿇고 발은 골반 너비로 두며 발끝은 정면을 향하게 한다.,Step:2 바벨을 상부 등에 올려 어깨에 얹는다.,Step:3 코어와 둔근에 힘을 준다.,Step:4 엉덩이와 무릎을 폭발적으로 펴며 점프한다.,Step:5 점프 중 발목/무릎/엉덩이를 완전히 펴며 발끝으로 밀어 올린다.,Step:6 무릎을 굽혀 충격을 흡수하며 부드럽게 착지한다.,Step:7 바로 다음 반복으로 이어가며 점프 스쿼트를 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7xeukSt', '견갑골 딥스', 'https://static.exercisedb.dev/media/7xeukSt.gif', '승모근', '등', '맨몸', '능형근,삼각근', 'Step:1 발을 어깨너비로 두고 서서 팔을 정면으로 뻗는다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 한다.,Step:3 팔꿈치를 굽히며 견갑골을 뒤로 모아 마치 견갑골 사이에 연필을 끼우듯 수축한다.,Step:4 하단에서 잠시 멈춘 뒤 팔꿈치를 펴며 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mTT3KLn', '케이블 프론트 숄더 레이즈', 'https://static.exercisedb.dev/media/mTT3KLn.gif', '삼각근', '어깨', '케이블', '승모근,이두근', 'Step:1 발을 어깨너비로 두고 서서 케이블 손잡이를 오버핸드 그립으로 잡는다.,Step:2 등을 곧게 하고 코어에 힘을 준다.,Step:3 팔을 곧게 유지한 채 손바닥이 아래를 향하도록 손잡이를 정면으로 들어 올린다.,Step:4 팔이 바닥과 평행해질 때까지 들어 올린다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 손잡이를 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AxFoqAD', '한쪽 다리 종아리 들어올리기', 'https://static.exercisedb.dev/media/AxFoqAD.gif', '종아리근', '종아리', '슬레이 기계', '햄스트링,둔근', 'Step:1 슬레이 머신 중량을 적절히 설정한다.,Step:2 한쪽 발로 발판에 서고 다른 발은 공중에 둔다.,Step:3 손잡이를 잡아 균형을 잡는다.,Step:4 발볼로 밀어 뒤꿈치를 최대한 들어 올린다.,Step:5 상단에서 잠시 멈춘 뒤 천천히 뒤꿈치를 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.,Step:7 다리를 바꿔 같은 동작을 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LCtQPn8', '덤벨 인클라인 인클라인 이두근 컬', 'https://static.exercisedb.dev/media/LCtQPn8.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 인클라인 벤치에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주 보게 한다.,Step:2 상완을 벤치에 대고 팔꿈치가 아래로 떨어지게 하여 손바닥이 앞을 보게 한다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 컬해 이두근을 수축한다.,Step:4 덤벨이 어깨 높이에 오고 이두근이 완전히 수축될 때까지 들어 올린다.,Step:5 상단에서 잠시 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VdLZ3nB', '덤벨 원암 리버스 스파이더 컬', 'https://static.exercisedb.dev/media/VdLZ3nB.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 곧게 서서 한 손에 덤벨을 들고 손바닥이 아래를 향하게 하며 팔을 완전히 편다.,Step:2 상완을 고정한 채 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 컬한다.,Step:3 상단에서 잠시 멈춘 뒤 천천히 덤벨을 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yzYH9pI', '바벨 손바닥을 아래로 벤치 위에 손목 컬', 'https://static.exercisedb.dev/media/yzYH9pI.gif', '전완근', '팔 아래', '바벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 평평하게 두고, 전완을 허벅지 위에 올린 채 손바닥이 아래를 보게 한다.,Step:2 바벨을 오버핸드 그립으로 어깨너비로 잡는다.,Step:3 전완은 고정하고 손목만 굽혀 바벨을 바닥 쪽으로 천천히 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 손목을 펴며 바벨을 천천히 들어 올린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xbkPfaw', '원 암로 서서 체중', 'https://static.exercisedb.dev/media/xbkPfaw.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 발을 어깨너비로 서고 무릎을 약간 굽힌 뒤 한 손에 덤벨을 든다.,Step:2 엉덩이에서 힙힌지를 하며 상체를 숙이되 등을 곧게 펴고 코어를 고정한다.,Step:3 팔을 완전히 편 채 덤벨이 몸 앞에서 수직으로 늘어지게 둔다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 덤벨을 가슴 쪽으로 끌어올린다.,Step:5 정점에서 견갑골을 모아 등을 수축한다.,Step:6 덤벨을 시작 자세로 천천히 내린다.,Step:7 원하는 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bKWbrTA', '한쪽 팔 수건 줄', 'https://static.exercisedb.dev/media/bKWbrTA.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 발을 어깨너비로 서고 무릎을 약간 굽힌 뒤 한 손으로 수건을 잡는다.,Step:2 허리에서 상체를 숙이되 등을 곧게 펴고 코어를 고정한다.,Step:3 팔을 완전히 펴 수건이 몸 앞에서 늘어지게 둔다.,Step:4 견갑골을 조이며 수건을 가슴 쪽으로 당긴다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5MRH8H2', '스키 스텝', 'https://static.exercisedb.dev/media/5MRH8H2.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 발을 어깨너비로 서서 준비한다.,Step:2 무릎을 살짝 굽히고 등을 곧게 유지한다.,Step:3 오른쪽으로 점프해 오른발로 착지하면서 왼발을 오른발 뒤로 스윙한다.,Step:4 즉시 왼쪽으로 점프해 왼발로 착지하면서 오른발을 왼발 뒤로 스윙한다.,Step:5 스키 타듯 좌우로 번갈아 점프를 이어간다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xGgAGPm', '체스트 레그 익스텐션 스트레칭', 'https://static.exercisedb.dev/media/xGgAGPm.gif', '대퇴사두근', '허벅지', '맨몸', '햄스트링,종아리근', 'Step:1 등을 곧게 펴고 의자 끝에 앉으며 양발을 바닥에 둔다.,Step:2 한쪽 다리를 앞으로 곧게 뻗어 뒤꿈치를 바닥에 둔다.,Step:3 상체를 조금 앞으로 기울여 대퇴근이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MUic5zN', '원암 푸쉬업', 'https://static.exercisedb.dev/media/MUic5zN.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 푸쉬업 자세에서 손을 어깨너비로 두고 한 손은 다른 손보다 약간 더 넓게 둔다.,Step:2 코어를 조여 몸통을 일직선으로 유지한 채 팔꿈치를 굽혀 몸을 내린다.,Step:3 내려가면서 체중을 한쪽으로 실어 반대쪽 팔을 바닥에서 떼고 옆으로 곧게 뻗는다.,Step:4 가슴과 삼두로 밀어올려 시작 자세로 돌아오면서, 뻗었던 팔을 다시 바닥에 둔다.,Step:5 반복하며 매 반복마다 뻗는 팔을 번갈아 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hl8DUh8', '바벨 디클라인 와이드 그립 프레스', 'https://static.exercisedb.dev/media/hl8DUh8.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 발을 고정하고 머리가 엉덩이보다 낮게 위치하게 한다.,Step:2 어깨너비보다 약간 넓게 바벨을 와이드 그립으로 잡는다.,Step:3 팔꿈치를 옆으로 벌린 채 바벨을 가슴 쪽으로 내린다.,Step:4 팔을 완전히 펴며 바벨을 시작 자세로 밀어 올린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UNAB8ak', '원 암 밴드 머리 위로 바이셉스 컬', 'https://static.exercisedb.dev/media/UNAB8ak.gif', '이두근', '상완이두근', '밴드', '전완근,어깨', 'Step:1 발을 어깨너비로 서고 밴드 한쪽 끝을 발 아래에 고정한다.,Step:2 다른 끝을 잡고 팔을 머리 위로 완전히 펴 손바닥이 앞을 보게 한다.,Step:3 상완은 고정한 채 전완을 어깨 쪽으로 말아 올리며 이두를 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤 전완을 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wDUqY2u', '케이블 오버헤드 컬', 'https://static.exercisedb.dev/media/wDUqY2u.gif', '이두근', '상완이두근', '케이블', '전완근,어깨', 'Step:1 케이블 머신 상단 풀리에 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 선다.,Step:3 바를 언더핸드 그립으로 어깨너비로 잡는다.,Step:4 팔꿈치를 몸통 옆에 붙이고 상완을 고정한다.,Step:5 내쉬며 바를 이마 쪽으로 말아 내려 이두를 수축한다.,Step:6 아래 지점에서 잠깐 멈추며 이두를 조인다.,Step:7 들이쉬며 팔을 펴 바를 천천히 시작 자세로 올린다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QTXKWPh', '케이블 풀다운 바이셉 컬', 'https://static.exercisedb.dev/media/QTXKWPh.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 최고 높이로 설정하고 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 선다.,Step:3 바를 언더핸드 그립으로 어깨너비로 잡는다.,Step:4 팔꿈치를 몸통 옆에 붙이고 상완을 고정한다.,Step:5 내쉬며 바를 허벅지 쪽으로 천천히 말아 내리되 손목을 곧게 유지한다.,Step:6 아래 지점에서 잠깐 멈추며 이두를 조인다.,Step:7 들이쉬며 팔을 펴 바를 천천히 시작 자세로 올린다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wPypxFY', '케이블 사이드 굴곡', 'https://static.exercisedb.dev/media/wPypxFY.gif', '복근', '허리', '케이블', '복사근', 'Step:1 발을 어깨너비로 서고 한 손으로 케이블 손잡이를 잡는다.,Step:2 등을 곧게 펴고 코어를 조인다.,Step:3 허리에서 옆으로 천천히 굽혀 손잡이를 무릎 쪽으로 내린다.,Step:4 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:5 반대쪽도 동일하게 수행한다.,Step:6 원하는 횟수만큼 좌우 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kj3hy6W', '레버 리버스 그립 프리처 컬', 'https://static.exercisedb.dev/media/kj3hy6W.gif', '이두근', '상완이두근', '레버리지 머신', '전완근', 'Step:1 레버리지 머신의 시트 높이를 조절해 자세를 맞춘다.,Step:2 손바닥이 위를 보게 언더핸드 그립으로 손잡이를 잡는다.,Step:3 상완을 프리처 패드에 올리고 팔꿈치를 완전히 편 상태로 시작한다.,Step:4 상완을 고정한 채 내쉬며 손잡이를 어깨 쪽으로 말아 올린다.,Step:5 정점에서 잠깐 멈추며 이두를 수축한다.,Step:6 들이쉬며 팔꿈치를 펴 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UDm6cGl', '케틀벨 시소 프레스', 'https://static.exercisedb.dev/media/UDm6cGl.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 서고 양손에 케틀벨을 들어 어깨 높이에 둔다.,Step:2 한쪽 케틀벨을 머리 위로 밀어 올리는 동안 반대쪽은 어깨 높이에 유지한다.,Step:3 올렸던 케틀벨을 어깨 높이로 내리며 동시에 반대쪽 케틀벨을 머리 위로 밀어 올린다.,Step:4 시소처럼 번갈아 프레스를 이어간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vtusOWT', '바벨 원암 플로어 프레스', 'https://static.exercisedb.dev/media/vtusOWT.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 바닥에 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 한 손으로 바벨을 잡고 손바닥이 위를 보게 한 뒤, 팔을 가슴 위로 곧게 뻗는다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 바벨을 가슴 쪽으로 천천히 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 바벨을 시작 자세로 밀어 올린다.,Step:5 원하는 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ffQsyBj', '덤벨 원 암 스탠딩 컬', 'https://static.exercisedb.dev/media/ffQsyBj.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 한 손에 덤벨을 들고 곧게 서서 손바닥이 앞을 보게 하며 팔을 완전히 편다.,Step:2 상완은 고정한 채 내쉬며 덤벨을 위로 말아 올려 이두를 수축한다.,Step:3 이두가 완전히 수축되고 덤벨이 어깨 높이에 오도록 올린다.,Step:4 정점에서 잠깐 멈추며 이두를 조인다.,Step:5 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XeMvLgE', '롤러 바디 톱', 'https://static.exercisedb.dev/media/XeMvLgE.gif', '복근', '허리', '롤러', '어깨,삼두근,코어', 'Step:1 플랭크 자세에서 전완을 롤러 위에 올리고 몸을 일직선으로 만든다.,Step:2 코어를 조이고 롤러를 천천히 앞으로 굴려 가능한 만큼 몸을 뻗되 컨트롤을 유지한다.,Step:3 가장 멀리 뻗은 지점에서 잠깐 멈춘다.,Step:4 롤러를 천천히 다시 당겨 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZXnjcOQ', '케이블 원 암 리버스 프리처 컬', 'https://static.exercisedb.dev/media/ZXnjcOQ.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 풀리를 최저 위치로 조절한다.,Step:2 머신을 마주보고 발을 어깨너비로 선다.,Step:3 언더핸드 그립으로 손잡이를 잡고 상완을 프리처 패드에 밀착한다.,Step:4 등을 곧게 펴고 코어를 조여 자세를 유지한다.,Step:5 상완을 고정한 채 전완을 이두 쪽으로 천천히 말아 올린다.,Step:6 정점에서 잠깐 멈추며 이두를 수축한다.,Step:7 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 횟수만큼 반복한다.,Step:9 팔을 바꿔 동일하게 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mbkgB44', '잭나이프 윗몸 일으키기', 'https://static.exercisedb.dev/media/mbkgB44.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 다리를 뻗고 팔을 머리 위로 뻗는다.,Step:2 코어를 조이고 다리와 상체를 동시에 들어 올려 손이 발끝을 향하게 한다.,Step:3 정점에서 잠깐 멈춘 뒤 다리와 상체를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yn2lLSI', '슬레이 45в° 레그 프레스(뒤 POV)', 'https://static.exercisedb.dev/media/yn2lLSI.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신 좌석을 조절해 무릎이 45도 각도가 되게 한다.,Step:2 등받이에 등을 대고 앉아 발을 어깨너비로 풋플레이트에 둔다.,Step:3 좌석 양옆 손잡이를 잡아 안정적으로 고정한다.,Step:4 뒤꿈치를 유지한 채 다리를 펴 풋플레이트를 밀어낸다.,Step:5 완전히 편 지점에서 잠깐 멈춘다.,Step:6 무릎을 굽혀 풋플레이트를 천천히 되돌리며 동작을 컨트롤한다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1gFNTZV', '바벨 점프 스쿼트', 'https://static.exercisedb.dev/media/1gFNTZV.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 바벨을 상부 등에 올린다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트 자세로 내려간다.,Step:3 스쿼트 바닥 지점에서 폭발적으로 올라오며 점프한다.,Step:4 점프하면서 고관절, 무릎, 발목을 펴고 발끝으로 지면을 밀어낸다.,Step:5 부드럽게 착지해 다시 스쿼트로 들어가며 바로 다음 반복을 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bZq4bwK', '중량 삼두근 딥스', 'https://static.exercisedb.dev/media/bZq4bwK.gif', '삼두근', '상완이두근', '가중', '가슴,어깨', 'Step:1 벤치나 의자 가장자리에 앉아 손을 엉덩이 옆 가장자리에 짚는다.,Step:2 엉덩이를 앞으로 빼고 다리를 앞으로 뻗는다.,Step:3 등을 벤치에 가깝게 유지하고 팔꿈치를 약간 굽힌다.,Step:4 팔꿈치를 굽혀 상완이 바닥과 평행해질 때까지 몸을 내린다.,Step:5 팔을 펴며 시작 자세로 밀어 올린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VjYliFZ', '케이블 리버스 그립 푸시다운', 'https://static.exercisedb.dev/media/VjYliFZ.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신 상단 풀리에 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 선다.,Step:3 손바닥이 위를 보게 언더핸드 그립으로 바를 어깨너비로 잡는다.,Step:4 팔꿈치를 몸통 옆에 붙이고 상완을 고정한다.,Step:5 삼두로 바를 아래로 밀어 팔이 완전히 펴질 때까지 내려간다.,Step:6 잠깐 멈춘 뒤 바를 천천히 시작 자세로 올린다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XFc3vpY', '저항 밴드 장착 바이셉스 컬', 'https://static.exercisedb.dev/media/XFc3vpY.gif', '이두근', '상완이두근', '저항 밴드', '전완근', 'Step:1 의자나 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 밴드를 언더핸드 그립으로 잡고 팔을 옆으로 내린 채 완전히 편다.,Step:3 상완을 고정한 채 내쉬며 밴드를 어깨 쪽으로 말아 올려 이두를 수축한다.,Step:4 정점에서 잠깐 멈추며 이두를 조인다.,Step:5 들이쉬며 밴드를 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xnInPfE', '바벨 스탠딩 AB 롤러아웃', 'https://static.exercisedb.dev/media/xnInPfE.gif', '복근', '허리', '바벨', '어깨,허리', 'Step:1 발을 어깨너비로 서서 허벅지 앞에서 양손으로 바벨을 잡는다.,Step:2 코어를 조이고 팔을 뻗은 채 바벨을 바닥 쪽으로 천천히 굴린다.,Step:3 몸이 완전히 뻗고 손이 머리 위쪽까지 가도록 계속 굴린다.,Step:4 잠깐 멈춘 뒤 바벨을 다시 굴려 허벅지 쪽으로 천천히 되돌린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SpYC0Kp', '덤벨 벤치 프레스', 'https://static.exercisedb.dev/media/SpYC0Kp.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 벤치에 누워 발을 바닥에 평평하게 두고 등을 벤치에 밀착한다.,Step:2 양손에 덤벨을 들고 손바닥이 앞을 보게 하여 가슴 위로 팔을 뻗는다.,Step:3 팔꿈치를 90도로 유지하며 덤벨을 가슴 옆으로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 덤벨을 다시 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('K3dIO25', '덤벨 누워서 원 암 프레스 v. 2', 'https://static.exercisedb.dev/media/K3dIO25.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 벤치에 등을 대고 누워 발을 바닥에 둔다.,Step:2 한 손에 덤벨을 들고 손바닥이 발 쪽을 보게 한다.,Step:3 팔꿈치를 약간 굽힌 채 천장 쪽으로 팔을 곧게 뻗는다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 덤벨을 가슴 쪽으로 천천히 내린다.,Step:5 아래 지점에서 잠깐 멈춘 뒤 덤벨을 시작 자세로 밀어 올린다.,Step:6 원하는 횟수만큼 반복한 뒤 반대팔로 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XUUD0Fs', '덤벨 누워 후면 삼각근 행', 'https://static.exercisedb.dev/media/XUUD0Fs.gif', '등 위쪽', '등', '덤벨', '어깨,이두근', 'Step:1 평벤치에 엎드려 누워 양손에 덤벨을 들고 손바닥이 안쪽을 보게 한다.,Step:2 팔을 바닥 쪽으로 늘어뜨리되 팔꿈치를 약간 굽힌다.,Step:3 등을 사용해 덤벨을 가슴 쪽으로 끌어올리며 견갑골을 모은다.,Step:4 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 다시 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KHGNa16', '케이블 디클라인 원 암 프레스', 'https://static.exercisedb.dev/media/KHGNa16.gif', '가슴근육', '가슴', '케이블', '삼두근,어깨', 'Step:1 케이블 머신을 디클라인 방향으로 세팅한다.,Step:2 머신을 등지고 한 손으로 손잡이를 잡는다.,Step:3 디클라인 벤치에 등을 기대고 팔을 정면으로 뻗어 시작한다.,Step:4 상완을 고정한 채 팔꿈치를 굽혀 손잡이를 가슴 쪽으로 내린다.,Step:5 아래 지점에서 잠깐 멈춘 뒤 손잡이를 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Fhdtwf3', '한쪽 팔을 줄 위로 구부린 레버', 'https://static.exercisedb.dev/media/Fhdtwf3.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 서고 무릎을 약간 굽힌 뒤 바벨을 오버핸드 그립으로 잡는다.,Step:2 엉덩이에서 힙힌지를 하며 상체를 숙이되 등을 곧게 펴고 시선을 정면에 둔다.,Step:3 팔을 완전히 펴 바벨이 몸 앞에서 늘어지게 둔다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 바벨을 가슴 쪽으로 끌어올린다.,Step:5 정점에서 견갑골을 모아 등을 수축한다.,Step:6 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xiA6lRr', '덤벨 시티드 바이셉 컬', 'https://static.exercisedb.dev/media/xiA6lRr.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 양손에 덤벨을 들어 손바닥이 위를 보게 한다.,Step:2 등을 곧게 펴고 팔꿈치를 몸통에 가깝게 둔다.,Step:3 내쉬며 덤벨을 어깨 쪽으로 말아 올려 이두를 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤 들이쉬며 덤벨을 천천히 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PNtsX17', '케이블 리버스 그립 스트레이트 백 시트 하이 로우', 'https://static.exercisedb.dev/media/PNtsX17.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 케이블 머신을 마주보고 좌석에 앉아 발을 바닥에 둔다.,Step:2 손바닥이 위를 보게 언더핸드 그립으로 어태치먼트를 어깨너비로 잡는다.,Step:3 등을 곧게 펴고 엉덩이에서 약간 앞으로 기울인다.,Step:4 견갑골을 당기며 케이블을 몸통 쪽으로 끌어와 등 근육을 수축한다.,Step:5 수축 지점에서 잠깐 멈춘 뒤 케이블을 천천히 풀어 시작 자세로 돌아간다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o17Jfkt', '레버 인클라인 체스트 프레스 v. 2', 'https://static.exercisedb.dev/media/o17Jfkt.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 레버리지 머신의 시트 높이와 등받이 각도를 편하게 조절한다.,Step:2 등에 등받이를 대고 앉아 발을 바닥에 둔다.,Step:3 오버핸드 그립으로 손잡이를 잡고 손을 어깨너비보다 약간 넓게 둔다.,Step:4 팔꿈치를 잠그지 않으며 손잡이를 앞으로 밀어 팔을 뻗는다.,Step:5 완전히 뻗은 지점에서 잠깐 멈춘 뒤 팔꿈치를 굽혀 손잡이를 가슴 쪽으로 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1YB40kg', '인클라인 클로즈 그립 푸쉬업', 'https://static.exercisedb.dev/media/1YB40kg.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 스텝 같은 높은 표면에 손을 어깨너비보다 약간 넓게 올린다.,Step:2 다리를 뒤로 뻗어 발끝으로 지탱하고 머리부터 발뒤꿈치까지 일직선을 만든다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 가슴을 표면 쪽으로 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cwsAI4G', '덤벨 디클라인 슈러그', 'https://static.exercisedb.dev/media/cwsAI4G.gif', '승모근', '등', '덤벨', '어깨,능형근', 'Step:1 디클라인 벤치를 45도 각도로 세팅한다.,Step:2 가슴과 복부를 벤치에 대고 엎드린다.,Step:3 양손에 덤벨을 들고 팔을 바닥 쪽으로 완전히 늘어뜨린다.,Step:4 팔을 곧게 유지한 채 어깨를 귀 쪽으로 최대한 끌어올린다.,Step:5 수축을 잠깐 유지한 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('t8iSghb', '바벨 런지', 'https://static.exercisedb.dev/media/t8iSghb.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 바벨을 상부 등에 올린다.,Step:2 오른발을 앞으로 내딛으며 상체를 세운다.,Step:3 오른무릎을 굽혀 허벅지가 바닥과 평행해질 때까지 몸을 내린다.,Step:4 오른발 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 왼발로 반복하며 좌우 번갈아 원하는 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aqvSOQE', '케이블 크로스오버 리버스 플라이', 'https://static.exercisedb.dev/media/aqvSOQE.gif', '삼각근', '어깨', '케이블', '능형근,승모근', 'Step:1 케이블 크로스오버 머신의 낮은 풀리에 D-핸들을 각각 연결하고 중앙에 선다.,Step:2 손바닥이 아래를 보게 오버핸드 그립으로 손잡이를 잡고 한 걸음 앞으로 나가 자세를 잡는다.,Step:3 무릎을 약간 굽히고 허리에서 앞으로 기울이되 등을 곧게 펴고 복부에 힘을 준다.,Step:4 팔을 옆으로 뻗고 팔꿈치를 살짝 굽힌 채, 내쉬며 케이블을 뒤·위 방향으로 벌려 리버스 플라이 동작을 한다.,Step:5 수축 지점에서 잠깐 멈춘 뒤 들이쉬며 천천히 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dCPESfR', '바벨 스탠딩 브래드포드 프레스', 'https://static.exercisedb.dev/media/dCPESfR.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 서서 오버핸드 그립으로 바벨을 어깨 앞쪽에 든다.,Step:2 바벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:3 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('f7Y9eDZ', '바벨 스러스터', 'https://static.exercisedb.dev/media/f7Y9eDZ.gif', '삼각근', '어깨', '바벨', '대퇴사두근,둔근,햄스트링,코어', 'Step:1 발을 어깨너비로 서서 바벨을 어깨 높이에 오버핸드로 잡는다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 보내 스쿼트로 내려간다.,Step:3 바닥 지점에서 뒤꿈치로 강하게 밀어 일어서며 동시에 바벨을 머리 위로 프레스한다.,Step:4 바벨을 어깨 높이로 내리며 다시 스쿼트로 내려간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('r5DgrW9', '덤벨 서포트 스쿼트', 'https://static.exercisedb.dev/media/r5DgrW9.gif', '대퇴사두근', '허벅지', '덤벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 양손에 덤벨을 옆으로 들고 선다.,Step:2 가슴을 들고 코어를 조인 채 무릎을 굽히고 엉덩이를 뒤로 보내며 내려간다.,Step:3 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:4 바닥에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JhYSVwT', '덤벨 시트 벤치 익스텐션', 'https://static.exercisedb.dev/media/JhYSVwT.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 덤벨을 양손으로 잡고 팔을 머리 위로 곧게 뻗는다.,Step:3 팔꿈치를 귀 옆에 붙인 채 덤벨을 머리 뒤로 천천히 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 덤벨을 다시 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7saC5zz', '케이블 디클라인 플라이', 'https://static.exercisedb.dev/media/7saC5zz.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 케이블 머신을 디클라인 각도로 조절한다.,Step:2 머신을 등지고 발을 어깨너비로 선다.,Step:3 손바닥이 앞을 보게 손잡이를 잡고 팔을 정면으로 뻗어 시작한다.,Step:4 팔꿈치를 살짝 굽힌 채 팔을 좌우로 벌려 가슴을 늘리며 컨트롤한다.,Step:5 완전히 벌린 지점에서 잠깐 멈춘 뒤 천천히 원위치로 모은다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gfk9kD4', '바벨 오버헤드 스쿼트', 'https://static.exercisedb.dev/media/gfk9kD4.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 서고 발끝을 약간 바깥으로 돌린다.,Step:2 와이드 그립으로 바벨을 잡아 팔을 완전히 펴 머리 위로 고정한다.,Step:3 코어를 조이고 가슴을 든 채 무릎이 발끝 방향으로 나가게 하며 스쿼트로 내려간다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DotAgEF', '바벨 리버스 그립 디클라인 벤치 프레스', 'https://static.exercisedb.dev/media/DotAgEF.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 발을 고정하고 머리가 엉덩이보다 낮게 위치하게 한다.,Step:2 리버스 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 바벨을 랙에서 빼고 가슴 위에 든다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 바벨을 가슴 쪽으로 천천히 내린다.,Step:5 아래 지점에서 잠깐 멈춘 뒤 바벨을 시작 자세로 밀어 올린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xmM75XG', '웨이티드 오버헤드 크런치(안정성 공 사용)', 'https://static.exercisedb.dev/media/xmM75XG.gif', '복근', '허리', '가중', '복사근,허리', 'Step:1 짐볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 원판이나 덤벨을 양손으로 잡고 팔을 머리 위로 뻗는다.,Step:3 복부에 힘을 주고 상체를 천천히 말아 올려 가슴을 무릎 쪽으로 가져간다.,Step:4 정점에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('i11JWU7', '케이블 스탠딩 리버스 그립 원 암 오버헤드 삼두근 익스텐션', 'https://static.exercisedb.dev/media/i11JWU7.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 케이블 머신을 등지고 발을 어깨너비로 선다.,Step:2 언더핸드 그립으로 손잡이를 잡고 팔을 머리 위로 뻗어 팔꿈치를 머리 옆에 둔다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 손잡이를 머리 뒤로 천천히 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IeTIEqg', '바벨 프론트 체스트 스쿼트', 'https://static.exercisedb.dev/media/IeTIEqg.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 서고 발끝을 약간 바깥으로 돌린다.,Step:2 바벨을 가슴 앞에서 들고 팔꿈치를 앞으로 향하게 한다.,Step:3 코어를 조이고 가슴을 든 채 엉덩이를 뒤로 보내며 무릎을 굽혀 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:5 바닥에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GUT8I22', '레버 데드리프트', 'https://static.exercisedb.dev/media/GUT8I22.gif', '둔근', '허벅지', '레버리지 머신', '햄스트링,대퇴사두근', 'Step:1 시트 높이와 풋플랫폼을 원하는 자세에 맞게 조절한다.,Step:2 등에 패드를 대고 앉아 발을 풋플랫폼에 둔다.,Step:3 안정성을 위해 손잡이나 좌석 옆을 잡는다.,Step:4 둔근과 햄스트링에 힘을 주고 뒤꿈치로 밀어 무게를 들어 올린다.,Step:5 등을 곧게 유지하고 어깨가 말리지 않게 한다.,Step:6 정점에서 엉덩이를 완전히 펴 둔근을 수축한다.,Step:7 둔근과 햄스트링에 긴장을 유지하며 천천히 내려간다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yU7w7CA', '엑서사이즈볼 스트레칭(피라미드)', 'https://static.exercisedb.dev/media/yU7w7CA.gif', '광배근', '등', '스태빌리티 볼', '둔근,햄스트링', 'Step:1 발을 바닥에 두고 무릎을 90도로 굽힌 상태로 짐볼에 앉는다.,Step:2 발을 천천히 앞으로 걸어 나가며 짐볼이 등에 따라 굴러가 허리 아래쪽이 볼 위에 오게 한다.,Step:3 손은 머리 뒤에 두거나 가슴 위로 교차해 둔다.,Step:4 코어에 힘을 주고 상체를 천천히 바닥 쪽으로 내려 허리 아래쪽이 볼 위에서 늘어나도록 한다.,Step:5 몇 초간 유지한 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zHEpuuc', '케이블 보조 인버스 레그 컬', 'https://static.exercisedb.dev/media/zHEpuuc.gif', '햄스트링', '허벅지', '케이블', '둔근,종아리근', 'Step:1 케이블 머신을 최저 설정으로 두고 발목 스트랩을 연결한다.,Step:2 벤치에 엎드려 다리를 곧게 편 채 발목에 스트랩을 고정한다.,Step:3 안정성을 위해 벤치 손잡이를 잡는다.,Step:4 상체는 고정한 채 내쉬며 무릎을 굽혀 발을 둔근 쪽으로 끌어올린다.,Step:5 정점에서 잠깐 멈추며 햄스트링을 수축한다.,Step:6 들이쉬며 다리를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ykA5tU7', '짐 볼을 이용한 체스트 스트레칭', 'https://static.exercisedb.dev/media/ykA5tU7.gif', '가슴근육', '가슴', '스태빌리티 볼', '어깨,삼두근', 'Step:1 발을 바닥에 두고 등을 곧게 편 상태로 짐볼에 앉는다.,Step:2 양손으로 짐볼을 잡고 팔을 앞으로 곧게 뻗는다.,Step:3 짐볼을 천천히 가슴 쪽으로 가져와 가슴 근육이 늘어나는 것을 느낀다.,Step:4 몇 초간 유지한 뒤 천천히 시작 자세로 돌아간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4cWjYEN', '짐 볼에 좁은 팔 굽혀 펴기', 'https://static.exercisedb.dev/media/4cWjYEN.gif', '삼두근', '상완이두근', '스태빌리티 볼', '가슴,어깨', 'Step:1 짐볼을 바닥에 두고 손을 볼 위에 올려 어깨너비보다 약간 좁게 푸쉬업 자세를 만든다.,Step:2 코어를 조여 머리부터 발끝까지 일직선을 유지한다.,Step:3 팔꿈치를 몸에 가깝게 굽혀 가슴을 볼 쪽으로 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 팔을 펴 시작 자세로 밀어 올린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HBYyX94', '바벨 스플릿 스쿼트 v. 2', 'https://static.exercisedb.dev/media/HBYyX94.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 바벨을 상부 등에 올린다.,Step:2 오른발을 크게 앞으로 내딛고 상체를 세운다.,Step:3 무릎과 고관절을 굽혀 오른 허벅지가 바닥과 평행해질 때까지 내려간다.,Step:4 잠깐 멈춘 뒤 오른발 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 왼발을 앞으로 내딛어 동일하게 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KtRomty', '스탠딩휠 롤러아웃', 'https://static.exercisedb.dev/media/KtRomty.gif', '복근', '허리', '휠 롤러', '허리,어깨', 'Step:1 휠 롤러를 앞에 두고 발을 어깨너비로 서서 시작한다.,Step:2 허리에서 숙이며 등을 곧게 펴고 휠을 천천히 앞으로 굴린다.,Step:3 복부가 늘어나는 느낌이 들 때까지 가능한 범위로 굴린다.,Step:4 잠깐 멈춘 뒤 휠을 천천히 당겨 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Snj1wSv', '플라이 푸시 업', 'https://static.exercisedb.dev/media/Snj1wSv.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 손을 어깨너비보다 약간 넓게 두고 하이 플랭크 자세를 만든다.,Step:2 팔꿈치를 굽혀 몸을 일직선으로 유지하며 가슴을 바닥 쪽으로 내린다.,Step:3 가슴 힘으로 바닥을 강하게 밀어 상체를 순간적으로 띄운다.,Step:4 손을 부드럽게 착지시켜 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('y5p0H8a', '스프린트(장비)', 'https://static.exercisedb.dev/media/y5p0H8a.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 골반너비로 서서 곧게 선다.,Step:2 코어에 힘을 주고 상체는 편안하게 둔다.,Step:3 제자리에서 조깅을 시작해 무릎을 가슴 쪽으로 들어 올리고 발볼로 부드럽게 착지한다.,Step:4 일정한 속도를 유지하며 원하는 시간 또는 거리만큼 계속한다.,Step:5 깊게 호흡하며 바른 자세를 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zd4P4B2', '스탈더 프레스', 'https://static.exercisedb.dev/media/zd4P4B2.gif', '삼두근', '상완이두근', '맨몸', '어깨,코어', 'Step:1 발을 어깨너비로 서서 팔을 머리 위로 뻗는다.,Step:2 무릎을 약간 굽히고 코어를 조인다.,Step:3 팔을 머리 위로 유지한 채 스쿼트로 내려간다.,Step:4 내려가면서 팔을 바닥 쪽으로 누르듯이 내려 삼두에 힘을 준다.,Step:5 바닥에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 일어서며 팔을 다시 머리 위로 올린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3s4NnTh', '덤벨 스탠딩 바이셉스 컬', 'https://static.exercisedb.dev/media/3s4NnTh.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 곧게 서서 손바닥이 앞을 보게 하고 팔을 완전히 편다.,Step:2 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두를 수축한다.,Step:3 이두가 완전히 수축되고 덤벨이 어깨 높이에 오도록 올린다.,Step:4 정점에서 잠깐 멈추며 이두를 조인다.,Step:5 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tZkGYZ9', '밴드 바이시클 크런치', 'https://static.exercisedb.dev/media/tZkGYZ9.gif', '복근', '허리', '밴드', '고관절 굴근,복사근', 'Step:1 등을 대고 누워 손을 머리 뒤에 두고 무릎을 굽힌다.,Step:2 발을 바닥에서 들어 올리고 오른무릎을 가슴 쪽으로 당기며 상체를 비틀어 왼팔꿈치를 오른무릎 쪽으로 보낸다.,Step:3 오른다리를 펴며 동시에 왼무릎을 가슴 쪽으로 당기고 상체를 비틀어 오른팔꿈치를 왼무릎 쪽으로 보낸다.,Step:4 자전거 페달을 밟듯 좌우를 번갈아 비틀며 코어 긴장을 유지한다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bTpEUcm', '바벨 로우바 스쿼트', 'https://static.exercisedb.dev/media/bTpEUcm.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 바벨을 상부 등에 올린다.,Step:2 가슴을 들고 코어를 조인 채 무릎을 굽히고 엉덩이를 뒤로 보내며 내려간다.,Step:3 허벅지가 바닥과 평행해지거나 그보다 약간 더 내려갈 때까지 내려간다.,Step:4 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OmQ8w0p', '케이블 팜 회전 행', 'https://static.exercisedb.dev/media/OmQ8w0p.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 허리 높이에 케이블 손잡이를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 선다.,Step:3 손바닥이 아래를 보게 오버핸드로 손잡이를 잡는다.,Step:4 케이블에 장력이 걸리도록 한 걸음 뒤로 가며 등을 곧게 펴고 무릎을 약간 굽힌다.,Step:5 손잡이를 몸 쪽으로 당기면서 손바닥이 위로 향하도록 회전한다.,Step:6 끝지점에서 견갑골을 모아 등을 수축한다.,Step:7 손잡이를 천천히 풀어 시작 자세로 돌아간다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CvPn9WV', '케이블 스탠딩 풀다운(로프 포함)', 'https://static.exercisedb.dev/media/CvPn9WV.gif', '이두근', '상완이두근', '케이블', '전완근,어깨', 'Step:1 케이블 머신을 최고 높이로 설정하고 로프를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 선다.,Step:3 손바닥이 아래를 보게 오버핸드로 로프를 잡는다.,Step:4 등을 곧게 펴고 코어를 조여 자세를 유지한다.,Step:5 로프를 허벅지 쪽으로 당겨 내리며 이두를 수축한다.,Step:6 아래 지점에서 잠깐 멈춘 뒤 로프를 천천히 올려 시작 자세로 돌아간다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TUZLh71', '밴드 스쿼트', 'https://static.exercisedb.dev/media/TUZLh71.gif', '둔근', '허벅지', '밴드', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서고 밴드를 무릎 바로 위에 건다.,Step:2 가슴을 들고 코어를 조인 채 엉덩이를 뒤로 보내며 무릎을 굽혀 스쿼트로 내려간다.,Step:3 무릎이 발끝 방향으로 나가게 하고 체중은 뒤꿈치에 둔다.,Step:4 바닥에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6sMAmNv', '덤벨 리버스 스파이더 컬', 'https://static.exercisedb.dev/media/6sMAmNv.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 곧게 서서 손바닥이 몸을 향하게 하고 팔을 완전히 편다.,Step:2 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두를 수축한다.,Step:3 이두가 완전히 수축되고 덤벨이 어깨 높이에 오도록 올린다.,Step:4 정점에서 잠깐 멈추며 이두를 조인다.,Step:5 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('75Bgtjy', '스쿼트', 'https://static.exercisedb.dev/media/75Bgtjy.gif', '복근', '허리', '맨몸', '대퇴사두근,둔근', 'Step:1 발을 어깨너비로 서고 발끝을 약간 바깥으로 돌린다.,Step:2 의자에 앉듯이 무릎을 굽히고 엉덩이를 뒤로 보내며 내려간다.,Step:3 가슴을 들고 등을 곧게 유지한다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:5 바닥에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('945zpRg', '바벨 와이드 리버스 그립 벤치 프레스', 'https://static.exercisedb.dev/media/945zpRg.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 벤치에 누워 발을 바닥에 평평하게 두고 등을 벤치에 밀착한다.,Step:2 어깨너비보다 약간 넓게 리버스 그립으로 바벨을 잡는다.,Step:3 바벨을 랙에서 빼 가슴 위로 팔을 뻗어 든다.,Step:4 팔꿈치를 몸에 가깝게 유지하고 손목을 곧게 하며 바벨을 가슴 쪽으로 천천히 내린다.,Step:5 바벨이 가슴에 닿는 지점에서 잠깐 멈춘 뒤 시작 자세로 밀어 올린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Am02iPd', '짐 볼에 덤벨 원 암 플라이', 'https://static.exercisedb.dev/media/Am02iPd.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐볼에 앉아 한 손에 덤벨을 들고 발을 바닥에 둔다.,Step:2 발을 앞으로 걸으며 몸을 내려 상부 등이 짐볼에 기대게 한다.,Step:3 덤벨 든 팔을 가슴 위로 곧게 뻗고 손바닥이 안쪽을 보게 한다.,Step:4 팔꿈치를 살짝 굽힌 채 덤벨을 옆으로 천천히 내린다.,Step:5 잠깐 멈춘 뒤 가슴을 수축해 덤벨을 시작 위치로 다시 모은다.,Step:6 원하는 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7vG5o25', '덤벨 인클라인 로우', 'https://static.exercisedb.dev/media/7vG5o25.gif', '등 위쪽', '등', '덤벨', '이두근,어깨', 'Step:1 인클라인 벤치를 45도 각도로 세팅한다.,Step:2 양손에 덤벨을 들고 가슴을 벤치에 대고 앉는다.,Step:3 팔을 완전히 펴 덤벨이 어깨 아래로 수직으로 늘어지게 둔다.,Step:4 견갑골을 모으며 덤벨을 가슴 쪽으로 끌어올린다.,Step:5 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BIb1tGo', '덤벨 스탠딩 원 암 컬(인클라인 벤치 위)', 'https://static.exercisedb.dev/media/BIb1tGo.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 서서 한 손에 덤벨을 들고 손바닥이 앞을 보게 한다.,Step:2 다른 손은 인클라인 벤치에 올려 균형을 잡는다.,Step:3 상완을 고정한 채 내쉬며 덤벨을 어깨 쪽으로 말아 올려 이두를 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤 들이쉬며 덤벨을 천천히 내린다.,Step:5 원하는 횟수만큼 반복한 뒤 반대팔도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AQIhRjM', '팔꿈치부터 무릎까지 누워서', 'https://static.exercisedb.dev/media/AQIhRjM.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 옆으로 벌린다.,Step:3 복부에 힘을 주고 상체를 들어 올리며 오른팔꿈치를 왼무릎 쪽으로 가져간다.,Step:4 동시에 오른다리를 곧게 펴고 바닥에서 들어 올린다.,Step:5 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:6 이번에는 왼팔꿈치를 오른무릎 쪽으로 가져가며 왼다리를 뻗는다.,Step:7 좌우 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cALKspW', '케이블 직립 행', 'https://static.exercisedb.dev/media/cALKspW.gif', '삼각근', '어깨', '케이블', '승모근,이두근', 'Step:1 발을 어깨너비로 서고 무릎을 약간 굽힌 뒤 케이블 어태치먼트를 오버핸드로 잡는다.,Step:2 등을 곧게 펴고 코어를 조여 자세를 유지한다.,Step:3 팔꿈치를 위로 이끌며 케이블을 턱 쪽으로 수직으로 끌어올린다.,Step:4 정점에서 잠깐 멈추며 견갑골을 조인다.,Step:5 케이블을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tFGKm99', '중간 고관절 굴근 및 쿼드 스트레치', 'https://static.exercisedb.dev/media/tFGKm99.gif', '대퇴사두근', '허벅지', '로프', '햄스트링,둔근', 'Step:1 발을 어깨너비로 서서 곧게 선다.,Step:2 균형을 위해 고정된 물체를 잡는다.,Step:3 오른무릎을 굽혀 발을 둔근 쪽으로 가져오고 오른손으로 로프를 잡는다.,Step:4 로프를 천천히 당겨 오른발을 둔근 쪽으로 가까이 하며 대퇴사두근 스트레치를 느낀다.,Step:5 20-30초 유지한다.,Step:6 풀고 왼쪽도 동일하게 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('T0yTjgW', '레버 체스트 프레스', 'https://static.exercisedb.dev/media/T0yTjgW.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 시트 높이를 조절하고 등에 패드를 밀착해 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔꿈치를 90도로 맞춘다.,Step:3 내쉬며 손잡이를 앞으로 밀어 팔을 완전히 뻗는다.,Step:4 끝지점에서 잠깐 멈춘 뒤 들이쉬며 손잡이를 천천히 되돌린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9WTm7dq', '가슴 딥스', 'https://static.exercisedb.dev/media/9WTm7dq.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 평행봉에 올라 팔을 완전히 펴고 몸을 곧게 유지한다.,Step:2 팔꿈치를 굽혀 어깨가 팔꿈치보다 아래로 내려갈 때까지 몸을 내린다.,Step:3 팔을 펴며 시작 자세로 밀어 올린다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gu2rNJd', '스미스 체어 스쿼트', 'https://static.exercisedb.dev/media/Gu2rNJd.gif', '대퇴사두근', '허벅지', '스미스 머신', '둔근,햄스트링,종아리근', 'Step:1 스미스 바 높이를 편한 위치로 조절한다.,Step:2 발을 어깨너비로 서고 발끝을 약간 바깥으로 돌린다.,Step:3 바를 승모근 위에 올려 고정한다.,Step:4 코어를 조이고 가슴을 든 채 무릎과 고관절을 굽혀 천천히 내려간다.,Step:5 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:6 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HjdqmZa', '원 암 턱걸이', 'https://static.exercisedb.dev/media/HjdqmZa.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 턱걸이 바를 마주보고 발을 어깨너비로 선다.,Step:2 한 손은 언더핸드 그립으로 바를 잡고 다른 손은 잡은 손목을 잡아 보조한다.,Step:3 팔을 완전히 편 채 매달려 몸을 곧게 하고 코어를 조인다.,Step:4 팔꿈치를 굽히며 등을 수축해 몸을 바 쪽으로 끌어올린다.,Step:5 턱이 바 위로 올라올 때까지 당긴 뒤 천천히 내려간다.,Step:6 원하는 횟수만큼 반복한 뒤 손을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OAguZoG', '레버 해머 그립 프리처 컬', 'https://static.exercisedb.dev/media/OAguZoG.gif', '이두근', '상완이두근', '레버리지 머신', '전완근', 'Step:1 시트 높이를 조절해 자세를 맞춘다.,Step:2 상완을 프리처 패드에 올리고 가슴을 패드에 밀착한다.,Step:3 손바닥이 서로 마주보는 해머 그립으로 손잡이를 잡는다.,Step:4 상완을 고정한 채 내쉬며 손잡이를 어깨 쪽으로 말아 올린다.,Step:5 정점에서 잠깐 멈추며 이두를 수축한다.,Step:6 들이쉬며 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bBi35y3', '덤벨 스탠딩 대체 오버헤드 프레스', 'https://static.exercisedb.dev/media/bBi35y3.gif', '삼각근', '어깨', '덤벨', '삼두근,코어', 'Step:1 발을 어깨너비로 서서 양손에 덤벨을 어깨 높이에 들고 손바닥이 앞을 보게 한다.,Step:2 한쪽 덤벨을 머리 위로 밀어 팔을 완전히 편다.,Step:3 덤벨을 어깨 높이로 다시 내린다.,Step:4 반대쪽도 동일하게 수행한다.,Step:5 좌우 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Z5YStHW', '오버헤드 삼두근 스트레칭', 'https://static.exercisedb.dev/media/Z5YStHW.gif', '삼두근', '상완이두근', '맨몸', '어깨', 'Step:1 발을 어깨너비로 벌린 상태로 서거나 앉는다.,Step:2 한쪽 팔을 머리 위로 올린 뒤 팔꿈치를 굽혀 손이 반대쪽 날개뼈 방향으로 가게 한다.,Step:3 다른 손으로 굽힌 팔꿈치를 머리 반대쪽으로 부드럽게 당겨 삼두근이 늘어나는 것을 느낀다.,Step:4 15–30초 동안 유지한 뒤 풀어준다.,Step:5 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JsOV1SU', '머슬 업', 'https://static.exercisedb.dev/media/JsOV1SU.gif', '광배근', '등', '가중', '이두근,삼두근,어깨,가슴', 'Step:1 손바닥이 앞을 보게 하여 어깨너비보다 약간 넓게 턱걸이 바에 매달린다.,Step:2 코어를 조이고 가슴을 먼저 이끈다는 느낌으로 몸을 바 쪽으로 당긴다.,Step:3 정점에서 손바닥이 자신을 향하게 그립을 전환한다.,Step:4 가슴이 바에 닿을 때까지 계속 끌어올린 뒤 잠깐 멈춘다.,Step:5 컨트롤하며 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7B4F5nZ', '레버 종아리 프레스', 'https://static.exercisedb.dev/media/7B4F5nZ.gif', '종아리근', '종아리', '레버리지 머신', '햄스트링', 'Step:1 어깨가 레버 패드와 정렬되도록 시트를 조절한다.,Step:2 발끝을 레버 패드에 올리고 뒤꿈치는 가장자리 밖으로 나오게 둔다.,Step:3 안정성을 위해 손잡이나 측면 지지대를 잡는다.,Step:4 발목을 펴 레버 패드를 밀어 종아리를 수축한다.,Step:5 아래 지점에서 잠깐 멈춘다.,Step:6 뒤꿈치가 다시 올라오도록 천천히 되돌려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CfKsRbG', '덤벨 대체 바이셉스 컬(암 블래스터 포함)', 'https://static.exercisedb.dev/media/CfKsRbG.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 서서 양손에 덤벨을 들고 손바닥이 앞을 보게 한다.,Step:2 암 블래스터를 상완에 걸어 고정한다.,Step:3 상완을 고정한 채 내쉬며 한쪽 덤벨을 어깨 쪽으로 말아 올려 이두를 수축한다.,Step:4 이두가 완전히 수축되고 덤벨이 어깨 높이에 오도록 올린다.,Step:5 정점에서 잠깐 멈추며 이두를 조인다.,Step:6 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:7 반대팔도 동일하게 수행한다.,Step:8 좌우 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('I1OBLnn', '가중 스벤 프레스', 'https://static.exercisedb.dev/media/I1OBLnn.gif', '가슴근육', '가슴', '가중', '어깨,삼두근', 'Step:1 발을 어깨너비로 서서 원판을 양손으로 가슴 앞에 든다.,Step:2 팔꿈치를 약간 굽히고 손바닥이 서로 마주보게 한다.,Step:3 원판을 정면으로 밀어 팔을 완전히 뻗는다.,Step:4 끝지점에서 잠깐 멈춘 뒤 원판을 천천히 가슴 앞으로 되돌린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RYcV1kH', '바벨 스쿼트 점프 스텝 리어 런지', 'https://static.exercisedb.dev/media/RYcV1kH.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 바벨을 상부 등에 올린다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 보내 스쿼트로 내려간다.,Step:3 폭발적으로 점프해 최대한 높이 뜬다.,Step:4 부드럽게 착지한 뒤 즉시 한쪽 다리를 뒤로 보내 리어 런지로 들어간다.,Step:5 앞다리 허벅지가 바닥과 평행해질 때까지 내려가며 등을 곧게 유지한다.,Step:6 앞발 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:7 반대 다리로 점프+런지 시퀀스를 반복한다.,Step:8 좌우 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('v3vLFW0', '클로즈 그립 푸시업(무릎)', 'https://static.exercisedb.dev/media/v3vLFW0.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 손과 무릎을 바닥에 대고 손은 어깨너비로 둔다.,Step:2 팔꿈치를 몸에 가깝게 굽혀 상체를 바닥 쪽으로 내린다.,Step:3 가슴이 바닥 바로 위에 올 때 잠깐 멈춘다.,Step:4 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RqOtqD7', '케이블 리버스 크런치', 'https://static.exercisedb.dev/media/RqOtqD7.gif', '복근', '허리', '케이블', '고관절 굴근', 'Step:1 로우 풀리에 케이블을 연결하고 매트에 등을 대고 눕는다.,Step:2 케이블을 양손으로 잡고 팔을 천장 쪽으로 곧게 뻗는다.,Step:3 무릎을 굽혀 다리를 들어 올리고 허벅지를 가슴 쪽으로 가져간다.,Step:4 상체는 고정한 채 골반을 말아 올려 엉덩이를 매트에서 들어 올린다.,Step:5 정점에서 잠깐 멈춘 뒤 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uKyN64F', '바벨 한쪽 다리 스쿼트', 'https://static.exercisedb.dev/media/uKyN64F.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 서서 바벨을 상부 등에 올린다.,Step:2 한 발을 바닥에서 들어 앞으로 뻗어 바닥과 평행하게 둔다.,Step:3 지지하는 다리의 무릎을 굽히며 의자에 앉듯이 내려가고 가슴과 등을 곧게 유지한다.,Step:4 허벅지가 바닥과 평행해질 때까지 내려간 뒤 뒤꿈치로 밀어 올라온다.,Step:5 원하는 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YtaCTYl', '덤벨 한쪽 팔 장착 중립 손목 컬', 'https://static.exercisedb.dev/media/YtaCTYl.gif', '전완근', '팔 아래', '덤벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 한 손에 덤벨을 들어 손바닥이 위를 보게 한다.,Step:2 전완을 허벅지 위에 올리고 손목이 끝에서 떨어지게 둔다.,Step:3 전완을 고정한 채 손목만 위로 말아 올린다.,Step:4 정점에서 잠깐 멈춘 뒤 손목을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한 뒤 반대손으로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3ZflifB', '케이블 푸시다운', 'https://static.exercisedb.dev/media/3ZflifB.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신 상단 풀리에 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 서며 무릎을 약간 굽힌다.,Step:3 오버핸드 그립으로 바를 어깨너비로 잡는다.,Step:4 팔꿈치를 몸통 옆에 붙이고 상완을 고정한다.,Step:5 내쉬며 바를 아래로 밀어 팔꿈치를 완전히 편다.,Step:6 잠깐 멈춘 뒤 들이쉬며 바를 천천히 올려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LYJodFS', '컷팅', 'https://static.exercisedb.dev/media/LYJodFS.gif', '복근', '허리', '맨몸', '어깨,가슴,삼두근', 'Step:1 푸쉬업 자세에서 손을 어깨너비로 두고 몸을 곧게 만든다.,Step:2 코어를 조이고 어깨가 손보다 앞으로 나가도록 천천히 체중을 앞으로 이동한다.,Step:3 팔꿈치를 약간 굽힌 채 몸을 곧게 유지하며 앞으로 기울어진 자세를 만든다.,Step:4 이 자세를 몇 초 유지한 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9Tkqa9O', '케틀벨 스피닝', 'https://static.exercisedb.dev/media/9Tkqa9O.gif', '복근', '허리', '케틀벨', '복사근,어깨', 'Step:1 발을 어깨너비로 서서 오른손에 케틀벨을 들어 머리 위로 고정한다.,Step:2 왼발은 약 45도 바깥으로 돌리고 오른발은 정면을 향하게 둔다.,Step:3 케틀벨을 든 팔을 뻗은 채 시선을 케틀벨에 두고 상체를 왼쪽으로 기울인다.,Step:4 오른팔을 곧게 유지하며 가능한 범위까지 상체를 낮추고 왼팔은 옆으로 뻗는다.,Step:5 잠깐 멈춘 뒤 오른발로 지면을 밀며 복사근을 사용해 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cALkHHX', '덤벨 철 십자가', 'https://static.exercisedb.dev/media/cALkHHX.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 발을 어깨너비로 서서 양손에 덤벨을 들고 팔을 옆으로 둔다.,Step:2 팔을 옆으로 들어 올려 바닥과 평행하게 만들어 몸이 T자 형태가 되게 한다.,Step:3 잠깐 멈춘 뒤 팔을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('b6hQYMb', '레버 프리처 컬', 'https://static.exercisedb.dev/media/b6hQYMb.gif', '이두근', '상완이두근', '레버리지 머신', '전완근', 'Step:1 시트 높이를 조절해 자세를 맞춘다.,Step:2 상완을 패드 위에 올리고 언더핸드 그립으로 손잡이를 잡는다.,Step:3 등을 곧게 펴고 팔꿈치를 패드에 고정한다.,Step:4 내쉬며 전완을 말아 올려 이두를 수축한다.,Step:5 정점에서 잠깐 멈추며 이두를 조인다.,Step:6 들이쉬며 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4Jt8QsQ', '팔 아래로 푸시업', 'https://static.exercisedb.dev/media/4Jt8QsQ.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 전완을 바닥에 두고 팔꿈치를 어깨 바로 아래에 위치시켜 플랭크 자세를 만든다.,Step:2 코어를 조이고 머리부터 발끝까지 일직선을 유지한다.,Step:3 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리되 팔꿈치를 몸에 가깝게 유지한다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 전완으로 밀어 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nFc4FyV', '덤벨 바이셉스 컬 리버스', 'https://static.exercisedb.dev/media/nFc4FyV.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 손바닥이 아래를 보게 하여 팔을 완전히 편다.,Step:2 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두를 수축한다.,Step:3 이두가 완전히 수축되고 덤벨이 어깨 높이에 오도록 올린다.,Step:4 정점에서 잠깐 멈추며 이두를 조인다.,Step:5 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5eLRITT', '덤벨 스티프 레그 데드리프트', 'https://static.exercisedb.dev/media/5eLRITT.gif', '둔근', '허벅지', '덤벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 서서 양손에 덤벨을 오버핸드로 잡는다.,Step:2 등을 곧게 펴고 코어를 조인 채, 무릎을 약간만 굽히고 엉덩이를 뒤로 보내며 덤벨을 바닥 쪽으로 내린다.,Step:3 햄스트링이 늘어나는 느낌이 들 때까지 내린다.,Step:4 둔근을 조이고 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7OeHptV', '서포티드 풀업', 'https://static.exercisedb.dev/media/7OeHptV.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 머신의 보조 중량(어시스트)을 원하는 수준으로 조절한다.,Step:2 발판에 올라 손잡이를 오버핸드로 어깨너비보다 약간 넓게 잡는다.,Step:3 가슴을 들고 어깨를 내린 채 코어를 조이고 무릎을 약간 굽힌다.,Step:4 팔꿈치를 굽히며 아래로 끌어내린다는 느낌으로 몸을 올린다.,Step:5 턱이 바 위로 올라올 때까지 당긴다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RgJDRR1', '바벨 와이드 그립 업라이트 로우', 'https://static.exercisedb.dev/media/RgJDRR1.gif', '삼각근', '어깨', '바벨', '승모근,이두근', 'Step:1 발을 어깨너비로 서서 바벨을 와이드 오버핸드 그립으로 잡는다.,Step:2 바벨이 허벅지 앞에서 늘어지게 하고 팔을 완전히 편다.,Step:3 등을 곧게 유지한 채 내쉬며 팔꿈치를 위로 이끌어 바벨을 턱 쪽으로 끌어올린다.,Step:4 정점에서 잠깐 멈춘 뒤 들이쉬며 바벨을 천천히 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hvV79Si', '케이블 로우 시티드 행잉', 'https://static.exercisedb.dev/media/hvV79Si.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 머신에 앉아 발을 풋레스트에 두고 무릎을 약간 굽힌다.,Step:2 손바닥이 아래를 보게 오버핸드로 손잡이를 잡는다.,Step:3 등을 곧게 펴고 약간 앞으로 기울이며 팔꿈치를 살짝 굽힌다.,Step:4 손잡이를 몸 쪽으로 당기며 견갑골을 모은다.,Step:5 정점에서 잠깐 멈춘 뒤 손잡이를 천천히 풀어 시작 자세로 돌아간다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('U7D9Fx3', '덤벨 인클라인 투 암 익스텐션', 'https://static.exercisedb.dev/media/U7D9Fx3.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 인클라인 벤치에 앉아 양손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 벤치에 천천히 누우며 덤벨을 가슴 가까이 유지한다.,Step:3 완전히 누운 뒤 팔을 천장 쪽으로 뻗되 팔꿈치를 약간 굽힌다.,Step:4 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mpKZGWz', '덤벨 라잉 삼두근 익스텐션', 'https://static.exercisedb.dev/media/mpKZGWz.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 등을 대고 누워 각 손에 덤벨을 쥐고 손바닥이 서로 마주보게 한다.,Step:2 팔을 가슴 위로 곧게 뻗되, 팔꿈치는 몸에 가깝게 유지한다.,Step:3 팔꿈치를 굽혀 덤벨을 이마 쪽으로 천천히 내린다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤, 팔을 펴서 시작 자세로 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0xDpB4L', '밴드 활용 고관절 회전', 'https://static.exercisedb.dev/media/0xDpB4L.gif', '외전근', '허벅지', '저항 밴드', '둔근,햄스트링', 'Step:1 의자나 벤치에 등을 곧게 펴고 앉고 발바닥을 바닥에 둔다.,Step:2 저항 밴드를 허벅지에 감아 무릎 바로 위에 위치시킨다.,Step:3 지지하기 위해 의자/벤치 양옆을 손으로 잡는다.,Step:4 바깥 허벅지 근육(외전근)을 사용해 무릎을 천천히 바깥으로 밀어 밴드 저항에 맞선다.,Step:5 끝 지점에서 잠깐 멈춘다.,Step:6 무릎을 천천히 다시 모아 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('x825CZm', '케이블 시트 리어 레터럴 레이즈', 'https://static.exercisedb.dev/media/x825CZm.gif', '삼각근', '어깨', '케이블', '승모근,능형근', 'Step:1 케이블 머신을 마주보고 벤치에 앉아 발을 바닥에 둔다.,Step:2 오버핸드 그립으로 케이블 핸들을 잡고 팔을 정면으로 곧게 뻗는다.,Step:3 팔을 곧게 유지한 채 천천히 양옆으로 들어 바닥과 평행이 되게 올린다.,Step:4 최고 지점에서 잠깐 멈춘다.,Step:5 팔을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wf24o8S', '케틀벨 투 암 로우', 'https://static.exercisedb.dev/media/wf24o8S.gif', '등 위쪽', '등', '케틀벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌 채, 각 손에 케틀벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 엉덩이를 접어 상체를 앞으로 기울이되, 등을 곧게 펴고 코어를 고정한다.,Step:3 케틀벨을 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:4 최고 지점에서 잠깐 멈춘다.,Step:5 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ln9iTbU', '바벨 리어 델트 레이즈', 'https://static.exercisedb.dev/media/Ln9iTbU.gif', '삼각근', '어깨', '바벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 오버핸드 그립으로 바벨을 잡는다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되, 등을 곧게 유지한다.,Step:3 팔을 곧게 유지한 채 바벨을 양옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 최고 지점에서 잠깐 멈춘다.,Step:5 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rDAiRf9', '덤벨 인클라인 원 암 프레스', 'https://static.exercisedb.dev/media/rDAiRf9.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 인클라인 벤치에 앉아 한 손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 벤치에 등을 기대 눕고 덤벨을 어깨 높이에 위치시키며 손바닥은 정면을 향하게 한다.,Step:3 팔을 위로 그리고 약간 안쪽으로 밀어 올려 완전히 편다.,Step:4 최고 지점에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽 팔로 교체한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XDOiFns', '슬레이 앞으로 각진 종아리 들어올리기', 'https://static.exercisedb.dev/media/XDOiFns.gif', '종아리근', '종아리', '슬레이 기계', '햄스트링,둔근', 'Step:1 슬레이 머신의 무게와 위치를 편하게 맞춘 뒤, 발끝을 플랫폼에 두고 뒤꿈치는 밖으로 살짝 빼고 선다/기댄다.,Step:2 손잡이나 머신 측면을 잡아 몸을 지지한다.,Step:3 종아리에 힘을 주어 뒤꿈치를 가능한 높이 들어 올리며 저항을 민다.,Step:4 최고 지점에서 잠깐 멈춘다.,Step:5 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('niXESDw', '덤벨 바이셉스 컬 스쿼트', 'https://static.exercisedb.dev/media/niXESDw.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서, 양손에 덤벨을 들고 손바닥이 정면을 향하게 한다.,Step:2 등을 곧게 유지하고 팔꿈치를 몸 옆에 붙인 채, 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:3 최고 지점에서 잠깐 멈추며 이두근을 수축한다.,Step:4 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aee2Fcj', '바벨 바이셉스 컬(암 블래스터 포함)', 'https://static.exercisedb.dev/media/aee2Fcj.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 언더핸드 그립으로 바벨을 잡는다.,Step:2 상완을 암 블래스터에 밀착해 팔꿈치를 몸통에 가깝게 유지한다.,Step:3 상완을 고정한 채 내쉬며 바벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 강하게 조인다.,Step:6 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iZop9xO', '바벨 라이딩 삼두근 익스텐션', 'https://static.exercisedb.dev/media/iZop9xO.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 등을 대고 누워 발을 바닥에 두고, 머리는 벤치 끝쪽에 오게 한다.,Step:2 오버핸드 그립으로 바벨을 잡고 가슴 위로 팔을 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바벨을 이마 쪽으로 천천히 내린다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 팔을 펴서 바벨을 다시 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4LIG9xr', '바벨 리버스 프리처컬 컬', 'https://static.exercisedb.dev/media/4LIG9xr.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 프리처 벤치에 앉아 가슴을 패드에 붙이고 팔을 아래로 곧게 뻗은 채 오버핸드 그립으로 바벨을 잡는다.,Step:2 상완을 고정한 채 내쉬며 바벨을 말아 올려 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tgryw5Y', '푸쉬업(스태빌리티 볼 위에서)', 'https://static.exercisedb.dev/media/tgryw5Y.gif', '가슴근육', '가슴', '스태빌리티 볼', '삼두근,어깨,코어', 'Step:1 스태빌리티 볼을 바닥에 두고, 볼 위에 어깨너비로 손을 짚은 채 엎드린다.,Step:2 다리를 뒤로 곧게 뻗어 발끝으로 균형을 잡는다.,Step:3 코어를 조이고 몸이 일직선이 되게 유지한 채, 팔꿈치를 굽혀 가슴을 볼 쪽으로 내린다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 팔을 펴서 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xUwnBMT', '스미스 시티드 숄더 프레스', 'https://static.exercisedb.dev/media/xUwnBMT.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 좌석 높이를 조절해 손잡이가 어깨 높이에 오게 맞춘다.,Step:2 등을 패드에 붙이고 앉아 발을 바닥에 둔다.,Step:3 오버핸드 그립으로 손잡이를 잡고 지지대에서 들어 올려 팔을 편다.,Step:4 손잡이를 어깨 높이까지 천천히 내리되 팔꿈치는 살짝 굽힌 상태를 유지한다.,Step:5 손잡이를 머리 위로 밀어 올려 팔을 완전히 편다.,Step:6 정점에서 잠깐 멈춘다.,Step:7 손잡이를 천천히 내려 어깨 높이로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rWoBmi5', '코리아 딥스', 'https://static.exercisedb.dev/media/rWoBmi5.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 평행봉 사이에 올라가 팔을 펴서 체중을 지탱한다.,Step:2 팔꿈치를 굽혀 몸을 내려 상완이 바닥과 평행이 되게 한다.,Step:3 바닥 지점에서 잠깐 멈춘다.,Step:4 팔을 펴서 시작 자세로 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('i6LWjok', '바벨 풀오버', 'https://static.exercisedb.dev/media/i6LWjok.gif', '광배근', '등', '바벨', '가슴,삼두근', 'Step:1 벤치에 등을 대고 누워 머리는 한쪽 끝에 오게 하고 발은 바닥에 둔다.,Step:2 어깨너비 그립으로 바벨을 잡고 가슴 위로 팔을 곧게 편다.,Step:3 팔을 곧게 유지한 채, 바벨을 머리 뒤로 천천히 내려 광배근이 늘어나는 느낌이 들 때까지 내린다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 바벨을 천천히 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('H1XAdpk', '덤벨 바이셉스 컬 v 싯 온 보수 볼', 'https://static.exercisedb.dev/media/H1XAdpk.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 보수 볼 위에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 양손에 덤벨을 들고 손바닥이 정면을 향하게 하며 팔을 아래로 완전히 편다.,Step:3 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9XjtHvS', '덤벨 풀오버', 'https://static.exercisedb.dev/media/9XjtHvS.gif', '가슴근육', '가슴', '덤벨', '광배근,삼두근', 'Step:1 벤치에 등을 대고 누워 머리는 한쪽 끝에 오게 하고 발은 바닥에 둔다.,Step:2 양손으로 덤벨 하나를 잡고 가슴 위로 팔을 곧게 편다.,Step:3 팔꿈치를 약간 굽힌 채, 덤벨을 머리 뒤로 천천히 내려 가슴과 어깨가 늘어나는 느낌이 들 때까지 내린다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('D5yqP2p', '레버 오버핸드 삼두근 딥', 'https://static.exercisedb.dev/media/D5yqP2p.gif', '삼두근', '상완이두근', '레버리지 머신', '가슴,어깨', 'Step:1 머신 높이를 적절히 조절하고 몸을 고정해 자세를 잡는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔을 완전히 펴서 시작한다.,Step:3 팔꿈치를 굽혀 몸을 내리되 상완을 몸 옆에 가깝게 유지한다.,Step:4 상완이 바닥과 평행이 될 때까지 내려간다.,Step:5 바닥 지점에서 잠깐 멈춘다.,Step:6 팔꿈치를 펴서 시작 자세로 밀어 올린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YZ4961r', '풀 플랜체', 'https://static.exercisedb.dev/media/YZ4961r.gif', '복근', '허리', '맨몸', '어깨,가슴,삼두근', 'Step:1 손을 어깨너비로 두고 손가락은 정면을 향한 푸쉬업 자세에서 시작한다.,Step:2 코어에 힘을 주고 체중을 천천히 앞으로 이동시키며 발을 바닥에서 들어 올린다.,Step:3 몸이 바닥과 평행이 될 때까지 더 앞으로 이동해 손으로 균형을 잡는다.,Step:4 머리부터 발끝까지 일직선을 유지하며 가능한 오래 버틴다.,Step:5 발을 천천히 바닥에 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SLKj2pX', '고치', 'https://static.exercisedb.dev/media/SLKj2pX.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 되게 말아 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 상체를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jTkSc6o', '옆 엉덩이(평행봉 위)', 'https://static.exercisedb.dev/media/jTkSc6o.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 평행봉 사이에 서서 발을 어깨너비로 벌린다.,Step:2 손으로 봉을 잡고 몸을 들어 팔로 체중을 지탱한다.,Step:3 복근에 힘을 주고 다리를 곧게 편 채 옆으로 천천히 들어 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XhfS1DZ', '비골 스트레칭', 'https://static.exercisedb.dev/media/XhfS1DZ.gif', '종아리근', '종아리', '로프', '발목,피트', 'Step:1 다리를 앞으로 곧게 뻗은 채 바닥에 앉는다.,Step:2 로프를 발앞쪽 볼 부분에 걸고 양손으로 로프의 양끝을 잡는다.,Step:3 로프를 천천히 몸쪽으로 당겨 발을 당기며 종아리 근육이 늘어나는 것을 느낀다.,Step:4 15–30초 동안 유지한다.,Step:5 로프의 긴장을 풀고 반대쪽 다리도 반복한다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BReCuOn', '맨몸 스쿼트 로우(수건 포함)', 'https://static.exercisedb.dev/media/BReCuOn.gif', '등 위쪽', '등', '맨몸', '이두근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서, 손바닥이 아래를 향하게 수건을 앞에서 잡는다.,Step:2 무릎을 굽혀 스쿼트 자세로 내려가되 등을 곧게 유지하고 가슴을 편다.,Step:3 내려가면서 동시에 수건을 가슴 쪽으로 당겨 견갑골을 모아 조인다.,Step:4 스쿼트 최저점에서 잠깐 멈춘다.,Step:5 팔을 펴며 천천히 일어나 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XVzF3iZ', '덤벨 거짓말 앙와위 바이셉스 컬', 'https://static.exercisedb.dev/media/XVzF3iZ.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 등을 대고 누워 머리와 등이 지지되게 하고 발은 바닥에 둔다.,Step:2 양손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔을 아래로 완전히 편다.,Step:3 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qaZVsGk', '대체 힐터처', 'https://static.exercisedb.dev/media/qaZVsGk.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 팔을 양옆으로 곧게 뻗어 바닥과 평행하게 둔다.,Step:3 복근에 힘을 주고 어깨를 들어 올리며 오른손을 오른쪽 발뒤꿈치 쪽으로 뻗는다.,Step:4 시작 자세로 돌아온 뒤 왼손을 왼쪽 발뒤꿈치 쪽으로 뻗는다.,Step:5 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XgWyAiA', '가슴 딥스(딥 풀업 케이지)', 'https://static.exercisedb.dev/media/XgWyAiA.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 딥 바 높이를 편하게 잡을 수 있게 조절한다.,Step:2 바 사이에 서서 각 바를 어깨보다 약간 넓게 잡는다.,Step:3 점프해 팔을 펴고 바 위에서 체중을 지탱한다.,Step:4 무릎을 굽히고 발목을 뒤에서 교차한다.,Step:5 팔꿈치를 굽혀 몸을 내리되 가슴을 들고 어깨를 내린다.,Step:6 어깨가 팔꿈치보다 아래로 내려가거나 가슴이 늘어나는 지점까지 내려간다.,Step:7 손바닥으로 밀어 팔꿈치를 펴며 시작 자세로 올라온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oROuvrX', '레버 행잉', 'https://static.exercisedb.dev/media/oROuvrX.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이를 조절하고 머신을 마주보고 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 등을 곧게 편다.,Step:3 손잡이를 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:4 최고 수축 지점에서 잠깐 멈춘다.,Step:5 손잡이를 천천히 놓아 팔을 뻗으며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('84sESNy', '짐볼 원암 바이셉스 컬 덤벨', 'https://static.exercisedb.dev/media/84sESNy.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 짐볼 위에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔을 아래로 완전히 편다.,Step:3 균형을 위해 반대손은 엉덩이에 둔다.,Step:4 상완을 고정한 채 덤벨을 천천히 말아 올려 어깨 쪽으로 당긴다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.,Step:8 팔을 바꿔 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EmlJR2y', '인클라인 벤치 위에 한쪽 팔 컬을 서 있는 덤벨', 'https://static.exercisedb.dev/media/EmlJR2y.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 든다.,Step:2 반대손을 인클라인 벤치에 올려 몸을 지지한다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('isofgzg', '롤러백 스트레칭', 'https://static.exercisedb.dev/media/isofgzg.gif', '척추', '등', '롤러', '햄스트링,둔근', 'Step:1 다리를 앞으로 곧게 뻗은 채 바닥에 앉는다.,Step:2 로프를 발앞쪽 볼 부분에 걸고 양손으로 로프의 양끝을 잡는다.,Step:3 로프를 천천히 몸쪽으로 당겨 발을 당기며 종아리 근육이 늘어나는 것을 느낀다.,Step:4 15–30초 동안 유지한다.,Step:5 로프의 긴장을 풀고 반대쪽 다리도 반복한다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IENzBdA', '바벨 드래그 컬', 'https://static.exercisedb.dev/media/IENzBdA.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 언더핸드 그립으로 바벨을 잡는다.,Step:2 바벨을 허벅지 앞에서 팔을 완전히 편 채로 늘어뜨린다.,Step:3 상완을 고정한 채, 바벨을 몸에 가깝게 끌어올리듯 가슴 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PDaMuyV', '덤벨 원 암 인클라인 체스트 프레스', 'https://static.exercisedb.dev/media/PDaMuyV.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 인클라인 벤치를 45도 각도로 맞춘다.,Step:2 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 둔다.,Step:3 한 손에 덤벨을 오버핸드 그립으로 잡고 어깨 위에 둔다.,Step:4 덤벨을 위로 그리고 몸에서 약간 멀어지게 밀어 올려 팔을 완전히 편다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rEhi2o5', '바닥에 누워 있는 아령', 'https://static.exercisedb.dev/media/rEhi2o5.gif', '전완근', '팔 아래', '덤벨', '이두근,어깨', 'Step:1 바닥에 등을 대고 누워 다리를 뻗고, 양손에 덤벨을 들고 팔을 몸 옆에 둔다.,Step:2 손바닥이 위를 향하게 천천히 회전시키되 팔꿈치는 몸 옆에 붙인다.,Step:3 덤벨을 천천히 어깨 쪽으로 말아 올리며 전완에 힘을 준다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OM46QHm', '케이블 풀스루(로프 포함)', 'https://static.exercisedb.dev/media/OM46QHm.gif', '둔근', '허벅지', '케이블', '햄스트링,허리', 'Step:1 케이블 머신에서 등지고 서서 발을 어깨너비로 벌린다.,Step:2 로프 어태치먼트를 양손으로 잡고 한두 걸음 앞으로 나가 케이블에 장력을 만든다.,Step:3 엉덩이를 접어 상체를 앞으로 숙여 몸통이 바닥과 평행에 가깝게 내려가되 등을 곧게 유지한다.,Step:4 둔근과 햄스트링에 힘을 주어 몸을 다시 세워 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TVdivgY', '덤벨 인클라인 얼터너티브 프레스', 'https://static.exercisedb.dev/media/TVdivgY.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 인클라인 벤치에 앉아 양손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 벤치에 기대 눕고 허벅지를 이용해 덤벨을 어깨 높이로 올리며 손바닥이 정면을 향하게 한다.,Step:3 어깨 높이에 오면 손목을 돌려 손바닥이 정면을 향하도록 고정한다.,Step:4 가슴과 어깨 힘으로 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아오되 팔꿈치는 살짝 굽힌 상태를 유지한다.,Step:6 원하는 반복 횟수만큼 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TXtXc84', '케이블 턱 리버스 크런치', 'https://static.exercisedb.dev/media/TXtXc84.gif', '복근', '허리', '케이블', '고관절 굴근', 'Step:1 로우 풀리에 케이블을 연결하고 매트 위에 등을 대고 눕는다.,Step:2 케이블을 양손으로 잡고 팔을 가슴 위로 곧게 뻗는다.,Step:3 무릎을 굽히고 다리를 들어 무릎을 가슴 쪽으로 끌어온다.,Step:4 동시에 골반을 말아 올려 엉덩이를 바닥에서 들어 올린다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 다리와 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('euI1BwR', '바벨 스피드 스쿼트', 'https://static.exercisedb.dev/media/euI1BwR.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 돌린다.,Step:2 바벨을 등 상부(승모근 또는 후면 삼각근)에 올려 얹는다.,Step:3 코어에 힘을 주고 가슴을 편 채, 엉덩이를 뒤로 빼며 무릎을 굽혀 내려간다.,Step:4 허벅지가 바닥과 평행이 되거나 가능한 범위까지 내려간다.,Step:5 뒤꿈치로 바닥을 밀어 빠르게 일어서며 정점에서 둔근을 조인다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0S75mYG', '스미스 시티드 한쪽 다리 종아리 들어올리기', 'https://static.exercisedb.dev/media/0S75mYG.gif', '종아리근', '종아리', '스미스 머신', '햄스트링', 'Step:1 머신에 앉아 등을 패드에 붙이고 발을 발판에 둔다.,Step:2 한쪽 발만 발판에 올리고 다른 발은 발판에서 뗀다.,Step:3 종아리 힘으로 뒤꿈치를 가능한 높이 들어 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y5X65IB', 'ez 바벨 리버스 그립 컬', 'https://static.exercisedb.dev/media/Y5X65IB.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 EZ바를 언더핸드 그립으로 잡는다.,Step:2 팔꿈치를 몸통에 붙이고 상완을 고정해 동작 내내 움직이지 않게 한다.,Step:3 내쉬며 이두근을 수축해 바를 위로 말아 올린다.,Step:4 이두근이 완전히 수축되고 바가 어깨 높이에 올 때까지 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이마시며 바를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EcaV7aL', '바벨 라이딩 클로즈 그립 프레스', 'https://static.exercisedb.dev/media/EcaV7aL.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 벤치에 등을 대고 누워 발을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 손을 어깨너비 정도의 좁은 그립으로 바벨을 잡고 손바닥이 발쪽을 향하게 한다.,Step:3 바벨을 랙에서 들어 가슴 위에 팔을 완전히 편 채 고정한다.,Step:4 팔꿈치를 몸에 붙인 채 바벨을 가슴 쪽으로 천천히 내린다.,Step:5 바벨이 가슴에 닿는 지점에서 잠깐 멈춘다.,Step:6 바벨을 밀어 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EZeDVzO', '가중 감소 윗몸 일으키기', 'https://static.exercisedb.dev/media/EZeDVzO.gif', '복근', '허리', '가중', '고관절 굴근,허리', 'Step:1 디클라인 벤치에 등을 대고 누워 발을 패드 아래에 고정한다.,Step:2 손을 머리 뒤에 두거나 가슴 위에 교차한다.,Step:3 복근에 힘을 주고 상체를 천천히 들어 올려 몸통이 바닥과 수직에 가깝게 되도록 말아 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 상체를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SSsBDwB', '덤벨 리어 런지', 'https://static.exercisedb.dev/media/SSsBDwB.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 오른발을 뒤로 내딛으며 몸을 내려 런지 자세를 만든다.,Step:3 왼쪽 무릎을 굽혀 왼쪽 허벅지가 바닥과 평행이 될 때까지 내려간다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 왼발 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 반대쪽도 동일하게 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2qTvJAZ', '바벨 스탠딩 백 리스트 컬', 'https://static.exercisedb.dev/media/2qTvJAZ.gif', '전완근', '팔 아래', '바벨', '이두근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 바벨을 잡는다.,Step:2 손등 위에 바벨이 놓이도록 하고 손바닥은 아래를 향하게 하며 손가락이 몸쪽을 향하게 한다.,Step:3 상완을 고정한 채 내쉬며 손목을 위로 굽혀 가능한 범위까지 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FxhcxUW', '덤벨 시트 한쪽 다리 종아리 들어올리기 - 해머 그립', 'https://static.exercisedb.dev/media/FxhcxUW.gif', '종아리근', '종아리', '덤벨', '햄스트링,둔근', 'Step:1 벤치나 의자에 앉아 발을 바닥에 두고, 덤벨을 허벅지 위에 올린다.,Step:2 한쪽 발을 스텝/블록 같은 받침에 올리고 뒤꿈치는 끝에서 살짝 빼서 걸치게 둔다.,Step:3 덤벨을 해머 그립(손바닥이 서로 마주보는 그립)으로 잡는다.,Step:4 코어에 힘을 주고 등을 곧게 유지한 채, 발볼로 밀어 뒤꿈치를 가능한 높이 들어 올린다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('u0pLNgz', ' 한쪽 다리 종아리 프레스 온 레그 프레스', 'https://static.exercisedb.dev/media/u0pLNgz.gif', '종아리근', '종아리', '슬레이 기계', '햄스트링,둔근', 'Step:1 레그프레스 좌석을 조절해 발을 슬레이에 올렸을 때 무릎이 살짝 굽혀진 상태가 되게 한다.,Step:2 등에 등받이를 밀착하고 앉아 발을 슬레이에 어깨너비로 둔다.,Step:3 발끝과 발볼만 슬레이에 두고 뒤꿈치는 밖으로 빼서 띄운다.,Step:4 발목을 펴서 슬레이를 밀어 올리되 무릎은 살짝 굽힌 상태를 유지한다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 발목을 굽혀 슬레이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RoV1Rfa', '스테이빌리티 볼을 이용한 좌위 대흉근 스트레칭', 'https://static.exercisedb.dev/media/RoV1Rfa.gif', '가슴근육', '가슴', '도움을 준', '어깨,삼두근', 'Step:1 발을 바닥에 두고 등을 곧게 편 상태로 짐볼에 앉는다.,Step:2 양손으로 짐볼을 잡고 팔을 앞으로 곧게 뻗는다.,Step:3 짐볼을 천천히 가슴 쪽으로 내리며 가슴 근육이 늘어나는 것을 느낀다.,Step:4 몇 초간 유지한 뒤 천천히 시작 자세로 돌아간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1LVFcEn', '로프 종아리 스트레칭', 'https://static.exercisedb.dev/media/1LVFcEn.gif', '종아리근', '종아리', '로프', '햄스트링', 'Step:1 벽이나 단단한 지지물을 마주보고 발을 엉덩이너비로 벌려 선다.,Step:2 양손에 로프 양끝을 잡고 로프의 중간을 오른발 앞쪽 볼 부분에 건다.,Step:3 왼발을 뒤로 내딛고 뒤꿈치를 바닥에 둔 채 다리를 곧게 유지한다.,Step:4 등을 곧게 편 상태에서 상체를 앞으로 기울이며 로프를 천천히 당겨 종아리를 스트레칭한다.,Step:5 20–30초 동안 유지한 뒤 풀어준다.,Step:6 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kmVVAfu', '밴드 컨센트레이션 컬', 'https://static.exercisedb.dev/media/kmVVAfu.gif', '이두근', '상완이두근', '밴드', '전완근', 'Step:1 벤치나 의자에 앉아 다리를 벌리고 발을 바닥에 둔다.,Step:2 밴드 한쪽 끝을 손으로 잡고, 같은 쪽 발로 반대쪽 끝을 밟아 고정한다.,Step:3 상체를 약간 숙이고 팔꿈치를 허벅지 안쪽(무릎 바로 위)에 댄다.,Step:4 손바닥이 위를 향하게 한 채, 상완을 고정하고 손을 어깨 쪽으로 천천히 말아 올린다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 손을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2kr2lWy', '푸쉬업(보스볼)', 'https://static.exercisedb.dev/media/2kr2lWy.gif', '가슴근육', '가슴', '보수 공', '삼두근,어깨,코어', 'Step:1 보수 볼을 바닥에 두고 평평한 면이 위로 오게 둔다.,Step:2 보수 볼 가장자리에 손을 짚고 푸쉬업 자세를 만든다.,Step:3 코어에 힘을 주고 팔꿈치를 굽혀 몸을 보수 볼 쪽으로 내린다.,Step:4 팔을 펴서 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oZjMu1t', '타이어 뒤집기', 'https://static.exercisedb.dev/media/oZjMu1t.gif', '둔근', '허벅지', '타이어', '햄스트링,대퇴사두근,코어', 'Step:1 타이어를 마주보고 발을 어깨너비로 벌린다.,Step:2 무릎을 굽히고 엉덩이를 접어 스쿼트처럼 내려간다.,Step:3 타이어 아래쪽 가장자리를 양손으로 잡되 손가락은 몸쪽을 향하게 한다.,Step:4 둔근과 다리 힘으로 폭발적으로 밀어 올려 타이어를 들어 올린다.,Step:5 타이어가 넘어갈 때 상체 힘으로 방향을 잡아 안정적으로 넘긴다.,Step:6 완전히 넘어가면 빠르게 한 걸음 물러나 자세를 재정렬한다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BU15nH4', '덤벨 대체 바이셉스 컬', 'https://static.exercisedb.dev/media/BU15nH4.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 똑바로 서서 양손에 덤벨을 들고 손바닥이 정면을 향하게 하며 팔을 아래로 완전히 편다.,Step:2 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LWuA3aZ', '바벨 스탠딩 리버스 그립 컬', 'https://static.exercisedb.dev/media/LWuA3aZ.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 언더핸드 그립으로 바벨을 잡는다.,Step:2 팔꿈치를 몸통에 붙이고 상완을 고정한다.,Step:3 내쉬며 이두근을 수축해 바벨을 가능한 어깨 가까이까지 말아 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TiaZTxx', '덤벨 시티드 컬', 'https://static.exercisedb.dev/media/TiaZTxx.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 양손에 덤벨을 들며 손바닥이 정면을 향하게 한다.,Step:2 등을 곧게 펴고 팔꿈치를 몸통에 붙인다.,Step:3 내쉬며 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('c9MnDRp', '덤벨 레이즈', 'https://static.exercisedb.dev/media/c9MnDRp.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 등을 곧게 펴고 코어에 힘을 준다.,Step:3 팔꿈치를 약간 굽힌 채 팔을 양옆으로 들어 바닥과 평행이 되게 올린다.,Step:4 최고 지점에서 잠깐 멈춘다.,Step:5 팔을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PsVS1QP', '메디신볼 캐치 및 머리 위로 던지기', 'https://static.exercisedb.dev/media/PsVS1QP.gif', '광배근', '등', '메디신볼', '어깨,코어', 'Step:1 발을 어깨너비로 벌리고 서서 메디신볼을 가슴 높이에서 양손으로 잡는다.,Step:2 무릎을 살짝 굽히고 코어에 힘을 준다.,Step:3 등을 곧게 유지한 채 스쿼트로 내려간다.,Step:4 엉덩이와 다리를 폭발적으로 펴면서 동시에 메디신볼을 머리 위로 던진다.,Step:5 던진 공이 내려올 때 받아낸다.,Step:6 다시 스쿼트로 내려가며 동작을 반복한다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('P9GFBME', '거미 크롤링 푸시 업', 'https://static.exercisedb.dev/media/P9GFBME.gif', '둔근', '허벅지', '맨몸', '코어,가슴,어깨', 'Step:1 손은 어깨보다 약간 넓게, 발은 모아 푸쉬업 자세에서 시작한다.,Step:2 오른쪽 무릎을 오른쪽 팔꿈치 쪽으로 끌어온다(바닥에 닿지 않게).,Step:3 오른쪽 무릎을 되돌리면서 동시에 팔꿈치를 굽혀 몸을 바닥 쪽으로 내린다.,Step:4 팔을 펴서 시작 자세로 올라온다.,Step:5 왼쪽 무릎을 왼쪽 팔꿈치 쪽으로 끌어오며 동일하게 반복한다.,Step:6 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('W6PxUkg', '덤벨 리베이트', 'https://static.exercisedb.dev/media/W6PxUkg.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:3 상완을 몸 옆에 붙이고 팔꿈치를 90도로 굽힌다.,Step:4 팔을 뒤로 곧게 펴 삼두근을 수축한다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lHeUULr', '밴드 스트레이트 백 스티프 레그 데드리프트', 'https://static.exercisedb.dev/media/lHeUULr.gif', '둔근', '허벅지', '밴드', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 서서 밴드를 허벅지 위쪽에 걸어 둔다.,Step:2 양손으로 밴드를 허벅지 앞에서 잡고 손바닥이 몸을 향하게 한다.,Step:3 등을 곧게 유지하고 무릎은 살짝 굽힌 채, 엉덩이를 접어 밴드를 바닥 쪽으로 내려간다.,Step:4 내려가며 햄스트링이 늘어나는 느낌을 받는다.,Step:5 둔근과 햄스트링에 힘을 주어 몸을 다시 세워 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('S9zHIvU', '바벨 리어 델트 로우', 'https://static.exercisedb.dev/media/S9zHIvU.gif', '삼각근', '어깨', '바벨', '승모근,능형근,이두근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 오버핸드 그립으로 바벨을 어깨보다 약간 넓게 잡는다.,Step:3 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 펴고 가슴을 연다.,Step:4 바벨을 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tnaj0mT', '스윙 360', 'https://static.exercisedb.dev/media/tnaj0mT.gif', '심혈관계', '유산소', '맨몸', '어깨,코어', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 팔을 정면으로 곧게 뻗어 바닥과 평행하게 둔다.,Step:3 코어에 힘을 주고 팔을 원을 그리듯 휘두르며 상체를 함께 회전시킨다.,Step:4 원하는 횟수만큼 원운동을 유지하며 팔을 휘두르고 몸통을 회전한다.,Step:5 동작 내내 호흡을 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('T2mxWqc', '턱걸이', 'https://static.exercisedb.dev/media/T2mxWqc.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 손바닥이 자신을 향하게 어깨너비로 철봉을 잡고 매달린다.,Step:2 코어에 힘을 주고 가슴을 리드하며 몸을 위로 당긴다.,Step:3 턱이 철봉 위로 올라갈 때까지 당긴다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 몸을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gH5fRsC', '덤벨 시티드 얼터너티브 프론트 레이즈', 'https://static.exercisedb.dev/media/gH5fRsC.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 양손에 덤벨을 들고 손바닥이 몸을 향하게 하여 팔을 아래로 뻗는다.,Step:3 팔을 곧게 유지한 채 한쪽 덤벨을 정면으로 들어 바닥과 평행이 될 때까지 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 반대쪽도 동일하게 수행한다.,Step:7 원하는 반복 횟수만큼 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AR0ig3o', '굴곡 다리 윗몸 일으키기(무릎 구부리기)', 'https://static.exercisedb.dev/media/AR0ig3o.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주며 상체를 들어 올려 몸통이 약 45도 각도가 되게 말아 올린다.,Step:4 동시에 다리를 들어 무릎을 굽혀 가슴 쪽으로 끌어온다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 상체와 다리를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eXFXCY0', '레버 시트 크런치 v. 2', 'https://static.exercisedb.dev/media/eXFXCY0.gif', '복근', '허리', '레버리지 머신', '복사근,고관절 굴근', 'Step:1 레버리지 머신에 앉아 등을 패드에 붙이고 발을 발패드 아래에 고정한다.,Step:2 손잡이나 좌석 측면을 잡아 몸을 지지한다.,Step:3 복근에 힘을 주고 가슴을 무릎 쪽으로 가져오듯 천천히 크런치한다.,Step:4 정점에서 잠깐 멈추며 복근을 조인다.,Step:5 등을 약간 말아주며 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('s999Hdo', '짐 볼에 덤벨 한쪽 팔 장착 이두근 컬', 'https://static.exercisedb.dev/media/s999Hdo.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐볼 위에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔을 아래로 완전히 편다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wpbD28t', '사이드 푸시업', 'https://static.exercisedb.dev/media/wpbD28t.gif', '삼두근', '상완이두근', '맨몸', '어깨,가슴,코어', 'Step:1 옆으로 누워 다리를 곧게 펴고 포개어 둔다.,Step:2 아래쪽 손을 어깨 바로 아래 바닥에 두고 손가락은 정면을 향하게 한다.,Step:3 아래쪽 손으로 바닥을 밀어 몸을 들어 올리며 코어를 고정한다.,Step:4 위쪽 팔은 천장을 향해 곧게 뻗어 머리부터 발끝까지 일직선을 만든다.,Step:5 몸을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('V4ryaZa', 'ez 바벨 클로즈 그립 컬', 'https://static.exercisedb.dev/media/V4ryaZa.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 언더핸드 그립으로 EZ바를 어깨너비로 잡는다.,Step:2 팔꿈치를 몸통에 붙이고 상완을 고정해 동작 내내 움직이지 않게 한다.,Step:3 EZ바를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 EZ바를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lCKm4Rs', '짐볼 라잉 레그레이즈', 'https://static.exercisedb.dev/media/lCKm4Rs.gif', '척추', '등', '스태빌리티 볼', '복부,둔근', 'Step:1 매트 위에 엎드리고 다리를 곧게 뻗어 발끝을 스태빌리티 볼 위에 올린다.,Step:2 손을 어깨너비로 바닥에 짚고 코어에 힘을 준다.,Step:3 다리를 곧게 유지한 채 허리와 둔근을 사용해 다리를 천천히 들어 올린다.,Step:4 가능한 높이까지 올린 뒤 잠깐 멈춘다.,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7w6i0vE', '바닥에 케틀벨 교대 프레스', 'https://static.exercisedb.dev/media/7w6i0vE.gif', '가슴근육', '가슴', '케틀벨', '어깨,삼두근', 'Step:1 바닥에 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 양손에 케틀벨을 들고 손바닥이 발쪽을 향하게 하며 팔을 천장 방향으로 곧게 뻗는다.,Step:3 한쪽 케틀벨을 어깨 쪽으로 천천히 내리는 동안 다른 쪽은 곧게 유지한다.,Step:4 내린 케틀벨을 다시 밀어 올리며 동시에 반대쪽 케틀벨을 어깨 쪽으로 내린다.,Step:5 원하는 반복 횟수만큼 좌우로 번갈아 프레스한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nnmCTLN', '레버 무릎을 꿇고 다리 컬', 'https://static.exercisedb.dev/media/nnmCTLN.gif', '햄스트링', '허벅지', '레버리지 머신', '둔근', 'Step:1 머신을 몸에 맞게 조절하고 원하는 무게를 선택한다.,Step:2 머신에 무릎을 꿇고 엎드린 방향으로 자세를 잡아 무릎을 패드에 두고 발목을 패드 아래에 고정한다.,Step:3 손잡이나 머신 측면을 잡아 몸을 안정화한다.,Step:4 상체를 고정한 채 내쉬며 무릎을 굽혀 발을 둔근 쪽으로 말아 올린다.,Step:5 정점에서 잠깐 멈추며 햄스트링을 조인다.,Step:6 들이마시며 다리를 천천히 내려 무릎을 완전히 펴 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yT9tk17', '크로스 레그 레이즈(여성)', 'https://static.exercisedb.dev/media/yT9tk17.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 등을 대고 누워 다리를 뻗고 팔은 몸 옆에 둔다.,Step:2 무릎을 굽혀 다리를 들어 가슴 쪽으로 끌어온다.,Step:3 다리를 들어 올리며 골반을 한쪽으로 비틀어 무릎이 반대쪽 어깨 방향으로 가게 한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 반대쪽으로도 골반을 비틀어 동일하게 반복한다.,Step:7 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2Pya1cP', '케이블 디클라인 프레스', 'https://static.exercisedb.dev/media/2Pya1cP.gif', '가슴근육', '가슴', '케이블', '삼두근,어깨', 'Step:1 케이블 머신을 디클라인 프레스에 맞게 설정한다.,Step:2 디클라인 벤치에 앉아 케이블 머신을 마주본다.,Step:3 오버핸드 그립으로 손잡이를 잡고 가슴 높이에 위치시킨다.,Step:4 발을 바닥에 두고 등을 벤치에 단단히 밀착한다.,Step:5 내쉬며 손잡이를 앞으로 밀어 팔을 완전히 편다.,Step:6 끝 지점에서 잠깐 멈추며 가슴에 힘을 준다.,Step:7 들이마시며 손잡이를 천천히 되돌려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UDlhcO8', '바벨 업라이트 로우', 'https://static.exercisedb.dev/media/UDlhcO8.gif', '삼각근', '어깨', '바벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 바벨을 어깨보다 약간 넓게 잡는다.,Step:2 바벨을 허벅지 앞에서 팔을 완전히 편 채로 둔다.,Step:3 등을 곧게 펴고 코어에 힘을 준 상태에서, 내쉬며 바벨을 턱 쪽으로 수직으로 끌어올리되 팔꿈치가 리드하게 한다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('n5cWCsI', '덤벨 원 암 사이드 올리기', 'https://static.exercisedb.dev/media/n5cWCsI.gif', '삼각근', '어깨', '덤벨', '승모근,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 동작 내내 등을 곧게 펴고 코어에 힘을 준다.,Step:3 덤벨을 옆으로 들어 올리되 팔을 곧게 유지하고 손바닥은 바닥을 향하게 한다.,Step:4 팔이 바닥과 평행이 될 때까지 올린다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QfAKy1G', '덤벨 쿠바 프레스', 'https://static.exercisedb.dev/media/QfAKy1G.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 어깨 높이에서 덤벨을 들고 손바닥이 아래를 향하게 한다.,Step:2 코어에 힘을 주고 팔꿈치를 살짝 굽힌다.,Step:3 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 손목을 돌려 손바닥이 정면을 향하게 한다.,Step:5 손목을 다시 돌리며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('11wrviz', '아이소메트릭 와이퍼', 'https://static.exercisedb.dev/media/11wrviz.gif', '가슴근육', '가슴', '맨몸', '어깨,삼두근,코어', 'Step:1 매트나 벤치 위에 등을 대고 누워 시작한다.,Step:2 팔을 양옆으로 곧게 뻗어 몸과 수직이 되게 둔다.,Step:3 코어에 힘을 주고 두 다리를 모아 곧게 편 채 바닥에서 들어 올린다.,Step:4 통제하며 다리를 한쪽으로 천천히 내려 발이 바닥에 닿도록(또는 닿기 직전까지) 한다.,Step:5 잠깐 멈춘 뒤 코어 힘으로 다리를 다시 중앙으로 올린다.,Step:6 반대쪽으로도 동일하게 내려간다.,Step:7 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('faHKVkK', '바벨 스탠딩 와이드 그립 이두근 컬', 'https://static.exercisedb.dev/media/faHKVkK.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 언더핸드 그립으로 바벨을 어깨너비보다 넓게 잡는다.,Step:2 등을 곧게 펴고 팔꿈치를 몸통에 가깝게 유지한다.,Step:3 내쉬며 바벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 들이마시며 바벨을 천천히 내려 팔을 완전히 펴 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oR7O9LW', '바벨 스쿼트(무릎을 꿇고)', 'https://static.exercisedb.dev/media/oR7O9LW.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 무릎을 꿇고 시작하되 무릎은 골반너비로 벌리고 발끝은 정면을 향하게 둔다.,Step:2 바벨을 어깨 위에 올리고 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:3 코어에 힘을 주고 가슴을 들며, 무릎을 굽혀 몸을 천천히 아래로 내린다.,Step:4 허벅지가 바닥과 평행이 되거나 가능한 범위까지 내려간다.,Step:5 바닥 지점에서 잠깐 멈춘다.,Step:6 뒤꿈치(또는 정강이/무릎 지지)로 밀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SJAA2IQ', '바벨 손바닥 위로 손목 컬 벤치 위로', 'https://static.exercisedb.dev/media/SJAA2IQ.gif', '전완근', '팔 아래', '바벨', '이두근,어깨', 'Step:1 벤치에 앉아 발을 바닥에 두고 언더핸드 그립으로 바벨을 잡는다.,Step:2 전완을 벤치 위에 올리고 손목이 벤치 끝 밖으로 나오게 둔다.,Step:3 전완을 고정한 채 내쉬며 손목을 위로 굽혀 가능한 범위까지 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nFUwqG6', '스미스 리어 델트 로우', 'https://static.exercisedb.dev/media/nFUwqG6.gif', '삼각근', '어깨', '스미스 머신', '승모근,능형근,이두근', 'Step:1 좌석 높이를 조절하고 가슴을 패드에 대고 앉아 발을 바닥에 둔다.,Step:2 오버핸드 그립으로 손잡이를 어깨보다 약간 넓게 잡는다.,Step:3 등을 곧게 펴고 코어에 힘을 준 채 손잡이를 가슴 쪽으로 당겨 견갑골을 모아 조인다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('s34Y4LR', '웨이트 시트 트위스트(안정성 볼)', 'https://static.exercisedb.dev/media/s34Y4LR.gif', '복근', '허리', '가중', '복사근,허리', 'Step:1 스태빌리티 볼 위에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 웨이트 플레이트나 덤벨을 가슴 앞에서 양손으로 잡는다.,Step:3 코어에 힘을 주고 골반은 고정한 채 상체를 한쪽으로 천천히 회전한다.,Step:4 회전 끝 지점에서 잠깐 멈춘다.,Step:5 천천히 중앙으로 돌아온다.,Step:6 반대쪽으로도 동일하게 회전한다.,Step:7 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vAwm6rK', '짐볼에 케이블 프레스', 'https://static.exercisedb.dev/media/vAwm6rK.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 짐볼 위에 앉아 발을 바닥에 두고 무릎을 90도로 만든다.,Step:2 케이블 손잡이를 가슴 높이에서 잡고 손바닥은 아래를 향하게 하며 팔꿈치를 굽힌다.,Step:3 코어에 힘을 주고 손잡이를 앞으로 밀어 팔을 완전히 편다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 천천히 장력을 풀며 손잡이를 되돌려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OTgkHwR', '덤벨 디클라인 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/OTgkHwR.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 디클라인 벤치에 누워 머리가 발보다 낮게 오게 하고, 양손에 덤벨을 들어 손바닥이 서로 마주보게 한다.,Step:2 팔을 완전히 펴되 팔꿈치는 머리 가까이에 유지한다.,Step:3 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 덤벨을 다시 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('otqIxU4', '케이블 라이잉 바이셉 컬', 'https://static.exercisedb.dev/media/otqIxU4.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 로우 풀리에 스트레이트 바를 연결한다.,Step:2 평벤치에 등을 대고 누워 발을 바닥에 둔다.,Step:3 언더핸드 그립으로 바를 어깨너비로 잡는다.,Step:4 팔을 완전히 펴되 팔꿈치는 몸 옆에 붙인다.,Step:5 상완을 고정한 채 내쉬며 바를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:6 정점에서 잠깐 멈추며 이두근을 조인다.,Step:7 들이마시며 바를 천천히 내려 팔을 완전히 펴 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('d960PgE', '시티드 바벨 굿 모닝', 'https://static.exercisedb.dev/media/d960PgE.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 벤치에 앉아 발을 바닥에 두고 바벨을 등 상부에 올린다.,Step:2 등을 곧게 펴고 가슴을 든다.,Step:3 엉덩이를 접어 상체를 천천히 앞으로 숙여 바닥 쪽으로 내려간다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 뒤꿈치로 밀며 상체를 세워 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GWoKnIm', '웨이티드 코사크 스쿼트(남성)', 'https://static.exercisedb.dev/media/GWoKnIm.gif', '둔근', '허벅지', '가중', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝을 약간 바깥으로 둔다.,Step:2 웨이트를 가슴 앞에서 양손으로 잡는다.,Step:3 체중을 한쪽으로 옮기며 그쪽 무릎을 굽혀 내려가고, 반대쪽 다리는 곧게 편다.,Step:4 균형을 유지하며 가능한 낮게 내려가되 가슴을 편다.,Step:5 굽힌 다리의 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 반대쪽도 동일하게 반복하며 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eOG0r6v', '케이블 리버스 컬', 'https://static.exercisedb.dev/media/eOG0r6v.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 로우 풀리에 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 서서 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:3 언더핸드 그립으로 바를 어깨너비로 잡는다.,Step:4 팔꿈치를 몸 옆에 붙이고 상완을 고정한다.,Step:5 내쉬며 바를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:6 정점에서 잠깐 멈추며 이두근을 조인다.,Step:7 들이마시며 바를 천천히 내려 팔을 완전히 펴 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dzz6BiV', '스미스 스모 스쿼트', 'https://static.exercisedb.dev/media/dzz6BiV.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 스미스 머신 바를 힙 높이에 오게 세팅한다.,Step:2 발을 어깨너비보다 넓게 벌리고 발끝을 바깥으로 돌린다.,Step:3 바 아래로 들어가 등을 상부에 바를 얹는다.,Step:4 코어에 힘을 주고 가슴을 편 채 엉덩이를 뒤로 빼며 무릎을 굽혀 내려간다.,Step:5 허벅지가 바닥과 평행이 되거나 가능한 범위까지 내려간다.,Step:6 바닥 지점에서 잠깐 멈춘다.,Step:7 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('U5INZY6', '케이블 원 암 풀다운', 'https://static.exercisedb.dev/media/U5INZY6.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 하이 풀리에 싱글 핸들을 연결한다.,Step:2 머신을 마주보고 서서 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 핸들을 잡고 팔을 완전히 편다.,Step:4 등을 곧게 펴고 코어에 힘을 준다.,Step:5 팔꿈치를 몸 옆으로 끌어내리며 핸들을 옆구리 쪽으로 당긴다.,Step:6 끝 지점에서 잠깐 멈추며 광배근을 조인다.,Step:7 핸들을 천천히 놓아 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.,Step:9 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ae9UoXQ', '덤벨 인클라인 컬', 'https://static.exercisedb.dev/media/ae9UoXQ.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 인클라인 벤치를 45도로 맞추고 양손에 덤벨을 들고 앉아 손바닥이 정면을 향하게 한다.,Step:2 상완을 인클라인 벤치에 기대고 팔꿈치가 아래로 늘어지게 하여 팔을 완전히 편다.,Step:3 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('y5U5B9Y', '덤벨 조트만 프리처 컬', 'https://static.exercisedb.dev/media/y5U5B9Y.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 벤치에 앉아 양손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔꿈치를 패드에 둔다.,Step:2 덤벨을 어깨 쪽으로 말아 올리되 상완을 고정하고 손바닥이 위를 향하게 유지한다.,Step:3 정점에서 손목을 돌려 손바닥이 아래를 향하게 한다.,Step:4 손바닥이 아래를 향한 상태로 덤벨을 천천히 내리며, 내려가면서 손목을 다시 돌려 시작 자세로 맞춘다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VedGSby', '보조 엎드린 햄스트링', 'https://static.exercisedb.dev/media/VedGSby.gif', '햄스트링', '허벅지', '도움을 준', '둔근,허리', 'Step:1 매트나 벤치에 엎드려 다리를 완전히 편다.,Step:2 파트너가 발목을 고정해주거나 저항 밴드로 발목을 고정한다.,Step:3 햄스트링에 힘을 주고 무릎을 굽혀 발을 둔근 쪽으로 들어 올린다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AX1kB0o', '트위스트 힙 리프트', 'https://static.exercisedb.dev/media/AX1kB0o.gif', '둔근', '허벅지', '맨몸', '복사근,햄스트링', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손은 몸 옆에 두어 지지한다.,Step:3 둔근에 힘을 주고 엉덩이를 들어 올려 무릎부터 어깨까지 일직선이 되게 한다.,Step:4 엉덩이를 든 상태에서 무릎을 오른쪽 바닥 쪽으로 내려 하체를 비튼다.,Step:5 중앙으로 돌아온다.,Step:6 왼쪽으로도 동일하게 비튼다.,Step:7 원하는 반복 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1xHyxys', '케이블 하이 풀리 오버헤드 삼두근 익스텐션', 'https://static.exercisedb.dev/media/1xHyxys.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 하이 풀리에 로프를 연결하고 머신을 등지고 선다.,Step:2 로프를 양손으로 잡고 팔을 머리 위로 뻗는다.,Step:3 팔꿈치를 머리 가까이에 두고 상완을 고정한다.,Step:4 팔꿈치를 굽혀 로프를 머리 뒤로 천천히 내린다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 팔을 펴서 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OVIKwsd', '덤벨 인클라인 삼두근 익스텐션', 'https://static.exercisedb.dev/media/OVIKwsd.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 인클라인 벤치에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 팔을 머리 위로 완전히 펴되 팔꿈치는 머리 가까이에 유지한다.,Step:3 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:4 바닥 지점에서 잠깐 멈춘다.,Step:5 팔을 펴서 덤벨을 다시 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YwnI4ja', '케이블 스탠딩 내부 컬', 'https://static.exercisedb.dev/media/YwnI4ja.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 마주보고 서서 발을 어깨너비로 벌린다.,Step:2 언더핸드 그립으로 케이블 손잡이를 잡고 손바닥이 위를 향하게 한다.,Step:3 팔꿈치를 몸 옆에 붙이고 상완을 고정한다.,Step:4 내쉬며 손잡이를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이마시며 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rseLfH3', '케틀벨 익스텐션 범위 원 암 바닥에 프레스', 'https://static.exercisedb.dev/media/rseLfH3.gif', '가슴근육', '가슴', '케틀벨', '삼두근,어깨', 'Step:1 바닥에 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 한 손에 케틀벨을 들고 손바닥이 발쪽을 향하게 한다.,Step:3 팔을 천장 쪽으로 곧게 펴되 팔꿈치를 잠그고 손목을 곧게 유지한다.,Step:4 케틀벨을 통제하며 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('W31mMjd', '바벨 사이드 스플릿 스쿼트', 'https://static.exercisedb.dev/media/W31mMjd.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝을 약간 바깥으로 둔다.,Step:2 바벨을 등 상부에 올려 승모근 위에 얹는다.,Step:3 코어에 힘을 주고 가슴을 편 채, 무릎과 엉덩이를 굽혀 스쿼트로 내려간다.,Step:4 내려가며 무릎이 바깥으로 향하게 하고 체중은 뒤꿈치에 둔다.,Step:5 허벅지가 바닥과 평행이 될 때까지 내려간다.,Step:6 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jFtipLl', '스미스 스쿼트', 'https://static.exercisedb.dev/media/jFtipLl.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 스미스 머신 바를 스쿼트에 적절한 높이로 세팅한다.,Step:2 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 둔다.,Step:3 바 아래로 들어가 바를 승모근 위에 올린다.,Step:4 바를 어깨너비보다 약간 넓게 잡는다.,Step:5 코어에 힘을 주고 바를 랙에서 빼낸 뒤 뒤로 한 걸음 물러나 랙을 피한다.,Step:6 가슴을 편 채 엉덩이와 무릎을 굽혀 스쿼트를 시작한다.,Step:7 허벅지가 바닥과 평행이 되거나 약간 더 낮아질 때까지 내려간다.,Step:8 바닥 지점에서 잠깐 멈춘다.,Step:9 뒤꿈치로 밀어 시작 자세로 돌아온다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PrQbjvB', '푸쉬 스프린트', 'https://static.exercisedb.dev/media/PrQbjvB.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 푸쉬업 자세에서 시작해 손은 어깨너비로 두고 몸을 일직선으로 만든다.,Step:2 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리되 몸은 곧게 유지한다.,Step:3 손으로 바닥을 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:4 한쪽 무릎을 가슴 쪽으로 빠르게 끌어온다.,Step:5 다리를 빠르게 바꿔 반대쪽 무릎을 가슴 쪽으로 끌어온다.,Step:6 자세를 유지하며 가능한 빠르게 무릎을 번갈아 당기고, 원하는 시간/횟수만큼 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LLNh6q5', '덤벨 인클라인 원 암 짐 볼 위에서 플라이', 'https://static.exercisedb.dev/media/LLNh6q5.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 짐볼 위에 앉아 한 손에 덤벨을 든다.,Step:2 발을 앞으로 걸으며 몸을 굴려 머리/목/등 상부가 볼에 지지되게 한다.,Step:3 덤벨을 가슴 위로 팔을 곧게 펴 들어 올리고 손바닥은 안쪽을 향하게 한다.,Step:4 팔꿈치를 약간 굽힌 채 덤벨을 옆으로 천천히 내려간다.,Step:5 팔이 바닥과 평행이 될 때 잠깐 멈춘다.,Step:6 가슴 근육에 힘을 주어 덤벨을 다시 위로 모아 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yCvYdi7', '케틀벨 원암 밀리터리 프레스(사이드)', 'https://static.exercisedb.dev/media/yCvYdi7.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 케틀벨을 어깨 높이로 든다.,Step:2 코어에 힘을 주고 등을 곧게 유지한다.,Step:3 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uTv34oq', '스탠딩 로우(수건)', 'https://static.exercisedb.dev/media/uTv34oq.gif', '등 위쪽', '등', '맨몸', '이두근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 수건을 양손으로 앞에서 잡는다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:3 수건을 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 장력을 천천히 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('X6ytgYZ', '리어 플라이가 있는 덤벨 사이드 플랭크', 'https://static.exercisedb.dev/media/X6ytgYZ.gif', '등 위쪽', '등', '덤벨', '어깨,코어', 'Step:1 Start by lying on your side with your legs extended and stacked on top of each other.,Step:2 Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.,Step:3 Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.,Step:4 Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.,Step:5 While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.,Step:6 Lower the dumbbell back down to the starting position.,Step:7 Repeat for the desired number of repetitions, then switch sides.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('w4dLzSx', '케이블 원 암 디클라인 체스트 플라이', 'https://static.exercisedb.dev/media/w4dLzSx.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.,Step:2 Lie down on the bench with your head towards the machine and grab the handle with your right hand.,Step:3 Extend your arm straight up above your chest, keeping a slight bend in your elbow.,Step:4 With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.,Step:5 Pause for a moment, then reverse the motion and bring your arm back to the starting position.,Step:6 Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Hx1WC8I', '케이블 인클라인 삼두근 익스텐션', 'https://static.exercisedb.dev/media/Hx1WC8I.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 Adjust the cable machine to a low pulley position.,Step:2 Attach a straight bar to the cable.,Step:3 Stand facing away from the machine with your feet shoulder-width apart.,Step:4 Grasp the bar with an overhand grip and extend your arms straight overhead.,Step:5 Lean forward slightly, keeping your back straight and core engaged.,Step:6 Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.,Step:7 Pause for a moment, then extend your arms back to the starting position.,Step:8 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BCGQ6J5', '케이블 클로즈 그립 컬', 'https://static.exercisedb.dev/media/BCGQ6J5.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 Attach a straight bar to a low pulley cable machine.,Step:2 Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.,Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.,Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.,Step:5 Exhale and curl the bar up towards your shoulders, contracting your biceps.,Step:6 Pause for a moment at the top of the movement, squeezing your biceps.,Step:7 Inhale and slowly lower the bar back to the starting position, fully extending your arms.,Step:8 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GKEH6jj', '케이블 원 암 인클라인 프레스', 'https://static.exercisedb.dev/media/GKEH6jj.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 Adjust the cable machine to a low pulley position.,Step:2 Sit on an incline bench facing away from the cable machine.,Step:3 Grasp the handle with one hand and bring it up to shoulder height.,Step:4 Position your feet firmly on the ground and maintain a stable position.,Step:5 Press the handle forward and upward, extending your arm fully.,Step:6 Pause for a moment at the top, then slowly lower the handle back to the starting position.,Step:7 Repeat for the desired number of repetitions, then switch sides.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dG5Smob', '잡아당기기', 'https://static.exercisedb.dev/media/dG5Smob.gif', '대퇴사두근', '허벅지', '바벨', '햄스트링,둔근,종아리근', 'Step:1 Stand with your feet shoulder-width apart and the barbell on the ground in front of you.,Step:2 Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.,Step:3 Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.,Step:4 As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.,Step:5 As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.,Step:6 Catch the barbell overhead with your arms fully extended and your knees bent.,Step:7 Stand up by extending your hips and knees, keeping the barbell overhead.,Step:8 Lower the barbell back down to the starting position by reversing the movement.,Step:9 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4ievMJ9', '덤벨 앉은 자세로 구부린 자세로 삼두근 익스텐션', 'https://static.exercisedb.dev/media/4ievMJ9.gif', '삼두근', '상완이두근', '덤벨', '어깨,등', 'Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.,Step:2 Bend forward at the waist, keeping your back straight and your head up.,Step:3 Extend your arms straight back, keeping your elbows close to your head.,Step:4 Pause for a moment, then slowly lower the dumbbells back to the starting position.,Step:5 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aXcUyKb', '케틀벨 원암 스내치', 'https://static.exercisedb.dev/media/aXcUyKb.gif', '삼각근', '어깨', '케틀벨', '승모근,전완근,코어', 'Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.,Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.,Step:3 Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.,Step:4 As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.,Step:5 Lower the kettlebell back down between your legs and repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Bg5JKSH', '덤벨 인클라인 한쪽 팔 짐 볼 누르기', 'https://static.exercisedb.dev/media/Bg5JKSH.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.,Step:2 Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.,Step:3 Hold the dumbbell at shoulder height with your palm facing forward.,Step:4 Press the dumbbell upward until your arm is fully extended.,Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.,Step:6 Repeat for the desired number of repetitions, then switch to the other arm.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mExgrF9', '벤치 풀업', 'https://static.exercisedb.dev/media/mExgrF9.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 Position yourself under a bar or a sturdy horizontal surface that is at chest height.,Step:2 Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.,Step:3 Hang with your arms fully extended and your body straight.,Step:4 Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.,Step:5 Continue pulling until your chin is above the bar or surface.,Step:6 Lower yourself back down to the starting position with control.,Step:7 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gEyURal', '바벨 싱글 레그 데드리프트', 'https://static.exercisedb.dev/media/gEyURal.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.,Step:2 Shift your weight onto your left foot and lift your right foot slightly off the ground.,Step:3 Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.,Step:4 Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.,Step:5 Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.,Step:6 Repeat for the desired number of repetitions, then switch sides.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aWedzZX', '벤치 위의 둔부 다리 두 다리(남성)', 'https://static.exercisedb.dev/media/aWedzZX.gif', '둔근', '허벅지', '맨몸', '햄스트링,코어', 'Step:1 Sit on the edge of a bench with your back against it and your feet flat on the ground.,Step:2 Place your hands on the bench beside your hips for support.,Step:3 Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.,Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.,Step:5 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7Ba7bQ2', '케틀벨 투암 클린', 'https://static.exercisedb.dev/media/7Ba7bQ2.gif', '삼각근', '어깨', '케틀벨', '승모근,전완근', 'Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.,Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.,Step:3 Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.,Step:4 As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.,Step:5 Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JsKq9so', '바벨 와이드 벤치 프레스', 'https://static.exercisedb.dev/media/JsKq9so.gif', '가슴근육', '가슴', '바벨', '어깨,삼두근', 'Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.,Step:2 Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.,Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.,Step:4 Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.,Step:5 Pause for a moment when the barbell touches your chest, then push it back up to the starting position.,Step:6 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('53Ttlck', '덤벨 누워서 뒤로 옆으로 올리기', 'https://static.exercisedb.dev/media/53Ttlck.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.,Step:2 Extend your arms straight down towards the floor, keeping a slight bend in your elbows.,Step:3 Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.,Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.,Step:5 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xXm4nYq', '덤벨 디클라인 플라이', 'https://static.exercisedb.dev/media/xXm4nYq.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 Lie on a decline bench with your feet secured and your head lower than your hips.,Step:2 Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.,Step:3 Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.,Step:4 Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.,Step:5 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gscGLOU', '체중 옆으로 누워 바이셉스 컬', 'https://static.exercisedb.dev/media/gscGLOU.gif', '이두근', '상완이두근', '맨몸', '전완근', 'Step:1 Lie on your side with your legs extended and your head supported by your arm.,Step:2 Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.,Step:3 Pause for a moment at the top, then slowly lower your forearm back down to the starting position.,Step:4 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5WiFcYk', '스윙을 이용한 가중 런지', 'https://static.exercisedb.dev/media/5WiFcYk.gif', '둔근', '허벅지', '가중', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨(또는 중량)을 하나씩 든다.,Step:2 오른발을 앞으로 내딛으며 런지 자세로 몸을 낮춘다.,Step:3 앞으로 런지하며 팔을 곧게 편 채 중량을 앞쪽-위쪽으로 스윙한다.,Step:4 오른발로 바닥을 밀어 시작 자세로 돌아오며 중량을 아래로 되돌려 스윙한다.,Step:5 왼발로 반복하고, 원하는 횟수만큼 좌우를 번갈아 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('F7vjXqT', '인클라인 푸쉬업(박스 위)', 'https://static.exercisedb.dev/media/F7vjXqT.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 박스(또는 높인 지지대) 가장자리에 손을 어깨너비보다 약간 넓게 올린다.,Step:2 다리를 뒤로 뻗어 발볼로 지지하고, 머리부터 발뒤꿈치까지 일직선을 만든다.,Step:3 팔꿈치를 굽혀 몸이 일직선을 유지한 채 가슴을 박스 쪽으로 천천히 내린다.,Step:4 바닥에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('v3xmPAR', '레버 장착 플라이', 'https://static.exercisedb.dev/media/v3xmPAR.gif', '가슴근육', '가슴', '레버리지 머신', '삼각근,승모근', 'Step:1 시트 높이를 조절하고 패드에 등을 대고 머신에 앉는다.,Step:2 손잡이를 잡되, 팔꿈치를 약간 굽힌 상태를 유지한다.,Step:3 숨을 내쉬며 손잡이를 앞으로 밀어 가슴 앞에서 서로 모은다.,Step:4 가슴을 조이며 잠깐 멈춘다.,Step:5 숨을 들이마시며 천천히 시작 자세로 돌아가 가슴이 늘어나는 것을 느낀다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yg8Totb', '바벨 머리 뒤쪽에 누워 삼두근 익스텐션', 'https://static.exercisedb.dev/media/yg8Totb.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 눕고 발을 바닥에 고정한 뒤, 머리가 벤치 끝 쪽에 오게 한다.,Step:2 오버핸드 그립으로 바벨을 잡고(어깨너비), 가슴 위로 팔을 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바벨을 머리 뒤쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gxg9lDc', '벤치에서 바벨 롤아웃', 'https://static.exercisedb.dev/media/Gxg9lDc.gif', '복근', '허리', '바벨', '어깨,삼두근', 'Step:1 바닥에 무릎을 꿇고, 앞쪽 벤치 위에 바벨을 올려둔다.,Step:2 바벨을 오버핸드로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 코어를 조이고 등을 곧게 유지한 채 바벨을 앞으로 천천히 굴린다.,Step:4 몸이 충분히 늘어나 팔이 머리 위로 오도록 끝까지 전진한다.,Step:5 끝 지점에서 잠깐 멈춘 뒤, 바벨을 몸 쪽으로 천천히 굴려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eOCOwIR', '덤벨 누워 팔꿈치 프레스', 'https://static.exercisedb.dev/media/eOCOwIR.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 벤치에 누워 양손에 덤벨을 들고, 손바닥이 서로 마주보게 한 채 가슴 위로 팔을 편다.,Step:2 상완을 고정하고 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 내린다.,Step:3 아래에서 잠깐 멈춘 뒤, 팔꿈치를 펴며 덤벨을 다시 밀어 올린다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PG1kcIb', '덤벨 인클라인 해머 프레스', 'https://static.exercisedb.dev/media/PG1kcIb.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 인클라인 벤치를 45도로 세팅하고, 양손에 덤벨을 들고 앉아 허벅지 위에 올린다.,Step:2 벤치에 기대 눕고 덤벨을 어깨 높이로 올리되 손바닥이 서로 마주보게 한다.,Step:3 덤벨을 위-앞쪽으로 밀어 올려 팔을 완전히 편다.,Step:4 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 위치로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OYFhXVD', '와이드 그립 리어 풀업', 'https://static.exercisedb.dev/media/OYFhXVD.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 풀업 바를 어깨너비보다 넓게 오버핸드로 잡는다.,Step:2 팔을 완전히 펴서 매달리고 몸을 곧게 유지한다.,Step:3 가슴을 바 쪽으로 이끈다는 느낌으로 등 근육을 사용해 몸을 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 당긴다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6e2DcYX', '덤벨 인클라인 숄더 레이즈', 'https://static.exercisedb.dev/media/6e2DcYX.gif', '전거근', '가슴', '덤벨', '삼각근,승모근', 'Step:1 인클라인 벤치를 45도로 세팅하고 양손에 덤벨을 들고 앉아 손바닥이 아래를 보게 한다.,Step:2 덤벨을 허벅지에 올린 뒤 벤치에 기대 눕는다.,Step:3 허벅지 힘을 보조로 덤벨을 어깨 높이까지 올린 후, 손목을 돌려 손바닥이 앞을 보게 만든다.,Step:4 숨을 내쉬며 팔꿈치를 살짝 굽힌 채 덤벨을 머리 위로 천천히 들어 올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 숨을 들이마시며 어깨 높이까지 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gtO1ErP', '가중 벤치 딥스 3개', 'https://static.exercisedb.dev/media/gtO1ErP.gif', '삼두근', '상완이두근', '가중', '가슴,어깨', 'Step:1 벤치 가장자리에 앉아 손으로 벤치 끝을 잡고 손가락은 앞으로 향하게 한다.,Step:2 발을 앞으로 걸어 엉덩이를 벤치 밖으로 빼고 팔로 체중을 지지한다.,Step:3 팔꿈치를 굽혀 등을 벤치에 가깝게 유지하며 몸을 내린다.,Step:4 바닥에서 잠깐 멈춘 뒤, 팔로 몸을 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Lt3iWnf', '짐 볼에 덤벨 플라이', 'https://static.exercisedb.dev/media/Lt3iWnf.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐 볼 위에 앉아 양손에 덤벨을 든다.,Step:2 발로 걸어 내려가며 몸을 굴려 머리/목/등 상부가 공에 지지되도록 만든다.,Step:3 덤벨을 가슴 위로 들어 올려 팔을 곧게 펴고 손바닥이 서로 마주보게 한다.,Step:4 팔꿈치를 약간 굽힌 채 양팔을 큰 원을 그리며 옆으로 내려 가슴이 늘어나는 것을 느낀다.,Step:5 잠깐 멈춘 뒤, 가슴을 조이며 덤벨을 다시 시작 위치로 모은다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8fgqP5a', '덤벨 서 원 암 집중 컬', 'https://static.exercisedb.dev/media/8fgqP5a.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 한 손에 덤벨을 들고 손바닥을 위로 향하게 한다.,Step:2 반대손은 허벅지 위에 올려 몸을 지지한다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 이두근이 완전히 수축될 때까지 올려 덤벨이 어깨 높이에 오게 한다.,Step:5 상단에서 잠깐 멈추며 이두근을 강하게 조인다.,Step:6 숨을 들이마시며 덤벨을 천천히 시작 위치로 내린다.,Step:7 원하는 횟수만큼 반복한 뒤 반대팔도 동일하게 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kjJ3VoQ', '크런치(손을 머리 위로 올리기)', 'https://static.exercisedb.dev/media/kjJ3VoQ.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 붙인다.,Step:2 양팔을 머리 위로 곧게 뻗는다.,Step:3 복근에 힘을 주고 상체를 말아 올려 무릎 쪽으로 컬링한다.,Step:4 상단에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('y8bYM8w', '밴드 싱글 레그 스플릿 스쿼트', 'https://static.exercisedb.dev/media/y8bYM8w.gif', '대퇴사두근', '허벅지', '밴드', '둔근,햄스트링', 'Step:1 발목에 저항 밴드를 걸고 발을 엉덩이너비로 벌리고 선다.,Step:2 오른발을 크게 앞으로, 왼발은 작게 뒤로 두어 스플릿 스탠스를 만든다.,Step:3 무릎을 굽혀 내려가며 오른쪽 허벅지가 바닥과 평행해질 때까지 낮추고, 왼쪽 무릎은 바닥 위에서 살짝 띄운다.,Step:4 오른발 뒤꿈치로 밀어 올라와 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('j74M6Zn', '벽에 운동공 종아리 들어올리기(무릎 사이에 테니스공)', 'https://static.exercisedb.dev/media/j74M6Zn.gif', '종아리근', '종아리', '덤벨', '대퇴사두근,햄스트링', 'Step:1 벽에 등을 대고 서서 허리 뒤쪽과 벽 사이에 짐 볼을 끼운다.,Step:2 발을 어깨너비로 두고 몸 앞쪽으로 약간 내민다.,Step:3 양손에 덤벨을 들고 팔은 몸 옆으로 편다.,Step:4 무릎 사이에 테니스공을 끼운다.,Step:5 발뒤꿈치를 들어 올려 발끝으로 몸을 올린다.,Step:6 상단에서 잠깐 멈춘 뒤, 발뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IMRsOCn', '스쿼트 바보', 'https://static.exercisedb.dev/media/IMRsOCn.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근,코어', 'Step:1 바벨을 어깨에 얹고 발을 어깨너비로 벌린다.,Step:2 가슴을 세우고 무릎이 발끝 방향으로 나가게 하며 스쿼트로 내려간다.,Step:3 바닥 지점에서 폭발적으로 일어서며 바벨을 머리 위로 밀어 올린다.,Step:4 바벨이 최고점에 도달하면 재빠르게 스플릿 자세로 내려가 앞발/뒷발로 받친다.,Step:5 팔을 완전히 펴서 바벨을 머리 위에서 고정하고, 뒷무릎은 바닥에 살짝 닿게 한다.,Step:6 스플릿에서 일어나 발을 모아 선다.,Step:7 바벨을 다시 어깨로 내리고 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yq3GAJX', '양손을 반대로 쥐고 원형 발가락 터치(남성)', 'https://static.exercisedb.dev/media/yq3GAJX.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 팔을 옆으로 뻗는다.,Step:2 등을 곧게 유지한 채 엉덩이로 접으며 상체를 앞으로 숙이고 무릎은 약간 굽힌다.,Step:3 양손을 다리 뒤쪽에서 맞잡는다.,Step:4 다리를 곧게 유지하며 손을 원을 그리듯 머리 위로 천천히 올린다.,Step:5 원을 이어가며 손이 발가락에 닿을 때까지 움직인다.,Step:6 동작을 반대로 되돌려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HYe1ZqR', '짐 볼에 덤벨 인클라인 플라이', 'https://static.exercisedb.dev/media/HYe1ZqR.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 짐 볼에 앉아 앞으로 굴려 상부 등이 인클라인 벤치에 지지되도록 만든다.,Step:3 손바닥이 서로 마주보게 덤벨을 들고 가슴 위로 팔을 편다.,Step:4 큰 원을 그리며 덤벨을 옆으로 내려 가슴이 늘어나는 것을 느낀다.,Step:5 잠깐 멈춘 뒤, 가슴을 조이며 덤벨을 시작 위치로 모은다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dB07vDu', '케이블 한쪽 팔 사이드 구부러짐', 'https://static.exercisedb.dev/media/dB07vDu.gif', '가슴근육', '가슴', '케이블', '삼각근,승모근', 'Step:1 케이블 머신을 정면으로 보고 발을 어깨너비로 벌리고 선다.,Step:2 한 손으로 핸들을 잡고 뒤로 물러나 케이블에 긴장을 만든다.,Step:3 등을 곧게 유지한 채 힙힌지로 상체를 앞으로 숙이고 코어에 힘을 준다.,Step:4 팔꿈치를 약간 굽힌 채 팔을 옆으로 뻗어 바닥과 평행하게 만든다.,Step:5 천천히 팔을 시작 위치로 되돌리며 계속 컨트롤한다.,Step:6 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pP8wP2P', '덤벨 뉴트럴 그립 벤치 프레스', 'https://static.exercisedb.dev/media/pP8wP2P.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 벤치에 누워 발을 바닥에 고정하고 등을 벤치에 밀착한다.,Step:2 손바닥이 서로 마주보는 뉴트럴 그립으로 덤벨을 잡고 가슴 위로 팔을 편다.,Step:3 팔꿈치를 몸통 쪽으로 가깝게 유지하며 덤벨을 가슴 쪽으로 천천히 내린다.,Step:4 바닥에서 잠깐 멈춘 뒤, 덤벨을 다시 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wi2H9QX', '스미스 와이드 그립 디클라인 벤치 프레스', 'https://static.exercisedb.dev/media/wi2H9QX.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 디클라인 벤치를 원하는 각도로 조절한다.,Step:2 벤치에 누워 발을 고정 패드 아래에 끼운다.,Step:3 바를 어깨너비보다 넓게 잡는다.,Step:4 바를 걸이에서 풀고 가슴 쪽으로 천천히 내리며 팔꿈치를 바깥으로 향하게 한다.,Step:5 바가 가슴에 닿는 지점에서 잠깐 멈춘다.,Step:6 팔을 펴며 바를 위로 밀어 올려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G70mEAJ', '턱걸이(좁은 평행 그립)', 'https://static.exercisedb.dev/media/G70mEAJ.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 평행(뉴트럴) 좁은 그립으로 풀업 바를 잡고 손바닥이 서로 마주보게 한다.,Step:2 등 근육에 힘을 주고 팔꿈치를 몸통에 가깝게 유지하며 몸을 끌어올린다.,Step:3 턱이 바 위로 올라갈 때까지 당긴다.,Step:4 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HJ63mSO', '바벨 라이딩 클로즈 그립 삼두근 익스텐션', 'https://static.exercisedb.dev/media/HJ63mSO.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 눕고 발을 바닥에 고정하되 머리가 벤치 끝 쪽에 오게 한다.,Step:2 손바닥이 위를 보게 클로즈 그립(어깨너비)으로 바벨을 잡고 가슴 위로 팔을 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바벨을 이마 쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KHPZL0b', '케이블 대체 숄더 프레스', 'https://static.exercisedb.dev/media/KHPZL0b.gif', '삼각근', '어깨', '케이블', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 케이블 머신의 핸들을 오버핸드로 잡는다.,Step:2 손을 어깨 높이에 두고 손바닥이 앞을 보게 한다.,Step:3 코어에 힘을 주고 등을 곧게 유지한다.,Step:4 한쪽 핸들을 위-앞쪽으로 밀어 팔을 완전히 편다.,Step:5 상단에서 잠깐 멈춘 뒤, 핸들을 천천히 시작 위치로 내린다.,Step:6 반대팔로 반복한다.,Step:7 좌우를 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vYk8lqw', '덤벨 인클라인 리어 레터럴 레이즈', 'https://static.exercisedb.dev/media/vYk8lqw.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 가슴을 등받이에 대고 앉아 양손에 덤벨을 든다.,Step:3 손바닥이 서로 마주보게 팔을 아래로 뻗어 덤벨을 늘어뜨린다.,Step:4 팔꿈치를 약간 굽힌 채 양팔을 옆으로 들어 올려 바닥과 평행하게 만든다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RKjH6Lt', '사이드 브릿지 v. 2', 'https://static.exercisedb.dev/media/RKjH6Lt.gif', '복근', '허리', '맨몸', '복사근,둔근', 'Step:1 옆으로 누워 다리를 곧게 펴고 위아래로 포개어 둔다.,Step:2 아래쪽 팔뚝을 어깨 바로 아래에 두고 팔꿈치를 90도로 굽혀 바닥에 둔다.,Step:3 코어에 힘을 주고 엉덩이를 들어 머리부터 발까지 일직선을 만든다.,Step:4 원하는 시간 동안 자세를 유지한다.,Step:5 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:6 반대쪽도 동일하게 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CQHoDm0', 'ez 바벨 디클라인 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/CQHoDm0.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 디클라인 벤치에 누워 머리가 발보다 낮게 오도록 하고 발을 고정한다.,Step:2 오버핸드 그립(어깨너비)으로 EZ바를 잡는다.,Step:3 팔을 완전히 펴고 팔꿈치를 머리 가까이 유지한다.,Step:4 팔꿈치를 굽혀 바를 이마 쪽으로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6HmFgmx', '서서 종아리 들기(계단에서)', 'https://static.exercisedb.dev/media/6HmFgmx.gif', '종아리근', '종아리', '맨몸', '발목,피트', 'Step:1 계단(또는 단단한 받침) 끝에 서서 발뒤꿈치를 밖으로 빼고 발앞꿈치로 지지한다.,Step:2 필요하면 난간이나 벽을 잡아 균형을 유지한다.,Step:3 발뒤꿈치를 천천히 최대한 높이 들어 올려 발볼로 체중을 실는다.,Step:4 상단에서 잠깐 멈춘 뒤, 발뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vBNyir7', 'ez 바벨 리버스 그립 프리처 컬', 'https://static.exercisedb.dev/media/vBNyir7.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 프리처 벤치에 앉아 가슴을 패드에 대고 발을 바닥에 둔다.,Step:2 언더핸드(역그립)로 EZ바를 어깨너비로 잡는다.,Step:3 상완을 패드에 고정하고 팔뚝이 아래로 늘어지게 둔다.,Step:4 상완을 움직이지 않고 숨을 내쉬며 바를 어깨 쪽으로 말아 올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 숨을 들이마시며 천천히 바를 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FVM1AUZ', '레버 T바 리버스 그립 로우', 'https://static.exercisedb.dev/media/FVM1AUZ.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 시트 높이를 조절하고 가슴을 패드에 대고 발을 바닥에 고정한다.,Step:2 손잡이를 오버핸드로 어깨너비보다 약간 넓게 잡는다.,Step:3 등을 곧게 유지하고 코어에 힘을 준다.,Step:4 손잡이를 가슴 쪽으로 당기며 견갑골을 모아 등 근육을 조인다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 팔을 펴서 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6FMU51h', '세미 스쿼트 점프(남자)', 'https://static.exercisedb.dev/media/6FMU51h.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽혀 스쿼트처럼 반쯤 내려간다.,Step:3 팔 스윙을 활용해 엉덩이와 무릎을 펴며 폭발적으로 점프한다.,Step:4 발볼로 부드럽게 착지한 뒤 곧바로 다음 반복으로 이어간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qKBpF7I', '바벨 글루트 브릿지', 'https://static.exercisedb.dev/media/qKBpF7I.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 붙인다.,Step:2 바벨을 골반 위에 올리고 양손으로 단단히 고정한다.,Step:3 둔근과 코어에 힘을 준 뒤 엉덩이를 들어 올려 무릎-어깨가 일직선이 되게 만든다.,Step:4 상단에서 둔근을 조이며 잠깐 멈춘다.,Step:5 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UVL20oz', '오티스 업', 'https://static.exercisedb.dev/media/UVL20oz.gif', '복근', '허리', '가중', '고관절 굴근,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 붙인다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도까지 올라오게 한다.,Step:4 상단에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VQ3sNCn', '한쪽 팔로 앉은 덤벨 리베이트', 'https://static.exercisedb.dev/media/VQ3sNCn.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 발을 바닥에 두고 한 손에 덤벨을 든다.,Step:2 등을 곧게 유지한 채 허리에서 상체를 앞으로 숙여 바닥과 평행에 가깝게 만든다.,Step:3 팔꿈치를 몸통에 붙이고 팔을 뒤로 뻗어 완전히 편다.,Step:4 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 위치로 내린다.,Step:5 원하는 횟수만큼 반복한 뒤 반대팔로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('j9Q5crt', '스텝 밀 (천국의 계단)', 'https://static.exercisedb.dev/media/j9Q5crt.gif', '심혈관계', '유산소', '스텝밀 기계', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 스텝밀 머신을 편한 강도로 설정한다.,Step:2 머신에 올라가 필요하면 손잡이를 잡고 균형을 잡는다.,Step:3 한 발씩 계단을 오르듯 번갈아 디딘다.,Step:4 상체를 세우고 코어에 힘을 준다.,Step:5 원하는 시간(또는 거리)만큼 지속한다.,Step:6 익숙해지면 강도나 속도를 점진적으로 올린다.,Step:7 운동 후에는 천천히 마무리하고 스트레칭한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LsZkfU6', '바벨 리버스 리스트 컬', 'https://static.exercisedb.dev/media/LsZkfU6.gif', '전완근', '팔 아래', '바벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 두고, 손바닥이 아래를 보게 오버핸드로 바벨을 잡는다.,Step:2 팔뚝을 허벅지 위에 올려 지지하고 손목이 끝에서 밖으로 나오게 한다.,Step:3 손목을 말아 올려 바벨을 몸 쪽으로 끌어올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 바벨을 천천히 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('f38OEuO', '무릎꿇고 랫스트레칭', 'https://static.exercisedb.dev/media/f38OEuO.gif', '광배근', '등', '맨몸', '어깨,삼두근', 'Step:1 무릎을 엉덩이너비로 벌리고 발끝을 뒤로 향하게 한 채 바닥에 무릎을 꿇는다.,Step:2 팔을 머리 위로 들어 올리고 손가락을 깍지 낀다.,Step:3 등을 곧게 유지한 상태에서 상체를 천천히 오른쪽으로 기울여 왼쪽 광배근이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한 뒤 시작 자세로 돌아온다.,Step:5 이번에는 왼쪽으로 기울여 오른쪽 광배근이 늘어나는 것을 느끼며 스트레칭한다.,Step:6 원하는 횟수만큼 좌우로 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6CKUx7o', 'ez 바 누워서 머리 뒤로 클로즈 그립 삼두근 익스텐션', 'https://static.exercisedb.dev/media/6CKUx7o.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 벤치에 누워 발을 바닥에 고정하고 머리가 벤치 끝 쪽에 오게 한다.,Step:2 손바닥이 위를 보게 클로즈 그립으로 EZ바를 잡고 가슴 위로 팔을 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바를 머리 뒤쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DEEqoI2', '후경골근 스트레칭', 'https://static.exercisedb.dev/media/DEEqoI2.gif', '종아리근', '종아리', '로프', '햄스트링,대퇴사두근', 'Step:1 다리를 앞으로 곧게 뻗은 채 바닥에 앉는다.,Step:2 로프를 발앞쪽 볼 부분에 걸고 양손으로 로프의 양끝을 잡는다.,Step:3 로프를 천천히 몸쪽으로 당겨 발을 굽히며 종아리 근육이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 로프의 긴장을 풀고 발을 편안하게 둔다.,Step:6 반대쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rQhGcin', '프로그 플란체', 'https://static.exercisedb.dev/media/rQhGcin.gif', '복근', '허리', '맨몸', '어깨,가슴,삼두근', 'Step:1 손을 어깨너비로 두고 푸쉬업 시작 자세를 만든다.,Step:2 팔꿈치를 굽혀 등을 곧게 유지한 채 몸을 아래로 내린다.,Step:3 내려가면서 발을 바닥에서 떼고 무릎을 가슴 쪽으로 끌어당긴다.,Step:4 몇 초간 자세를 유지한다.,Step:5 다리를 다시 뻗고 팔로 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('v1qBec9', '덤벨 리어 레터럴 레이즈', 'https://static.exercisedb.dev/media/v1qBec9.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 무릎을 약간 굽히고 엉덩이로 접어 상체를 앞으로 숙이되 등을 곧게 유지하고 코어에 힘을 준다.,Step:3 팔꿈치를 살짝 굽힌 채 양팔을 옆으로 들어 올려 바닥과 평행하게 만든다.,Step:4 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ufaxB52', '밴드 클로즈 그립 푸쉬업', 'https://static.exercisedb.dev/media/ufaxB52.gif', '삼두근', '상완이두근', '밴드', '가슴,어깨', 'Step:1 팔꿈치 바로 위 상완에 밴드를 둘러 고정한다.,Step:2 손을 어깨 바로 아래에 두고 푸쉬업 자세를 만들어 머리부터 발까지 일직선을 유지한다.,Step:3 팔꿈치를 몸통에 붙인 채 굽혀 가슴을 바닥 쪽으로 내린다.,Step:4 손바닥으로 바닥을 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BkxB8LW', '케틀벨 시티드 프레스', 'https://static.exercisedb.dev/media/BkxB8LW.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 양손에 케틀벨을 들고 어깨 높이에서 손바닥이 앞을 보게 한다.,Step:3 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 케틀벨을 어깨 높이로 다시 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bpJL2Qs', '덤벨 프로네이트 그립 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/bpJL2Qs.gif', '삼두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치나 의자에 앉아 등을 곧게 세우고 발을 바닥에 둔다.,Step:2 손바닥이 아래를 보게(프로네이트) 양손으로 덤벨을 잡고 머리 위로 팔을 편다.,Step:3 상완을 머리 옆에 붙이고 팔꿈치가 앞을 보게 유지한다.,Step:4 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FkBIE6a', '덤벨 거짓말 대퇴골', 'https://static.exercisedb.dev/media/FkBIE6a.gif', '햄스트링', '허벅지', '덤벨', '둔근', 'Step:1 등을 대고 누워 다리를 뻗고, 덤벨을 아랫배(골반 위) 쪽에 올린다.,Step:2 무릎을 굽혀 덤벨이 둔근 쪽으로 가까워지게 한다(발은 바닥에 둔다).,Step:3 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 위치로 내린다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('K1vlode', '높은 평행봉에서 웨이트 트라이셉스 딥', 'https://static.exercisedb.dev/media/K1vlode.gif', '삼두근', '상완이두근', '가중', '가슴,어깨', 'Step:1 평행봉 사이에 몸을 위치시키고 팔을 완전히 펴서 지지한다.,Step:2 팔꿈치를 굽혀 몸을 내려 상완이 바닥과 평행해질 때까지 내린다.,Step:3 아래에서 잠깐 멈춘 뒤, 손바닥으로 밀어 팔을 펴며 올라온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qx4fgX7', '덤벨 싱글 레그 스플릿 스쿼트', 'https://static.exercisedb.dev/media/qx4fgX7.gif', '대퇴사두근', '허벅지', '덤벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 양손에 덤벨을 든다.,Step:2 한 발을 앞으로 두고, 뒷발은 벤치나 스텝 위에 올려 스플릿 자세를 만든다.,Step:3 앞쪽 무릎과 고관절을 굽혀 내려가며 뒷무릎은 약간 굽힌 채 뒷꿈치는 들린 상태를 유지한다.,Step:4 앞쪽 허벅지가 바닥과 평행해질 때까지 내려간 뒤, 앞발 뒤꿈치로 밀어 올라온다.,Step:5 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mweqJin', '스프린트 풋워크 v. 2', 'https://static.exercisedb.dev/media/mweqJin.gif', '대퇴사두근', '허벅지', '맨몸', '종아리근,햄스트링', 'Step:1 발을 어깨너비로 벌리고 팔은 몸 옆에 둔 채 선다.,Step:2 제자리에서 달리듯 발을 빠르게 번갈아 디딘다.,Step:3 발볼로 가볍게 튕기듯 움직이며 속도를 유지한다.,Step:4 원하는 시간 또는 횟수만큼 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DsgkuIt', '덤벨 래터럴 레이즈', 'https://static.exercisedb.dev/media/DsgkuIt.gif', '삼각근', '어깨', '덤벨', '승모근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 등을 곧게 세우고 코어에 힘을 준다.,Step:3 팔꿈치를 약간 굽힌 채 양팔을 옆으로 들어 올려 바닥과 평행하게 만든다.,Step:4 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9E25EOx', '스플릿 스쿼트', 'https://static.exercisedb.dev/media/9E25EOx.gif', '대퇴사두근', '허벅지', '맨몸', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 한 발을 앞으로 내딛어 앞뒤 발 간격을 약 2피트 정도로 만든다.,Step:3 등을 곧게 유지한 채 무릎과 엉덩이를 굽혀 몸을 내린다.,Step:4 앞쪽 허벅지가 바닥과 평행해지고 뒷무릎이 바닥 바로 위에 올 때까지 내려간다.,Step:5 아래에서 잠깐 멈춘 뒤, 앞발 뒤꿈치로 밀어 올라온다.,Step:6 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LIGZSTA', '덤벨 원 암 엎드린 해머 컬', 'https://static.exercisedb.dev/media/LIGZSTA.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 평벤치에 엎드려 한 손에 덤벨을 들고 손바닥이 몸을 향하게(해머 그립) 하며 팔을 아래로 늘어뜨린다.,Step:2 상완을 고정한 채 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:3 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 위치로 내린다.,Step:4 원하는 횟수만큼 반복한 뒤 반대팔로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Mz6lLcW', '바이셉 컬을 이용한 덤벨 런지', 'https://static.exercisedb.dev/media/Mz6lLcW.gif', '이두근', '상완이두근', '덤벨', '대퇴사두근,햄스트링', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥을 앞쪽으로 향하게 한다.,Step:2 오른발을 앞으로 내딛으며 런지로 내려가는데, 오른쪽 무릎은 90도, 왼쪽 무릎은 바닥 바로 위에 오게 한다.,Step:3 런지로 내려가면서 동시에 덤벨을 어깨 쪽으로 컬링하되 팔꿈치를 몸통에 가깝게 둔다.,Step:4 런지 바닥에서 잠깐 멈춘 뒤, 오른발 뒤꿈치로 밀어 올라오며 덤벨을 다시 옆으로 내린다.,Step:5 왼발로도 동일하게 런지+컬을 수행한다.,Step:6 좌우를 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2kattbR', 'ez 바벨 스파이더 컬', 'https://static.exercisedb.dev/media/2kattbR.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 언더핸드로 EZ바를 잡는다.,Step:2 상완을 프리처 벤치나 스태빌리티 볼에 올려 팔꿈치가 아래로 향하게 둔다.,Step:3 상완을 고정한 채 숨을 내쉬며 바를 어깨 쪽으로 말아 올린다.,Step:4 상단에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 천천히 바를 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eGDudUV', '케이블 데드리프트', 'https://static.exercisedb.dev/media/eGDudUV.gif', '둔근', '허벅지', '케이블', '햄스트링,대퇴사두근,허리', 'Step:1 케이블 머신을 정면으로 보고 발을 어깨너비로 벌린다.,Step:2 엉덩이와 무릎을 굽혀 상체를 낮추고 등을 바닥과 거의 평행하게 만든다.,Step:3 팔을 곧게 편 채 오버핸드로 핸들을 잡고 어깨를 뒤로 둔다.,Step:4 둔근과 햄스트링에 힘을 줘 일어서며 케이블을 끌어올려 힙을 완전히 편다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aHDy5O5', '밴드 y-레이즈', 'https://static.exercisedb.dev/media/aHDy5O5.gif', '삼각근', '어깨', '밴드', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 서서 밴드를 허벅지 앞쪽에서 잡되 손바닥이 안쪽을 보게 한다.,Step:2 팔을 곧게 편 채 바깥-위쪽으로 들어 올려 몸이 \'Y\' 모양이 되게 한다.,Step:3 상단에서 견갑골을 모아 어깨를 조인다.,Step:4 팔을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Qyk5J3p', '덤벨 크로스 바디 해머 컬', 'https://static.exercisedb.dev/media/Qyk5J3p.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 똑바로 서서 손바닥이 몸을 향하게 한다.,Step:2 팔꿈치를 몸통에 붙이고 상완을 고정한다.,Step:3 숨을 내쉬며 덤벨을 해머 그립으로 말아 올리되, 반대쪽 어깨 방향으로 대각선으로 들어 올린다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오면 잠깐 멈춘다.,Step:5 숨을 들이마시며 덤벨을 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zCgxPbV', '케이블 트위스트 풀', 'https://static.exercisedb.dev/media/zCgxPbV.gif', '광배근', '등', '케이블', '어깨,이두근', 'Step:1 로우 풀리(하단)에 핸들을 연결하고 머신을 정면으로 보고 선다.,Step:2 왼손으로 핸들을 잡고 머신에서 멀어져 팔이 완전히 펴지게 한다.,Step:3 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 핸들을 몸쪽으로 당기며 상체를 오른쪽으로 회전한다.,Step:6 끝 지점에서 등 근육을 조인다.,Step:7 케이블 긴장을 유지하며 천천히 시작 자세로 돌아온다.,Step:8 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4LoWllp', '밴드 고정 백 클로즈 그립 풀다운', 'https://static.exercisedb.dev/media/4LoWllp.gif', '광배근', '등', '밴드', '이두근,전완근', 'Step:1 풀업 바나 단단한 고정점처럼 머리 위 높은 곳에 밴드를 고정한다.,Step:2 밴드를 마주보고 벤치/의자에 앉아 발을 바닥에 두고 무릎을 굽힌다.,Step:3 손바닥이 서로 마주보게 클로즈 그립으로 밴드를 잡는다.,Step:4 등을 곧게 세우고 코어에 힘을 준다.,Step:5 밴드를 가슴 쪽으로 당기며 견갑골을 모아 광배근을 수축한다.,Step:6 바닥에서 잠깐 멈추며 수축을 느낀다.,Step:7 밴드를 천천히 놓아 시작 자세로 돌아가되 계속 컨트롤한다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gvsWLQw', '덤벨 컨센트레이션 컬', 'https://static.exercisedb.dev/media/gvsWLQw.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 다리를 벌리고 한 손에 덤벨을 든 뒤, 팔꿈치를 허벅지 안쪽에 대어 지지한다.,Step:2 팔을 완전히 펴고 언더핸드로 덤벨을 잡는다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오면 잠깐 멈춘다.,Step:5 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 덤벨을 천천히 내린다.,Step:7 원하는 횟수만큼 반복한 뒤 반대팔로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bdWcbaU', '프랑켄슈타인 스쿼트', 'https://static.exercisedb.dev/media/bdWcbaU.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 팔을 곧게 편 채 바벨을 몸 앞쪽에 든다.,Step:2 등을 곧게 유지한 채 무릎과 엉덩이를 굽혀 의자에 앉듯 내려간다.,Step:3 허벅지가 바닥과 평행해질 때까지(가능한 범위에서) 내려간다.,Step:4 잠깐 멈춘 뒤, 뒤꿈치로 밀어 올라와 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('13VW2VO', '웨이티드 스트레치 런지', 'https://static.exercisedb.dev/media/13VW2VO.gif', '둔근', '허벅지', '가중', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 오른발을 앞으로 내딛고 등을 곧게 유지한다.,Step:3 무릎을 굽혀 내려가며 오른쪽 허벅지가 바닥과 평행해질 때까지 내린다.,Step:4 오른발 뒤꿈치로 밀어 올라와 시작 자세로 돌아온다.,Step:5 왼발로 반복한다.,Step:6 좌우를 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eXMFHww', '지뢰 사이드 상승', 'https://static.exercisedb.dev/media/eXMFHww.gif', '삼각근', '어깨', '바벨', '승모근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:2 오버핸드로 바벨을 잡고 앞쪽 어깨에 가깝게 둔다.,Step:3 코어에 힘을 주고 등을 곧게 유지한다.,Step:4 바벨을 위-바깥쪽으로 들어 올려 어깨 높이까지 올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('R1WYG5D', '서스펜디드 리버스 크런치', 'https://static.exercisedb.dev/media/R1WYG5D.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 오버핸드로 풀업 바에 매달려 팔을 완전히 편다.,Step:2 코어에 힘을 주고 무릎을 가슴 쪽으로 들어 올리며 골반을 말아 올린다.,Step:3 상단에서 잠깐 멈춘 뒤, 무릎을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LrV4s90', '케이블 손목 컬', 'https://static.exercisedb.dev/media/LrV4s90.gif', '전완근', '팔 아래', '케이블', '이두근,상완근', 'Step:1 로우 풀리 케이블에 스트레이트 바를 연결한다.,Step:2 머신을 정면으로 보고 발을 어깨너비로 벌리고 선다.,Step:3 언더핸드로 바를 어깨너비로 잡고 손바닥을 위로 향하게 한다.,Step:4 팔뚝을 벤치나 패드 위에 올려 지지하고 손목이 끝에서 밖으로 나오게 한다.,Step:5 팔뚝을 고정한 채 숨을 내쉬며 손목을 말아 올린다.,Step:6 상단에서 잠깐 멈춘 뒤, 숨을 들이마시며 천천히 내린다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dCJnuVq', '3점 자세에서 메디신 볼 가슴 밀기', 'https://static.exercisedb.dev/media/dCJnuVq.gif', '가슴근육', '가슴', '메디신볼', '어깨,삼두근', 'Step:1 한 손은 메디신볼 위에, 다른 손은 바닥에 두고 3점 지지 자세를 만든다.,Step:2 다리를 뻗어 몸이 일직선이 되게 한다.,Step:3 등을 곧게 유지한 채 가슴을 바닥 쪽으로 내린다.,Step:4 메디신볼을 손으로 밀어내듯 강하게 밀어 팔을 완전히 편다.,Step:5 시작 자세로 돌아와 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3XFdb1Z', '케이블 스쿼트 컬', 'https://static.exercisedb.dev/media/3XFdb1Z.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신 하단에 핸들을 연결한다.,Step:2 머신을 정면으로 보고 발을 어깨너비로 벌리고 선다.,Step:3 언더핸드로 핸들을 잡고 팔을 완전히 편다.,Step:4 등을 곧게 유지하고 무릎이 발끝을 넘지 않게 하며 스쿼트로 내려간다.,Step:5 내려가면서 동시에 핸들을 어깨 쪽으로 컬링하되 팔꿈치를 몸통에 붙인다.,Step:6 컬 상단에서 잠깐 멈추며 이두근을 조인다.,Step:7 핸들을 천천히 내려 팔을 펴고 시작 자세로 돌아온다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SzX3uzM', '바벨 리버스 그립 벤트 오버 로우', 'https://static.exercisedb.dev/media/SzX3uzM.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:2 오버핸드로 바벨을 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 엉덩이로 접어 상체를 앞으로 숙여 몸통이 바닥과 거의 평행해지게 하고, 가슴을 편다.,Step:4 바벨을 아랫가슴 쪽으로 당기며 견갑골을 모아 등 근육을 조인다.,Step:5 상단에서 잠깐 멈춘 뒤, 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ky8FLU8', '레버 리버스 그립 사이드 풀다운', 'https://static.exercisedb.dev/media/ky8FLU8.gif', '광배근', '등', '레버리지 머신', '이두근,능형근,후면 삼각근', 'Step:1 시트 높이를 조절하고 무릎을 패드 아래에 넣고 발을 바닥에 둔다.,Step:2 손잡이를 오버핸드로 어깨너비보다 약간 넓게 잡는다.,Step:3 가슴을 내밀고 어깨를 뒤로 두며 허리에 약간의 아치를 유지한다.,Step:4 팔꿈치를 이끌며 손잡이를 가슴 쪽으로 당겨 견갑골을 모은다.,Step:5 바닥에서 잠깐 멈춘 뒤, 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UVo2Qs2', '펄럭이는 차기', 'https://static.exercisedb.dev/media/UVo2Qs2.gif', '둔근', '허벅지', '맨몸', '고관절 굴근,하복근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔은 몸 옆에 둔다.,Step:2 코어에 힘을 주고 다리를 바닥에서 약 15cm 정도 들어 올린다.,Step:3 다리를 곧게 유지한 채 한쪽 다리를 조금 더 올리고 다른 쪽은 조금 내리며 교대로 움직인다.,Step:4 원하는 횟수만큼 이 동작을 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('i5cEhka', '푸시업 거부', 'https://static.exercisedb.dev/media/i5cEhka.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 손은 어깨너비보다 약간 넓게 바닥에 두고, 발은 안정된 높은 지지대 위에 올린다.,Step:2 머리부터 발끝까지 일직선을 유지하며 코어에 힘을 준다.,Step:3 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리되 팔꿈치는 몸통에 가깝게 둔다.,Step:4 손바닥으로 바닥을 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Qqi7bko', '와이드 그립 풀업', 'https://static.exercisedb.dev/media/Qqi7bko.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 손바닥이 바깥을 보게 어깨너비보다 넓게 풀업 바를 잡는다.,Step:2 코어에 힘을 주고 견갑골을 모아 준비한다.,Step:3 몸을 끌어올려 턱이 바 위로 올라가게 한다.,Step:4 컨트롤하며 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1V1gj1u', '바벨 싯티드 클로즈 그립 컨센트레이션 컬', 'https://static.exercisedb.dev/media/1V1gj1u.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 언더핸드로 바벨을 어깨너비로 잡는다.,Step:2 상완을 허벅지 안쪽(무릎 바로 위)에 밀착해 지지하고 바벨을 아래로 늘어뜨린다.,Step:3 상완을 고정한 채 숨을 내쉬며 바벨을 어깨 쪽으로 말아 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 숨을 들이마시며 천천히 바벨을 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qg2PGl6', '바벨 글루트 브릿지 벤치 위의 두 다리(남성)', 'https://static.exercisedb.dev/media/qg2PGl6.gif', '둔근', '허벅지', '바벨', '햄스트링,코어', 'Step:1 벤치 가장자리에 앉아 등 상부를 벤치에 대고, 발은 바닥에 엉덩이너비로 둔다.,Step:2 바벨을 골반 위에 올리고 양손으로 단단히 고정한다.,Step:3 둔근과 코어에 힘을 주고 뒤꿈치로 밀어 엉덩이를 들어 올려 무릎-어깨가 일직선이 되게 한다.,Step:4 상단에서 둔근을 조이며 잠깐 멈춘다.,Step:5 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wEulIzp', '케이블 원 암 사이드 들어올리기', 'https://static.exercisedb.dev/media/wEulIzp.gif', '삼각근', '어깨', '케이블', '승모근,삼두근', 'Step:1 케이블 머신을 옆에 두고 발을 어깨너비로 벌리고 선다.,Step:2 한 손으로 핸들을 잡고 손바닥이 아래를 보게 한다.,Step:3 케이블에 긴장이 생기도록 머신에서 충분히 떨어진다.,Step:4 팔을 곧게 유지한 채 옆으로 들어 올려 바닥과 평행하게 만든다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1kB3Wmk', '덤벨 싱글 레그 종아리 들어올리기', 'https://static.exercisedb.dev/media/1kB3Wmk.gif', '종아리근', '종아리', '덤벨', '발목', 'Step:1 계단/플랫폼 끝에 한 발로 서서 뒤꿈치는 밖으로 빼고 발앞꿈치로 지지한다.,Step:2 한 손에 덤벨을 들고, 반대손은 벽이나 난간에 대어 균형을 잡는다.,Step:3 뒤꿈치를 최대한 들어 올려 발볼로 몸을 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한 뒤 반대발로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1qrWgZ2', '덤벨 디클라인 해머 프레스', 'https://static.exercisedb.dev/media/1qrWgZ2.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 발을 고정하고 머리가 골반보다 낮게 오게 한다.,Step:2 손바닥이 서로 마주보게 덤벨을 들고 가슴 위로 팔을 편다.,Step:3 팔꿈치를 약간 굽힌 채 덤벨을 가슴 양옆으로 천천히 내린다.,Step:4 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9pQSkH8', '덤벨 리버스 그립 인클라인 벤치 투 암 로우', 'https://static.exercisedb.dev/media/9pQSkH8.gif', '등 위쪽', '등', '덤벨', '이두근,전완근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 가슴을 등받이에 대고 앉아 발을 바닥에 둔다.,Step:3 언더핸드(리버스 그립)로 양손에 덤벨을 든다.,Step:4 상체를 앞으로 기울여 팔을 아래로 늘어뜨려 완전히 편다.,Step:5 덤벨을 가슴 쪽으로 당기며 견갑골을 모아 등 근육을 조인다.,Step:6 상단에서 잠깐 멈춘 뒤, 덤벨을 천천히 내린다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('c8f5cSY', '옆으로 누운 고관절 내전(남성)', 'https://static.exercisedb.dev/media/c8f5cSY.gif', '내전근', '허벅지', '맨몸', '둔근,햄스트링', 'Step:1 옆으로 누워 다리를 곧게 펴고 위아래로 포개어 둔다.,Step:2 아래쪽 팔은 머리 아래에 두어 지지한다.,Step:3 내전근에 힘을 주고 위쪽 다리를 골반이 돌아가지 않게 유지한 채 최대한 들어 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 다리를 천천히 내린다.,Step:5 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kuXhl0o', '케틀벨 해적 만찬 다리', 'https://static.exercisedb.dev/media/kuXhl0o.gif', '삼각근', '어깨', '케틀벨', '삼두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 케틀벨을 든다.,Step:2 무릎을 약간 굽히고 엉덩이로 접어 상체를 앞으로 숙이되 등을 곧게 유지한다.,Step:3 팔꿈치를 몸통에 가깝게 두고 케틀벨을 어깨 높이까지 끌어올린다.,Step:4 팔을 완전히 펴서 머리 위로 들어 올린다.,Step:5 케틀벨을 어깨 높이로 다시 내린 뒤 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('H6ETwO9', '밴드 브이업', 'https://static.exercisedb.dev/media/H6ETwO9.gif', '복근', '허리', '밴드', '고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 양팔을 머리 위로 뻗은 채 밴드를 잡는다.,Step:2 복근에 힘을 주고 다리와 상체를 동시에 들어 올리며 손을 발가락 쪽으로 뻗는다.,Step:3 상단에서 잠깐 멈춘 뒤, 다리와 상체를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('f4xtKBj', '보조 스탠딩 풀업', 'https://static.exercisedb.dev/media/f4xtKBj.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 머신을 원하는 무게와 높이로 설정한다.,Step:2 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:3 손잡이를 오버핸드로 어깨너비보다 약간 넓게 잡는다.,Step:4 광배근과 이두근에 힘을 주며 몸을 위로 끌어올린다.,Step:5 상단에서 등 근육을 조이며 잠깐 멈춘다.,Step:6 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7xI5MXA', '케이블 벤치 프레스', 'https://static.exercisedb.dev/media/7xI5MXA.gif', '가슴근육', '가슴', '케이블', '삼두근,어깨', 'Step:1 케이블을 가슴 높이로 맞추고 핸들을 연결한다.,Step:2 머신을 등지고 발을 어깨너비로 벌린다.,Step:3 오버핸드로 핸들을 잡고 앞으로 한 걸음 나가 케이블 긴장을 만든다.,Step:4 발을 단단히 고정하고 코어에 힘을 준다.,Step:5 팔꿈치를 굽혀 손을 어깨 높이로 가져오며 팔꿈치를 90도로 유지한다.,Step:6 핸들을 앞으로 밀어 팔을 완전히 편다.,Step:7 잠깐 멈춘 뒤, 천천히 되돌려 손을 어깨 높이로 가져온다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('99rWm7w', '햄스트링 스트레칭', 'https://static.exercisedb.dev/media/99rWm7w.gif', '햄스트링', '허벅지', '맨몸', '둔근', 'Step:1 발을 어깨너비로 벌려 선다.,Step:2 오른발을 앞으로 내딛고 몸의 중심을 오른쪽 다리에 둔다.,Step:3 등을 곧게 유지한 채 엉덩이를 기준으로 상체를 천천히 앞으로 굽히며 양손으로 오른발 쪽을 향해 뻗는다.,Step:4 20–30초 동안 유지한 뒤 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('trqKQv2', '스미스 벤치프레스', 'https://static.exercisedb.dev/media/trqKQv2.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 스미스 바 높이를 가슴 높이로 맞춘다.,Step:2 벤치에 누워 발을 바닥에 단단히 고정한다.,Step:3 바를 어깨너비보다 약간 넓게 오버핸드로 잡는다.,Step:4 바를 걸이에서 풀고 가슴 쪽으로 천천히 내리며 팔꿈치를 몸통에 가깝게 둔다.,Step:5 바가 가슴에 닿는 지점에서 잠깐 멈춘다.,Step:6 팔을 펴며 바를 밀어 올려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('I3tsCnC', '매달린 다리 올리기', 'https://static.exercisedb.dev/media/I3tsCnC.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 오버핸드로 풀업 바에 매달려 팔을 완전히 편다.,Step:2 코어에 힘을 주고 다리를 앞으로 들어 올리되 무릎을 펴서 유지한다.,Step:3 다리가 바닥과 평행해질 때(또는 가능한 범위까지) 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4hATdoB', '케이블 로프 원 암 해머 설교자 컬', 'https://static.exercisedb.dev/media/4hATdoB.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 로우 풀리 케이블에 로프 핸들을 연결한다.,Step:2 머신을 정면으로 보고 발을 어깨너비로 벌리고 선다.,Step:3 로프를 언더핸드로 잡고 손바닥이 위를 보게 한다.,Step:4 상완을 프리처 벤치 패드에 대고 팔꿈치를 약간 굽힌다.,Step:5 등을 곧게 세우고 코어에 힘을 준다.,Step:6 상완을 고정한 채 로프를 어깨 쪽으로 말아 올린다.,Step:7 상단에서 이두근을 조이며 잠깐 멈춘 뒤, 로프를 천천히 내린다.,Step:8 원하는 횟수만큼 반복한 뒤 반대팔로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('61GrD55', '케이블 라이딩 클로즈 그립 컬', 'https://static.exercisedb.dev/media/61GrD55.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 로우 풀리 케이블에 스트레이트 바를 연결한다.,Step:2 평벤치에 등을 대고 누워 발을 바닥에 둔다.,Step:3 언더핸드로 바를 어깨너비로 잡는다.,Step:4 팔을 완전히 펴고 팔꿈치를 몸통에 가깝게 둔다.,Step:5 상완을 고정한 채 바를 가슴 쪽으로 말아 올려 이두근을 수축한다.,Step:6 상단에서 잠깐 멈추며 이두근을 조인다.,Step:7 바를 천천히 내려 팔을 완전히 펴서 시작 자세로 돌아온다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xBYcQHj', '케이블 언더핸드 풀다운', 'https://static.exercisedb.dev/media/xBYcQHj.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 풀다운 바가 머리 위에 오도록 케이블 높이를 조절한다.,Step:2 시트에 앉아 언더핸드로 바를 어깨너비보다 약간 넓게 잡는다.,Step:3 등을 곧게 세우고 상체를 약간 뒤로 기울인다.,Step:4 바를 가슴 쪽으로 당기며 견갑골을 모아 광배근을 수축한다.,Step:5 바닥에서 잠깐 멈춘 뒤, 바를 천천히 올려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DQ0cqkT', '세 번의 벤치 딥', 'https://static.exercisedb.dev/media/DQ0cqkT.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치에 앉아 손으로 벤치 가장자리를 잡고 손가락을 앞으로 향하게 한다.,Step:2 엉덩이를 벤치 밖으로 빼고 손으로 체중을 지지한다.,Step:3 팔꿈치를 굽혀 몸을 내려 상완이 바닥과 평행해질 때까지 내린다.,Step:4 팔로 밀어 올라와 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lI7easp', '짐 볼에 덤벨 풀오버 엉덩이 익스텐션', 'https://static.exercisedb.dev/media/lI7easp.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨,코어', 'Step:1 짐 볼 위에 앉아 덤벨을 허벅지 위에 올린다.,Step:2 발로 걸어 내려가며 공을 굴려 머리/목/등 상부가 공에 지지되게 한다.,Step:3 양손으로 덤벨을 잡고 팔꿈치를 살짝 굽힌 채 가슴 위로 팔을 편다.,Step:4 덤벨을 머리 뒤로 천천히 내려 큰 원호를 그리며 컨트롤한다.,Step:5 잠깐 멈춘 뒤, 덤벨을 다시 시작 위치로 들어 올린다.,Step:6 팔을 편 상태를 유지하며 엉덩이를 들어 올려 둔근과 코어를 조인다.,Step:7 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2dImyQ8', '덤벨 앉아서 손바닥 위로 손목 컬', 'https://static.exercisedb.dev/media/2dImyQ8.gif', '전완근', '팔 아래', '덤벨', '이두근,어깨', 'Step:1 벤치에 앉아 발을 바닥에 두고 양손에 덤벨을 들며 손바닥이 위를 보게 한다.,Step:2 팔뚝을 허벅지 위에 올려 지지하고 손목이 끝에서 밖으로 나오게 한다.,Step:3 손목을 말아 올려 전완을 수축한다.,Step:4 상단에서 잠깐 멈춘 뒤, 손목을 천천히 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y7YcmIJ', '바벨 벤치 프론트 스쿼트', 'https://static.exercisedb.dev/media/Y7YcmIJ.gif', '대퇴사두근', '허벅지', '바벨', '햄스트링,둔근,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 쇄골 아래 가슴 위쪽(프론트 랙)에 둔다.,Step:2 오버핸드로 바벨을 잡고 팔꿈치를 들어 상완이 바닥과 평행에 가깝게 한다.,Step:3 무릎과 엉덩이를 굽혀 스쿼트로 내려가되 등을 곧게, 가슴을 세운다.,Step:4 바닥에서 잠깐 멈춘 뒤, 뒤꿈치로 밀어 올라와 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9c6T1YX', '다리 - 마운틴 클라이머(크로스 바디)', 'https://static.exercisedb.dev/media/9c6T1YX.gif', '복근', '허리', '맨몸', '둔근,대퇴사두근,햄스트링,어깨,삼두근', 'Step:1 손을 어깨 바로 아래에 두고 하이 플랭크 자세를 만들어 몸을 일직선으로 유지한다.,Step:2 코어에 힘을 주고 오른발을 들어 오른무릎을 왼팔꿈치 쪽으로 가져온다.,Step:3 오른발을 시작 위치로 되돌리고, 왼무릎을 오른팔꿈치 쪽으로 가져온다.,Step:4 좌우를 번갈아 컨트롤된 속도로 반복한다.,Step:5 엉덩이가 들리거나 처지지 않게 수평을 유지한다.,Step:6 호흡을 일정하게 유지한다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MCUhf1F', '크런치(안정성 공 위에서)', 'https://static.exercisedb.dev/media/MCUhf1F.gif', '복근', '허리', '스태빌리티 볼', '고관절 굴근', 'Step:1 스태빌리티 볼 위에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 공 위로 등을 기대 누워 허리가 공에 지지되고 상체가 바닥과 평행해지게 한다.,Step:3 손을 머리 뒤에 두거나 가슴 앞에 교차한다.,Step:4 복근에 힘을 주고 상체를 들어 올려 무릎 쪽으로 말아 올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hMEptv0', '바벨 디클라인 벤트 암 풀오버', 'https://static.exercisedb.dev/media/hMEptv0.gif', '광배근', '등', '바벨', '삼두근,가슴', 'Step:1 디클라인 벤치에 누워 머리가 골반보다 낮게 오게 하고 발을 고정한다.,Step:2 오버핸드로 바벨을 잡고 가슴 위로 팔을 곧게 편다.,Step:3 팔꿈치를 약간 굽힌 채 바벨을 컨트롤하며 머리 뒤로 내려간다.,Step:4 아래에서 잠깐 멈춘 뒤, 광배근을 사용해 바벨을 다시 시작 위치로 올린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ztAa1RK', '밴드 교대 v-up', 'https://static.exercisedb.dev/media/ztAa1RK.gif', '복근', '허리', '밴드', '고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔을 머리 위로 뻗은 채 밴드를 잡는다.,Step:2 복근에 힘을 주고 다리와 상체를 동시에 들어 올리며 손을 발가락 쪽으로 뻗는다.,Step:3 다리와 상체를 다시 내리면서 다리 위치를 바꿔 한쪽 다리를 다른 쪽 위로 교차한다.,Step:4 다시 들어 올리며 교차된 다리를 반대로 바꾼다.,Step:5 원하는 횟수만큼 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('R5swFnc', '캠버 바 거짓말 행', 'https://static.exercisedb.dev/media/R5swFnc.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 바닥에 바벨을 준비하고 벤치에 엎드려 가슴이 벤치 끝 밖으로 약간 나오게 한다.,Step:2 오버핸드로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 다리를 곧게 펴고 발은 바닥에 둔 채 팔을 펴서 바벨을 바닥에서 들어 올린다.,Step:4 바벨을 가슴 쪽으로 당기며 견갑골을 모아 등 근육을 조인다.,Step:5 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WLvTAv5', '바벨 프론 인클라인 컬', 'https://static.exercisedb.dev/media/WLvTAv5.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 엎드려 가슴과 복부를 벤치에 대고 눕는다.,Step:3 언더핸드로 바벨을 어깨너비로 잡는다.,Step:4 팔을 완전히 펴 바벨이 바닥 쪽으로 늘어지게 둔다.,Step:5 상완을 고정한 채 숨을 내쉬며 바벨을 말아 올려 이두근을 수축한다.,Step:6 이두근이 완전히 수축되고 바벨이 어깨 높이에 오면 잠깐 멈춘다.,Step:7 잠깐 멈추며 이두근을 조인다.,Step:8 숨을 들이마시며 바벨을 천천히 내린다.,Step:9 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zfNHMN9', '스케이터 홉', 'https://static.exercisedb.dev/media/zfNHMN9.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 약간 굽히고 오른쪽으로 점프해 오른발로 착지한다.,Step:3 착지하며 왼다리를 오른다리 뒤로 보내 왼발끝으로 바닥을 살짝 터치한다.,Step:4 즉시 왼쪽으로 점프해 왼발로 착지한다.,Step:5 착지하며 오른다리를 왼다리 뒤로 보내 오른발끝으로 바닥을 살짝 터치한다.,Step:6 좌우를 번갈아 계속 반복한다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4x5Okof', '저항 밴드 장착 체스트 프레스', 'https://static.exercisedb.dev/media/4x5Okof.gif', '가슴근육', '가슴', '저항 밴드', '어깨,삼두근', 'Step:1 의자나 벤치에 앉아 등을 곧게 세우고 발을 바닥에 둔다.,Step:2 밴드 핸들을 양손에 잡고 손바닥이 아래를 보게 하며 팔꿈치를 90도로 굽혀 가슴 옆에 둔다.,Step:3 팔을 앞으로 뻗어 밴드를 밀어내며 가슴에서 멀어지게 한다.,Step:4 끝 지점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6ZCiYWQ', '팔을 가슴에 올리고 윗몸일으키기', 'https://static.exercisedb.dev/media/6ZCiYWQ.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 붙인다.,Step:2 팔을 가슴 위에 교차해 올린다.,Step:3 복근에 힘을 주고 상체를 들어 무릎 쪽으로 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cQ19bBP', '록키 풀업 풀다운', 'https://static.exercisedb.dev/media/cQ19bBP.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 풀업 바 앞에 서서 발을 어깨너비로 벌린다.,Step:2 바를 오버핸드로 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 펴서 매달리고 몸을 곧게 유지한다.,Step:4 등 근육을 사용해 가슴을 바 쪽으로 이끌며 몸을 끌어올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EIeI8Vf', '바벨 벤치 프레스', 'https://static.exercisedb.dev/media/EIeI8Vf.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 벤치에 누워 발을 바닥에 고정하고 등을 벤치에 밀착한다.,Step:2 바벨을 오버핸드로 어깨너비보다 약간 넓게 잡는다.,Step:3 랙에서 바벨을 들어 가슴 위에서 팔을 완전히 펴 고정한다.,Step:4 팔꿈치를 굽혀 바벨을 가슴 쪽으로 천천히 내리되 팔꿈치를 몸통에 가깝게 둔다.,Step:5 바가 가슴에 닿는 지점에서 잠깐 멈춘다.,Step:6 팔을 펴며 바벨을 밀어 올려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('b4b6afT', '웨이티드 시티드 바이셉 컬(스태빌리티 볼)', 'https://static.exercisedb.dev/media/b4b6afT.gif', '이두근', '상완이두근', '메디신볼', '전완근', 'Step:1 스태빌리티 볼 위에 앉아 발을 바닥에 두고 등을 곧게 세운다.,Step:2 메디신볼을 언더핸드로 잡고 팔을 몸 옆으로 늘어뜨린다.,Step:3 상완을 고정한 채 숨을 내쉬며 메디신볼을 어깨 쪽으로 말아 올린다.,Step:4 상단에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 메디신볼을 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JZuApnB', '고중량 스쿼트', 'https://static.exercisedb.dev/media/JZuApnB.gif', '둔근', '허벅지', '가중', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 중량을 가슴 앞(또는 어깨 위)에 든다.,Step:3 코어에 힘을 주고 가슴을 세운 채 엉덩이를 뒤로 빼며 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위에서) 내려간다.,Step:5 뒤꿈치로 밀어 일어서며 상단에서 둔근을 조인다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OPqShYN', '레버 힙 익스텐션 v. 2', 'https://static.exercisedb.dev/media/OPqShYN.gif', '둔근', '허벅지', '레버리지 머신', '햄스트링', 'Step:1 머신을 몸에 맞게 조절하고 등을 등받이에 대고 앉는다.,Step:2 발을 발판에 두고 손잡이를 잡아 안정적으로 고정한다.,Step:3 둔근과 햄스트링에 힘을 주며 발판을 밀어 고관절을 펴고 다리를 뒤로 들어 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ezTvXcr', '링 딥스', 'https://static.exercisedb.dev/media/ezTvXcr.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 링에 매달려 팔을 완전히 펴고 몸을 곧게 만든다.,Step:2 팔꿈치를 굽혀 어깨가 팔꿈치보다 아래로 내려갈 때까지 몸을 낮춘다.,Step:3 팔을 펴며 몸을 다시 밀어 올려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OrETs32', '플랫 벤치의 리버스 하이퍼', 'https://static.exercisedb.dev/media/OrETs32.gif', '둔근', '허벅지', '맨몸', '햄스트링,허리', 'Step:1 평벤치에 엎드려 골반이 벤치 끝에 오게 하고 다리는 벤치 밖으로 늘어뜨린다.,Step:2 벤치를 잡아 몸을 안정적으로 고정한다.,Step:3 무릎을 펴고 다리를 위로 들어 올려 가능한 만큼 천장 쪽으로 올린다.,Step:4 상단에서 둔근을 조이며 잠깐 멈춘다.,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o1HGDSq', '머리 뒤로 손을 대고 짐 볼 등 익스텐션', 'https://static.exercisedb.dev/media/o1HGDSq.gif', '척추', '등', '스태빌리티 볼', '둔근,햄스트링', 'Step:1 스태빌리티 볼을 바닥에 두고 그 위에 엎드려 골반이 공에 오게 한다.,Step:2 발을 벽이나 고정된 물체에 대어 안정적으로 고정한다.,Step:3 손을 머리 뒤에 두고 팔꿈치를 바깥으로 둔다.,Step:4 코어에 힘을 주고 상체를 들어 올려 등을 펴서 머리부터 골반까지 일직선이 되게 한다.,Step:5 상단에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0mB6wHO', '풋 스트레칭', 'https://static.exercisedb.dev/media/0mB6wHO.gif', '햄스트링', '허벅지', '맨몸', '종아리근,대퇴사두근', 'Step:1 발을 엉덩이너비로 벌려 선다.,Step:2 오른발을 한 걸음 앞으로 내딛고 왼발은 그대로 둔다.,Step:3 오른쪽 무릎을 굽혀 몸을 아래로 내리되 왼쪽 다리는 곧게 유지한다.,Step:4 양손을 오른쪽 허벅지 위에 두어 지지한다.,Step:5 20–30초 동안 유지한 뒤 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pZwUsKB', '아이언 크로스 스트레치', 'https://static.exercisedb.dev/media/pZwUsKB.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근', 'Step:1 등을 대고 누워 팔을 옆으로 뻗는다.,Step:2 다리를 곧게 펴서 천장 쪽으로 들어 올린다.,Step:3 다리를 한쪽으로 천천히 내리며 발이 바닥에 닿도록 시도한다.,Step:4 몇 초간 스트레치를 유지한 뒤 다리를 시작 위치로 되돌린다.,Step:5 반대쪽도 같은 방식으로 반복한다.,Step:6 좌우를 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qDnGfDb', '바벨 리버스 리스트 컬 v. 2', 'https://static.exercisedb.dev/media/qDnGfDb.gif', '전완근', '팔 아래', '바벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 무릎을 굽힌다.,Step:2 오버핸드로 바벨을 어깨너비로 잡아 손바닥이 아래를 보게 한다.,Step:3 팔뚝을 허벅지 위에 올려 지지하고 손목이 끝에서 밖으로 나오게 한다.,Step:4 팔뚝을 고정한 채 숨을 내쉬며 손목을 말아 올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 숨을 들이마시며 바벨을 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('s5PdDyY', '덤벨 테이트 프레스', 'https://static.exercisedb.dev/media/s5PdDyY.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 평벤치에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 덤벨을 어깨 높이로 올린 뒤, 손목을 돌려 손바닥이 바깥을 보게 한다.,Step:3 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:4 덤벨을 다시 어깨 높이로 내린다.,Step:5 손목을 다시 시작 자세로 되돌리고 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nDK1HJ0', 'ez 바 라이딩 벤트 암 풀오버', 'https://static.exercisedb.dev/media/nDK1HJ0.gif', '광배근', '등', 'EZ 바벨', '삼두근,가슴', 'Step:1 평벤치에 누워 머리는 한쪽 끝에 두고 발은 바닥에 둔다.,Step:2 오버핸드로 EZ바를 어깨너비로 잡고 가슴 위로 팔을 뻗는다.,Step:3 팔꿈치를 약간 굽힌 채 바를 원호로 머리 뒤쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘 뒤, 같은 궤적으로 바를 다시 시작 위치로 되돌린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PQ2AtC3', '레버 시트 레그 레이즈 크런치', 'https://static.exercisedb.dev/media/PQ2AtC3.gif', '복근', '허리', '레버리지 머신', '고관절 굴근', 'Step:1 머신에 앉아 등을 등받이에 대고 발을 발판에 올린다.,Step:2 손잡이나 측면 바를 잡아 몸을 고정한다.,Step:3 복근에 힘을 주고 다리를 들어 올리며 동시에 상체를 말아 올린다.,Step:4 상단에서 잠깐 멈춘 뒤, 다리와 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1IG6gVF', '스태빌리티 볼 트위스트', 'https://static.exercisedb.dev/media/1IG6gVF.gif', '복근', '허리', '스태빌리티 볼', '복사근,허리', 'Step:1 스태빌리티 볼 위에 엎드려 발을 어깨너비로 벌리고 발끝은 바닥에 둔다.,Step:2 손을 머리 뒤에 두거나 가슴 앞에 교차한다.,Step:3 코어에 힘을 주고 상체를 들어 올리며 등을 곧게 유지한다.,Step:4 몸통을 한쪽으로 회전해 어깨를 같은 쪽 골반 방향으로 가져간다(하체는 고정).,Step:5 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:6 반대쪽으로도 회전한다.,Step:7 좌우를 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8ARQ9Hw', '케틀벨 스모 하이 풀', 'https://static.exercisedb.dev/media/8ARQ9Hw.gif', '승모근', '등', '케틀벨', '어깨,둔근,햄스트링', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝을 바깥으로 향하게 한다.,Step:2 양손으로 케틀벨을 잡고 팔을 아래로 늘어뜨린다.,Step:3 무릎을 굽혀 스모 스쿼트처럼 내려가되 등을 곧게 유지한다.,Step:4 뒤꿈치로 밀어 일어서며 힙과 무릎을 펴면서 케틀벨을 턱 쪽으로 끌어올린다.,Step:5 케틀벨을 올릴 때 팔꿈치를 높고 넓게 유지하고 견갑골을 모아 조인다.,Step:6 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PERjVm8', '팔을 뻗은 상태에서 짐 볼 백 익스텐션', 'https://static.exercisedb.dev/media/PERjVm8.gif', '척추', '등', '스태빌리티 볼', '둔근,햄스트링', 'Step:1 스태빌리티 볼 위에 엎드려 골반을 공에 두고, 발은 벽에 대어 안정적으로 고정한다.,Step:2 팔을 앞으로 곧게 뻗어 손바닥이 아래를 보게 한다.,Step:3 코어에 힘을 주고 상체를 들어 올리되 목은 척추와 일직선이 되게 유지한다.,Step:4 상단에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QsSQWbf', '밴드 싱글 레그 리버스 카프 레이즈', 'https://static.exercisedb.dev/media/QsSQWbf.gif', '종아리근', '종아리', '밴드', '햄스트링,둔근', 'Step:1 발볼 부분에 밴드를 걸고 발을 엉덩이너비로 벌리고 선다.,Step:2 균형을 위해 안정된 물체를 잡는다.,Step:3 뒤꿈치를 들어 올려 발볼로 체중을 싣는다.,Step:4 상단에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한 뒤 반대발로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mr7pkqP', '잭 버피', 'https://static.exercisedb.dev/media/mr7pkqP.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근,어깨,삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 스쿼트로 내려가 손을 몸 앞 바닥에 둔다.,Step:3 다리를 뒤로 차서 푸쉬업 자세로 간다.,Step:4 푸쉬업을 1회 수행한다.,Step:5 발을 앞으로 점프해 스쿼트 자세로 돌아온다.,Step:6 위로 점프하며 팔을 머리 위로 뻗는다.,Step:7 부드럽게 착지하고 즉시 다음 반복을 위해 다시 스쿼트로 내려간다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jDOKRM5', '옆으로 누워서 바닥 스트레칭', 'https://static.exercisedb.dev/media/jDOKRM5.gif', '광배근', '등', '맨몸', '복사근,둔근', 'Step:1 다리를 곧게 편 상태로 옆으로 눕고 아래쪽 팔은 머리 위로 곧게 뻗는다.,Step:2 위쪽 무릎을 굽혀 발을 아래쪽 다리 앞 바닥에 둔다.,Step:3 위쪽 팔을 머리 위로 넘겨 벽이나 가구처럼 안정된 지지물을 잡는다.,Step:4 아래쪽 다리를 곧게 유지한 채 천천히 들어 올려 옆구리가 늘어나는 것을 느낀다.,Step:5 20–30초 동안 유지한 뒤 천천히 다리를 내린다.,Step:6 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bOOdeyc', '레버 시트 종아리 레이즈', 'https://static.exercisedb.dev/media/bOOdeyc.gif', '종아리근', '종아리', '레버리지 머신', '가자미근,발목 안정 장치', 'Step:1 무릎이 약간 굽혀지도록 시트 높이를 조절하고 발을 발판에 둔다.,Step:2 발앞꿈치를 발판에 두고 뒤꿈치는 밖으로 빼서 아래로 떨어지게 한다.,Step:3 손잡이(또는 시트 옆)를 잡아 몸을 고정한다.,Step:4 발볼로 밀어 뒤꿈치를 최대한 들어 올린다.,Step:5 상단에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('x2chWLO', '목 옆 스트레칭', 'https://static.exercisedb.dev/media/x2chWLO.gif', '견갑거근', '목', '맨몸', '승모근,흉쇄유돌근', 'Step:1 어깨에 힘을 빼고 곧게 서거나 앉는다.,Step:2 머리를 한쪽으로 기울여 귀가 어깨 쪽으로 가게 한다.,Step:3 15–30초 동안 유지한다.,Step:4 반대쪽도 같은 방식으로 반복한다.,Step:5 각 방향으로 2–4세트 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zK8Fu1W', '스미스 리버스 그립 프레스', 'https://static.exercisedb.dev/media/zK8Fu1W.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 스미스 머신 바 높이를 가슴 높이로 조절한다.,Step:2 바를 마주 보고 발을 어깨너비로 선다.,Step:3 양손을 어깨너비보다 약간 넓게 오버핸드 그립으로 잡는다.,Step:4 뒤로 한 걸음 물러나 무릎을 살짝 굽힌 자세를 만든다.,Step:5 동작 내내 가슴을 들어 올리고 코어에 힘을 준다.,Step:6 팔꿈치를 몸쪽으로 모은 채 바를 가슴 쪽으로 천천히 내린다.,Step:7 바닥 지점에서 잠깐 멈춘 뒤 시작 자세로 다시 밀어 올린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wd4ds3s', '체중 스탠딩 로우', 'https://static.exercisedb.dev/media/wd4ds3s.gif', '등 위쪽', '등', '맨몸', '이두근,어깨', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌 채 선다.,Step:2 바 또는 손잡이를 오버핸드 그립(손바닥 아래)으로 잡는다.,Step:3 등을 곧게 세우고 코어에 힘을 준다.,Step:4 바/손잡이를 몸쪽으로 당기며 견갑골을 모아 조인다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 천천히 힘을 풀며 팔을 시작 자세로 뻗는다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ealLwvX', '벽에 무릎을 대고', 'https://static.exercisedb.dev/media/ealLwvX.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 벽을 마주 보고 발을 골반 너비로 선다.,Step:2 손을 벽에 대어 지지한다.,Step:3 코어에 힘을 주고 오른쪽 무릎을 가슴 쪽으로 들어 올리되 왼발은 바닥에 둔다.,Step:4 빠르게 다리를 교체하여 왼무릎을 올리고 오른발을 내린다.,Step:5 달리듯이 번갈아 무릎을 가능한 높게 들어 올리며 계속한다.,Step:6 상체가 흔들리지 않게 안정적으로 유지한다.,Step:7 원하는 시간 또는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1ZFqTDN', '에어바이크', 'https://static.exercisedb.dev/media/1ZFqTDN.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 바닥에 대고 누워 손을 머리 뒤에 둔다.,Step:2 다리를 바닥에서 들어 올리고 무릎을 90도로 굽힌다.,Step:3 오른쪽 팔꿈치를 왼쪽 무릎 쪽으로 가져가며 동시에 오른쪽 다리를 뻗는다.,Step:4 시작 자세로 돌아오고 반대쪽도 같은 방식으로 수행한다(왼쪽 팔꿈치-오른쪽 무릎).,Step:5 페달링하듯 좌우를 번갈아 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YTur5nR', '케이블 원 암 컬', 'https://static.exercisedb.dev/media/YTur5nR.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 마주 보고 발을 어깨너비로 선다.,Step:2 손바닥이 위를 향하도록 언더핸드 그립으로 손잡이를 잡는다.,Step:3 팔꿈치를 몸 옆에 붙이고 전완을 어깨 쪽으로 천천히 말아 올린다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jivWf8n', '덤벨 프리처 컬', 'https://static.exercisedb.dev/media/jivWf8n.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 컬 벤치에 앉아 상완을 패드에 올리고 가슴을 패드에 밀착한다.,Step:2 덤벨을 양손에 들고 손바닥을 위로 하여 팔을 완전히 편다.,Step:3 상완은 고정한 채 숨을 내쉬며 이두근을 수축해 덤벨을 말아 올린다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 강하게 조인다.,Step:6 숨을 들이마시며 천천히 덤벨을 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('q7qkONO', '덤벨 착석 대체 어깨', 'https://static.exercisedb.dev/media/q7qkONO.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 벤치에 앉아 등을 곧게 세우고 발을 바닥에 붙인다.,Step:2 덤벨을 양손에 들고 손바닥이 안쪽을 향하게 하여 어깨 높이로 든다.,Step:3 한쪽 덤벨을 머리 위로 밀어 올리는 동안 다른쪽 덤벨은 어깨 높이에 유지한다.,Step:4 올린 덤벨을 어깨 높이로 내리면서 동시에 반대쪽 덤벨을 머리 위로 민다.,Step:5 팔을 번갈아가며 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('euq4pwp', '밴드 스탠딩 트위스트 크런치', 'https://static.exercisedb.dev/media/euq4pwp.gif', '복근', '허리', '밴드', '복사근', 'Step:1 발을 어깨너비로 벌리고 밴드를 등 윗부분에 걸친 뒤 가슴 앞에서 교차시킨다.,Step:2 밴드 끝을 손으로 잡고 팔꿈치는 굽힌 채 몸 옆에 가깝게 둔다.,Step:3 복근에 힘을 주고 상체를 한쪽으로 비틀며 반대쪽 무릎 쪽으로 팔꿈치를 가져간다.,Step:4 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:5 반대쪽도 수행한다.,Step:6 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Bn6TXyO', '윗몸일으키기 v. 2', 'https://static.exercisedb.dev/media/Bn6TXyO.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 되게 말아 올린다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 시작 자세로 내려간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ETZfAbZ', '스미스 디클라인 벤치프레스', 'https://static.exercisedb.dev/media/ETZfAbZ.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 디클라인 벤치 각도를 원하는 만큼 조절한다.,Step:2 벤치에 눕고 발을 고정 패드 아래에 넣어 고정한다.,Step:3 바를 어깨너비보다 약간 넓은 오버핸드 그립으로 잡는다.,Step:4 바를 랙에서 빼고 가슴 쪽으로 천천히 내리며 팔꿈치를 몸쪽으로 유지한다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤 시작 자세로 다시 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UtmIqcI', '손목 옆 당기기 스트레칭', 'https://static.exercisedb.dev/media/UtmIqcI.gif', '전완근', '팔 아래', '맨몸', '손목,소유', 'Step:1 발을 어깨너비로 벌리고 팔을 몸 앞쪽으로 뻗어 선다.,Step:2 오른팔을 바닥과 평행하게 옆으로 곧게 뻗고 손바닥은 아래로 향하게 한다.,Step:3 왼손으로 오른손을 잡고 몸 쪽으로 부드럽게 당겨 오른쪽 전완이 늘어나는 것을 느낀다.,Step:4 15–30초 동안 유지한 뒤 풀어준다.,Step:5 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('v7p5bYl', '쫓겨나 앉다', 'https://static.exercisedb.dev/media/v7p5bYl.gif', '햄스트링', '허벅지', '맨몸', '대퇴사두근,둔근', 'Step:1 벤치나 의자 끝에 앉고 발바닥을 바닥에 둔 채 무릎을 90도로 굽힌다.,Step:2 상체를 약간 뒤로 기대고 벤치/의자 가장자리를 손으로 잡아 지지한다.,Step:3 햄스트링에 힘을 주며 발을 바닥에서 들어 올려 다리를 앞쪽으로 곧게 편다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 무릎을 굽혀 발을 몸 쪽으로 가져온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eZyBC3j', '바벨이 로우 위로 구부러져 있음', 'https://static.exercisedb.dev/media/eZyBC3j.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌 채 선다.,Step:2 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 유지하고 가슴을 든다.,Step:3 바벨을 어깨너비보다 약간 넓게 오버핸드 그립으로 잡는다.,Step:4 견갑골을 모으며 바벨을 하부 가슴 쪽으로 당겨 등 근육을 수축한다.,Step:5 정점에서 잠깐 멈춘다.,Step:6 바벨을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RrLske5', '벤치딥(무릎 구부리기)', 'https://static.exercisedb.dev/media/RrLske5.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 의자 끝에 앉아 손을 엉덩이 옆 가장자리에 두고 잡는다.,Step:2 엉덩이를 벤치 밖으로 빼고 다리를 앞으로 뻗되 발뒤꿈치는 바닥에 둔다.,Step:3 팔꿈치를 굽혀 몸을 아래로 내리며 등을 벤치에 가깝게 유지한다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤 팔로 밀어 시작 자세로 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dZl9Q27', '바벨 스탠딩 오버헤드 삼두근 익스텐션', 'https://static.exercisedb.dev/media/dZl9Q27.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 선 채 바벨을 오버핸드 그립으로 잡는다.,Step:2 팔을 완전히 펴 바벨을 머리 위로 든다.,Step:3 상완을 머리 옆에 고정한 채 팔꿈치를 굽혀 바벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 팔을 펴 바벨을 시작 자세로 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('196HJGw', '엉덩이 들기(무릎 구부리기)', 'https://static.exercisedb.dev/media/196HJGw.gif', '복근', '허리', '맨몸', '둔근,햄스트링', 'Step:1 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손은 몸 옆에 두고 손바닥은 바닥을 향하게 둔다.,Step:3 코어와 둔근에 힘을 주고 엉덩이를 들어 올려 무릎-어깨가 일직선이 되게 한다.,Step:4 정점에서 잠깐 멈춘 뒤 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cWemPG8', '덤벨 엎드린 인클라인 해머 컬', 'https://static.exercisedb.dev/media/cWemPG8.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치를 45도 인클라인으로 조절한다.,Step:2 벤치에 엎드려 덤벨을 양손에 들고 손바닥이 서로 마주 보게 한다.,Step:3 팔을 바닥 쪽으로 늘어뜨리되 팔꿈치는 약간 굽힌다.,Step:4 상완은 고정한 채 숨을 내쉬며 이두근을 수축해 덤벨을 말아 올린다.,Step:5 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:6 정점에서 잠깐 멈추며 이두근을 조인다.,Step:7 숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OyoZ3Pu', '플랫벤치에서 다리 당기기', 'https://static.exercisedb.dev/media/OyoZ3Pu.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 플랫벤치에 앉아 다리를 앞쪽으로 곧게 뻗는다.,Step:2 손을 엉덩이 옆 벤치 위에 두고 지지한다.,Step:3 복근에 힘을 주고 다리를 들어 올리며 무릎을 가슴 쪽으로 당긴다.,Step:4 정점에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('d9Xaxq6', '케이블 러시안 트위스트(스태빌리티 볼)', 'https://static.exercisedb.dev/media/d9Xaxq6.gif', '복근', '허리', '케이블', '복사근,허리', 'Step:1 스태빌리티 볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 케이블 손잡이를 양손으로 잡고 팔을 앞쪽으로 곧게 뻗는다.,Step:3 등을 곧게 유지한 채 상체를 약간 뒤로 기울이고 코어에 힘을 준다.,Step:4 몸통을 오른쪽으로 비틀어 손잡이를 오른쪽 골반 쪽으로 가져간다.,Step:5 잠깐 멈춘 뒤 왼쪽으로 비틀어 손잡이를 왼쪽 골반 쪽으로 가져간다.,Step:6 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aXtJhlg', '덤벨 스텝업', 'https://static.exercisedb.dev/media/aXtJhlg.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 덤벨을 양손에 들고 벤치/박스 앞에 선다(손바닥은 몸을 향함).,Step:2 오른발을 벤치/박스 위에 올려 발 전체가 닿게 한다.,Step:3 오른쪽 뒤꿈치로 밀어 몸을 올리며 오른다리를 편다.,Step:4 왼발도 올려 완전히 선다.,Step:5 왼발부터 내려오고 이어서 오른발을 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Vvwjz6N', '글루트햄 레이즈', 'https://static.exercisedb.dev/media/Vvwjz6N.gif', '햄스트링', '허벅지', '맨몸', '둔근,허리', 'Step:1 글루트햄 레이즈 머신을 몸에 맞게 조절한다.,Step:2 머신에 엎드려 발목을 고정한다.,Step:3 손은 가슴 앞에 모으거나 교차한다.,Step:4 햄스트링과 둔근에 힘을 주어 상체를 들어 올린다.,Step:5 머리부터 발뒤꿈치까지 일직선이 될 때까지 올린다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 내려온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('M2Pm3zj', '덤벨 누워있는 외전', 'https://static.exercisedb.dev/media/M2Pm3zj.gif', '전완근', '팔 아래', '덤벨', '이두근,어깨', 'Step:1 벤치에 등을 대고 눕고 발바닥을 바닥에 둔다.,Step:2 덤벨을 양손에 들고 손바닥을 위로 하여 팔을 완전히 편다.,Step:3 상완은 고정한 채 전완을 말아 올리며 이두근/전완을 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BaE7O6U', '매달린 비스듬한 무릎 올리기', 'https://static.exercisedb.dev/media/BaE7O6U.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 풀업바에 매달려 팔을 완전히 펴고 몸을 안정시킨다.,Step:2 코어에 힘을 주고 무릎을 가슴 쪽으로 들어 올리며 상체를 한쪽으로 비튼다.,Step:3 정점에서 잠깐 멈춘 뒤 다리를 천천히 내린다.,Step:4 반대쪽도 같은 방식으로 수행한다.,Step:5 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZujAdR9', '케이블 로프 인클라인 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/ZujAdR9.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 하이 풀리에 로프를 연결하고 인클라인 벤치를 편한 각도로 조절한다.,Step:2 풀리를 등지고 발을 어깨너비로 선다.,Step:3 로프를 오버핸드 그립으로 잡고 팔을 머리 위로 곧게 뻗는다.,Step:4 팔꿈치를 머리 옆에 붙이고 상완이 움직이지 않게 고정한다.,Step:5 팔꿈치를 굽혀 로프를 머리 뒤로 내리며 전완이 이두근에 닿을 때까지 내린다.,Step:6 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vsMcDi9', '바벨 스탠딩 컨센트레이션 컬', 'https://static.exercisedb.dev/media/vsMcDi9.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손으로 바벨을 잡되 손바닥은 위로 향하게 한다.,Step:2 반대손은 허벅지에 올려 지지한다.,Step:3 상완은 고정한 채 숨을 내쉬며 무게를 어깨 쪽으로 말아 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IwX5NqK', '케이블 리버스 프리처 컬', 'https://static.exercisedb.dev/media/IwX5NqK.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신의 프리처 패드를 가슴 높이로 맞춘다.,Step:2 프리처 벤치에 앉아 상완을 패드에 올리고 손바닥이 아래를 보이게 팔을 편다.,Step:3 케이블 손잡이를 언더핸드 그립으로 어깨너비로 잡는다.,Step:4 상완을 고정한 채 숨을 내쉬며 손잡이를 어깨 쪽으로 말아 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 손잡이를 천천히 내리며 팔꿈치를 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4U7iLb5', '레버 풀오버', 'https://static.exercisedb.dev/media/4U7iLb5.gif', '광배근', '등', '레버리지 머신', '삼두근,어깨', 'Step:1 레버 머신의 좌석과 손잡이를 편한 위치로 조절한다.,Step:2 머신에 앉아 등을 패드에 붙이고 오버핸드 그립으로 손잡이를 잡는다.,Step:3 팔은 약간 굽힌 채 코어에 힘을 준다.,Step:4 손잡이를 가슴 쪽으로 천천히 당기며 광배근을 수축한다.,Step:5 최대 수축 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2Qh2J1e', '슬레이 45° 레그 프레스(사이드 포)', 'https://static.exercisedb.dev/media/2Qh2J1e.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 발판에 올렸을 때 무릎이 90도가 되도록 좌석을 조절한다.,Step:2 등받이에 등을 밀착하고 발을 어깨너비로 발판에 둔다.,Step:3 좌석 옆 손잡이를 잡아 몸을 고정한다.,Step:4 발판을 밀어 다리를 펴며 완전히 신전한다.,Step:5 정점에서 잠깐 멈춘 뒤 무릎을 굽혀 천천히 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0dCyly0', '바벨 시티드 브래드포드 록키 프레스', 'https://static.exercisedb.dev/media/0dCyly0.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 벤치에 앉아 등을 곧게 세우고 발을 바닥에 둔다.,Step:2 바벨을 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:3 바벨을 어깨 높이로 들어 올리고 팔꿈치는 약간 굽힌 채 앞을 향하게 한다.,Step:4 바벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:5 바벨을 다시 어깨 높이로 내려오며 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LEH9jxP', '푸시업(벽)', 'https://static.exercisedb.dev/media/LEH9jxP.gif', '가슴근육', '가슴', '맨몸', '삼두근,삼각근', 'Step:1 벽을 마주 보고 팔 길이 정도 떨어져 선다.,Step:2 손을 어깨 높이에 두고 어깨너비보다 약간 넓게 벽에 댄다.,Step:3 몸이 일직선이 되도록 몇 걸음 뒤로 물러나 발은 골반 너비로 둔다.,Step:4 팔꿈치를 굽혀 가슴을 벽 쪽으로 내리되 몸이 일직선이 되게 유지한다.,Step:5 팔을 펴며 시작 자세로 밀어 올라온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vzAxBtt', '케틀벨 원암 클린 앤 저크', 'https://static.exercisedb.dev/media/vzAxBtt.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 한 손으로 케틀벨을 오버핸드 그립으로 잡는다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 케틀벨을 다리 사이로 내린다.,Step:3 엉덩이-무릎-발목을 폭발적으로 펴며 케틀벨을 어깨 높이까지 스윙한다.,Step:4 케틀벨이 어깨 높이에 오면 손목을 회전하고 팔을 곧게 펴 머리 위로 락아웃한다.,Step:5 케틀벨을 시작 자세로 내려 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sTfvVsG', '밴드 리버스 플라이', 'https://static.exercisedb.dev/media/sTfvVsG.gif', '삼각근', '어깨', '밴드', '등 위쪽,승모근', 'Step:1 밴드를 가슴 높이의 고정물에 연결한다.,Step:2 발을 어깨너비로 벌리고 밴드를 양손으로 잡아 몸 앞에 둔다.,Step:3 팔을 곧게 편 채 양옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 정점에서 견갑골을 모아 조인다.,Step:5 팔을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bfiHMpI', '짐 볼에 덤벨 인클라인 프레스', 'https://static.exercisedb.dev/media/bfiHMpI.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐 볼 위에 앉아 덤벨을 양손에 들고 손바닥이 앞을 보게 한다.,Step:2 발을 앞으로 걸어가며 몸을 굴려 머리/목/등 윗부분이 공에 지지되게 한다.,Step:3 덤벨을 어깨 높이로 들고 팔꿈치를 굽혀 옆으로 향하게 한다.,Step:4 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:5 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HUEqZ1y', '바벨 사이드 스플릿 스쿼트 v. 2', 'https://static.exercisedb.dev/media/HUEqZ1y.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 바벨을 등 위(승모) 쪽에 얹어 잡는다.,Step:3 오른발로 옆으로 크게 내딛고 왼발은 고정한다.,Step:4 오른무릎을 굽혀 스쿼트 자세로 내려가되 가슴을 들고 등을 곧게 유지한다.,Step:5 오른쪽 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 반대쪽도 동일하게 수행한다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JOZhu2h', '케이블 스탠딩 트위스트 로우(v-bar)', 'https://static.exercisedb.dev/media/JOZhu2h.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 케이블 머신에 V-바를 가슴 높이로 연결한다.,Step:2 머신을 마주 보고 발을 어깨너비로 선다.,Step:3 V-바를 오버핸드 그립(손바닥 아래)으로 잡는다.,Step:4 뒤로 한 걸음 물러나 케이블에 장력을 만든다.,Step:5 등을 곧게 세우고 코어에 힘을 준다.,Step:6 견갑골을 모으며 팔꿈치를 굽혀 V-바를 몸통 쪽으로 당긴다.,Step:7 당기면서 상체를 한쪽으로 비틀어 등 위쪽 수축을 느낀다.,Step:8 정점에서 잠깐 멈춘다.,Step:9 천천히 풀며 상체를 다시 정면으로 돌리고 시작 자세로 돌아간다.,Step:10 반복할 때마다 비트는 방향을 번갈아 원하는 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o8aOcrz', '스미스 머신 인클라인 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/o8aOcrz.gif', '삼두근', '상완이두근', '스미스 머신', '어깨', 'Step:1 스미스 머신 좌석을 조절해 바가 어깨 높이에 오게 한다.,Step:2 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 둔다.,Step:3 바를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 팔을 완전히 펴 바를 랙에서 빼고 가슴 위에 위치시킨다.,Step:5 팔꿈치를 머리 쪽으로 유지한 채 바를 이마 쪽으로 천천히 내린다.,Step:6 바닥 지점에서 잠깐 멈춘 뒤 시작 자세로 다시 밀어 올린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iny3m5y', '죽은 벌레', 'https://static.exercisedb.dev/media/iny3m5y.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 바닥에 대고 누워 팔을 천장 쪽으로 뻗는다.,Step:2 무릎을 굽혀 다리를 들어 올려 엉덩이와 무릎이 90도가 되게 한다.,Step:3 코어에 힘을 주고 허리가 뜨지 않게 허리를 바닥에 밀착한다.,Step:4 오른팔과 왼다리를 천천히 바닥 쪽으로 내리되 곧게 펴고 바닥 바로 위에서 멈춘다.,Step:5 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:6 왼팔과 오른다리로 같은 동작을 반복한다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o1ntciW', '올림픽 바벨 해머 컬', 'https://static.exercisedb.dev/media/o1ntciW.gif', '이두근', '상완이두근', '올림픽 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 선다. 올림픽 바벨을 오버핸드 그립(손바닥이 몸을 향함)으로 잡는다.,Step:2 바벨이 허벅지 앞에서 팔 길이만큼 늘어지게 둔다.,Step:3 상완을 고정한 채 숨을 내쉬며 이두근을 수축해 바벨을 말아 올린다.,Step:4 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 바벨을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZuXu4Eq', 'V-바닥에 앉아', 'https://static.exercisedb.dev/media/ZuXu4Eq.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 바닥에 앉아 다리를 앞으로 곧게 뻗는다.,Step:2 상체를 약간 뒤로 기울이며 다리를 들어 올리되 무릎은 편다.,Step:3 동시에 상체도 들어 올리며 팔을 다리 쪽으로 뻗는다.,Step:4 몇 초간 유지한 뒤 상체와 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wVompEp', '보수 공 위로 밀어 올리기', 'https://static.exercisedb.dev/media/wVompEp.gif', '가슴근육', '가슴', '보수 공', '삼두근,어깨,코어', 'Step:1 보수 볼을 바닥에 두고 평평한 면이 위를 향하게 한다.,Step:2 보수 볼 가장자리에 손을 올리고 푸시업 자세를 만든다.,Step:3 코어에 힘을 주고 팔꿈치를 굽혀 몸을 보수 볼 쪽으로 내린다.,Step:4 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7WaDzyL', '옆 엉덩이 외전', 'https://static.exercisedb.dev/media/7WaDzyL.gif', '외전근', '허벅지', '맨몸', '둔근,대퇴사두근', 'Step:1 발을 어깨너비로 벌리고 손을 허리에 둔다.,Step:2 한쪽 다리에 체중을 싣고 반대쪽 다리를 옆으로 들어 올리되 무릎은 편다.,Step:3 정점에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:4 반대쪽도 수행한다.,Step:5 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IGtBdNT', '덤벨 시티드 해머 컬', 'https://static.exercisedb.dev/media/IGtBdNT.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 덤벨을 양손에 들고 손바닥이 몸을 향하게 한 채 팔을 아래로 뻗는다.,Step:2 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('225x2Vd', '밴드 무릎 꿇고 트위스트 크런치', 'https://static.exercisedb.dev/media/225x2Vd.gif', '복근', '허리', '밴드', '복사근', 'Step:1 밴드를 허리 높이의 단단한 고정물에 연결한다.,Step:2 고정물을 등지고 무릎을 꿇고 앉아 밴드를 양손으로 잡고 팔꿈치를 굽혀 몸 옆에 둔다.,Step:3 복근에 힘을 주고 상체를 한쪽으로 천천히 비틀며 손을 반대쪽 골반 쪽으로 가져간다.,Step:4 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 반대쪽도 수행한다.,Step:6 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rjiM4L3', '경사 런닝머신에서 걷기', 'https://static.exercisedb.dev/media/rjiM4L3.gif', '심혈관계', '유산소', '레버리지 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 트레드밀 경사도를 원하는 강도로 조절한다.,Step:2 트레드밀 위에 서서 발을 어깨너비로 둔다.,Step:3 편한 속도로 걷기 시작하며 자세를 바르게 유지한다.,Step:4 코어에 힘을 주고 등을 곧게 유지한다.,Step:5 원하는 시간 동안 경사 걷기를 수행한다.,Step:6 마무리로 경사와 속도를 서서히 낮춰 쿨다운한 뒤 멈춘다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bd5b860', '손목 롤러', 'https://static.exercisedb.dev/media/bd5b860.gif', '전완근', '팔 아래', '가중', '이두근,삼두근', 'Step:1 로프나 바 한쪽 끝에 무게추를 연결한다.,Step:2 로프/바의 반대쪽을 양손으로 잡고 손바닥이 아래를 보게 한다.,Step:3 발을 어깨너비로 벌리고 팔을 앞으로 곧게 뻗는다.,Step:4 손목을 굽혀 무게추가 손 쪽으로 말려 올라오게 천천히 감아 올린다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 풀어 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0lQnxMZ', '가중 시시 스쿼트', 'https://static.exercisedb.dev/media/0lQnxMZ.gif', '대퇴사두근', '허벅지', '가중', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 무게를 가슴 앞에 들거나 바벨을 등 위에 올려 잡는다.,Step:3 가슴을 들고 코어에 힘을 준 채 무릎과 엉덩이를 굽혀 천천히 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 올라온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gFyFj9z', '덤벨 스텝업 런지', 'https://static.exercisedb.dev/media/gFyFj9z.gif', '대퇴사두근', '허벅지', '덤벨', '둔근,햄스트링,종아리근', 'Step:1 덤벨을 양손에 들고 스텝/플랫폼 앞에 선다.,Step:2 오른발을 스텝 위에 올려 발 전체가 닿게 한다.,Step:3 오른쪽 뒤꿈치로 밀어 몸을 스텝 위로 올리고 왼발도 함께 올린다.,Step:4 두 발이 모두 스텝 위에 오면 왼발을 먼저 내려 시작 자세로 돌아가되 오른발은 스텝 위에 둔다.,Step:5 같은 동작을 반복하며 번갈아 수행한다.,Step:6 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2jl9K55', '척추 트위스트', 'https://static.exercisedb.dev/media/2jl9K55.gif', '복근', '허리', '맨몸', '복사근,허리', 'Step:1 바닥에 앉아 다리를 앞으로 뻗는다.,Step:2 무릎을 굽혀 발을 바닥에 두고 골반 너비로 둔다.,Step:3 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:4 복근에 힘을 주고 상체를 오른쪽으로 비틀어 오른쪽 팔꿈치를 왼쪽 무릎 쪽으로 가져간다.,Step:5 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:6 왼쪽으로도 비틀어 왼쪽 팔꿈치를 오른쪽 무릎 쪽으로 가져간다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QY39eBr', '앉아서 하는 스트레칭', 'https://static.exercisedb.dev/media/QY39eBr.gif', '둔근', '허벅지', '맨몸', '햄스트링', 'Step:1 다리를 앞으로 곧게 뻗은 채 바닥에 앉는다.,Step:2 오른쪽 무릎을 굽혀 오른발을 왼쪽 무릎 바깥쪽에 둔다.,Step:3 왼쪽 팔꿈치를 오른쪽 무릎 바깥쪽에 대고 상체를 오른쪽으로 부드럽게 비튼다.,Step:4 20–30초 동안 유지한 뒤 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HIgYKAB', '앉아 있는 광각 포즈 시퀀스', 'https://static.exercisedb.dev/media/HIgYKAB.gif', '햄스트링', '허벅지', '맨몸', '대퇴사두근,종아리근', 'Step:1 바닥에 앉아 다리를 넓게 벌려 뻗는다.,Step:2 발끝을 몸 쪽으로 당기고 허벅지 앞쪽에 힘을 준다.,Step:3 손을 몸 뒤 바닥에 짚어 지지한다.,Step:4 등을 곧게 유지한 채 엉덩이에서부터 상체를 앞으로 기울인다.,Step:5 햄스트링이 늘어나는 느낌이 들 때까지 천천히 더 숙인다.,Step:6 몇 번의 호흡 동안 자세를 유지한다.,Step:7 천천히 스트레칭을 풀고 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qXTaZnJ', '바벨 풀 스쿼트', 'https://static.exercisedb.dev/media/qXTaZnJ.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 바벨을 등 위(승모 또는 후면 삼각근)에 올린다.,Step:3 코어에 힘을 주고 가슴을 든 채 내려갈 준비를 한다.,Step:4 무릎과 엉덩이를 굽혀 의자에 앉듯 엉덩이를 뒤로 빼며 내려간다.,Step:5 허벅지가 바닥과 평행이 되거나 가능하면 그보다 더 아래까지 내려간다.,Step:6 무릎이 발끝 방향과 일치하게 유지하고 체중은 뒤꿈치에 둔다.,Step:7 뒤꿈치로 밀어 올라오며 엉덩이와 무릎을 편다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yUdIGNs', '케이블 후방 삼각근(등자)', 'https://static.exercisedb.dev/media/yUdIGNs.gif', '삼각근', '어깨', '케이블', '승모근,능형근,이두근', 'Step:1 로우 케이블 풀리에 등자 손잡이를 연결하고 머신을 마주 본다.,Step:2 왼손으로 손잡이를 잡고 오른발을 뒤로 내딛어 몸을 약간 비스듬히 선다.,Step:3 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:4 왼팔을 뻗고 손바닥이 아래를 보게 한 상태에서 견갑골을 당기며 손잡이를 가슴 쪽으로 끌어온다.,Step:5 정점에서 잠깐 멈추며 견갑골을 조인다.,Step:6 손잡이를 천천히 시작 자세로 되돌린다.,Step:7 반대쪽도 동일하게 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Xy4jlWA', '덤벨 아놀드 프레스', 'https://static.exercisedb.dev/media/Xy4jlWA.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴 위쪽', 'Step:1 등받이가 있는 벤치에 앉아 덤벨을 어깨 높이로 들고 손바닥은 몸을 향하게 한다(팔꿈치 굽힘).,Step:2 덤벨을 위로 밀어 올리며 팔을 펴고 손바닥이 앞을 보게 회전한다.,Step:3 들어 올리는 동안 손목을 회전해 정점에서 손바닥이 앞을 향하게 한다.,Step:4 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UpWmA5E', '나-바닥에 앉아', 'https://static.exercisedb.dev/media/UpWmA5E.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 바닥에 앉아 다리를 앞으로 곧게 뻗는다.,Step:2 손을 엉덩이 옆 바닥에 짚고 손가락은 앞을 향하게 한다.,Step:3 코어에 힘을 주고 다리를 들어 올리되 무릎은 편다.,Step:4 가능한 한 다리가 바닥과 평행해지도록 들어 올려 몸이 L자 형태가 되게 한다.,Step:5 가능한 오래 자세를 유지한다.,Step:6 다리를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3xK09Sk', '맨몸 스쿼트 로우', 'https://static.exercisedb.dev/media/3xK09Sk.gif', '등 위쪽', '등', '맨몸', '이두근,어깨', 'Step:1 발을 어깨너비로 벌리고 팔을 뻗어 튼튼한 고정물 또는 TRX를 잡는다.,Step:2 등을 곧게 유지한 채 스쿼트 자세로 내려가며 무릎이 발끝보다 앞으로 나가지 않게 한다.,Step:3 스쿼트 자세에서 팔로 몸을 끌어올리며 견갑골을 모아 조인다.,Step:4 정점에서 잠깐 멈춘다.,Step:5 천천히 내려와 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VLYXo8S', '가중 둥근 팔', 'https://static.exercisedb.dev/media/VLYXo8S.gif', '삼각근', '어깨', '가중', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 든다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:3 팔꿈치를 약간 굽힌 채 양팔을 옆으로 들어 올린다.,Step:4 팔이 바닥과 평행이 될 때까지 들어 올린다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KUaZst7', '아령 누워있는 앙와위 컬', 'https://static.exercisedb.dev/media/KUaZst7.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 등을 대고 눕고 덤벨을 양손에 들며 손바닥은 위로 향하게 한다.,Step:2 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cA9FuWG', '바벨 벤트 암 풀오버', 'https://static.exercisedb.dev/media/cA9FuWG.gif', '광배근', '등', '바벨', '삼두근,가슴', 'Step:1 벤치에 눕되 머리는 한쪽 끝 쪽에 두고 발은 바닥에 둔다.,Step:2 바벨을 어깨너비로 잡고 팔을 가슴 위로 곧게 뻗는다.,Step:3 팔꿈치를 약간 굽힌 채 바벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 바벨을 다시 시작 자세로 들어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ioTf098', '짐 볼에 케이블 오버 헤드 컬', 'https://static.exercisedb.dev/media/ioTf098.gif', '이두근', '상완이두근', '케이블', '전완근,어깨', 'Step:1 짐 볼에 앉아 케이블 손잡이를 언더핸드 그립으로 잡는다.,Step:2 팔을 머리 위로 완전히 뻗되 팔꿈치는 귀 옆에 가깝게 둔다.,Step:3 상완을 고정한 채 케이블을 이마 쪽으로 천천히 말아 내린다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SNFfUff', '누워서 들어 올리는 바벨(엉덩이 위)', 'https://static.exercisedb.dev/media/SNFfUff.gif', '둔근', '허벅지', '바벨', '햄스트링,대퇴사두근', 'Step:1 벤치에 등을 대고 눕고 발을 바닥에 두며 무릎을 굽힌다.,Step:2 바벨을 오버핸드 그립으로 잡아 골반 위에 올려둔다.,Step:3 둔근에 힘을 주고 엉덩이를 들어 올려 무릎-어깨가 일직선이 되게 한다.,Step:4 정점에서 잠깐 멈춘 뒤 엉덩이를 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('w1NOByi', '밴드 스쿼트 로우', 'https://static.exercisedb.dev/media/w1NOByi.gif', '둔근', '허벅지', '밴드', '햄스트링,대퇴사두근,등', 'Step:1 밴드를 허리 높이의 튼튼한 고정물에 연결한다.,Step:2 고정물을 마주 보고 발을 어깨너비로 선다.,Step:3 밴드 손잡이를 잡고 손바닥이 서로 마주 보게 하여 팔을 앞쪽으로 뻗는다.,Step:4 무릎을 굽혀 스쿼트 자세로 내려가되 등을 곧게 유지하고 가슴을 든다.,Step:5 스쿼트 자세에서 손잡이를 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 풀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('s7HX1BY', '바벨 와이드 스쿼트', 'https://static.exercisedb.dev/media/s7HX1BY.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 바벨을 등 위(승모 또는 후면 삼각근)에 올린다.,Step:3 코어에 힘을 주고 가슴을 든 채 스쿼트로 내려간다(엉덩이를 뒤로).,Step:4 허벅지가 바닥과 평행이 될 때까지(또는 가능한 범위까지) 내려간다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 올라온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nIR4Rwl', '케이블시트 체스트 프레스', 'https://static.exercisedb.dev/media/nIR4Rwl.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 좌석 높이와 케이블 손잡이를 편한 위치로 조절한다.,Step:2 벤치에 앉아 등을 곧게 세우고 발을 바닥에 둔다.,Step:3 손잡이를 어깨 높이에서 오버핸드 그립으로 잡는다.,Step:4 손잡이를 앞으로 밀어 팔을 완전히 편다.,Step:5 잠깐 멈춘 뒤 손잡이를 천천히 되돌려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rg59QCH', '케틀벨 원암 플로어 프레스', 'https://static.exercisedb.dev/media/rg59QCH.gif', '가슴근육', '가슴', '케틀벨', '삼두근,어깨', 'Step:1 바닥에 눕고 무릎을 굽혀 발을 바닥에 둔다.,Step:2 한 손으로 케틀벨을 들고 손바닥이 발 쪽을 향하게 하여 팔을 위로 뻗는다.,Step:3 팔꿈치를 굽혀 케틀벨을 가슴 쪽으로 천천히 내리되 상완은 몸에 가깝게 둔다.,Step:4 케틀벨이 가슴 바로 위에 왔을 때 잠깐 멈춘다.,Step:5 팔꿈치를 펴 케틀벨을 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 수행 후 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FS63wTN', '덤벨 푸시 프레스', 'https://static.exercisedb.dev/media/FS63wTN.gif', '삼각근', '어깨', '덤벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 덤벨을 어깨 높이로 든다.,Step:2 무릎을 살짝 굽혀 몸을 낮춘다(딥).,Step:3 다리를 폭발적으로 펴면서 덤벨을 머리 위로 밀어 올린다.,Step:4 정점에서 팔을 완전히 펴고 잠그며 덤벨을 고정한다.,Step:5 덤벨을 어깨 높이로 내려 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5v7KYld', '스미스 인클라인 벤치프레스', 'https://static.exercisedb.dev/media/5v7KYld.gif', '가슴근육', '가슴', '스미스 머신', '어깨,삼두근', 'Step:1 인클라인 벤치를 30-45도로 조절한다.,Step:2 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 단단히 둔다.,Step:3 바를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 바를 랙에서 빼고 상부 가슴 쪽으로 천천히 내린다(팔꿈치는 약간 몸쪽).,Step:5 바닥 지점에서 잠깐 멈춘 뒤 바를 시작 자세로 밀어 올리며 팔을 편다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jCrtE9b', '원 암 슬램(메디슨볼 사용)', 'https://static.exercisedb.dev/media/jCrtE9b.gif', '복근', '허리', '메디신볼', '어깨,등', 'Step:1 발을 어깨너비로 벌리고 서서 메디신볼을 한 손으로 허리 앞에 든다.,Step:2 무릎을 살짝 굽히고 코어에 힘을 준다.,Step:3 메디신볼을 머리 위로 들어 올려 팔을 완전히 편다.,Step:4 코어와 어깨 힘으로 바닥을 향해 강하게 내리꽂는다.,Step:5 튀어 오르는 볼을 잡고 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vIICElP', '밴드를 눕힌 상태에서 고관절 내회전', 'https://static.exercisedb.dev/media/vIICElP.gif', '둔근', '허벅지', '밴드', '햄스트링,대퇴사두근', 'Step:1 등을 바닥에 대고 눕고 다리를 곧게 편 채 밴드를 발에 걸어 둔다.,Step:2 무릎을 굽혀 가슴 쪽으로 당기되 발은 붙인 채 유지한다.,Step:3 발을 붙인 채 무릎을 바깥쪽으로 천천히 회전시킨다.,Step:4 끝 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('I4hDWkc', '팔굽혀펴기', 'https://static.exercisedb.dev/media/I4hDWkc.gif', '가슴근육', '가슴', '맨몸', '삼두근,삼각근,코어', 'Step:1 손을 어깨너비보다 약간 넓게 두고 하이 플랭크 자세를 만든다(발은 모음).,Step:2 코어에 힘을 주고 몸이 일직선이 되게 유지한다.,Step:3 팔꿈치를 굽혀 가슴이 바닥 바로 위에 올 때까지 내려간다.,Step:4 잠깐 멈춘 뒤 팔을 펴며 시작 자세로 밀어 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kiJ4Z2K', '보조 풀업', 'https://static.exercisedb.dev/media/kiJ4Z2K.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 머신의 무게와 높이를 원하는 설정으로 조절한다.,Step:2 손잡이를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 편 채 매달리고 발은 바닥에서 띄운다.,Step:4 등을 수축하며 몸을 끌어올리되 팔꿈치는 몸에 가깝게 유지한다.,Step:5 턱이 손잡이 위로 올라갈 때까지 당긴다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RJgzwny', '마운틴 클라이머', 'https://static.exercisedb.dev/media/RJgzwny.gif', '심혈관계', '유산소', '맨몸', '코어,어깨,삼두근', 'Step:1 손을 어깨 아래에 두고 하이 플랭크 자세를 만든다.,Step:2 코어에 힘을 주고 오른쪽 무릎을 가슴 쪽으로 당긴다.,Step:3 빠르게 다리를 바꿔 왼쪽 무릎을 가슴 쪽으로 당긴다.,Step:4 달리듯이 번갈아 수행하되 엉덩이가 들리지 않게 유지한다.,Step:5 일정한 속도로 호흡하며 원하는 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fy7Tgy4', '덤벨 대체 해머 프리처 컬', 'https://static.exercisedb.dev/media/fy7Tgy4.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 벤치에 앉아 덤벨을 양손에 들고 손바닥이 서로 마주 보게 한 채 팔을 완전히 편다.,Step:2 상완을 고정하고 숨을 내쉬며 이두근을 수축해 덤벨을 말아 올린다.,Step:3 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:6 권장 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tBWXbIT', '케이블 인클라인 플라이', 'https://static.exercisedb.dev/media/tBWXbIT.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 머신을 낮은 위치로 설정하고 손잡이를 연결한다.,Step:2 인클라인 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 둔다.,Step:3 손잡이를 오버핸드 그립으로 잡고 팔을 앞쪽으로 곧게 뻗는다.,Step:4 팔꿈치를 살짝 굽힌 상태에서 팔을 양옆으로 천천히 벌린다.,Step:5 최대 범위에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LHWF7us', '케틀벨은 깨끗하게 걸림', 'https://static.exercisedb.dev/media/LHWF7us.gif', '햄스트링', '허벅지', '케틀벨', '둔근,대퇴사두근,종아리근', 'Step:1 발을 어깨너비로 벌리고 케틀벨을 허벅지 앞에서 잡는다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 등을 곧게 유지한다.,Step:3 케틀벨을 바닥 쪽으로 내리며 다리 사이로 스윙되게 한다.,Step:4 엉덩이와 무릎을 빠르게 펴며 케틀벨을 어깨 높이까지 올린다.,Step:5 어깨 높이에 오면 손목을 회전해 랙 포지션에서 받는다(팔꿈치 몸쪽).,Step:6 케틀벨을 다시 다리 사이로 내려 시작 자세로 돌아와 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8DiFDVA', '덤벨 리어 플라이', 'https://static.exercisedb.dev/media/8DiFDVA.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 든다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:3 팔을 바닥 쪽으로 늘어뜨리고 손바닥이 서로 마주 보게 한다.,Step:4 팔꿈치를 약간 굽힌 채 양팔을 옆으로 들어 올리며 견갑골을 모아 조인다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hq2hyDH', '덤벨 스탠딩 프리처 컬', 'https://static.exercisedb.dev/media/hq2hyDH.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 선 채 덤벨을 양손에 들고 손바닥을 앞쪽으로 향하게 한다.,Step:2 프리처 벤치(또는 인클라인 벤치)에 상완 뒤쪽을 대고 팔꿈치를 살짝 굽힌다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wu5LXwz', '올림픽 바벨 삼두근 익스텐션', 'https://static.exercisedb.dev/media/wu5LXwz.gif', '삼두근', '상완이두근', '올림픽 바벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 선 채 바벨을 오버핸드 그립으로 잡는다.,Step:2 팔을 완전히 펴 바벨을 머리 위로 든다.,Step:3 상완을 머리 옆에 고정한 채 팔꿈치를 굽혀 바벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DpWMFP5', '케이블 시티드 오버헤드 컬', 'https://static.exercisedb.dev/media/DpWMFP5.gif', '이두근', '상완이두근', '케이블', '전완근,어깨', 'Step:1 케이블 머신을 마주 보고 벤치에 앉아 발을 바닥에 둔다.,Step:2 케이블 손잡이를 언더핸드 그립으로 어깨너비로 잡는다.,Step:3 상완을 고정하고 팔꿈치를 몸 옆에 가깝게 둔다.,Step:4 숨을 내쉬며 손잡이를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 손잡이를 천천히 내려 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rUXfn3R', '레버 백 익스텐션', 'https://static.exercisedb.dev/media/rUXfn3R.gif', '척추', '등', '레버리지 머신', '둔근,햄스트링', 'Step:1 머신을 몸에 맞게 조절해 움직임 범위를 편하게 만든다.,Step:2 머신에 앉아 등을 패드에 붙이고 발을 고정한다.,Step:3 손잡이나 그립 바를 잡는다.,Step:4 코어에 힘을 주고 상체를 천천히 앞으로 기울이며 등을 약간 둥글게 한다.,Step:5 바닥 지점에서 잠깐 멈추며 허리/등 아래쪽의 늘어남을 느낀다.,Step:6 등 근육을 사용해 상체를 천천히 들어 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aaxA3cm', '스미스 리버스 그립 벤트 오버 로우', 'https://static.exercisedb.dev/media/aaxA3cm.gif', '등 위쪽', '등', '스미스 머신', '이두근,전완근', 'Step:1 스미스 머신 바를 엉덩이 높이로 세팅한다.,Step:2 바를 마주 보고 발을 어깨너비로 선다.,Step:3 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:4 언더핸드 그립으로 어깨너비로 바를 잡는다.,Step:5 견갑골을 모으며 바를 하부 가슴 쪽으로 당긴다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 바를 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JWjujiY', '덤벨 원 암 엎드린 컬', 'https://static.exercisedb.dev/media/JWjujiY.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 평평한 벤치에 엎드려 한 손에 덤벨을 들고 손바닥이 아래를 보게 한다.,Step:2 팔을 완전히 펴 바닥 쪽으로 늘어뜨린다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 내린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Q4DSJPC', '스미스 원 암 로우', 'https://static.exercisedb.dev/media/Q4DSJPC.gif', '등 위쪽', '등', '스미스 머신', '이두근,전완근', 'Step:1 스미스 머신 바 높이를 허리 높이로 맞춘다.,Step:2 머신을 마주 보고 발을 어깨너비로 선다.,Step:3 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:4 한 손으로 바를 오버핸드 그립(손바닥 아래)으로 잡는다.,Step:5 팔꿈치를 몸에 가깝게 두고 바를 허리 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 바를 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 수행 후 반대팔도 한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3eGE2JC', '덤벨 프론트 레이즈', 'https://static.exercisedb.dev/media/3eGE2JC.gif', '삼각근', '어깨', '덤벨', '이두근,승모근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 들며 손바닥은 허벅지를 향하게 한다.,Step:2 팔을 곧게 편 채 숨을 내쉬며 덤벨을 앞쪽으로 들어 올려 어깨 높이까지 올린다.,Step:3 정점에서 잠깐 멈춘 뒤 숨을 들이마시며 덤벨을 천천히 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rGwhJ5o', '바벨 스탠딩 레그 종아리 들어올리기', 'https://static.exercisedb.dev/media/rGwhJ5o.gif', '종아리근', '종아리', '바벨', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 등 위에 올린다.,Step:2 종아리 힘으로 뒤꿈치를 가능한 높게 들어 올린다.,Step:3 정점에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('P5p0j8B', '케이블 스탠딩 크로스오버 하이 리버스 플라이', 'https://static.exercisedb.dev/media/P5p0j8B.gif', '삼각근', '어깨', '케이블', '승모근,능형근,후면 삼각근', 'Step:1 케이블 머신 양쪽에 D-핸들을 어깨 높이로 각각 연결한다.,Step:2 케이블 중앙에 서서 발을 어깨너비로 둔다.,Step:3 손잡이를 오버핸드 그립으로 잡고 팔을 양옆으로 뻗어 손바닥이 앞을 보게 한다.,Step:4 팔꿈치를 약간 굽힌 채 등을 곧게 유지한다.,Step:5 어깨와 상부 등을 사용해 손잡이를 몸 앞쪽으로 당기며 견갑골을 모아 조인다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IL0JUxR', '지론다 흉골 턱', 'https://static.exercisedb.dev/media/IL0JUxR.gif', '광배근', '등', '맨몸', '이두근,능형근,후면 삼각근', 'Step:1 높은 바를 마주 보고 발을 어깨너비로 선다.,Step:2 바를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 펴 매달리고 몸을 일직선으로 유지한다.,Step:4 광배와 이두에 힘을 주어 흉골이 바에 닿을 듯이 가슴을 끌어올린다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uX3sUBz', '거꾸로 된 행 v. 2', 'https://static.exercisedb.dev/media/uX3sUBz.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 스미스 머신 바를 허리 높이로 두거나 서스펜션 트레이너를 설치한다.,Step:2 바/손잡이를 오버핸드 그립으로 어깨너비로 잡는다.,Step:3 발을 앞으로 걸어 몸을 뒤로 기울여 약간 비스듬한 자세를 만든다.,Step:4 몸을 일직선으로 유지한 채 가슴을 바/손잡이 쪽으로 끌어올리며 견갑골을 모아 조인다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lFhb2Rw', '스미스 프런트 스쿼트(클린 그립)', 'https://static.exercisedb.dev/media/lFhb2Rw.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 스미스 머신 바벨을 어깨 높이로 세팅한다.,Step:2 바벨을 마주 보고 발을 어깨너비로 선다.,Step:3 바벨을 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 뒤로 물러나 바벨을 앞 어깨에 얹어 쇄골/삼각근 위에 올린다.,Step:5 가슴을 들고 등을 곧게 유지하며 코어에 힘을 준다.,Step:6 무릎과 엉덩이를 굽혀 의자에 앉듯 내려간다.,Step:7 허벅지가 바닥과 평행이 되거나 가능하면 더 아래까지 내려간다.,Step:8 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:9 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('A6wtbuL', '덤벨 스탠딩 오버헤드 프레스', 'https://static.exercisedb.dev/media/A6wtbuL.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 들어 어깨 높이에서 손바닥이 앞을 보게 한다.,Step:2 덤벨을 위로 밀어 올려 팔을 머리 위로 완전히 편다.,Step:3 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 어깨 높이로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SpsOSXk', '케이블 후면 풀다운', 'https://static.exercisedb.dev/media/SpsOSXk.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 케이블 풀리 위치를 가장 높게 설정한다.,Step:2 머신을 마주 보고 앉아 발을 바닥에 두고 무릎을 살짝 굽힌다.,Step:3 손잡이를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 등을 곧게 유지한 채 상체를 약간 뒤로 기울이고 가슴을 든다.,Step:5 손잡이를 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 바닥 지점에서 잠깐 멈춘 뒤 천천히 케이블을 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VYmYxK5', '짐 볼에 덤벨 원 암 해머 프레스', 'https://static.exercisedb.dev/media/VYmYxK5.gif', '삼두근', '상완이두근', '덤벨', '어깨,가슴', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 세운다.,Step:2 한 손에 덤벨을 들고 손바닥이 안쪽을 향하게 하며 팔꿈치를 90도로 굽힌다.,Step:3 반대손은 허리에 두어 몸을 안정시킨다.,Step:4 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:5 정점에서 잠깐 멈춘 뒤 덤벨을 천천히 내린다.,Step:6 원하는 반복 횟수만큼 수행 후 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RSOsp5d', '전 세계에 서있는 아령', 'https://static.exercisedb.dev/media/RSOsp5d.gif', '삼각근', '어깨', '덤벨', '삼두근,전완근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 든다.,Step:2 팔을 어깨 높이로 옆으로 곧게 뻗고 손바닥은 아래를 향하게 한다.,Step:3 팔을 곧게 편 채 원을 그리듯 천천히 회전해 덤벨을 몸 앞쪽으로 가져오고 이어 머리 위로 올린다.,Step:4 같은 원운동으로 덤벨을 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aaXr7ld', '레버 t 바 행', 'https://static.exercisedb.dev/media/aaXr7ld.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이와 발판 위치를 조절해 정렬이 맞게 한다.,Step:2 머신에 앉아 가슴을 패드에 대고 발을 발판에 둔다.,Step:3 손잡이를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 손잡이를 몸통 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 손잡이를 풀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('arvaszz', '팔을 낮추는 수정된 푸시업', 'https://static.exercisedb.dev/media/arvaszz.gif', '전완근', '팔 아래', '맨몸', '삼두근,가슴,어깨', 'Step:1 손을 어깨 아래에 두고 푸시업 자세를 만든다(몸은 일직선).,Step:2 팔꿈치를 몸에 가깝게 두고 굽혀 몸을 바닥 쪽으로 내린다.,Step:3 팔꿈치가 90도 정도가 되면 전완을 바닥에 내려 팔꿈치가 어깨 아래에 오게 한다.,Step:4 잠깐 멈춘 뒤 손바닥으로 밀어 전완을 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Qa55kX1', '슬레이 해킹 스쿼트', 'https://static.exercisedb.dev/media/Qa55kX1.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 자신의 키에 맞게 슬레이 머신 위치를 조절한다.,Step:2 발을 어깨너비로 플랫폼에 두고 발끝은 약간 바깥으로 향하게 한다.,Step:3 손잡이나 바를 잡아 몸을 고정한다.,Step:4 무릎과 엉덩이를 굽혀 몸을 내려가되 등을 곧게 유지하고 가슴을 든다.,Step:5 허벅지가 바닥과 평행이 되거나 가능하면 더 아래까지 내려간다.,Step:6 잠깐 멈춘 뒤 뒤꿈치로 밀어 몸을 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kont8Ut', '덤벨 시티드 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/kont8Ut.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 세우고 발을 바닥에 둔다.,Step:2 덤벨을 양손으로 잡고 팔을 머리 위로 곧게 뻗는다.,Step:3 팔꿈치를 굽혀 덤벨을 머리 뒤로 내리되 상완은 귀 옆에 고정한다.,Step:4 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UfePqpx', '스미스 데드리프트', 'https://static.exercisedb.dev/media/UfePqpx.gif', '둔근', '허벅지', '스미스 머신', '햄스트링,대퇴사두근,허리', 'Step:1 스미스 머신 바를 엉덩이 높이로 세팅한다.,Step:2 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:3 엉덩이와 무릎을 굽혀 등을 곧게 세우고 가슴을 든 채 바를 오버핸드 그립으로 잡는다(어깨너비보다 약간 넓게).,Step:4 코어에 힘을 주고 엉덩이와 무릎을 펴 바를 들어 올리되 바는 몸에 가깝게 유지한다.,Step:5 완전히 서서 엉덩이와 무릎을 잠근다.,Step:6 엉덩이와 무릎을 굽혀 바를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wt6rwjk', '덤벨 손바닥 회전 구부러진 행', 'https://static.exercisedb.dev/media/wt6rwjk.gif', '등 위쪽', '등', '덤벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 든다(오버핸드 그립).,Step:2 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 유지하고 무릎은 살짝 굽힌다.,Step:3 팔을 아래로 늘어뜨리고 손바닥이 몸을 향하게 한다.,Step:4 코어에 힘을 주고 덤벨을 가슴 쪽으로 당기되 팔꿈치를 몸에 가깝게 둔다.,Step:5 당기면서 손바닥이 몸 바깥을 향하도록 회전한다.,Step:6 정점에서 견갑골을 모아 조인다.,Step:7 덤벨을 천천히 내리며 손바닥을 다시 시작 방향으로 회전한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PdmaD0N', '덤벨 스탠딩 삼두근 익스텐션', 'https://static.exercisedb.dev/media/PdmaD0N.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 한 손에 덤벨을 든다.,Step:2 팔을 곧게 펴 덤벨을 머리 위로 든다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 덤벨을 머리 뒤로 내린다.,Step:4 팔을 펴 덤벨을 시작 자세로 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dXz8zjF', '케이블 드래그 컬', 'https://static.exercisedb.dev/media/dXz8zjF.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 마주 보고 발을 어깨너비로 선다.,Step:2 케이블 바/손잡이를 언더핸드 그립으로 잡고 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 손잡이를 어깨 쪽으로 끌어올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 손잡이를 천천히 내려 팔을 완전히 편다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('u4bAmKp', '밴드 트위스팅 오버헤드 프레스', 'https://static.exercisedb.dev/media/u4bAmKp.gif', '삼각근', '어깨', '밴드', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 밴드를 발 아래에 고정한다.,Step:2 밴드 손잡이를 어깨 높이로 들어 손바닥이 앞을 보게 한다.,Step:3 코어에 힘을 주고 밴드를 머리 위로 밀어 팔을 완전히 편다.,Step:4 밀어 올리면서 상체를 한쪽으로 비틀되 골반은 고정한다.,Step:5 정점에서 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:6 반대쪽도 같은 방식으로 수행한다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jpgqxiS', '케이블 스탠딩 크런치', 'https://static.exercisedb.dev/media/jpgqxiS.gif', '복근', '허리', '케이블', '복사근', 'Step:1 하이 풀리에 케이블 손잡이를 연결하고 머신을 등지고 선다.,Step:2 손잡이를 양손으로 잡아 머리 뒤에 두고 팔꿈치는 굽힌다.,Step:3 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:4 복근에 힘을 주며 숨을 내쉬고 상체를 무릎 쪽으로 말아 내리며 팔꿈치를 허벅지 쪽으로 가져간다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UzkLrem', '덤벨 리어 레터럴 레이즈(서포트 헤드)', 'https://static.exercisedb.dev/media/UzkLrem.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 든다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:3 팔꿈치를 약간 굽힌 채 양팔을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GOJKFfO', '짐 볼 한쪽 다리 대각선 차기 햄스트링 컬', 'https://static.exercisedb.dev/media/GOJKFfO.gif', '둔근', '허벅지', '스태빌리티 볼', '햄스트링,종아리근', 'Step:1 등을 바닥에 대고 누워 다리를 곧게 편 채 발뒤꿈치를 스태빌리티 볼 위에 올린다.,Step:2 팔은 몸 옆에 두어 안정적으로 지지한다.,Step:3 둔근과 코어에 힘을 주어 엉덩이를 들어 어깨-발뒤꿈치가 일직선이 되게 한다.,Step:4 오른쪽 무릎을 굽혀 가슴 쪽으로 당기되 왼다리는 곧게 편 채 발을 당긴다.,Step:5 오른다리를 몸의 대각선 방향으로 곧게 뻗어 햄스트링에 힘을 준다.,Step:6 오른다리를 천천히 시작 자세로 되돌리며 안정성을 유지한다.,Step:7 왼다리도 같은 방식으로 수행하며 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1PK5Uo3', '케이블 경사 푸시다운', 'https://static.exercisedb.dev/media/1PK5Uo3.gif', '광배근', '등', '케이블', '삼두근,어깨', 'Step:1 하이 풀리에 스트레이트 바를 연결한다.,Step:2 머신을 등지고 발을 어깨너비로 선다.,Step:3 바를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 상체를 약간 앞으로 기울이고 등을 곧게 유지한다.,Step:5 팔꿈치를 펴 바를 허벅지 쪽으로 당겨 내린다.,Step:6 바닥 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YtgD7Xq', '숄더 그립 풀업', 'https://static.exercisedb.dev/media/YtgD7Xq.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 풀업바를 어깨너비 그립으로 잡는다(손바닥은 바깥쪽).,Step:2 팔을 완전히 편 채 매달린다.,Step:3 등을 수축하며 몸을 끌어올려 턱이 바 위로 올라가게 한다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GdMa1ET', '경사 견갑골 밀어 올리기', 'https://static.exercisedb.dev/media/GdMa1ET.gif', '전거근', '가슴', '맨몸', '삼두근,어깨', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 손을 벤치 위에 어깨너비보다 약간 넓게 둔다.,Step:3 발을 바닥에 두고 골반 너비로 선다.,Step:4 팔꿈치를 굽혀 가슴을 벤치 쪽으로 내린다(팔꿈치는 몸쪽).,Step:5 내려가면서 견갑골을 뒤로 모아 조인다.,Step:6 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('H9y3Dkr', '인클라인 벤치에서 케이블 투 암 컬', 'https://static.exercisedb.dev/media/H9y3Dkr.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 인클라인 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 둔다.,Step:2 케이블 손잡이를 언더핸드 그립으로 잡고 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 손잡이를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 손잡이를 천천히 내려 팔을 완전히 편다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4Ml7QFO', '똑바로 다리 올리기', 'https://static.exercisedb.dev/media/4Ml7QFO.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 풀업바에 매달려 팔을 완전히 펴고 손바닥은 바깥쪽을 향하게 한다.,Step:2 코어에 힘을 주고 다리를 앞쪽으로 곧게 들어 올린다.,Step:3 다리가 바닥과 평행이 되거나 가능한 높이까지 올린다.,Step:4 정점에서 잠깐 멈춘 뒤 다리를 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aumB2IV', '보조 윗몸일으키기', 'https://static.exercisedb.dev/media/aumB2IV.gif', '복근', '허리', '도움을 준', '고관절 굴근', 'Step:1 벤치 가장자리에 앉거나 누군가 발을 잡아 고정해준다.,Step:2 등을 바닥에 대고 눕고 무릎을 굽혀 발바닥을 바닥에 둔다.,Step:3 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:4 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 되게 말아 올린다.,Step:5 정점에서 잠깐 멈춘 뒤 천천히 시작 자세로 내려간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NdIb5Z1', '바벨 스탠딩 와이드 그립 컬', 'https://static.exercisedb.dev/media/NdIb5Z1.gif', '이두근', '상완이두근', '바벨', '전완근,어깨', 'Step:1 발을 어깨너비로 벌리고 곧게 선다. 바벨을 와이드 오버핸드 그립으로 잡는다(손이 어깨너비보다 넓게).,Step:2 바벨을 허벅지 앞에서 팔 길이만큼 늘어지게 둔다(손바닥은 몸 바깥쪽).,Step:3 상완을 고정한 채 숨을 내쉬며 바벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 바벨을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RJa4tCo', '줄다리기', 'https://static.exercisedb.dev/media/RJa4tCo.gif', '삼각근', '어깨', '로프', '전완근,코어', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 로프 양 끝을 각각 한 손씩 잡고 손바닥이 서로 마주 보게 한다.,Step:3 팔을 어깨 높이까지 들어 올리되 팔꿈치는 살짝 굽힌다.,Step:4 팔을 번갈아 빠르게 위아래로 움직여 로프에 물결을 만든다.,Step:5 원하는 시간 또는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fY68AyX', '짐 볼에 덤벨 해머 컬', 'https://static.exercisedb.dev/media/fY68AyX.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 세운다.,Step:2 덤벨을 양손에 들고 손바닥이 몸을 향하게 한 채 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:5 정점에서 잠깐 멈추며 이두근을 조인다.,Step:6 숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('62Nw60O', '바벨 리어 런지 v. 2', 'https://static.exercisedb.dev/media/62Nw60O.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선 채 바벨을 등 위에 올린다.,Step:2 오른발을 뒤로 내딛어 발 앞쪽(볼)로 착지한다.,Step:3 양쪽 무릎을 굽혀 내려가며 왼 허벅지가 바닥과 평행이 되게 한다.,Step:4 왼쪽 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 반대쪽 다리로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BgljGjd', '레버 리버스 T바 로우', 'https://static.exercisedb.dev/media/BgljGjd.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 레버 머신의 좌석 높이와 발판 위치를 조절한다.,Step:2 머신에 앉아 가슴을 패드에 대고 발을 발판에 둔다.,Step:3 손잡이를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 손잡이를 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 정점에서 잠깐 멈춘 뒤 천천히 풀어 팔을 다시 뻗는다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('I4KkPdl', '케틀벨 더블 푸시 프레스', 'https://static.exercisedb.dev/media/I4KkPdl.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 케틀벨을 양손에 들어 어깨 높이에 둔다.,Step:2 무릎을 살짝 굽히고 코어에 힘을 준다.,Step:3 엉덩이-무릎-발목을 폭발적으로 펴며 케틀벨을 머리 위로 밀어 올린다.,Step:4 정점에서 팔을 완전히 펴 고정한다.,Step:5 팔꿈치를 굽혀 케틀벨을 어깨 높이로 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('K5xgdvI', '밧줄을 잡고 기대는 엄지발가락 자세', 'https://static.exercisedb.dev/media/K5xgdvI.gif', '햄스트링', '허벅지', '로프', '종아리근,둔근', 'Step:1 등을 바닥에 대고 누워 다리를 곧게 편 채 팔을 몸 옆에 둔다.,Step:2 로프를 오른발 앞쪽(발바닥 공) 위에 걸고 양손으로 로프 끝을 잡는다.,Step:3 무릎을 편 채 오른다리를 가슴 쪽으로 천천히 들어 올리고 발끝은 당긴다.,Step:4 몇 초간 스트레칭을 유지한 뒤 다리를 천천히 내린다.,Step:5 왼다리도 같은 방식으로 수행한다.,Step:6 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('T8UpLkb', '믹스그립 친업', 'https://static.exercisedb.dev/media/T8UpLkb.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 풀업바를 언더핸드 그립으로 잡되 손 간격은 어깨너비보다 약간 넓게 한다.,Step:2 팔을 완전히 편 채 매달리고 발은 바닥에서 띄운다.,Step:3 가슴을 끌어올리듯 당겨 턱이 바 위로 올라가게 한다.,Step:4 정점에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:5 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vptOQ4N', '딥 푸시 업', 'https://static.exercisedb.dev/media/vptOQ4N.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 덤벨을 바닥에 두고 하이 플랭크 자세를 만든다(손은 어깨너비보다 약간 넓게).,Step:2 팔꿈치를 몸에 가깝게 두고 굽혀 가슴을 바닥 쪽으로 내린다.,Step:3 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xgsGFVM', '크랩 트위스트 토 터치', 'https://static.exercisedb.dev/media/xgsGFVM.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 무릎을 굽히고 발을 바닥에 붙인 채 바닥에 앉아 시작한다.,Step:2 손가락이 발을 향하도록 손을 몸 뒤에 짚고 엉덩이를 바닥에서 들어 올린다.,Step:3 한쪽 다리를 앞으로 곧게 뻗는 동시에 반대쪽 손으로 발가락을 향해 뻗는다.,Step:4 시작 자세로 돌아온 뒤 반대쪽도 같은 동작으로 반복한다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LIlE5Tn', '점프 스쿼트', 'https://static.exercisedb.dev/media/LIlE5Tn.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트 자세로 내려간다.,Step:3 엉덩이·무릎·발목을 폭발적으로 펴며 바닥에서 점프한다.,Step:4 공중에서 균형을 위해 팔을 재빠르게 앞으로 가져온다.,Step:5 발 앞부분(앞꿈치)으로 부드럽게 착지하고 즉시 다음 반복으로 이어간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ainizkb', '덤벨 업라이트 로우', 'https://static.exercisedb.dev/media/ainizkb.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 서서 각 손에 덤벨을 오버핸드 그립으로 잡는다.,Step:2 팔을 완전히 편 채 덤벨을 허벅지 앞쪽에 자연스럽게 늘어뜨린다.,Step:3 등을 곧게 세우고 코어를 고정한 상태에서, 내쉬며 덤벨을 턱 쪽으로 수직에 가깝게 끌어올리되 팔꿈치가 앞서가게 한다.,Step:4 꼭대기에서 잠깐 멈춘 뒤, 들이쉬며 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eHBlPsa', '케이블 원 암 프리처 컬', 'https://static.exercisedb.dev/media/eHBlPsa.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 프리처 컬 패드가 가슴 높이에 오도록 조절한다.,Step:2 케이블 머신을 정면으로 보고 발을 어깨너비로 벌리고 선다.,Step:3 언더핸드 그립으로 케이블 핸들을 잡고, 상완을 프리처 패드에 밀착시킨다.,Step:4 등을 곧게 세우고 코어를 고정한다.,Step:5 상완이 패드에서 떨어지지 않게 유지하며 천천히 핸들을 어깨 쪽으로 컬한다.,Step:6 동작 상단에서 이두근을 수축하며 잠깐 멈춘다.,Step:7 천천히 시작 자세로 내려준다.,Step:8 원하는 반복 횟수만큼 반복한다.,Step:9 팔을 바꿔 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tznL2Ad', '케틀벨 더블 저크', 'https://static.exercisedb.dev/media/tznL2Ad.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 케틀벨을 어깨 높이에 든다.,Step:2 무릎을 살짝 굽히고 코어를 조인다.,Step:3 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 무릎을 굽히며 빠르게 부분 스쿼트(딥)로 내려간다.,Step:5 엉덩이와 무릎을 폭발적으로 펴며 케틀벨을 위로 강하게 밀어 올린다.,Step:6 무릎을 약간 굽힌 상태로 팔을 잠그고 머리 위에서 케틀벨을 받아낸다.,Step:7 몸을 곧게 세우고 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Kxquu2E', '바벨 스텝업', 'https://static.exercisedb.dev/media/Kxquu2E.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 상체 윗등에 바벨을 올린 채 벤치나 스텝 앞에 선다.,Step:2 한쪽 발을 벤치/스텝 위에 올려 발바닥 전체가 면에 닿도록 한다.,Step:3 뒤꿈치로 바닥을 밀며 올라가 엉덩이와 무릎을 완전히 편다.,Step:4 상단에서 잠깐 멈춘 뒤 시작 자세로 천천히 내려온다.,Step:5 반대쪽 다리로 반복한다.,Step:6 원하는 반복 횟수만큼 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sTg7iys', '밴드 프론트 레터럴 레이즈', 'https://static.exercisedb.dev/media/sTg7iys.gif', '삼각근', '어깨', '밴드', '승모근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 손바닥이 아래를 향하게 밴드를 허벅지 앞에서 잡는다.,Step:2 팔을 곧게 편 채 밴드를 앞쪽으로 들어 올려 팔이 바닥과 평행해질 때까지 올린다.,Step:3 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bWlZvXh', '나비 요가 자세', 'https://static.exercisedb.dev/media/bWlZvXh.gif', '내전근', '허벅지', '맨몸', '햄스트링,샅', 'Step:1 다리를 앞으로 뻗고 바닥에 앉아 시작한다.,Step:2 무릎을 굽혀 발바닥을 서로 붙이고 무릎이 양옆으로 떨어지게 한다.,Step:3 양손으로 발목이나 발을 잡는다.,Step:4 상체를 곧게 세우고 척추를 길게 늘린다.,Step:5 무릎을 바닥 쪽으로 부드럽게 눌러 허벅지 안쪽이 늘어나는 느낌을 받는다.,Step:6 몇 번의 호흡 동안 자세를 유지한다.,Step:7 풀 때는 무릎을 천천히 올리고 다리를 다시 뻗는다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('p195zsJ', '두 발가락 터치(남성)', 'https://static.exercisedb.dev/media/p195zsJ.gif', '척추', '등', '맨몸', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 팔을 옆으로 뻗는다.,Step:2 등을 곧게 유지한 채 허리에서 접어 상체를 앞으로 숙이고 무릎은 약간 굽힌다.,Step:3 다리를 곧게 유지하며 양손을 발가락 쪽으로 뻗는다.,Step:4 하단에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CuaWCmC', '케이블 사이드 풀다운(로프 부착 포함)', 'https://static.exercisedb.dev/media/CuaWCmC.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 케이블 머신의 높은 위치에 로프 어태치먼트를 연결한다.,Step:2 머신을 정면으로 보고 발을 어깨너비로 벌리고 선다.,Step:3 오버핸드 그립으로 로프를 잡되 손바닥이 서로 마주보게 한다.,Step:4 등을 곧게 세우고 상체를 약간 뒤로 기댄다.,Step:5 로프를 몸 옆으로 아래로 당기며 견갑골을 모아 등 근육을 수축한다.,Step:6 하단에서 잠깐 멈춘다.,Step:7 긴장을 유지한 채 천천히 시작 자세로 되돌린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RaflbWD', '덤벨 인클라인 컬 v. 2', 'https://static.exercisedb.dev/media/RaflbWD.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 인클라인 벤치에 앉아 양손에 덤벨을 들고 손바닥을 전방으로 하여 팔을 완전히 편다.,Step:2 상완을 고정한 채 내쉬며 덤벨을 컬해 이두근을 수축한다.,Step:3 이두근이 완전히 수축하고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 상단에서 이두근을 조이며 잠깐 멈춘다.,Step:5 들이쉬며 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pAIWRGu', '손 자전거', 'https://static.exercisedb.dev/media/pAIWRGu.gif', '가슴근육', '가슴', '상체 에르고미터', '삼두근,어깨', 'Step:1 좌석 높이와 핸들바 위치를 편안하게 조절한다.,Step:2 에르고미터에 앉아 등을 곧게 세우고 발은 페달에 둔다.,Step:3 손으로 핸들을 잡고 팔꿈치가 90도가 되도록 팔 위치를 잡는다.,Step:4 핸들을 밀고 당기는 동작으로 손으로 페달링을 시작한다.,Step:5 원하는 시간 또는 반복 횟수만큼 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nZZZy9m', '레버 하이 로우', 'https://static.exercisedb.dev/media/nZZZy9m.gif', '등 위쪽', '등', '레버리지 머신', '이두근,후면 삼각근', 'Step:1 좌석 높이와 발판을 편안하게 조절한다.,Step:2 가슴을 패드에 밀착하고 발을 발판에 평평하게 둔 채 앉는다.,Step:3 어깨너비보다 약간 넓게 오버핸드 그립으로 손잡이를 잡는다.,Step:4 등을 곧게 세우고 코어를 조인다.,Step:5 손잡이를 몸 쪽으로 당기며 견갑골을 모아준다.,Step:6 수축 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 되돌린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dTg95eZ', '무릎 터치 크런치', 'https://static.exercisedb.dev/media/dTg95eZ.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 무릎을 굽히고 발을 바닥에 둔 채 등을 대고 눕는다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 벌린다.,Step:3 복근에 힘을 주며 견갑골을 바닥에서 들어 올리고 오른손을 왼쪽 무릎 쪽으로 뻗는다.,Step:4 시작 자세로 돌아온 뒤 이번에는 왼손을 오른쪽 무릎 쪽으로 뻗는다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Q497lAE', '드롭 푸시 업', 'https://static.exercisedb.dev/media/Q497lAE.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 손을 어깨너비보다 약간 넓게 두고 하이 플랭크 자세로 시작한다.,Step:2 팔꿈치를 몸에 가깝게 유지하며 가슴을 바닥 쪽으로 내린다.,Step:3 가슴이 바닥 바로 위에 왔을 때 무릎을 빠르게 바닥에 내려놓는다.,Step:4 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GXoaSgn', '바벨 길로틴 벤치 프레스', 'https://static.exercisedb.dev/media/GXoaSgn.gif', '가슴근육', '가슴', '바벨', '어깨,삼두근', 'Step:1 벤치에 누워 발을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 어깨너비보다 약간 넓게 오버핸드 그립으로 바벨을 잡는다.,Step:3 팔꿈치를 바깥으로 향하게 유지하며 바벨을 목 쪽으로 천천히 내린다.,Step:4 바벨이 목 바로 위에 왔을 때 잠깐 멈춘다.,Step:5 팔을 펴며 시작 자세로 바벨을 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2sQGZ5b', '덤벨 원 암 서있는 해머 컬', 'https://static.exercisedb.dev/media/2sQGZ5b.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 손바닥이 몸통을 향하도록 각 손에 덤벨을 들고 곧게 선다.,Step:2 팔꿈치를 몸통에 가깝게 붙이고 상완을 고정한다.,Step:3 내쉬며 덤벨을 컬해 이두근을 수축한다.,Step:4 이두근이 완전히 수축하고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 상단에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이쉬며 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rR0LJzx', '덤벨 루마니안 데드리프트', 'https://static.exercisedb.dev/media/rR0LJzx.gif', '둔근', '허벅지', '덤벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 양손에 덤벨을 든다.,Step:2 등을 곧게 세우고 코어를 고정한 채, 엉덩이를 접어(힙 힌지) 덤벨을 바닥 쪽으로 내리며 무릎은 약간만 굽힌다.,Step:3 햄스트링이 늘어나는 느낌이 들 때까지 내린 뒤, 뒤꿈치로 밀어 올리며 둔근을 수축해 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pwt0pnM', '케이블 시트 하이 로우(v-bar)', 'https://static.exercisedb.dev/media/pwt0pnM.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 케이블 머신에 앉아 발을 바닥에 두고 무릎을 약간 굽힌다.,Step:2 손바닥이 서로 마주보게 오버핸드 그립으로 V-바를 잡고 손은 어깨너비로 둔다.,Step:3 등을 곧게 세우고 엉덩이에서 약간 앞으로 기울인다.,Step:4 견갑골을 모으며 V-바를 몸통 쪽으로 당겨 등 근육을 수축한다.,Step:5 수축 지점에서 잠깐 멈춘 뒤 천천히 긴장을 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SxHteRW', '덤벨 스탠딩 얼터너티브 레이즈', 'https://static.exercisedb.dev/media/SxHteRW.gif', '삼각근', '어깨', '덤벨', '승모근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 각 손에 덤벨을 든 채 손바닥이 몸을 향하게 한다.,Step:2 등을 곧게 세우고 코어를 고정한다.,Step:3 한쪽 덤벨을 옆으로 들어 올리되 팔은 곧게 펴고 손바닥은 아래를 향하게 한다.,Step:4 팔이 바닥과 평행해질 때까지 올린다.,Step:5 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:6 반대쪽도 같은 방식으로 수행한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NfP83rA', '덤벨 거짓말 대체 익스텐션', 'https://static.exercisedb.dev/media/NfP83rA.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 등을 대고 누워 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 팔을 가슴 위로 곧게 펴되 팔꿈치는 약간만 굽혀 고정한다.,Step:3 한쪽 팔꿈치를 굽혀 덤벨을 머리 쪽으로 내리며, 반대쪽 팔은 펴서 유지한다.,Step:4 하단에서 잠깐 멈춘 뒤 덤벨을 다시 들어 올려 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 반복하며 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('M5Y7GPg', '웨이티드 스탠딩 컬', 'https://static.exercisedb.dev/media/M5Y7GPg.gif', '이두근', '상완이두근', '가중', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥을 전방으로 향하게 한다.,Step:2 팔꿈치를 몸통에 가깝게 유지하고 내쉬며 덤벨을 어깨 높이까지 컬한다.,Step:3 상단에서 잠깐 멈춘 뒤, 들이쉬며 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eOrFCnx', '덤벨 아놀드 프레스 v. 2', 'https://static.exercisedb.dev/media/eOrFCnx.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴 위쪽', 'Step:1 등받이가 있는 벤치에 앉아 덤벨을 어깨 높이에 들고 손바닥이 몸을 향하게 하며 팔꿈치를 굽힌다.,Step:2 덤벨을 위로 밀어 올려 팔을 완전히 펴준다.,Step:3 올리면서 손목을 회전해 상단에서 손바닥이 전방을 향하게 한다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('q2ADGqV', '케이블 사이드 크런치', 'https://static.exercisedb.dev/media/q2ADGqV.gif', '복근', '허리', '케이블', '복사근', 'Step:1 낮은 풀리에 케이블 핸들을 연결하고 머신 옆으로 선다.,Step:2 머신에서 먼 쪽 손으로 핸들을 잡고 반대 손은 허리에 둔다.,Step:3 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:4 복근에 힘을 주고 허리를 옆으로 굽혀 팔꿈치가 엉덩이 쪽으로 내려가게 한다.,Step:5 하단에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 반대쪽으로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gn5FwYT', '안정성 볼 크런치(머리 뒤의 손 전체 범위)', 'https://static.exercisedb.dev/media/Gn5FwYT.gif', '복근', '허리', '스태빌리티 볼', '고관절 굴근', 'Step:1 발을 바닥에 평평하게 두고 무릎을 90도로 굽힌 채 스태빌리티 볼에 앉는다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 벌린다.,Step:3 복근에 힘을 주며 상체를 천천히 말아 올려 가슴이 무릎 쪽으로 가까워지게 한다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내려온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dG7tG5y', '바벨 슈러그', 'https://static.exercisedb.dev/media/dG7tG5y.gif', '승모근', '등', '바벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 바벨을 잡는다.,Step:2 팔을 곧게 편 채 등을 곧게 유지한다.,Step:3 어깨를 귀 쪽으로 최대한 끌어올리며 승모근을 수축한다.,Step:4 상단에서 잠깐 멈춘 뒤 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZZKbeMw', '레버 슈러그', 'https://static.exercisedb.dev/media/ZZKbeMw.gif', '승모근', '등', '레버리지 머신', '어깨', 'Step:1 좌석 높이를 조절한 뒤 등받이에 등을 대고 레버리지 머신에 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔을 곧게 편다.,Step:3 등을 곧게 유지한 채 어깨를 귀 쪽으로 최대한 끌어올린다.,Step:4 수축을 잠깐 유지한 뒤 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CMAxnsG', '시계 푸쉬업', 'https://static.exercisedb.dev/media/CMAxnsG.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 손을 어깨 아래에 두고 몸을 머리부터 발끝까지 일직선으로 만든 하이 플랭크 자세로 시작한다.,Step:2 팔꿈치를 옆구리에 가깝게 유지하며 몸을 바닥 쪽으로 내린다.,Step:3 내려가면서 몸을 왼쪽으로 회전해 왼팔을 옆으로 곧게 뻗는다.,Step:4 몸을 중앙으로 되돌리며 시작 자세로 밀어 올린다.,Step:5 다시 푸시업을 하되 이번에는 오른쪽으로 회전해 오른팔을 옆으로 곧게 뻗는다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NJzBsGJ', '아령 슈러그', 'https://static.exercisedb.dev/media/NJzBsGJ.gif', '승모근', '등', '덤벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 손바닥이 몸을 향하게 각 손에 덤벨을 든다.,Step:2 팔을 곧게 편 채 덤벨을 몸 옆에 늘어뜨린다.,Step:3 어깨를 최대한 끌어올려 마치 어깨로 귀를 만지려는 듯이 한다.,Step:4 수축을 1초 정도 유지한 뒤 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('khlHMqs', '밴드 벤치 프레스', 'https://static.exercisedb.dev/media/khlHMqs.gif', '가슴근육', '가슴', '밴드', '삼두근,어깨', 'Step:1 벤치에 누워 발을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 어깨너비보다 약간 넓게 오버핸드 그립으로 밴드 손잡이를 잡는다.,Step:3 팔을 완전히 펴며 밴드를 가슴에서 멀어지도록 밀어낸다.,Step:4 팔꿈치를 90도로 유지하며 밴드를 천천히 가슴 쪽으로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('goJ6ezq', '케이블 레터럴 레이즈', 'https://static.exercisedb.dev/media/goJ6ezq.gif', '삼각근', '어깨', '케이블', '승모근,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 케이블 손잡이를 잡는다.,Step:2 팔을 곧게 편 채 코어를 고정한다.,Step:3 팔을 옆으로 들어 올려 바닥과 평행해질 때까지 올린다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hvHhCv8', '케이블 앞으로 올리기', 'https://static.exercisedb.dev/media/hvHhCv8.gif', '삼각근', '어깨', '케이블', '삼두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 약간 굽힌다.,Step:2 오버핸드 그립으로 케이블 손잡이를 잡고 손바닥을 아래로 향하게 하며 팔을 앞쪽으로 완전히 편다.,Step:3 팔을 곧게 편 채 손잡이를 어깨 높이까지 들어 올린다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UilDHSs', '프레스에 덤벨 서 손바닥', 'https://static.exercisedb.dev/media/UilDHSs.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 발을 어깨너비로 벌리고 서서 손바닥이 서로 마주보게 어깨 높이에서 각 손에 덤벨을 든다.,Step:2 코어를 조이고 등을 곧게 유지한 채 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:3 상단에서 잠깐 멈춘 뒤 천천히 덤벨을 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sM84pE4', '짐 볼 위에서 스트레칭', 'https://static.exercisedb.dev/media/sM84pE4.gif', '광배근', '등', '스태빌리티 볼', '어깨,삼두근', 'Step:1 발을 바닥에 두고 등을 곧게 편 상태로 짐볼에 앉는다.,Step:2 한 손에 덤벨을 들고 팔을 머리 위로 곧게 뻗는다.,Step:3 몸을 천천히 반대쪽으로 기울여 광배근이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한 뒤 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ANbbry2', '허리 컬', 'https://static.exercisedb.dev/media/ANbbry2.gif', '척추', '등', '맨몸', '둔근,햄스트링', 'Step:1 다리를 곧게 뻗고 팔은 몸 옆에 둔 채 엎드린다.,Step:2 둔근과 햄스트링에 힘을 주고, 등을 말아 올리듯 상체를 천천히 바닥에서 들어 올린다.,Step:3 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VuoerH0', '삼두근 딥(벤치 다리)', 'https://static.exercisedb.dev/media/VuoerH0.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치 가장자리에 앉아 손으로 가장자리를 잡고 손가락을 전방으로 둔다.,Step:2 발을 앞으로 걸어 엉덩이를 벤치에서 빼고 팔을 편다.,Step:3 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 등을 벤치에 가깝게 유지한다.,Step:4 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Al3tP0D', '메디신 볼 앙와위 가슴 던지기', 'https://static.exercisedb.dev/media/Al3tP0D.gif', '삼두근', '상완이두근', '메디신볼', '가슴,어깨', 'Step:1 벤치에 등을 대고 누워 무릎을 굽혀 발을 바닥에 둔다.,Step:2 메디신볼을 양손으로 잡고 팔을 가슴 위로 곧게 편다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 메디신볼을 가슴 쪽으로 내린다.,Step:4 폭발적으로 밀어 올리며 팔을 완전히 펴서 공을 최대한 높이 던진다.,Step:5 메디신볼을 받아 다시 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wSScovH', '밴드 벤트 오버 힙 익스텐션', 'https://static.exercisedb.dev/media/wSScovH.gif', '둔근', '허벅지', '밴드', '햄스트링,허리', 'Step:1 발목 높이의 단단한 고정 지점에 밴드를 연결한다.,Step:2 고정 지점을 등지고 발을 어깨너비로 벌린 채 선다.,Step:3 밴드에 텐션이 생기도록 뒤로 물러서고 무릎을 약간 굽힌다.,Step:4 척추를 중립으로 유지하며 엉덩이를 접어 상체를 앞으로 기울인다.,Step:5 오른다리를 뒤로 곧게 뻗어 올리며 상단에서 둔근을 수축한다.,Step:6 오른다리를 내리고 왼다리로 반복한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('guT8YnS', '이두근 풀업', 'https://static.exercisedb.dev/media/guT8YnS.gif', '이두근', '상완이두근', '맨몸', '전완근,어깨', 'Step:1 손바닥이 바깥(전방)을 향하게 풀업 바에 매달리고 손은 어깨너비로 잡는다.,Step:2 코어를 조이고 팔꿈치를 굽혀 가슴이 바에 가까워지도록 몸을 끌어올린다.,Step:3 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내려온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('b63ZzGe', '지지대를 이용한 변기 스쿼트', 'https://static.exercisedb.dev/media/b63ZzGe.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝은 약간 바깥을 향하게 한다.,Step:2 균형을 위해 의자나 벽 등 안정적인 지지대를 잡는다.,Step:3 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트 자세로 내려간다.,Step:4 가슴을 들어 올리고 등을 곧게 유지한다.,Step:5 하단에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 올라온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yl2IYyy', '케이블 스탠딩 종아리 올리기', 'https://static.exercisedb.dev/media/yl2IYyy.gif', '종아리근', '종아리', '케이블', '햄스트링,둔근', 'Step:1 케이블 머신을 향해 서서 발을 어깨너비로 벌린다.,Step:2 케이블 머신 손잡이를 잡거나 케이블 발목 스트랩을 발목에 고정한다.,Step:3 발목을 펴서 뒤꿈치를 최대한 들어 올린다.,Step:4 상단에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Yza7XrQ', '바벨 대체 바이셉스 컬', 'https://static.exercisedb.dev/media/Yza7XrQ.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 서서 각 손에 바벨을 들고 손바닥을 전방으로 향하게 한다.,Step:2 상완을 고정한 채 내쉬며 이두근을 수축하면서 중량을 컬한다.,Step:3 이두근이 완전히 수축하고 바벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 상단에서 잠깐 멈추며 이두근을 조인다.,Step:5 들이쉬며 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 양팔을 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('v2DfH14', '체중 서 클로즈 그립 원 암 행', 'https://static.exercisedb.dev/media/v2DfH14.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌 채, 한 손에 덤벨을 중립 그립으로 잡는다.,Step:2 등을 곧게 유지하며 엉덩이를 접어 상체를 앞으로 숙이고 코어를 고정한다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 덤벨을 가슴 쪽으로 당기고 견갑골을 모아준다.,Step:4 상단에서 잠깐 멈춘 뒤 덤벨을 천천히 내린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대쪽으로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uZKq7lo', '앞으로 점프', 'https://static.exercisedb.dev/media/uZKq7lo.gif', '대퇴사두근', '허벅지', '맨몸', '종아리근,햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽혀 스쿼트 자세로 내려간다.,Step:3 팔을 뒤로 휘둘러 반동을 만든다.,Step:4 엉덩이·무릎·발목을 펴며 앞으로 폭발적으로 점프한다.,Step:5 발 앞부분으로 부드럽게 착지하고 즉시 다음 점프로 이어간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('veXwo0D', '케이블 플로어 시티드 와이드 그립 로우', 'https://static.exercisedb.dev/media/veXwo0D.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 다리를 앞으로 뻗고 등을 곧게 세운 채 바닥에 앉는다.,Step:2 낮은 풀리에 케이블 손잡이를 연결하고 케이블 머신이 뒤쪽에 오도록 위치를 잡는다.,Step:3 손바닥이 아래를 향하게 와이드 오버핸드 그립으로 손잡이를 잡는다.,Step:4 가슴을 들어 올리고 등을 곧게 유지하며 상체를 약간 뒤로 기댄다.,Step:5 손잡이를 허리 쪽으로 당기며 견갑골을 모아준다.,Step:6 상단에서 잠깐 멈춘 뒤 손잡이를 천천히 시작 자세로 되돌린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y1MsI1l', '저항 밴드 다리 익스텐션', 'https://static.exercisedb.dev/media/Y1MsI1l.gif', '대퇴사두근', '허벅지', '저항 밴드', '햄스트링', 'Step:1 저항 밴드를 단단한 고정 지점에 연결하고 발목에 고정한다.,Step:2 고정 지점을 향해 서서 발을 어깨너비로 벌린다.,Step:3 코어를 고정하고 상체를 안정적으로 유지한 채 다리를 앞으로 곧게 펴서 들어 올린다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('C31LMnP', '한쪽 다리 스쿼트', 'https://static.exercisedb.dev/media/C31LMnP.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 한쪽 다리를 앞으로 뻗어 바닥에서 띄운다.,Step:3 서 있는 다리의 무릎을 굽히며 의자에 앉듯 엉덩이를 뒤로 빼고 몸을 내린다.,Step:4 가슴을 들고 등을 곧게 유지한다.,Step:5 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 반대쪽 다리로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QZFv5ui', '짐 볼에 덤벨 원 암 프레스', 'https://static.exercisedb.dev/media/QZFv5ui.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근,코어', 'Step:1 발을 바닥에 두고 무릎을 90도로 굽힌 채 짐 볼에 앉는다.,Step:2 한 손에 덤벨을 들고 팔꿈치를 굽혀 어깨 높이에 위치시키며 손바닥은 전방을 향하게 한다.,Step:3 코어를 조여 균형을 유지하면서 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대쪽 팔로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dK9394r', '버피', 'https://static.exercisedb.dev/media/dK9394r.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근,어깨,가슴', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽혀 스쿼트로 내려가며 손을 몸 앞 바닥에 짚는다.,Step:3 발을 뒤로 차 올려 푸시업 자세로 만든다.,Step:4 몸을 일직선으로 유지하며 푸시업을 1회 수행한다.,Step:5 발을 다시 앞으로 당겨 스쿼트 자세로 돌아온다.,Step:6 위로 폭발적으로 점프하며 팔을 머리 위로 뻗는다.,Step:7 부드럽게 착지한 뒤 즉시 다시 스쿼트로 내려가 다음 반복을 시작한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Eh2v5Iu', '시저스 점프(남자)', 'https://static.exercisedb.dev/media/Eh2v5Iu.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 점프하면서 오른다리를 왼다리 앞쪽으로 교차시킨다.,Step:3 착지하자마자 다리를 빠르게 바꿔 왼다리를 오른다리 앞쪽으로 교차시킨다.,Step:4 가능한 빠르게 다리를 번갈아 교차하며 점프를 계속한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7f2jsqP', '덤벨 앉아 한쪽 팔 회전', 'https://static.exercisedb.dev/media/7f2jsqP.gif', '전완근', '팔 아래', '덤벨', '어깨,이두근', 'Step:1 벤치에 앉아 등을 곧게 세우고 한 손에 덤벨을 쥔 채 허벅지 위에 올린다.,Step:2 팔꿈치를 몸에 가깝게 유지하며 덤벨을 어깨 높이까지 들어 올린다.,Step:3 상완을 고정한 채 전완을 바깥쪽으로 회전시킨다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 되돌린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대쪽 팔로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xifhB5W', '후면 삼각근 스트레칭', 'https://static.exercisedb.dev/media/xifhB5W.gif', '삼각근', '어깨', '맨몸', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 곧게 선다.,Step:2 오른팔을 가슴 앞쪽으로 뻗어 왼손을 오른쪽 팔꿈치에 둔다.,Step:3 오른팔을 왼쪽 어깨 쪽으로 부드럽게 당겨 오른쪽 어깨가 늘어나는 것을 느낀다.,Step:4 15–30초 동안 유지한 뒤 풀어준다.,Step:5 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('01qpYSe', '위를 향한 개', 'https://static.exercisedb.dev/media/01qpYSe.gif', '척추', '등', '맨몸', '어깨,가슴', 'Step:1 다리를 뒤로 뻗고 바닥에 엎드린다.,Step:2 손을 아랫갈비뼈 옆 바닥에 두고 손가락을 전방으로 향하게 한다.,Step:3 손으로 바닥을 강하게 밀어 팔을 펴며 상체와 허벅지를 바닥에서 들어 올린다.,Step:4 어깨를 뒤로 아래로 내리며 가슴을 열고 시선을 천장 쪽으로 든다.,Step:5 몇 번의 호흡 동안 자세를 유지한 뒤 천천히 시작 자세로 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Rr7S3yg', '덤벨 프론트 레이즈 v. 2', 'https://static.exercisedb.dev/media/Rr7S3yg.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 서서 각 손에 덤벨을 들고 손바닥이 허벅지를 향하게 한다.,Step:2 등을 곧게 세우고 코어를 고정한다.,Step:3 팔을 곧게 편 채 덤벨을 앞쪽으로 천천히 들어 올려 어깨 높이까지 올린다.,Step:4 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gk1r408', '딥 케이지의 가중 클로즈 그립 친업', 'https://static.exercisedb.dev/media/Gk1r408.gif', '광배근', '등', '가중', '이두근,전완근', 'Step:1 딥 케이지 앞에 서서 평행 바를 언더핸드 그립으로 어깨너비로 잡는다.,Step:2 팔을 완전히 편 채 바에 매달리고 발을 바닥에서 띄운 뒤 몸을 일직선으로 유지한다.,Step:3 등 근육에 힘을 주고 팔꿈치를 몸에 가깝게 유지하며 몸을 위로 끌어올린다.,Step:4 턱이 바 위로 올라올 때까지 당긴 뒤 잠깐 멈춘다.,Step:5 팔을 완전히 펴며 천천히 시작 자세로 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ff18ItA', '웨이티드 스트레이트 바 딥', 'https://static.exercisedb.dev/media/Ff18ItA.gif', '가슴근육', '가슴', '가중', '삼두근,어깨', 'Step:1 평행 바 사이에 몸을 두고 팔을 완전히 편 채 지지한다.,Step:2 팔꿈치를 굽혀 상완이 바닥과 평행해질 때까지 몸을 내린다.,Step:3 하단에서 잠깐 멈춘 뒤 팔을 펴며 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KCBKjma', '밴드 잭나이프 윗몸일으키기', 'https://static.exercisedb.dev/media/KCBKjma.gif', '복근', '허리', '밴드', '고관절 굴근', 'Step:1 다리를 곧게 뻗고 등을 대고 누워 팔을 머리 위로 뻗은 상태에서 밴드를 잡는다.,Step:2 복근에 힘을 주고 다리와 상체를 동시에 들어 올려 손이 발 쪽으로 가게 한다.,Step:3 상단에서 잠깐 멈춘 뒤 다리와 상체를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qOgPVf6', '바벨 프리처 컬', 'https://static.exercisedb.dev/media/qOgPVf6.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 프리처 벤치에 앉아 상완을 패드에 올리고 가슴을 지지대에 붙인다.,Step:2 언더핸드 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 상완을 고정한 채 내쉬며 바벨을 어깨 쪽으로 컬한다.,Step:4 상단에서 이두근을 조이며 잠깐 멈춘다.,Step:5 들이쉬며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rZ80Gbp', '케이블 시티드 원 암 컨센트레이션 컬', 'https://static.exercisedb.dev/media/rZ80Gbp.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 등을 곧게 세운다.,Step:2 한 손으로 케이블 손잡이를 잡고 팔꿈치를 허벅지 안쪽(무릎 위쪽)에 댄다.,Step:3 상완을 고정한 채 내쉬며 손잡이를 어깨 쪽으로 컬한다.,Step:4 상단에서 이두근을 조이며 잠깐 멈춘다.,Step:5 들이쉬며 손잡이를 천천히 내린다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 팔을 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TFA88iB', '밴드 프론트 레이즈', 'https://static.exercisedb.dev/media/TFA88iB.gif', '삼각근', '어깨', '밴드', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 밴드를 허벅지 앞에서 잡고 손바닥을 아래로 향하게 한다.,Step:2 팔을 곧게 편 채 바닥과 평행해질 때까지 천천히 앞쪽으로 들어 올린다.,Step:3 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9ZGZuOD', '인클라인 트위스트 윗몸일으키기', 'https://static.exercisedb.dev/media/9ZGZuOD.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 인클라인 벤치를 45도 각도로 세팅한다.,Step:2 벤치에 누워 발을 발 고정 패드 아래에 끼운다.,Step:3 손을 머리 뒤에 두거나 가슴 앞에서 교차한다.,Step:4 복근에 힘을 주고 상체를 들어 올려 앞으로 말아 올린다.,Step:5 올라오면서 몸통을 한쪽으로 비틀어 팔꿈치가 반대쪽 무릎 쪽으로 향하게 한다.,Step:6 상단에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:7 다시 올라오되 이번에는 반대쪽으로 비틀어 수행한다.,Step:8 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Krmb3cB', '레버 역방향 하이퍼 익스텐션', 'https://static.exercisedb.dev/media/Krmb3cB.gif', '둔근', '허벅지', '레버리지 머신', '햄스트링,허리', 'Step:1 레버리지 머신을 몸에 맞게 조절하고 발을 발 패드에 고정한다.,Step:2 엎드려 상체가 가장자리 밖으로 나오게 하고 엉덩이를 패드에 둔다.,Step:3 팔을 가슴 위에 교차하거나 머리 뒤에 둔다.,Step:4 둔근과 햄스트링에 힘을 주어 다리를 들어 올려 바닥과 평행해질 때까지 올린다.,Step:5 상단에서 잠깐 멈춘 뒤 다리를 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y4BRNQF', '푸쉬업(스태빌리티 볼 위에서)', 'https://static.exercisedb.dev/media/Y4BRNQF.gif', '가슴근육', '가슴', '스태빌리티 볼', '삼두근,어깨,코어', 'Step:1 스태빌리티 볼을 바닥에 두고 손을 볼 위에 어깨너비로 올린 채 엎드린다.,Step:2 다리를 뒤로 곧게 뻗어 발끝으로 균형을 잡는다.,Step:3 코어를 조이고 몸을 일직선으로 유지하며 팔꿈치를 굽혀 가슴을 볼 쪽으로 내린다.,Step:4 하단에서 잠깐 멈춘 뒤 팔을 펴며 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kjE55n5', '케틀벨 벤트 프레스', 'https://static.exercisedb.dev/media/kjE55n5.gif', '복근', '허리', '케틀벨', '어깨,삼두근,복사근', 'Step:1 발을 어깨너비로 벌리고 서서 오른손에 케틀벨을 든다.,Step:2 무릎을 약간 굽히고 오른팔로 케틀벨을 머리 위로 프레스해 팔꿈치를 잠근다.,Step:3 몸통을 왼쪽으로 회전하며 체중을 왼발 쪽으로 옮긴다.,Step:4 왼무릎을 굽히고 상체를 바닥 쪽으로 내리되 오른팔은 머리 위로 곧게 유지한다.,Step:5 내려가면서 케틀벨을 계속 바라보고 가슴을 들어 올린다.,Step:6 왼손이 바닥에 닿으면 왼발로 밀어 왼다리를 펴며 엉덩이를 앞으로 밀어낸다.,Step:7 엉덩이를 전방으로 밀어내는 힘과 코어, 오른팔을 사용해 케틀벨을 시작 자세로 다시 밀어 올린다.,Step:8 원하는 반복 횟수만큼 수행한 뒤 반대쪽으로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9KU9TYF', '레버 수평 한쪽 다리 프레스', 'https://static.exercisedb.dev/media/9KU9TYF.gif', '둔근', '허벅지', '레버리지 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 풋플레이트에 올렸을 때 무릎이 90도가 되도록 좌석을 조절한다.,Step:2 등받이에 등을 대고 앉아 발을 풋플레이트에 어깨너비로 둔다.,Step:3 안정성을 위해 손잡이나 머신 옆을 잡는다.,Step:4 다리를 펴서 풋플레이트를 밀어내되 등을 등받이에 밀착한다.,Step:5 완전히 편 지점에서 잠깐 멈춘 뒤 다리를 굽혀 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OxJk1fg', '케이블 삼두근 푸시다운(v-bar)(암 블래스터 포함)', 'https://static.exercisedb.dev/media/OxJk1fg.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 가장 높은 위치로 맞추고 V-바 어태치먼트를 연결한다.,Step:2 머신을 향해 발을 어깨너비로 벌리고 선다.,Step:3 손바닥이 아래를 향하게 오버핸드 그립으로 V-바를 어깨너비로 잡는다.,Step:4 팔꿈치를 옆구리에 붙이고 상완이 움직이지 않게 고정한다.,Step:5 삼두근에 힘을 주고 내쉬며 V-바를 아래로 눌러 팔을 완전히 편다.,Step:6 하단에서 삼두근을 조이며 잠깐 멈춘다.,Step:7 들이쉬며 V-바를 천천히 시작 자세로 올리되 컨트롤을 유지한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jNU1gFQ', '아웃사이드 레그 킥 푸쉬업', 'https://static.exercisedb.dev/media/jNU1gFQ.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 손을 어깨너비보다 약간 넓게 두고 발을 모아 푸시업 자세로 시작한다.,Step:2 등을 곧게 유지하고 코어를 조인 채 팔꿈치를 굽혀 몸을 내린다.,Step:3 다시 밀어 올리면서 한쪽 다리를 옆으로 차 올려 곧게 펴고 둔근을 수축한다.,Step:4 다리를 시작 자세로 되돌린다.,Step:5 푸시업과 레그 킥을 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UEjSrKI', '케이블 장착 트위스트', 'https://static.exercisedb.dev/media/UEjSrKI.gif', '복근', '허리', '케이블', '복사근', 'Step:1 케이블 머신에 앉아 발을 바닥에 두고 무릎을 약간 굽힌다.,Step:2 양손으로 케이블 손잡이를 잡고 팔을 앞쪽으로 곧게 뻗는다.,Step:3 코어를 조인 상태에서 몸통을 한쪽으로 천천히 회전시키며 케이블을 몸 가로질러 당긴다.,Step:4 가동 범위 끝에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zG0zs85', '바벨 프론트 스쿼트', 'https://static.exercisedb.dev/media/zG0zs85.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 바벨을 어깨 앞쪽에 올려 쇄골/어깨 위에 걸치고 고정한다.,Step:3 코어를 조이고 가슴을 든 채 엉덩이를 뒤로 빼며 무릎을 굽혀 스쿼트로 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:5 하단에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CosupLu', '트위스트가 있는 전면 판자', 'https://static.exercisedb.dev/media/CosupLu.gif', '복근', '허리', '맨몸', '복사근,어깨', 'Step:1 손을 어깨 아래에 두고 하이 플랭크 자세로 시작하며 머리부터 발끝까지 일직선으로 만든다.,Step:2 코어와 둔근에 힘을 주어 자세를 안정적으로 유지한다.,Step:3 몸통을 오른쪽으로 회전하며 오른팔을 들어 올려 천장을 향해 뻗는다.,Step:4 엉덩이와 다리가 흔들리지 않게 유지하며 비틀어 준다.,Step:5 잠깐 유지한 뒤 시작 자세로 돌아온다.,Step:6 왼쪽도 같은 방식으로 비튼다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('J6Dx1Mu', '바벨 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/J6Dx1Mu.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 벤치에 누워 발을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 어깨너비보다 약간 좁게 클로즈 그립으로 바벨을 잡는다.,Step:3 바벨을 랙에서 꺼낸 뒤 가슴 쪽으로 천천히 내리며 팔꿈치를 몸에 가깝게 둔다.,Step:4 바벨이 가슴에 닿는 지점에서 잠깐 멈춘다.,Step:5 팔을 펴며 바벨을 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4Jc36XM', '벤치 위의 덤벨 원 암 리버스 손목 컬', 'https://static.exercisedb.dev/media/4Jc36XM.gif', '전완근', '팔 아래', '덤벨', '이두근,상완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 한 손에 덤벨을 잡되 손바닥이 아래를 향하게 한다.,Step:2 전완을 벤치 위에 올리고 손목이 가장자리 밖으로 나오게 둔다.,Step:3 손목을 천천히 위로 말아 덤벨을 전완 쪽으로 끌어올린다.,Step:4 상단에서 잠깐 멈춘 뒤 덤벨을 천천히 내린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대쪽으로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Sn8wxAI', '크런치(스태빌리티 볼 위에서, 팔을 쭉 편 상태)', 'https://static.exercisedb.dev/media/Sn8wxAI.gif', '복근', '허리', '스태빌리티 볼', '고관절 굴근', 'Step:1 발을 바닥에 평평하게 두고 무릎을 90도로 굽힌 채 스태빌리티 볼에 앉는다.,Step:2 볼 위로 기대어 누워 허리가 지지되도록 하고 상체가 바닥과 평행해지게 한다.,Step:3 손을 머리 뒤에 두거나 가슴 앞에서 교차한다.,Step:4 복근에 힘을 주고 상체를 들어 올려 어깨가 엉덩이 쪽으로 말리게 한다.,Step:5 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7HcfMBP', '보조 스탠딩 삼두근 익스텐션(타올 포함)', 'https://static.exercisedb.dev/media/7HcfMBP.gif', '삼두근', '상완이두근', '도움을 준', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 수건을 양손으로 잡고 머리 뒤로 넘긴다.,Step:2 팔꿈치를 귀 옆에 가깝게 두고 상완이 움직이지 않게 고정한다.,Step:3 전완을 위로 펴며 삼두근을 수축한다.,Step:4 상단에서 잠깐 멈춘 뒤 수건을 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WVD66ff', '회전 짐 볼 등 익스텐션', 'https://static.exercisedb.dev/media/WVD66ff.gif', '척추', '등', '스태빌리티 볼', '둔근,햄스트링', 'Step:1 스태빌리티 볼 위에 엎드려 엉덩이를 볼에 올리고 발은 바닥에 단단히 고정한다.,Step:2 손을 머리 뒤에 두거나 가슴 앞에서 교차한다.,Step:3 코어를 조이고 상체를 들어 올려 등(척추)을 펴서 머리부터 발끝까지 일직선이 되게 한다.,Step:4 상단에서 잠깐 멈춘 뒤 몸통을 한쪽으로 천천히 회전하되 엉덩이와 다리는 고정한다.,Step:5 중앙으로 돌아온 뒤 반대쪽으로도 같은 방식으로 회전한다.,Step:6 상체를 천천히 내려 시작 자세로 돌아온 뒤 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pkSoCW9', '바벨 제퍼슨 스쿼트', 'https://static.exercisedb.dev/media/pkSoCW9.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 오버핸드 그립으로 바벨을 잡아 허리 아래, 몸 앞쪽에 위치시킨다.,Step:3 왼발은 앞으로, 오른발은 뒤로 내딛어 어깨너비 정도로 선다.,Step:4 무릎을 굽혀 스쿼트로 내려가되 등을 곧게 유지하고 가슴을 든다.,Step:5 뒤꿈치로 밀어 시작 자세로 일어선다.,Step:6 반복마다 앞뒤 발을 번갈아 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ze7MoIb', '덤벨 원 암 리버스 그립 프레스', 'https://static.exercisedb.dev/media/Ze7MoIb.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 평벤치에 앉아 한 손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 발을 바닥에 두고 등을 곧게 세운다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 덤벨을 어깨 높이까지 들어 올린다.,Step:4 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:5 상단에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 반대쪽으로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rkg41Fb', '트윈 핸들 평행 그립 랫 풀다운', 'https://static.exercisedb.dev/media/rkg41Fb.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 좌석 높이를 조절하고 케이블 머신을 향해 위치를 잡는다.,Step:2 오버핸드 그립으로 손잡이를 어깨너비로 잡는다.,Step:3 앉아 허벅지를 패드 아래에 고정하고 발은 바닥에 평평하게 둔다.,Step:4 상체를 약간 뒤로 기댄 채 가슴을 들어 중립 척추를 유지한다.,Step:5 손잡이를 윗가슴 쪽으로 당기며 견갑골을 모아준다.,Step:6 하단에서 잠깐 멈추며 광배근 수축을 느낀다.,Step:7 손잡이를 천천히 놓아 시작 자세로 되돌린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vi8EhoE', '풀오버 주변의 덤벨', 'https://static.exercisedb.dev/media/vi8EhoE.gif', '가슴근육', '가슴', '덤벨', '삼두근,광배근', 'Step:1 벤치에 누워 머리는 한쪽 끝에 두고 발은 바닥에 단단히 둔다.,Step:2 양손으로 덤벨을 잡고 팔을 가슴 위로 곧게 편다.,Step:3 팔을 곧게 유지한 채 아치 형태로 덤벨을 머리 뒤쪽으로 천천히 내린다.,Step:4 하단에서 잠깐 멈춘 뒤 덤벨을 다시 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('B6dAO1t', '스미스 시티드 리스트 컬', 'https://static.exercisedb.dev/media/B6dAO1t.gif', '전완근', '팔 아래', '스미스 머신', '이두근,상완근', 'Step:1 스미스 머신 앞 벤치에 앉아 발을 바닥에 둔다.,Step:2 언더핸드 그립으로 바벨을 어깨너비로 잡는다.,Step:3 전완을 허벅지 위에 올려 손목이 가장자리 밖으로 나오게 한다.,Step:4 손목을 천천히 위로 말아 바벨을 전완 쪽으로 끌어올린다.,Step:5 상단에서 잠깐 멈춘 뒤 바벨을 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Af0EW2I', '머슬업(세로 막대)', 'https://static.exercisedb.dev/media/Af0EW2I.gif', '광배근', '등', '맨몸', '이두근,삼두근,전완근', 'Step:1 손바닥이 바깥을 향하게 세로 막대를 잡고 팔을 완전히 편 채 매달린다.,Step:2 코어를 조이고 가슴이 막대에 가까워지도록 몸을 끌어올린다.,Step:3 올라오면서 상체를 약간 뒤로 젖히고 팔꿈치를 옆구리 쪽으로 끌어온다.,Step:4 가슴이 막대에 닿을 때까지 당기고 팔꿈치가 완전히 굽혀질 때까지 수행한다.,Step:5 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fUBheHs', '케이블 좌석 행', 'https://static.exercisedb.dev/media/fUBheHs.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 케이블 로우 머신에 앉아 발을 발판에 두고 무릎을 약간 굽힌다.,Step:2 오버핸드 그립으로 손잡이를 잡고 등을 곧게 세우며 어깨를 내린다.,Step:3 손잡이를 몸 쪽으로 당기며 견갑골을 모아준다.,Step:4 상단에서 잠깐 멈춘 뒤 손잡이를 천천히 놓아 시작 자세로 되돌린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sU5BrfP', '다리 위로 햄스트링 스트레칭', 'https://static.exercisedb.dev/media/sU5BrfP.gif', '햄스트링', '허벅지', '맨몸', '둔근', 'Step:1 다리를 곧게 뻗은 채로 등을 바닥에 대고 눕는다.,Step:2 한쪽 무릎을 굽혀 가슴 쪽으로 끌어오며 허벅지나 정강이를 잡는다.,Step:3 다리를 들어 올린 상태에서 가능한 만큼 곧게 편다.,Step:4 20–30초 동안 유지한다.,Step:5 반대쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jQGwmxN', '트랩바 데드리프트', 'https://static.exercisedb.dev/media/jQGwmxN.gif', '둔근', '허벅지', '트랩바', '햄스트링,대퇴사두근,허리', 'Step:1 트랩바가 발 앞에 오도록 발을 어깨너비로 벌리고 선다.,Step:2 엉덩이와 무릎을 굽혀 내려가 오버핸드 그립으로 트랩바 손잡이를 잡는다.,Step:3 등을 곧게 세우고 가슴을 든 채 엉덩이와 무릎을 펴며 트랩바를 들어 올린다.,Step:4 올라오면서 뒤꿈치로 밀어내고 상단에서 둔근을 수축하는 데 집중한다.,Step:5 엉덩이와 무릎을 굽혀 트랩바를 천천히 바닥으로 내리되 등을 곧게 유지한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xAySMB0', '밸런스 보드', 'https://static.exercisedb.dev/media/xAySMB0.gif', '대퇴사두근', '허벅지', '맨몸', '종아리근,햄스트링,둔근', 'Step:1 평평한 바닥에 밸런스 보드를 놓는다.,Step:2 한쪽 발을 보드 중앙에 올려 발이 중심에 오도록 한다.,Step:3 코어를 조이며 보드 위 발로 체중을 천천히 실어 균형을 잡는다.,Step:4 원하는 시간 동안 균형과 안정성을 유지한다.,Step:5 반대쪽 발로 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nxW6BkN', '덤벨 인클라인 레이즈', 'https://static.exercisedb.dev/media/nxW6BkN.gif', '삼각근', '어깨', '덤벨', '승모근,삼두근', 'Step:1 인클라인 벤치에 앉아 각 손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 벤치에 등을 기대고 덤벨을 어깨 높이로 들어 올려 손바닥이 전방을 향하게 한다.,Step:3 등을 벤치에 붙인 채 내쉬며 덤벨을 머리 위로 들어 올려 팔을 완전히 편다.,Step:4 상단에서 잠깐 멈춘 뒤 들이쉬며 덤벨을 천천히 어깨 높이로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vKilzz3', '덤벨 스탠딩 이너 바이셉스 컬 v. 2', 'https://static.exercisedb.dev/media/vKilzz3.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 곧게 서서 각 손에 덤벨을 들고 손바닥이 몸통을 향하게 한다.,Step:2 팔꿈치를 몸통에 가깝게 유지하고 손바닥을 회전해 전방을 향하게 한다.,Step:3 상완을 고정한 채 덤벨을 컬하며 이두근을 수축한다.,Step:4 이두근이 완전히 수축하고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 상단에서 잠깐 멈추며 이두근을 조인다.,Step:6 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:7 권장 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hoXt6wv', '레프트 훅. 권투', 'https://static.exercisedb.dev/media/hoXt6wv.gif', '삼각근', '어깨', '맨몸', '이두근,삼두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:2 왼손은 얼굴을 보호하도록 올리고 오른손은 턱 옆에 둔다.,Step:3 엉덩이를 회전시키며 왼발로 피벗하면서 왼팔을 뻗어 훅 펀치를 낸다.,Step:4 몸통을 비틀고 코어를 사용해 펀치에 힘을 실어준다.,Step:5 팔을 재빠르게 시작 자세로 되돌리고 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('g376LuL', '슬레이 누워 송아지 프레스', 'https://static.exercisedb.dev/media/g376LuL.gif', '종아리근', '종아리', '슬레이 기계', '햄스트링,둔근', 'Step:1 슬레이 머신의 중량을 편안한 수준으로 조절한다.,Step:2 머신에 앉아 등을 패드에 대고 발을 플랫폼에 올린다.,Step:3 발가락과 앞꿈치를 플랫폼 가장자리에 두고 뒤꿈치는 밖으로 나오게 한다.,Step:4 발목을 펴서 플랫폼을 밀어내되 무릎은 약간 굽힌 상태를 유지한다.,Step:5 종아리가 완전히 수축할 때까지 밀어낸다.,Step:6 수축을 잠깐 유지한 뒤 플랫폼을 천천히 시작 위치로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kprile3', '운동 볼 딥', 'https://static.exercisedb.dev/media/kprile3.gif', '삼두근', '상완이두근', '스태빌리티 볼', '가슴,어깨', 'Step:1 스태빌리티 볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 손을 엉덩이 옆 볼 위에 두고 손가락은 전방을 향하게 한다.,Step:3 손으로 밀어 팔을 펴며 몸을 볼에서 들어 올려 지지한다.,Step:4 팔꿈치를 굽혀 몸을 내리되 팔꿈치를 몸에 가깝게 유지한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4f8RXP8', '케이블 스탠딩 로우(v-bar)', 'https://static.exercisedb.dev/media/4f8RXP8.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 케이블 머신을 향해 발을 어깨너비로 벌리고 선다.,Step:2 오버핸드 그립으로 V-바를 잡고 손바닥이 아래를 향하게 한다.,Step:3 등을 곧게 세우고 코어를 고정한다.,Step:4 V-바를 몸 쪽으로 당기며 견갑골을 모아준다.,Step:5 상단에서 잠깐 멈춘 뒤 천천히 긴장을 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('awG04cF', '손가락 컬', 'https://static.exercisedb.dev/media/awG04cF.gif', '전완근', '팔 아래', '바벨', '손목 굴근,그립 근육', 'Step:1 벤치에 앉아 발을 바닥에 두고 언더핸드 그립으로 바벨을 잡아 손바닥이 위를 향하게 한다.,Step:2 전완을 허벅지 위에 올려 손목이 가장자리 밖으로 나오게 한다.,Step:3 손가락을 손바닥 쪽으로 말아 바벨을 꽉 쥐며 수축한다.,Step:4 수축을 잠깐 유지한 뒤 손가락을 천천히 풀어 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('e1e76I2', '줄넘기', 'https://static.exercisedb.dev/media/e1e76I2.gif', '심혈관계', '유산소', '로프', '종아리근,대퇴사두근,햄스트링,둔근', 'Step:1 손으로 줄넘기 손잡이를 잡고 손바닥이 안쪽을 향하게 한다.,Step:2 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:3 줄을 머리 위로 넘기고 발 쪽으로 올 때 점프해 줄을 넘는다.,Step:4 앞꿈치로 부드럽게 착지하고 줄이 다시 돌아올 때 반복 점프한다.,Step:5 원하는 시간 또는 반복 횟수만큼 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qm9veZw', '덤벨 누워 넓은 컬', 'https://static.exercisedb.dev/media/qm9veZw.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 누워 양손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔을 완전히 편다.,Step:2 상완을 고정한 채 내쉬며 덤벨을 컬해 이두근을 수축한다.,Step:3 이두근이 완전히 수축하고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 상단에서 잠깐 멈추며 이두근을 조인다.,Step:5 들이쉬며 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vpp9Ku2', '케이블 시트 한쪽 팔 대체 행', 'https://static.exercisedb.dev/media/vpp9Ku2.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 케이블 머신을 향해 벤치에 앉아 발을 바닥에 두고 무릎을 약간 굽힌다.,Step:2 한 손으로 손잡이를 잡고 팔을 앞쪽으로 완전히 편다.,Step:3 견갑골을 모으면서 팔꿈치를 몸에 가깝게 두고 손잡이를 몸 쪽으로 당긴다.,Step:4 상단에서 잠깐 멈추며 등 근육을 수축한다.,Step:5 손잡이를 천천히 놓아 시작 자세로 되돌린다.,Step:6 반대쪽 팔로 반복한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1DN3iz4', '스미스 업라이트 로우', 'https://static.exercisedb.dev/media/1DN3iz4.gif', '삼각근', '어깨', '스미스 머신', '승모근,이두근', 'Step:1 스미스 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:2 어깨너비보다 약간 넓게 오버핸드 그립으로 바를 잡는다.,Step:3 등을 곧게 세우고 코어를 고정한다.,Step:4 팔꿈치가 앞서가게 바를 턱 쪽으로 끌어올린다.,Step:5 상단에서 잠깐 멈춘 뒤 바를 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WbNq5Xu', '레버 스탠딩 체스트 프레스', 'https://static.exercisedb.dev/media/WbNq5Xu.gif', '가슴근육', '가슴', '레버리지 머신', '어깨,삼두근', 'Step:1 좌석 높이를 조절한 뒤 머신에 앉아 발을 바닥에 평평하게 둔다.,Step:2 오버핸드 그립으로 손잡이를 잡고 손을 가슴 높이에 위치시킨다.,Step:3 팔을 펴며 손잡이를 앞으로 밀어낸다(팔꿈치는 약간 굽힌 상태).,Step:4 잠깐 멈춘 뒤 손잡이를 천천히 가슴 쪽으로 되돌리며 컨트롤한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4CBIBOM', '바벨 시트드 클로즈 그립 비하인드 넥 삼두근 익스텐션', 'https://static.exercisedb.dev/media/4CBIBOM.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 세우고 발을 바닥에 둔다.,Step:2 손바닥이 전방을 향하게 클로즈 그립으로 바벨을 잡아 목 뒤에 둔다.,Step:3 팔꿈치를 머리 가까이에 두고 바벨을 머리 뒤쪽으로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 팔을 펴 바벨을 시작 자세로 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('znQUdHY', '덤벨 시티드 숄더 프레스', 'https://static.exercisedb.dev/media/znQUdHY.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 벤치에 앉아 각 손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 덤벨을 어깨 높이로 들어 올려 손바닥이 전방을 향하게 한다.,Step:3 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 상단에서 잠깐 멈춘 뒤 덤벨을 천천히 어깨 높이로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tig3PXb', '맨몸으로 서서 클로즈 그립 로우', 'https://static.exercisedb.dev/media/tig3PXb.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:2 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 세우고 코어를 고정한다.,Step:3 바(또는 손잡이)를 클로즈 그립으로 잡고 팔을 앞으로 곧게 뻗는다.,Step:4 바(또는 손잡이)를 몸 쪽으로 당기며 견갑골을 모아준다.,Step:5 상단에서 잠깐 멈춘 뒤 천천히 놓아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uJmK7Z1', '덤벨 시티드 뉴트럴 리스트 컬', 'https://static.exercisedb.dev/media/uJmK7Z1.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 각 손에 덤벨을 들어 손바닥이 서로 마주보게 한다.,Step:2 전완을 허벅지 위에 올려 덤벨이 아래로 늘어뜨려지게 둔다.,Step:3 손목을 중립으로 유지한 채 덤벨을 어깨 쪽으로 컬한다.,Step:4 상단에서 잠깐 멈춘 뒤 덤벨을 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FY3UdNT', '벽에 운동공 종아리 들어올리기(발목 사이에 테니스공)', 'https://static.exercisedb.dev/media/FY3UdNT.gif', '종아리근', '종아리', '덤벨', '햄스트링,대퇴사두근', 'Step:1 벽을 향해 서서 발을 어깨너비로 벌린다.,Step:2 짐 볼을 벽과 허리 아래쪽(요추) 사이에 끼운다.,Step:3 양손에 덤벨을 들고 팔을 몸 옆으로 내린다.,Step:4 발목 사이에 테니스공을 끼운다.,Step:5 뒤꿈치를 들어 올려 발끝으로 올라선다.,Step:6 상단에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('A9qxk2F', '아처 푸시 업', 'https://static.exercisedb.dev/media/A9qxk2F.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 손을 어깨너비보다 넓게 두고 푸시업 자세로 시작한다.,Step:2 한쪽 팔을 옆으로 곧게 뻗어 바닥과 평행하게 한다.,Step:3 등을 곧게 유지하고 코어를 조인 채 팔꿈치를 굽혀 몸을 내린다.,Step:4 팔을 펴며 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 수행한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VnfUNW7', '클로즈 그립 친업', 'https://static.exercisedb.dev/media/VnfUNW7.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 손바닥이 자신을 향하게 풀업 바를 어깨너비로 잡는다.,Step:2 팔을 완전히 편 채 바에 매달리고 발을 바닥에서 띄운다.,Step:3 등 근육에 힘을 주고 팔꿈치를 몸에 가깝게 유지하며 몸을 끌어올린다.,Step:4 턱이 바 위로 올라올 때까지 당긴다.,Step:5 상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mnzcrIB', '덤벨 벤치 스쿼트', 'https://static.exercisedb.dev/media/mnzcrIB.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 벤치 앞 바닥에 덤벨을 놓는다.,Step:2 벤치를 등지고 서서 발을 어깨너비로 벌린다.,Step:3 무릎과 엉덩이를 굽혀 가슴을 들고 등을 곧게 유지하며 벤치 쪽으로 내려간다.,Step:4 둔근이 벤치에 닿으면 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gw2HFvW', '덤벨 인클라인 원암 플라이', 'https://static.exercisedb.dev/media/Gw2HFvW.gif', '가슴근육', '가슴', '덤벨', '삼각근,삼두근', 'Step:1 인클라인 벤치를 30-45도 각도로 조절한다.,Step:2 벤치에 앉아 한 손에 덤벨을 들고 허벅지 위에 둔다.,Step:3 벤치에 등을 기대고 발을 바닥에 평평하게 둔다.,Step:4 덤벨을 가슴 위로 곧게 뻗어 들어 올린다.,Step:5 팔꿈치를 약간 굽힌 채 넓은 아치로 덤벨을 옆으로 천천히 내린다.,Step:6 팔이 바닥과 평행해지는 지점에서 잠깐 멈춘 뒤 반대로 움직여 덤벨을 시작 자세로 되돌린다.,Step:7 원하는 반복 횟수만큼 수행한 뒤 팔을 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7aVz15j', '삼두근 딥 바닥', 'https://static.exercisedb.dev/media/7aVz15j.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 의자나 벤치 가장자리에 앉아 손을 엉덩이 옆에 두고 손가락을 전방으로 향하게 한다.,Step:2 엉덩이를 의자 앞쪽으로 빼고 다리를 앞으로 뻗는다.,Step:3 팔꿈치를 완전히 펴되 관절 부담을 줄이기 위해 약간만 굽힌 상태로 유지한다.,Step:4 팔꿈치를 굽혀 약 90도가 될 때까지 몸을 바닥 쪽으로 천천히 내린다.,Step:5 하단에서 의자를 아래로 눌러 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('znLogoF', '바벨 풀오버 프레스', 'https://static.exercisedb.dev/media/znLogoF.gif', '광배근', '등', '바벨', '삼두근,가슴,어깨', 'Step:1 벤치에 누워 머리는 한쪽 끝에 두고 발은 바닥에 둔다.,Step:2 손바닥이 바깥을 향하도록(프로나티드 그립) 바벨을 잡고 팔을 가슴 위로 곧게 편다.,Step:3 팔을 곧게 유지한 채 아치 형태로 바벨을 머리 뒤쪽으로 천천히 내려 광배근이 늘어나는 느낌을 받는다.,Step:4 하단에서 잠깐 멈춘 뒤 동작을 반대로 수행해 바벨을 가슴 위 시작 자세로 다시 프레스한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nqs5HGV', '싱글 레그 스쿼트(권총) 남자', 'https://static.exercisedb.dev/media/nqs5HGV.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 팔을 앞쪽으로 뻗는다.,Step:2 오른발을 바닥에서 들어 앞으로 뻗는다.,Step:3 왼무릎을 굽히며 엉덩이를 뒤로 빼고 몸을 천천히 내린다.,Step:4 내려가는 동안 가슴을 들고 등을 곧게 유지한다.,Step:5 왼허벅지가 바닥과 평행해질 때까지(또는 가능한 범위까지) 내려간다.,Step:6 하단에서 잠깐 멈춘 뒤 왼뒤꿈치로 밀어 시작 자세로 올라온다.,Step:7 원하는 반복 횟수만큼 수행한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Hy9D21L', '45° 사이드 굽힘', 'https://static.exercisedb.dev/media/Hy9D21L.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 발을 어깨너비로 벌리고 서서 팔을 몸 옆으로 곧게 내린다.,Step:2 등을 곧게 세우고 코어를 조인 상태에서 몸통을 한쪽으로 천천히 굽혀 손이 무릎 쪽으로 내려가게 한다.,Step:3 하단에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:4 반대쪽도 같은 방식으로 반복한다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UM8mgyG', '케틀벨 아놀드 프레스', 'https://static.exercisedb.dev/media/UM8mgyG.gif', '삼각근', '어깨', '케틀벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 케틀벨을 어깨 높이에 들고 손바닥이 자신을 향하게 한다.,Step:2 코어를 조이고 케틀벨을 머리 위로 밀어 올리면서 손바닥이 전방을 향하도록 회전한다.,Step:3 상단에서 잠깐 멈춘 뒤 케틀벨을 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('arsYEd3', '밴드 원 암 싱글 레그 스플릿 스쿼트', 'https://static.exercisedb.dev/media/arsYEd3.gif', '대퇴사두근', '허벅지', '밴드', '둔근,햄스트링', 'Step:1 발목 주변에 저항 밴드를 걸고 발을 골반너비로 벌린다.,Step:2 한쪽 다리를 앞으로 뻗고 반대쪽 발등을 뒤의 벤치/스텝에 올린다.,Step:3 균형을 위해 한 손으로 지지대를 잡는다.,Step:4 서 있는 다리의 무릎을 굽혀 스쿼트로 내려가되 무릎이 발끝과 같은 방향을 향하게 한다.,Step:5 뒤꿈치로 밀어 시작 자세로 올라온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0Yz8WdV', '곰 크롤링', 'https://static.exercisedb.dev/media/0Yz8WdV.gif', '심혈관계', '유산소', '맨몸', '코어,어깨,삼두근', 'Step:1 손을 어깨 아래, 무릎을 엉덩이 아래에 두고 네발기기 자세로 시작한다.,Step:2 무릎을 바닥에서 살짝 띄우고 등을 평평하게 유지하며 코어를 조인다.,Step:3 오른손과 왼발을 동시에 앞으로 내딛고, 이어서 왼손과 오른발을 내딛는다.,Step:4 손과 발을 번갈아 움직이며 앞으로 계속 기어간다.,Step:5 일정한 속도를 유지하고 전 과정에서 코어에 힘을 유지한다.,Step:6 원하는 거리 또는 시간만큼 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ion0XWz', '바닥에 누워 있는 덤벨 후면 삼각근 올리기', 'https://static.exercisedb.dev/media/Ion0XWz.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 바닥에 엎드려 각 손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 팔꿈치를 약간 굽힌 채 팔을 앞으로 곧게 뻗는다.,Step:3 어깨 근육에 힘을 주어 팔을 옆으로 들어 올리며 견갑골을 모아준다.,Step:4 상단에서 잠깐 멈춘 뒤 팔을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wqNPGCg', '케이블 후면 삼각근(로프 포함)', 'https://static.exercisedb.dev/media/wqNPGCg.gif', '삼각근', '어깨', '케이블', '승모근,능형근,이두근', 'Step:1 낮은 풀리에 로프 손잡이를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 로프를 잡되 손바닥이 서로 마주보게 한다.,Step:4 무릎을 약간 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:5 팔꿈치를 약간 굽힌 상태로 로프를 가슴 쪽으로 당기며 견갑골을 모아준다.,Step:6 상단에서 잠깐 멈춘 뒤 긴장을 유지하며 천천히 시작 자세로 되돌린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8K7m2SS', '메디신 볼 클로즈 그립 푸시업', 'https://static.exercisedb.dev/media/8K7m2SS.gif', '삼두근', '상완이두근', '메디신볼', '가슴,어깨', 'Step:1 메디신볼 위에 손을 어깨너비로 올리고 하이 플랭크 자세로 시작한다.,Step:2 팔꿈치를 몸에 가깝게 유지하며 몸을 바닥 쪽으로 내린다.,Step:3 팔을 펴며 시작 자세로 밀어 올린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MvQPqVW', '케이블 유도 플립', 'https://static.exercisedb.dev/media/MvQPqVW.gif', '복근', '허리', '케이블', '복사근,어깨', 'Step:1 케이블 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:2 케이블 손잡이를 양손으로 가슴 높이에서 잡고 손바닥이 아래를 향하게 한다.,Step:3 코어에 힘을 주고 몸통을 오른쪽으로 회전하며 케이블을 몸 가로질러 당긴다.,Step:4 회전하면서 뒷발을 피벗하고 엉덩이가 자연스럽게 함께 돌아가도록 한다.,Step:5 팔을 끝까지 뻗어 마무리하며 손잡이를 어깨 뒤쪽으로 넘기듯이 플립 동작으로 끝낸다.,Step:6 동작을 역순으로 수행하며 몸통을 가운데로 돌려 시작 자세로 돌아온다.,Step:7 반대쪽도 같은 방식으로 반복한다.,Step:8 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('m0tCHqc', '벽에 손을 대고 종아리 스트레칭', 'https://static.exercisedb.dev/media/m0tCHqc.gif', '종아리근', '종아리', '맨몸', '햄스트링', 'Step:1 벽을 마주보고 발을 엉덩이너비로 벌려 선다.,Step:2 손을 어깨 높이에 두고 벽에 댄다.,Step:3 오른발을 뒤로 내딛고 뒤꿈치를 바닥에 둔 채 다리를 곧게 유지한다.,Step:4 왼쪽 무릎을 굽히고 상체를 앞으로 기울이며 뒷다리를 곧게 유지하고 뒤꿈치를 바닥에 둔다.,Step:5 20–30초 동안 유지한다.,Step:6 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4GqRrAk', '슈퍼맨 푸쉬업', 'https://static.exercisedb.dev/media/4GqRrAk.gif', '가슴근육', '가슴', '맨몸', '코어,어깨', 'Step:1 손을 어깨보다 약간 넓게 두고 발을 모은 하이 플랭크 자세를 만든다.,Step:2 코어에 힘을 주고 팔꿈치를 몸쪽으로 유지하며 몸을 바닥 쪽으로 내린다.,Step:3 내려가면서 동시에 오른팔과 왼다리를 바닥에서 들어 곧게 뻗는다.,Step:4 위에서 잠깐 멈춘다.,Step:5 팔과 다리를 내리며 동시에 팔로 밀어 시작 자세로 올라온다.,Step:6 이번에는 왼팔과 오른다리를 들어 같은 동작을 수행한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('C5jncD2', '스탠딩 싱글 레그 컬', 'https://static.exercisedb.dev/media/C5jncD2.gif', '햄스트링', '허벅지', '맨몸', '둔근', 'Step:1 발을 엉덩이너비로 벌리고 서서 손은 허리에 둔다.,Step:2 체중을 왼쪽 다리에 싣고 오른발을 들어 무릎을 굽힌다.,Step:3 오른쪽 뒤꿈치를 둔근 쪽으로 천천히 당기며 햄스트링을 수축한다.,Step:4 위에서 잠깐 멈춘다.,Step:5 오른발을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Lsqrgh4', '스미스 리버스 카프 레이즈', 'https://static.exercisedb.dev/media/Lsqrgh4.gif', '종아리근', '종아리', '스미스 머신', '햄스트링', 'Step:1 스미스 머신 바를 어깨 아래 정도 높이로 맞춘다.,Step:2 바를 마주보고 발을 엉덩이너비로 두고 선다.,Step:3 계단/플랫폼 끝에 발볼을 올려 뒤꿈치가 바깥으로 나오게 한다.,Step:4 지지를 위해 바를 잡는다.,Step:5 뒤꿈치를 최대한 들어 발끝으로 몸을 들어 올린다.,Step:6 꼭대기에서 잠깐 멈춘다.,Step:7 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KyLtiLT', 'ez 바벨 인클라인 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/KyLtiLT.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 인클라인 벤치를 45도 각도로 세팅한다.,Step:2 벤치에 앉아 EZ바를 오버핸드 그립으로 잡는다.,Step:3 팔을 머리 위로 완전히 뻗되 팔꿈치는 머리 가까이 유지한다.,Step:4 팔꿈치를 굽혀 바를 머리 뒤로 천천히 내리며 상완은 고정한다.,Step:5 아래에서 잠깐 멈춘다.,Step:6 팔을 펴서 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OQ1otBN', '케이블 크로스오버 사이드 풀다운', 'https://static.exercisedb.dev/media/OQ1otBN.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 케이블 머신 양쪽에 어깨 높이로 손잡이를 각각 연결한다.,Step:2 머신 중앙에 서서 발을 어깨너비로 둔다.,Step:3 손잡이를 오버핸드 그립으로 잡고 뒤로 한 걸음 물러 케이블에 장력을 만든다.,Step:4 엉덩이에서 약간 상체를 숙이고 등을 곧게, 가슴은 들어 올린다.,Step:5 손잡이를 아래로 그리고 몸 앞쪽으로 당기며 견갑골을 모아 준다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 천천히 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ht8xDrP', '머리 밀리터리 프레스 뒤에 서있는 스미스', 'https://static.exercisedb.dev/media/ht8xDrP.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 스미스 머신에서 바가 어깨 높이에 오도록 높이를 맞춘다.,Step:2 발을 어깨너비로 두고 무릎은 살짝 굽힌 채 선다.,Step:3 어깨보다 약간 넓게 오버핸드 그립으로 바를 잡는다.,Step:4 바를 랙에서 빼고 안정적인 자세를 유지한다.,Step:5 바를 머리 뒤쪽, 승모 상부에 위치시킨다.,Step:6 코어에 힘을 주고 가슴을 들어 올린 채 자세를 유지한다.,Step:7 팔을 펴서 바를 머리 위로 밀어 올린다.,Step:8 위에서 잠깐 멈춘다.,Step:9 바를 천천히 내려 시작 자세로 돌아온다.,Step:10 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZuPXtCK', '스미스 해킹 스쿼트', 'https://static.exercisedb.dev/media/ZuPXtCK.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 스미스 머신 바 높이를 신체에 맞게 조절한다.,Step:2 발을 어깨너비로 두고 발끝은 약간 바깥쪽으로 향하게 선다.,Step:3 바가 상부 승모와 어깨 위에 얹히도록 바 아래로 들어간다.,Step:4 어깨보다 약간 넓게 오버핸드 그립으로 바를 잡는다.,Step:5 코어에 힘을 주고 가슴을 들어 올린 채로 바를 언랙한다.,Step:6 한 걸음 뒤로 물러 발을 어깨보다 약간 넓게 둔다.,Step:7 무릎을 굽혀 내려가며 상체를 세우고 등을 곧게 유지한다.,Step:8 허벅지가 바닥과 평행하거나 약간 더 내려갈 때까지 하강한다.,Step:9 아래에서 잠깐 멈춘다.,Step:10 뒤꿈치로 밀어 올라와 시작 자세로 돌아온다.,Step:11 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CqhoytW', '스미스 힙 레이즈', 'https://static.exercisedb.dev/media/CqhoytW.gif', '복근', '허리', '스미스 머신', '둔근,햄스트링', 'Step:1 스미스 머신에서 등은 패드에 기대고 발은 어깨너비로 둔다.,Step:2 손은 바를 어깨보다 약간 넓게 잡는다.,Step:3 코어와 둔근에 힘을 준다.,Step:4 뒤꿈치로 밀어 엉덩이를 들어 올린다.,Step:5 무릎부터 어깨까지 일직선이 되도록 올린다.,Step:6 위에서 잠깐 멈춘다.,Step:7 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RQNVT10', '누워서 둔부 및 이상근 스트레칭', 'https://static.exercisedb.dev/media/RQNVT10.gif', '둔근', '허벅지', '도움을 준', '햄스트링', 'Step:1 다리를 곧게 뻗은 채로 등을 바닥에 대고 눕는다.,Step:2 오른쪽 무릎을 굽혀 오른쪽 발목을 왼쪽 허벅지 위, 무릎 바로 위에 둔다.,Step:3 양손으로 왼쪽 허벅지를 잡고 가슴 쪽으로 천천히 당긴다.,Step:4 20–30초 동안 유지한다.,Step:5 스트레치를 풀고 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('S4pwGlc', '덤벨 플라이오 스쿼트', 'https://static.exercisedb.dev/media/S4pwGlc.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 들고 옆으로 둔다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트로 내려간다.,Step:3 스쿼트 바닥 지점에서 폭발적으로 점프해 위로 뛴다.,Step:4 공중에서 발 위치를 빠르게 바꿔 반대발이 앞으로 오도록 착지한다.,Step:5 착지 직후 다시 스쿼트로 내려가며 반복한다.,Step:6 점프할 때마다 발을 번갈아 바꾸며 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GaSzzuh', '뒤 레버', 'https://static.exercisedb.dev/media/GaSzzuh.gif', '등 위쪽', '등', '맨몸', '이두근,전완근,코어', 'Step:1 풀업 바에 오버핸드 그립으로 매달려 손을 어깨보다 약간 넓게 잡는다.,Step:2 코어에 힘을 주고 견갑골을 아래로 당겨 고정한다.,Step:3 무릎을 굽혀 가슴 쪽으로 당긴다.,Step:4 다리를 곧게 펴며 몸이 바닥과 평행이 되도록 천천히 들어 올린다.,Step:5 몇 초간 유지한다.,Step:6 천천히 다리를 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dNFYIU1', '레버 숄더 프레스 v. 3', 'https://static.exercisedb.dev/media/dNFYIU1.gif', '삼각근', '어깨', '레버리지 머신', '삼두근,가슴', 'Step:1 레버리지 머신의 좌석 높이와 등받이를 편한 위치로 조절한다.,Step:2 등받이에 등을 대고 앉아 발은 바닥에 평평하게 둔다.,Step:3 손잡이를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:4 팔꿈치를 잠그지 않도록 주의하며 손잡이를 위/앞으로 밀어 올린다.,Step:5 위에서 잠깐 멈춘다.,Step:6 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IZVHb27', '워킹 런지', 'https://static.exercisedb.dev/media/IZVHb27.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 오른발을 앞으로 내딛고 런지 자세로 내려간다.,Step:3 상체를 세우고 앞무릎이 발목 위에 오도록 정렬한다.,Step:4 오른발로 밀어 일어서며 왼발을 앞으로 가져와 다음 런지로 연결한다.,Step:5 좌우를 번갈아 앞으로 전진하며 수행한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NlfIbzq', '덤벨 얼터너티브 프리처 컬', 'https://static.exercisedb.dev/media/NlfIbzq.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 벤치에 앉아 덤벨을 양손에 들고 손바닥이 위를 향하게 한다.,Step:2 상완을 패드에 대고 팔을 완전히 편다.,Step:3 상완은 고정한 채 숨을 내쉬며 오른쪽 덤벨을 말아 올려 이두근을 수축한다.,Step:4 덤벨이 어깨 높이에 오고 이두근이 완전히 수축될 때까지 올린다.,Step:5 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 왼팔도 같은 방식으로 수행한다.,Step:8 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('76vfTdU', '바이셉스 컬을 이용한 덤벨 스텝업 싱글 레그 밸런스', 'https://static.exercisedb.dev/media/76vfTdU.gif', '이두근', '상완이두근', '덤벨', '대퇴사두근,둔근,햄스트링', 'Step:1 덤벨을 양손에 들고 발은 몸 옆에 둔 채 스텝/플랫폼 앞에 선다.,Step:2 오른발을 스텝 위에 올려 발바닥 전체가 닿게 한다.,Step:3 코어에 힘을 주고 오른쪽 뒤꿈치로 밀어 몸을 올리며 왼쪽 무릎을 가슴 쪽으로 들어 올린다.,Step:4 위에서 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 당기며 이두근 컬을 수행한다.,Step:5 덤벨을 내리면서 동시에 왼발을 바닥으로 내려 시작 자세로 돌아온다.,Step:6 반대쪽도 같은 방식으로 반복한다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1VpF8db', '볼링 동작을 이용한 덤벨 바이셉 컬 런지', 'https://static.exercisedb.dev/media/1VpF8db.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 덤벨을 양손에 들고 손바닥이 앞을 향하게 한다.,Step:2 오른발을 앞으로 내딛고 런지로 내려간다.,Step:3 런지로 내려가면서 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 런지 바닥 지점에서 몸통을 오른쪽으로 회전해 볼링을 던지듯 동작한다.,Step:5 동작을 되돌려 오른발을 뒤로 빼며 시작 자세로 돌아오고 덤벨도 내린다.,Step:6 이번에는 왼쪽으로 회전하도록 반대쪽으로 수행한다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FVmZVhk', '케이블 로우 플라이', 'https://static.exercisedb.dev/media/FVmZVhk.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 머신 하단 풀리에 손잡이를 연결하고 적절한 무게를 선택한다.,Step:2 머신 중앙에 서서 무릎을 약간 굽힌다.,Step:3 오버핸드 그립으로 손잡이를 잡고 팔을 옆으로 벌려(팔꿈치 약간 굽힘) 시작한다.,Step:4 팔꿈치 각도를 유지하며 팔을 앞으로 쓸어 모아 몸 앞에서 교차한다.,Step:5 수축 지점에서 잠깐 멈추며 가슴의 당김을 느낀다.,Step:6 팔을 벌려 천천히 시작 자세로 돌아온다.,Step:7 가슴에 지속적으로 긴장을 유지한 채 반복한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DeDThfG', '앉아서 하는 둔근 스트레칭', 'https://static.exercisedb.dev/media/DeDThfG.gif', '둔근', '허벅지', '맨몸', '햄스트링', 'Step:1 다리를 앞으로 곧게 뻗은 채 바닥에 앉는다.,Step:2 오른쪽 무릎을 굽혀 오른쪽 발목을 왼쪽 허벅지 위에 올린다.,Step:3 오른손을 몸 뒤 바닥에 두어 지지한다.,Step:4 왼손으로 오른쪽 무릎을 부드럽게 눌러 스트레치를 깊게 한다.,Step:5 30초에서 1분 동안 유지한다.,Step:6 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mwpPcr1', '덤벨 프론 인클라인 컬', 'https://static.exercisedb.dev/media/mwpPcr1.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치를 45도 인클라인으로 조절한다.,Step:2 벤치에 엎드려 가슴과 복부를 벤치에 댄다.,Step:3 덤벨을 양손에 들고 손바닥이 아래를 향하게 하여 팔을 완전히 편다.,Step:4 상완은 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:5 덤벨이 어깨 높이에 오고 이두근이 완전히 수축될 때까지 올린다.,Step:6 수축 지점에서 잠깐 멈추며 이두근을 조인다.,Step:7 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sYCcnon', '케이블 스탠딩 원 암 삼두근 익스텐션', 'https://static.exercisedb.dev/media/sYCcnon.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 발을 어깨너비로 벌리고 케이블 머신을 마주보고 선다.,Step:2 오른손으로 손잡이를 잡고 손바닥이 아래를 향하게 한다.,Step:3 팔을 곧게 뻗어 바닥과 평행이 되게 위치시킨다.,Step:4 팔꿈치는 몸 가까이 고정하고 움직이지 않게 한다.,Step:5 팔꿈치를 굽혀 손잡이를 머리 뒤쪽으로 천천히 내린다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 팔을 펴서 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hrVQWvE', '바벨 스트레이트 레그 데드리프트', 'https://static.exercisedb.dev/media/hrVQWvE.gif', '햄스트링', '허벅지', '바벨', '둔근,허리', 'Step:1 발을 어깨너비로 두고 발끝은 정면을 향하게 선다.,Step:2 바벨을 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:3 등을 곧게 유지하며 엉덩이를 접어 바벨을 바닥 쪽으로 내린다(무릎은 약간 굽힘).,Step:4 햄스트링이 늘어나는 느낌이 날 때까지 내린다.,Step:5 햄스트링과 둔근에 힘을 주어 바벨을 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6TG6x2w', 'ez 바벨 컬', 'https://static.exercisedb.dev/media/6TG6x2w.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 서서 EZ바를 언더핸드 그립(손바닥 위)으로 잡는다.,Step:2 팔꿈치를 몸통에 붙이고 상완이 움직이지 않게 고정한다.,Step:3 숨을 내쉬며 바를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 위에서 잠깐 멈춘다.,Step:5 숨을 들이마시며 바를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('g2oKspu', '컬업', 'https://static.exercisedb.dev/media/g2oKspu.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 벌린다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 정도가 되게 말아 올린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 상체를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LSTChY9', '바벨 저처 스쿼트', 'https://static.exercisedb.dev/media/LSTChY9.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 두고 발끝을 약간 바깥으로 향하게 선다.,Step:2 바벨을 팔꿈치 안쪽(팔꿈치 접히는 부분)에 걸고 안정적으로 잡는다.,Step:3 코어에 힘을 주고 가슴을 들어 올린 채 스쿼트로 내려간다.,Step:4 무릎이 발끝 방향과 일직선이 되게 유지하고 체중은 뒤꿈치에 둔다.,Step:5 아래에서 잠깐 멈춘다.,Step:6 뒤꿈치로 밀어 올라와 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hnOYgH3', 'ez 바벨 JM 벤치 프레스', 'https://static.exercisedb.dev/media/hnOYgH3.gif', '삼두근', '상완이두근', 'EZ 바벨', '가슴,어깨', 'Step:1 벤치에 누워 발바닥을 바닥에 두고 등을 벤치에 밀착한다.,Step:2 EZ바를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:3 팔꿈치를 몸쪽으로 유지하며 바를 가슴 쪽으로 내린다.,Step:4 팔을 펴서 바를 다시 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EMpUwRI', '바벨 라이딩 익스텐션', 'https://static.exercisedb.dev/media/EMpUwRI.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 누워 발바닥을 바닥에 두고 머리는 벤치 끝 쪽에 오게 한다.,Step:2 바벨을 오버핸드 그립으로 어깨너비로 잡고 가슴 위로 팔을 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바벨을 이마 쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘다.,Step:5 팔을 펴서 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6cKQC5E', '덤벨 한쪽 팔 직립 로우', 'https://static.exercisedb.dev/media/6cKQC5E.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 한 손에 덤벨을 오버핸드 그립으로 잡는다.,Step:2 덤벨을 허벅지 앞쪽에 팔을 곧게 편 채로 늘어뜨리고 손바닥은 몸을 향하게 한다.,Step:3 등을 곧게 하고 코어에 힘을 준다.,Step:4 숨을 내쉬며 팔꿈치를 먼저 올리듯 덤벨을 턱 쪽으로 수직으로 끌어올린다.,Step:5 위에서 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('k6tUeqS', '밴드 언더핸드 풀다운', 'https://static.exercisedb.dev/media/k6tUeqS.gif', '광배근', '등', '밴드', '이두근,전완근', 'Step:1 풀업 바나 튼튼한 빔 등 높은 고정점에 밴드를 걸어 고정한다.,Step:2 고정점을 마주보고 발을 어깨너비로 벌리고 선다.,Step:3 밴드를 언더핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:4 팔을 머리 위로 완전히 뻗고 팔꿈치는 약간 굽힌다.,Step:5 광배에 힘을 주고 견갑골을 모으며 밴드를 가슴 쪽으로 끌어내린다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 장력을 유지하며 천천히 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('my33uHU', '레버 다리 익스텐션', 'https://static.exercisedb.dev/media/my33uHU.gif', '대퇴사두근', '허벅지', '레버리지 머신', '햄스트링', 'Step:1 좌석 높이와 등받이를 몸에 맞게 조절한다.,Step:2 등을 등받이에 붙이고 앉아 발을 패드에 둔다.,Step:3 손잡이나 옆 손잡이를 잡아 자세를 고정한다.,Step:4 무릎을 펴며 다리를 앞으로 들어 올려 무게를 올린다.,Step:5 위에서 잠깐 멈춘다.,Step:6 무게를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('km2Ljzj', '휠런', 'https://static.exercisedb.dev/media/km2Ljzj.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 몸을 일직선으로 유지한 플랭크 자세에서 손을 휠 위에 둔다.,Step:2 코어에 힘을 주고 팔을 뻗으며 휠을 앞으로 굴린다.,Step:3 몸이 최대한 길게 늘어나고 팔이 머리 위 방향이 될 때까지 굴린다.,Step:4 코어와 팔로 휠을 다시 몸 쪽으로 당겨 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vmwLyCg', '덤벨 w-프레스', 'https://static.exercisedb.dev/media/vmwLyCg.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 벤치에 앉아 덤벨을 양손에 들고 손바닥이 앞을 보게 한다.,Step:2 덤벨을 어깨 높이로 올리고 팔꿈치를 굽힌다.,Step:3 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 덤벨을 다시 어깨 높이로 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Vh0GsK4', '케이블 인클라인 벤치프레스', 'https://static.exercisedb.dev/media/Vh0GsK4.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 벤치를 45도 인클라인으로 조절한다.,Step:2 케이블 손잡이를 상단 풀리에 연결한다.,Step:3 케이블 머신을 마주보고 벤치에 앉아 발을 바닥에 둔다.,Step:4 오버핸드 그립으로 손잡이를 잡아 어깨 높이로 가져온다.,Step:5 손잡이를 앞으로/위로 밀어 팔을 완전히 편다.,Step:6 위에서 잠깐 멈춘다.,Step:7 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PQStVXH', '케이블 윗줄', 'https://static.exercisedb.dev/media/PQStVXH.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 케이블 머신을 가슴 높이에 맞추고 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:3 바를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:4 등을 곧게 하고 코어에 힘을 준다.,Step:5 견갑골을 모으며 바를 윗가슴 쪽으로 당긴다.,Step:6 수축 지점에서 잠깐 멈춘다.,Step:7 바를 천천히 놓아 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dU605di', '케이블 푸시다운(로프 부착 포함)', 'https://static.exercisedb.dev/media/dU605di.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신 상단 풀리에 로프 어태치먼트를 연결한다.,Step:2 발을 어깨너비로 벌리고 무릎은 약간 굽힌 채 머신을 마주보고 선다.,Step:3 로프를 오버핸드 그립으로 잡고 손바닥이 서로 마주보게 한다.,Step:4 팔꿈치를 몸통에 붙이고 상완이 움직이지 않게 고정한다.,Step:5 숨을 내쉬며 팔꿈치를 펴 로프를 아래로 밀어 팔을 완전히 편다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 숨을 들이마시며 팔꿈치를 굽혀 천천히 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vvNjDJS', '케이블 투 암 트라이셉스 킥백', 'https://static.exercisedb.dev/media/vvNjDJS.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 발을 어깨너비로 벌리고 무릎은 약간 굽힌다.,Step:2 양손으로 손잡이를 잡고 손바닥이 서로 마주보게 하며 팔꿈치를 90도로 굽힌다.,Step:3 상완을 고정한 채 전완을 뒤로 펴 팔을 완전히 편다.,Step:4 위에서 잠깐 멈춘다.,Step:5 팔을 천천히 굽혀 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XlZ4lAC', '바벨 좋은 아침', 'https://static.exercisedb.dev/media/XlZ4lAC.gif', '햄스트링', '허벅지', '바벨', '허리', 'Step:1 바벨을 상부 등(승모)에 올리고 발을 어깨너비로 벌리고 선다.,Step:2 등을 곧게 하고 코어에 힘을 준다.,Step:3 엉덩이를 접어 뒤로 빼며 상체를 앞으로 숙인다(마치 뒤 벽에 둔근을 대려는 느낌).,Step:4 상체가 바닥과 평행해질 때까지 내려 햄스트링 스트레치를 느낀다.,Step:5 잠깐 멈춘다.,Step:6 둔근을 조이며 엉덩이를 앞으로 밀어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('U6G2gk9', '바디업', 'https://static.exercisedb.dev/media/U6G2gk9.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 평행봉 같은 높은 지지대에 손바닥을 대고 손가락은 정면을 향하게 한다.,Step:2 다리를 앞으로 뻗어 뒤꿈치를 바닥에 두고 몸을 곧게 만든다.,Step:3 팔꿈치를 굽혀 몸을 내리되 팔꿈치를 몸쪽으로 유지하며 상완이 바닥과 평행해질 때까지 내려간다.,Step:4 잠깐 멈춘다.,Step:5 손바닥으로 밀어 팔을 펴며 몸을 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PzQanLE', '케이블 숄더 프레스', 'https://static.exercisedb.dev/media/PzQanLE.gif', '삼각근', '어깨', '케이블', '삼두근,등 위쪽', 'Step:1 케이블 손잡이를 어깨 높이에 오도록 세팅한다.,Step:2 머신을 등지고 발을 어깨너비로 벌리고 선다.,Step:3 오버핸드 그립으로 손잡이를 잡아 어깨 높이로 올리고 팔꿈치를 굽힌다.,Step:4 손잡이를 위로 밀어 올려 팔을 완전히 편다.,Step:5 위에서 잠깐 멈춘다.,Step:6 손잡이를 천천히 내려 어깨 높이로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4IKbhHV', '대체 사이드 풀다운', 'https://static.exercisedb.dev/media/4IKbhHV.gif', '광배근', '등', '케이블', '이두근,능형근', 'Step:1 케이블 머신에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 손잡이를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:3 상체를 약간 뒤로 기대며 손잡이를 가슴 쪽으로 당겨 견갑골을 모은다.,Step:4 위에서 잠깐 멈춘다.,Step:5 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hwygydB', '덤벨 컬 오버 (짐 볼)', 'https://static.exercisedb.dev/media/hwygydB.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐볼에 앉아 발을 바닥에 평평하게 두고 등을 곧게 편다.,Step:2 한 손에 덤벨을 언더핸드 그립으로 잡고 팔꿈치를 짐볼 안쪽에 지지한다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qcY50ZD', '케이블 시트 와이드 그립 로우', 'https://static.exercisedb.dev/media/qcY50ZD.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 케이블 로우 머신에 앉아 발을 발판에 두고 무릎을 약간 굽힌다.,Step:2 손잡이를 와이드 오버핸드 그립으로 잡아 손바닥이 아래를 향하게 한다.,Step:3 등을 곧게 하고 엉덩이에서 약간 앞으로 기울인다.,Step:4 손잡이를 아랫가슴 쪽으로 당기며 견갑골을 모은다.,Step:5 수축 지점에서 잠깐 멈춘다.,Step:6 팔을 완전히 펴며 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Db7eEgw', '케이블 집중 익스텐션(무릎)', 'https://static.exercisedb.dev/media/Db7eEgw.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 벤치나 의자에 앉아 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 오른손으로 손잡이를 잡고 오른팔꿈치를 오른쪽 무릎 안쪽에 댄다.,Step:3 팔꿈치를 고정한 채 팔을 완전히 펴서 위로 뻗는다.,Step:4 위에서 잠깐 멈춘다.,Step:5 팔을 천천히 굽혀 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('c3Pfhti', '롤러 사이드 랫 스트레치', 'https://static.exercisedb.dev/media/c3Pfhti.gif', '광배근', '등', '롤러', '어깨,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서 롤러를 양손으로 몸 앞에 든다.,Step:2 무릎을 약간 굽히고 엉덩이에서 상체를 앞으로 숙이며 등을 곧게 유지한다.,Step:3 팔을 앞으로 뻗어 롤러를 발 쪽으로 굴리며 광배 스트레치를 느낀다.,Step:4 몇 초간 유지한다.,Step:5 롤러를 천천히 다시 굴려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Iptlv6x', '덤벨 직립 로우(뒤 POV)', 'https://static.exercisedb.dev/media/Iptlv6x.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 덤벨을 양손에 오버핸드 그립으로 잡는다.,Step:2 덤벨을 허벅지 앞에 팔을 완전히 편 채로 늘어뜨리고 손바닥은 몸을 향하게 한다.,Step:3 등을 곧게 하고 코어에 힘을 준다.,Step:4 숨을 내쉬며 팔꿈치를 먼저 올리듯 덤벨을 턱 쪽으로 수직으로 끌어올린다.,Step:5 덤벨이 어깨 높이에 오고 팔꿈치가 옆으로 향할 때까지 올린다.,Step:6 위에서 잠깐 멈춘다.,Step:7 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dFSNDOA', '바벨 시트 트위스트', 'https://static.exercisedb.dev/media/dFSNDOA.gif', '복근', '허리', '바벨', '복사근,허리', 'Step:1 벤치에 앉아 발바닥을 바닥에 두고 무릎을 굽힌다.,Step:2 팔꿈치를 약간 굽힌 채 가슴 앞에서 바벨을 양손으로 잡는다.,Step:3 코어에 힘을 주고 등을 곧게 유지하며 몸통을 한쪽으로 천천히 비튼다.,Step:4 비틀기 끝에서 잠깐 멈춘다.,Step:5 몸통을 천천히 되돌려 시작 자세로 돌아온다.,Step:6 반대쪽도 같은 방식으로 반복한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('83HoW9X', '바벨 업라이트 로우 v. 2', 'https://static.exercisedb.dev/media/83HoW9X.gif', '삼각근', '어깨', '바벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 바벨을 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:2 바벨을 허벅지 앞에 팔을 완전히 편 채로 둔다.,Step:3 등을 곧게 유지한 채 숨을 내쉬며 팔꿈치를 먼저 올리듯 바벨을 턱 쪽으로 끌어올린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 숨을 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('f91FwXG', '레버 그립리스 슈러그', 'https://static.exercisedb.dev/media/f91FwXG.gif', '승모근', '등', '레버리지 머신', '어깨,전완근', 'Step:1 레버리지 머신 좌석 높이를 조절하고 자세를 잡는다.,Step:2 손바닥이 서로 마주보게 손잡이를 잡고 팔을 완전히 편다.,Step:3 등을 곧게 유지한 채 숨을 내쉬며 어깨를 귀 쪽으로 최대한 끌어올린다.,Step:4 수축 지점에서 잠깐 멈춘다.,Step:5 숨을 들이마시며 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GSDioYu', '상부 등 스트레칭', 'https://static.exercisedb.dev/media/GSDioYu.gif', '등 위쪽', '등', '맨몸', '어깨', 'Step:1 발을 어깨너비로 벌리고 곧게 선다.,Step:2 팔을 바닥과 평행하게 앞으로 곧게 뻗는다.,Step:3 손가락을 깍지 끼고 손바닥을 몸 반대 방향으로 돌린다.,Step:4 팔을 곧게 유지한 채 서로 평행하도록 위로 천천히 들어 올린다.,Step:5 팔을 올리면서 견갑골을 서로 모으듯이 조인다.,Step:6 15–30초 동안 유지한 뒤 풀고 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QYysSLV', '마인 180', 'https://static.exercisedb.dev/media/QYysSLV.gif', '복근', '허리', '바벨', '복사근,대퇴사두근', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 양손으로 가슴 앞에 잡는다.,Step:2 무릎을 약간 굽힌다.,Step:3 몸통을 오른쪽으로 회전하며 바벨을 오른쪽 엉덩이 쪽으로 내려 보낸다.,Step:4 아래 지점에서 즉시 방향을 바꿔 몸통을 왼쪽으로 회전하며 바벨을 왼쪽 어깨 쪽으로 올린다.,Step:5 이 비틀기 동작을 좌우로 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DwhEmmE', '덤벨 디클라인 벤치 프레스', 'https://static.exercisedb.dev/media/DwhEmmE.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 발을 고정하고 머리가 엉덩이보다 낮게 위치하게 한다.,Step:2 덤벨을 양손에 들고 가슴 위로 팔을 곧게 펴 손바닥이 앞을 향하게 한다.,Step:3 팔꿈치를 90도 정도로 유지하며 덤벨을 가슴 옆으로 천천히 내린다.,Step:4 덤벨을 밀어 올려 팔을 완전히 펴 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UQr48Oi', '풀인(스태빌리티 볼)', 'https://static.exercisedb.dev/media/UQr48Oi.gif', '복근', '허리', '스태빌리티 볼', '고관절 굴근', 'Step:1 짐볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 지지를 위해 양손을 짐볼 옆에 둔다.,Step:3 복근에 힘을 주고 골반을 앞으로 굴리며 무릎을 가슴 쪽으로 당긴다.,Step:4 위에서 잠깐 멈춘다.,Step:5 다리를 천천히 뻗어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yz9nUhF', '덤벨 플라이', 'https://static.exercisedb.dev/media/yz9nUhF.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 벤치에 누워 덤벨을 양손에 들고 손바닥이 서로 마주보게 한다.,Step:2 팔꿈치를 약간 굽힌 채 덤벨을 가슴 위로 곧게 뻗는다.,Step:3 팔꿈치 각도를 유지하며 팔을 옆으로 넓게 벌려 가슴이 늘어나는 지점까지 내린다.,Step:4 아래에서 잠깐 멈춘다.,Step:5 가슴을 조이며 덤벨을 다시 위로 모아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yRLPCLu', '바벨 리버스 그립 스컬 크러셔', 'https://static.exercisedb.dev/media/yRLPCLu.gif', '삼두근', '상완이두근', '바벨', '전완근', 'Step:1 벤치에 누워 발바닥을 바닥에 두고 머리는 벤치 끝에 오게 한다.,Step:2 바벨을 리버스 그립(손바닥이 얼굴 쪽)으로 어깨너비로 잡는다.,Step:3 팔을 가슴 위로 곧게 펴고 팔꿈치를 몸쪽으로 모으며 손목은 곧게 유지한다.,Step:4 상완을 고정한 채 팔꿈치를 굽혀 바벨을 이마 쪽으로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘다.,Step:6 팔을 펴서 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ila4NZS', '바벨 데드리프트', 'https://static.exercisedb.dev/media/ila4NZS.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 바벨을 발 앞 바닥에 둔다.,Step:2 무릎을 굽히고 엉덩이를 접어 상체를 낮추며 바벨을 오버핸드 그립으로 잡는다(어깨보다 약간 넓게).,Step:3 등을 곧게 하고 가슴을 들어 올린 채 뒤꿈치로 밀어 바벨을 들어 올리며 엉덩이와 무릎을 편다.,Step:4 완전히 선 지점에서 둔근을 조이고 코어 긴장을 유지한다.,Step:5 엉덩이와 무릎을 굽혀 바벨을 천천히 바닥으로 내려놓는다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZH68exZ', '밴드 고정 백 언더핸드 풀다운', 'https://static.exercisedb.dev/media/ZH68exZ.gif', '광배근', '등', '밴드', '이두근,능형근,후면 삼각근', 'Step:1 머리 위쪽의 튼튼한 고정점에 밴드를 걸어 고정한다.,Step:2 고정점을 마주보고 발을 어깨너비로 벌리고 선다.,Step:3 밴드를 언더핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:4 뒤로 한 걸음 물러 밴드 장력을 만들고 팔을 완전히 뻗는다.,Step:5 코어에 힘을 주고 견갑골을 모아 고정한다.,Step:6 팔꿈치를 먼저 내리듯 밴드를 가슴 쪽으로 당긴다.,Step:7 아래에서 잠깐 멈추며 광배 수축을 느낀다.,Step:8 밴드 장력을 유지하며 천천히 시작 자세로 돌아온다.,Step:9 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fKZgDEO', '한쪽 다리 종아리 들기(덤벨 위에서)', 'https://static.exercisedb.dev/media/fKZgDEO.gif', '종아리근', '종아리', '덤벨', '발목,피트', 'Step:1 발을 엉덩이너비로 두고 서서 한 손에 덤벨을 든다.,Step:2 한쪽 발을 들어 다른 쪽 발로 균형을 잡는다.,Step:3 종아리로 뒤꿈치를 최대한 들어 올린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Kpajagk', '케이블 스탠딩 힙 익스텐션', 'https://static.exercisedb.dev/media/Kpajagk.gif', '둔근', '허벅지', '케이블', '햄스트링,대퇴사두근', 'Step:1 케이블을 하단 풀리에 연결하고 머신을 등지고 선다.,Step:2 케이블 스트랩을 발목에 걸고 발을 어깨너비로 둔다.,Step:3 코어에 힘을 주고 등을 곧게 유지한다.,Step:4 다리를 뒤로 곧게 뻗어 올리며 위에서 둔근을 조인다.,Step:5 위에서 잠깐 멈춘다.,Step:6 다리를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XsCcxCC', '레버에 앉아 좋은 아침', 'https://static.exercisedb.dev/media/XsCcxCC.gif', '둔근', '허벅지', '레버리지 머신', '햄스트링,허리', 'Step:1 좌석 높이를 조절해 엉덩이가 무릎보다 약간 높게 오도록 맞춘다.,Step:2 등 패드에 등을 대고 발은 발판에 평평하게 둔다.,Step:3 손잡이나 좌석 옆을 잡아 자세를 고정한다.,Step:4 등을 곧게 유지하며 엉덩이에서 상체를 앞으로 천천히 숙여 상체가 바닥과 평행에 가깝게 되게 한다.,Step:5 아래에서 잠깐 멈춘다.,Step:6 둔근과 햄스트링으로 밀어 상체를 세워 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PcPe0P5', '케이블 로프 해머 설교자 컬', 'https://static.exercisedb.dev/media/PcPe0P5.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신 하단 풀리에 로프를 연결한다.,Step:2 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:3 로프를 뉴트럴 그립(손바닥 마주봄)으로 잡는다.,Step:4 상완을 프리처 패드에 붙이고 팔꿈치는 약간 굽힌다.,Step:5 상완을 고정한 채 숨을 내쉬며 로프를 어깨 쪽으로 끌어올린다.,Step:6 수축 지점에서 잠깐 멈추며 이두근을 조인다.,Step:7 숨을 들이마시며 로프를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('D9qe7CM', '골반이 브릿지로 기울어짐', 'https://static.exercisedb.dev/media/D9qe7CM.gif', '둔근', '허벅지', '맨몸', '햄스트링,코어', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 팔을 몸 옆에 두고 손바닥이 바닥을 향하게 한다.,Step:3 둔근과 코어에 힘을 준다.,Step:4 골반을 말아 올리며 엉덩이를 들어 올린다.,Step:5 브릿지 자세를 몇 초간 유지한다.,Step:6 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DU5Kkj2', '덤벨 서 원 암 리버스 컬', 'https://static.exercisedb.dev/media/DU5Kkj2.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 서서 한 손에 덤벨을 오버핸드 그립으로 잡는다.,Step:2 팔을 완전히 편 채 몸 옆에 붙이고 손바닥은 아래를 향하게 한다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 천천히 말아 올린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yRYyfdA', '엑서사이즈볼 위에 앉아 햄스트링 스트레칭', 'https://static.exercisedb.dev/media/yRYyfdA.gif', '햄스트링', '허벅지', '스태빌리티 볼', '둔근,허리', 'Step:1 발을 바닥에 두고 무릎을 90도로 굽힌 상태로 짐볼에 앉는다.,Step:2 발을 앞으로 걸어 나가며 짐볼이 천천히 굴러가 상부등이 볼 위에 놓이고 다리가 앞으로 곧게 뻗힌 상태가 되도록 한다.,Step:3 양손을 허리에 두어 지지한다.,Step:4 코어에 힘을 주고 등을 곧게 유지한 채 상체를 천천히 바닥 쪽으로 내리면서 가슴을 들어 올린다.,Step:5 햄스트링이 늘어나는 느낌이 들 때 멈추고 20–30초 동안 유지한다.,Step:6 뒤꿈치로 바닥을 밀고 햄스트링을 사용하여 몸을 끌어올리며 천천히 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('P14Dz9D', '케이블 한쪽 팔 인클라인 플라이 위 짐 볼', 'https://static.exercisedb.dev/media/P14Dz9D.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 짐볼에 앉아 발을 바닥에 두고 등은 인클라인 벤치에 기대어 지지한다.,Step:2 한 손으로 케이블 손잡이를 잡고 팔을 뻗어 손바닥이 안쪽을 향하게 한다.,Step:3 팔꿈치를 약간 굽힌 채 팔을 옆으로 천천히 내려 어깨 선과 일직선이 되게 한다.,Step:4 아래에서 잠깐 멈춘다.,Step:5 가슴을 조이며 팔을 다시 모아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7ePTw4B', '엑서사이즈볼 위에 앉아 삼두근 스트레칭', 'https://static.exercisedb.dev/media/7ePTw4B.gif', '삼두근', '상완이두근', '스태빌리티 볼', '어깨', 'Step:1 발을 바닥에 두고 등을 곧게 편 상태로 짐볼에 앉는다.,Step:2 한 손에 덤벨을 들고 팔을 머리 위로 곧게 뻗는다.,Step:3 팔꿈치를 굽혀 덤벨을 머리 뒤로 내리되 위팔은 귀 가까이에 둔다.,Step:4 몇 초간 유지한 뒤 시작 자세로 돌아온다.,Step:5 반대쪽 팔도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uWpxD4v', '무릎을 굽힌 채 매달린 턱걸이', 'https://static.exercisedb.dev/media/uWpxD4v.gif', '복근', '허리', '맨몸', '어깨,등', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 무릎은 90도로 굽힌다.,Step:2 코어에 힘을 주고 무릎을 가슴 쪽으로 들어 올려 팔꿈치에 최대한 가깝게 가져간다.,Step:3 다리를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G7PXMlT', '밴드 수직 팔로프 프레스', 'https://static.exercisedb.dev/media/G7PXMlT.gif', '복근', '허리', '밴드', '복사근,둔근', 'Step:1 가슴 높이에 튼튼한 고정물에 밴드를 감아 고정한다.,Step:2 밴드를 양손으로 잡고 고정물에서 멀어져 장력을 만든다.,Step:3 몸이 고정물과 직각이 되도록 옆으로 서서 밴드가 몸 옆에서 당기게 한다.,Step:4 팔을 가슴 높이에서 앞으로 곧게 뻗는다.,Step:5 코어에 힘을 주고 밴드를 가슴에서 멀어지게 밀어 팔을 완전히 편다.,Step:6 몇 초간 유지한다.,Step:7 팔을 굽혀 밴드를 가슴 쪽으로 천천히 가져온다.,Step:8 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XalXcvM', '덤벨 포워드 런지 삼두근 익스텐션', 'https://static.exercisedb.dev/media/XalXcvM.gif', '삼두근', '상완이두근', '덤벨', '어깨,코어', 'Step:1 발을 어깨너비로 벌리고 서서 덤벨을 양손에 든다.,Step:2 오른발을 앞으로 내딛고 런지 자세로 내려간다.,Step:3 등을 곧게 하고 가슴을 들어 올린다.,Step:4 덤벨을 머리 위로 들어 팔을 곧게 뻗고 팔꿈치를 귀 옆에 붙인다.,Step:5 팔꿈치를 굽혀 덤벨을 머리 뒤로 내린다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 팔을 펴서 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('neonEDL', '플로어 플라이(바벨 포함)', 'https://static.exercisedb.dev/media/neonEDL.gif', '가슴근육', '가슴', '바벨', '삼각근,삼두근', 'Step:1 바닥에 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 바벨을 오버핸드 그립으로 잡고 가슴 위로 팔을 곧게 편다.,Step:3 팔꿈치를 약간 굽힌 채 바벨을 좌우로 천천히 내려 팔이 바닥과 평행해질 때까지 내린다.,Step:4 가슴이 늘어나는 느낌이 들 때까지 내린다.,Step:5 아래에서 잠깐 멈춘다.,Step:6 가슴을 조이며 바벨을 다시 위로 모아 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sJFIDIp', '이두근 다리 컨센트레이션 컬', 'https://static.exercisedb.dev/media/sJFIDIp.gif', '이두근', '상완이두근', '맨몸', '전완근', 'Step:1 벤치에 앉아 다리를 벌리고 발바닥을 바닥에 둔다.,Step:2 한 손에 덤벨을 들고 팔꿈치를 허벅지 안쪽(무릎 바로 위)에 댄다.,Step:3 손바닥이 위를 향한 상태에서 상완을 고정하고 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 이두근을 조인다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2zNKRUB', '손목 서클', 'https://static.exercisedb.dev/media/2zNKRUB.gif', '전완근', '팔 아래', '맨몸', '소유,손목', 'Step:1 팔을 앞으로 곧게 뻗는다.,Step:2 양손을 쥐어 주먹을 만든다.,Step:3 팔은 고정한 채 손목을 원을 그리듯 회전시킨다.,Step:4 원하는 반복 횟수만큼 손목 서클을 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2NpxjC1', '덤벨 해머 컬 v. 2', 'https://static.exercisedb.dev/media/2NpxjC1.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 덤벨을 양손에 들고 곧게 서서 손바닥이 몸통을 향하게 한다.,Step:2 팔꿈치를 몸통에 붙인다.,Step:3 손바닥을 앞으로 향하게 회전해 시작 자세를 만든다.,Step:4 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:5 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 올린다.,Step:6 수축 지점에서 잠깐 멈추며 이두근을 조인다.,Step:7 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3T12T87', '두 팔 삼두근 익스텐션 위로 구부린 자세로 서있는 덤벨', 'https://static.exercisedb.dev/media/3T12T87.gif', '삼두근', '상완이두근', '덤벨', '어깨,등', 'Step:1 발을 어깨너비로 벌리고 서서 덤벨을 양손에 든다.,Step:2 등을 곧게 유지한 채 허리에서 상체를 앞으로 숙이고 무릎은 약간 굽힌다.,Step:3 팔꿈치를 몸쪽에 두고 팔을 뒤로 곧게 뻗는다.,Step:4 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WU9BLIs', '가중 러시안 트위스트(다리 위로)', 'https://static.exercisedb.dev/media/WU9BLIs.gif', '복근', '허리', '가중', '복사근,고관절 굴근', 'Step:1 바닥에 앉아 무릎을 굽히고 발을 바닥에서 들어 다리를 모은다.,Step:2 가중치를 양손으로 가슴 앞에 든다.,Step:3 코어를 사용하기 위해 상체를 약간 뒤로 기울인다.,Step:4 몸통을 오른쪽으로 비틀며 가중치를 오른쪽 바닥 쪽으로 가져간다.,Step:5 잠깐 멈춘다.,Step:6 몸통을 왼쪽으로 비틀며 가중치를 왼쪽 바닥 쪽으로 가져간다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BmrwWzo', '덤벨 스모 풀 스루', 'https://static.exercisedb.dev/media/BmrwWzo.gif', '둔근', '허벅지', '덤벨', '햄스트링,대퇴사두근,코어', 'Step:1 발을 어깨보다 넓게 벌리고 발끝을 바깥으로 향하게 선다.,Step:2 양손으로 덤벨을 몸 앞에 팔을 뻗어 잡는다.,Step:3 무릎을 굽혀 스모 스쿼트로 내려가며 덤벨을 다리 사이로 내린다.,Step:4 등을 곧게 유지한다.,Step:5 뒤꿈치로 밀며 올라오면서 엉덩이를 앞으로 펴 덤벨을 몸 앞쪽으로 끌어올린다.,Step:6 위에서 둔근을 조인다.,Step:7 덤벨을 다시 다리 사이로 천천히 내린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1bQkKZK', '스미스 굽은 무릎 좋은 아침', 'https://static.exercisedb.dev/media/1bQkKZK.gif', '둔근', '허벅지', '스미스 머신', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 발끝은 정면을 향하게 선다.,Step:2 바를 상부 승모에 얹는다.,Step:3 무릎을 약간 굽힌다.,Step:4 엉덩이를 접어 앞으로 숙이되 등을 곧게 유지한다.,Step:5 상체가 바닥과 평행해질 때까지 내려 햄스트링 스트레치를 느낀다.,Step:6 둔근과 햄스트링으로 상체를 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wyaqzOS', '덤벨 누워 한쪽 팔 내전 삼두근 익스텐션', 'https://static.exercisedb.dev/media/wyaqzOS.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 누워 머리와 등을 지지하고 발바닥을 바닥에 둔다.,Step:2 한 손에 덤벨을 들고 손바닥이 아래를 향하게 하여 어깨 위로 팔을 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘다.,Step:5 팔을 펴서 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NAgVB3t', '휠 롤아웃', 'https://static.exercisedb.dev/media/NAgVB3t.gif', '복근', '허리', '휠 롤러', '허리', 'Step:1 바닥에 무릎을 대고 휠 롤러를 몸 앞에 둔다.,Step:2 손잡이를 잡고 팔을 앞으로 곧게 뻗는다.,Step:3 코어에 힘을 주고 등을 곧게 유지하며 휠을 천천히 앞으로 굴린다.,Step:4 몸이 최대한 늘어날 때까지 굴린다.,Step:5 잠깐 멈춘다.,Step:6 휠을 무릎 쪽으로 천천히 당겨 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1g5bPpA', '잭 점프(남)', 'https://static.exercisedb.dev/media/1g5bPpA.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,종아리근', 'Step:1 발을 모으고 팔을 몸 옆에 둔 채 선다.,Step:2 점프하며 발을 벌리고 팔을 머리 위로 들어 올린다.,Step:3 착지하자마자 다시 점프해 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iYzB0Cz', '바벨 풀 스쿼트(사이드 POV)', 'https://static.exercisedb.dev/media/iYzB0Cz.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 벌리고 발끝을 약간 바깥으로 향하게 선다.,Step:2 바벨을 상부 등(승모/후면 삼각근 라인)에 올린다.,Step:3 코어에 힘을 주고 가슴을 들어 올린다.,Step:4 무릎과 엉덩이를 굽혀 의자에 앉듯이 내려간다.,Step:5 허벅지가 바닥과 평행하거나 약간 더 내려갈 때까지 하강한다.,Step:6 무릎이 발끝 방향과 일직선이 되게 하고 체중은 뒤꿈치에 둔다.,Step:7 뒤꿈치로 밀어 올라오며 엉덩이와 무릎을 편다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OUQ0ZyW', '스미스 숄더 슈레그', 'https://static.exercisedb.dev/media/OUQ0ZyW.gif', '승모근', '등', '스미스 머신', '어깨', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:2 바를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:3 팔을 곧게 펴고 어깨 힘을 뺀다.,Step:4 어깨를 귀 쪽으로 끌어올려 승모근을 수축한다.,Step:5 위에서 잠깐 멈춘다.,Step:6 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hCjGsRQ', '파워 포인트 판자', 'https://static.exercisedb.dev/media/hCjGsRQ.gif', '복근', '허리', '맨몸', '어깨,삼두근,둔근', 'Step:1 손을 어깨 아래에 두고 하이 플랭크 자세를 만든다(머리부터 발끝까지 일직선).,Step:2 코어와 둔근을 조여 안정적으로 유지한다.,Step:3 한 팔씩 천천히 팔꿈치를 바닥에 내려 포어암 플랭크로 전환한다.,Step:4 원하는 시간 동안 자세를 유지한다.,Step:5 팔꿈치로 바닥을 밀어 하이 플랭크로 다시 올라온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KZXAtKQ', '푸시업 클로즈 그립 오프 덤벨', 'https://static.exercisedb.dev/media/KZXAtKQ.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 손을 서로 가깝게 두고 어깨 아래에 오도록 푸시업 자세를 만든다.,Step:2 양손에 덤벨을 잡고 바닥에 덤벨을 두어 지지한다.,Step:3 팔꿈치를 몸쪽으로 붙이며 몸을 바닥 쪽으로 내린다.,Step:4 손바닥으로 밀어 팔을 펴 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jjUPrze', '스미스 스탠딩 밀리터리 프레스', 'https://static.exercisedb.dev/media/jjUPrze.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌다.,Step:2 바를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:3 바를 랙에서 빼 어깨 높이로 내리며 손바닥은 정면을 향하게 한다.,Step:4 바를 머리 위로 밀어 올려 팔을 완전히 편다.,Step:5 위에서 잠깐 멈춘다.,Step:6 바를 천천히 내려 어깨 높이로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('K9VL0Jq', '트위스트와 함께 돌진', 'https://static.exercisedb.dev/media/K9VL0Jq.gif', '복근', '허리', '맨몸', '대퇴사두근,둔근,햄스트링', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 오른발을 앞으로 내딛고 런지로 내려간다.,Step:3 런지 자세에서 몸통을 오른쪽으로 비틀어 왼팔꿈치를 오른무릎 쪽으로 가져간다.,Step:4 잠깐 멈춘다.,Step:5 시작 자세로 돌아온다.,Step:6 왼발로 앞으로 내딛고 반대 방향으로 비틀어 반복한다.,Step:7 좌우를 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZEkjZDi', '케틀벨 시티드 투 암 밀리터리 프레스', 'https://static.exercisedb.dev/media/ZEkjZDi.gif', '삼각근', '어깨', '케틀벨', '삼두근,등 위쪽', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 케틀벨을 양손에 들어 어깨 높이에서 손바닥이 정면을 향하게 한다.,Step:3 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 위에서 잠깐 멈춘다.,Step:5 케틀벨을 천천히 내려 어깨 높이로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mWppALS', '사타구니 위기', 'https://static.exercisedb.dev/media/mWppALS.gif', '복근', '허리', '맨몸', '고관절 굴근,허벅지 안쪽', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 벌린다.,Step:3 복근에 힘을 주며 다리를 들어 무릎을 가슴 쪽으로 끌어당긴다.,Step:4 위에서 잠깐 멈춘다.,Step:5 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('r29jP7S', '덤벨 시트 카프 레이즈', 'https://static.exercisedb.dev/media/r29jP7S.gif', '종아리근', '종아리', '덤벨', '햄스트링', 'Step:1 벤치나 의자에 앉아 발바닥을 바닥에 두고 덤벨을 허벅지 위에 올린다.,Step:2 계단/블록 위에 발볼을 올리고 뒤꿈치는 밖으로 빼 둔다.,Step:3 자세를 안정적으로 유지한다.,Step:4 뒤꿈치를 최대한 들어 올려 종아리를 수축한다.,Step:5 위에서 잠깐 멈춘다.,Step:6 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('peAeMR3', '밴드 숄더 프레스', 'https://static.exercisedb.dev/media/peAeMR3.gif', '삼각근', '어깨', '밴드', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 밴드를 발 아래에 둔다.,Step:2 손바닥이 앞을 향하게 밴드를 잡고 손을 어깨 높이로 올리며 팔꿈치를 굽힌다.,Step:3 밴드를 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 위에서 잠깐 멈춘다.,Step:5 밴드를 천천히 내려 어깨 높이로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hfmQ0Tz', '스미스 스탠딩 백 리스트 컬', 'https://static.exercisedb.dev/media/hfmQ0Tz.gif', '전완근', '팔 아래', '스미스 머신', '이두근,삼두근', 'Step:1 발을 어깨너비로 벌리고 스미스 머신을 마주보고 선다.,Step:2 바를 오버핸드 그립으로 어깨너비로 잡는다.,Step:3 등을 곧게 하고 팔꿈치를 몸에 붙인다.,Step:4 손목을 굽혀 바를 몸 쪽으로 끌어올리듯 말아 올린다.,Step:5 위에서 잠깐 멈춘다.,Step:6 손목을 풀어 바를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y9hNPcN', '시티드 사이드 크런치(벽)', 'https://static.exercisedb.dev/media/Y9hNPcN.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 벽에 등을 대고 바닥에 앉아 다리를 앞으로 뻗는다.,Step:2 무릎을 굽혀 발을 바닥에 두고 엉덩이너비로 벌린다.,Step:3 손을 머리 뒤에 두고 팔꿈치를 바깥으로 벌린다.,Step:4 복근에 힘을 주고 옆으로 몸을 기울여 팔꿈치를 엉덩이 쪽으로 가져간다.,Step:5 잠깐 멈춘다.,Step:6 시작 자세로 돌아온다.,Step:7 반대쪽도 같은 방식으로 반복한다.,Step:8 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MgKwAAo', '케이블 로프 연장 경사 벤치 행', 'https://static.exercisedb.dev/media/MgKwAAo.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 인클라인 벤치를 45도로 세팅하고 케이블 머신을 하단 풀리에 맞춘다.,Step:2 케이블에 로프 손잡이를 연결한다.,Step:3 인클라인 벤치에 앉아 머신을 향해 자세를 잡는다.,Step:4 오버핸드 그립으로 로프를 잡고 등을 곧게 유지하며 팔을 완전히 편다.,Step:5 로프를 윗가슴 쪽으로 당기며 팔꿈치를 몸쪽으로 붙인다.,Step:6 끝 지점에서 견갑골을 모아 수축한다.,Step:7 장력을 유지하며 로프를 천천히 놓아 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LEprlgG', '케이블 랫 풀다운 전체 동작 범위', 'https://static.exercisedb.dev/media/LEprlgG.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 랫 풀다운 머신에 앉아 무릎을 패드 아래에 넣는다.,Step:2 바를 오버핸드 그립으로 어깨보다 약간 넓게 잡는다.,Step:3 상체를 약간 뒤로 기대고 가슴을 들어 올리며 허리에 자연스러운 아치를 만든다.,Step:4 바를 윗가슴 쪽으로 당기며 견갑골을 모은다.,Step:5 아래에서 잠깐 멈춘다.,Step:6 바를 천천히 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VaP75jl', '바벨 리어 런지', 'https://static.exercisedb.dev/media/VaP75jl.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 바벨을 상부 등(승모)에 올리고 발을 어깨너비로 벌리고 선다.,Step:2 오른발을 뒤로 내딛어 발볼로 착지한다.,Step:3 양쪽 무릎을 굽혀 내려가 왼쪽 허벅지가 바닥과 평행해질 때까지 하강한다.,Step:4 왼쪽 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('P2lNrGL', '케이블 프리처 컬', 'https://static.exercisedb.dev/media/P2lNrGL.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 프리처 패드가 가슴 높이에 오도록 케이블 머신을 조절한다.,Step:2 프리처 벤치에 앉아 상완을 패드에 올리고 케이블 손잡이를 언더핸드 그립으로 잡는다.,Step:3 등을 곧게 하고 팔꿈치를 몸쪽으로 모은다.,Step:4 손잡이를 어깨 쪽으로 천천히 말아 올리며 위에서 이두근을 수축한다.,Step:5 잠깐 멈춘다.,Step:6 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IeDEXTe', '레그 프레스 머신에 레버를 장착한 스쿼트 종아리 들어올리기', 'https://static.exercisedb.dev/media/IeDEXTe.gif', '종아리근', '종아리', '레버리지 머신', '대퇴사두근,햄스트링,둔근', 'Step:1 레그 프레스 좌석을 조절해 발을 발판에 뒀을 때 무릎이 약간 굽혀지게 한다.,Step:2 등을 등받이에 대고 앉아 발을 어깨너비로 발판에 둔다.,Step:3 발끝과 발볼만 발판에 두고 뒤꿈치는 가장자리 밖으로 빼 둔다.,Step:4 안전 손잡이를 해제하고 무릎을 펴 발판을 밀어낸다.,Step:5 무릎이 펴진 상태에서 종아리를 늘리며 뒤꿈치를 천천히 내린다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 종아리로 밀어 발판을 다시 위로 올린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mgejmGP', '죄수 반 윗몸일으키기(남)', 'https://static.exercisedb.dev/media/mgejmGP.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 벌린다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 정도가 되게 말아 올린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 상체를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SKXQAx3', '롤러 리버스 크런치', 'https://static.exercisedb.dev/media/SKXQAx3.gif', '복근', '허리', '롤러', '고관절 굴근', 'Step:1 등을 대고 누워 팔을 머리 위로 곧게 뻗고 다리도 앞으로 곧게 뻗는다.,Step:2 롤러를 발 사이에 끼우고 발끝으로 고정한다.,Step:3 복근에 힘을 주고 다리를 들어 무릎을 가슴 쪽으로 말아 올리며 롤러를 몸 쪽으로 굴린다.,Step:4 위에서 잠깐 멈춘다.,Step:5 다리를 천천히 내려 롤러를 멀리 굴리며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ia7tumC', '덤벨 앉아서 한쪽 다리 종아리 들어올리기', 'https://static.exercisedb.dev/media/Ia7tumC.gif', '종아리근', '종아리', '덤벨', '햄스트링,둔근', 'Step:1 벤치나 의자에 앉아 오른쪽 허벅지 위에 덤벨을 올리고 발을 바닥에 둔다.,Step:2 왼쪽 다리는 앞으로 곧게 뻗고 발끝을 몸 쪽으로 당긴다.,Step:3 오른발 발볼을 높은 곳(스텝/원판)에 올린다.,Step:4 종아리로 뒤꿈치를 최대한 들어 올린다.,Step:5 위에서 잠깐 멈춘다.,Step:6 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GibBPPg', '둔근 레그 포워드 익스텐션', 'https://static.exercisedb.dev/media/GibBPPg.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 둔근에 힘을 주어 엉덩이를 들어 올려 무릎부터 어깨까지 일직선이 되게 한다.,Step:3 엉덩이를 든 상태를 유지하며 한쪽 발을 들어 무릎을 가슴 쪽으로 당긴다.,Step:4 발을 다시 바닥에 두고 반대쪽 다리도 같은 동작을 한다.,Step:5 브릿지 자세를 유지한 채 좌우를 번갈아 행진하듯 반복한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zhF9lW4', '밴드 보조 휠 롤러아웃', 'https://static.exercisedb.dev/media/zhF9lW4.gif', '복근', '허리', '밴드', '허리', 'Step:1 바닥에 무릎을 꿇고 밴드 손잡이를 양손으로 잡되 손바닥이 아래를 향하게 한다.,Step:2 밴드를 몸 앞 바닥에 놓고 손을 어깨너비로 위치시킨다.,Step:3 코어에 힘을 주고 컨트롤을 유지한 채 휠을 천천히 앞으로 굴려 몸을 가능한 한 멀리 뻗는다.,Step:4 가장 멀리 뻗은 지점에서 잠깐 멈춘 뒤, 천천히 휠을 무릎 쪽으로 굴려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bmwlYvD', '고릴라 턱', 'https://static.exercisedb.dev/media/bmwlYvD.gif', '복근', '허리', '맨몸', '전완근,이두근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 약간 굽힌다.,Step:2 풀업 바를 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 뻗어 바에 매달리고 손바닥이 앞쪽을 향하게 한다.,Step:4 코어에 힘을 주고 몸을 끌어올려 턱이 바 위로 올라가게 한다.,Step:5 맨 위에서 잠깐 멈춘 뒤, 천천히 내려와 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gi2BXfK', '삼두근 반동을 번갈아 가며 서있는 덤벨', 'https://static.exercisedb.dev/media/Gi2BXfK.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 덤벨을 양손에 든다.,Step:2 무릎을 약간 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 편다.,Step:3 팔을 뒤로 곧게 펴서 들어 올리며 팔꿈치를 몸에 가깝게 유지한다.,Step:4 맨 위에서 잠깐 멈춘 뒤, 덤벨을 천천히 시작 위치로 내린다.,Step:5 반대쪽 팔로 반복하며 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QChZi3x', '머리 위로 손을 뻗을 때까지 스쿼트', 'https://static.exercisedb.dev/media/QChZi3x.gif', '대퇴사두근', '허벅지', '맨몸', '둔근,햄스트링,코어', 'Step:1 발을 어깨너비로 벌리고 서서 발끝을 약간 바깥으로 둔다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트 자세로 내려간다.,Step:3 스쿼트에서 올라오면서 팔을 머리 위로 뻗어 천장을 향해 뻗는다.,Step:4 팔을 내리며 다시 무릎을 굽혀 스쿼트로 내려가 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CmEr4pM', '케이블 와이드 그립 리어 풀다운 비하인드 넥', 'https://static.exercisedb.dev/media/CmEr4pM.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 케이블 머신에서 풀다운 바가 머리 위 높이에 오도록 조절한다.,Step:2 좌석에 앉아 바를 와이드 오버핸드 그립으로 잡는다.,Step:3 등을 곧게 펴고 가슴을 들면서 상체를 약간 뒤로 기울인다.,Step:4 바를 위쪽 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 바닥 지점에서 잠깐 멈춘 뒤, 천천히 바를 위로 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iK59oEA', '짐 볼에 아령 거짓말 풀오버', 'https://static.exercisedb.dev/media/iK59oEA.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨,등', 'Step:1 짐볼에 앉아 앞으로 굴려 상부 등이 볼 위에 놓이게 한다.,Step:2 덤벨을 양손으로 잡고 팔을 가슴 위로 곧게 뻗는다.,Step:3 팔을 곧게 유지한 채 덤벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 덤벨을 시작 위치로 들어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('B1EVP9F', '인클라인 푸쉬업', 'https://static.exercisedb.dev/media/B1EVP9F.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 벤치나 스텝 같은 높은 지지대에 손을 올려 어깨너비보다 약간 넓게 짚는다.,Step:2 다리를 뒤로 뻗고 발끝으로 지지하여 머리부터 발뒤꿈치까지 일직선이 되게 한다.,Step:3 팔꿈치를 굽혀 가슴을 지지대 쪽으로 내리되 몸을 일직선으로 유지한다.,Step:4 바닥 지점에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 올라온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ser9eQp', '레버 삼두근 익스텐션', 'https://static.exercisedb.dev/media/Ser9eQp.gif', '삼두근', '상완이두근', '레버리지 머신', '어깨', 'Step:1 좌석 높이를 조절하고 등받이에 등을 대고 머신에 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔을 앞쪽으로 완전히 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 손잡이를 이마 쪽으로 천천히 내린다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 팔을 펴며 손잡이를 시작 위치로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('r7cT9YD', '보조 모션 러시안 트위스트', 'https://static.exercisedb.dev/media/r7cT9YD.gif', '복근', '허리', '메디신볼', '복사근,허리', 'Step:1 무릎을 굽히고 발바닥을 바닥에 둔 채 앉는다.,Step:2 메디신볼을 양손으로 잡고 가슴 앞에 둔다.,Step:3 등을 곧게 유지하며 상체를 약간 뒤로 기울이고 복근에 힘을 준다.,Step:4 몸통을 오른쪽으로 천천히 비틀어 공을 몸 오른쪽으로 이동시킨다.,Step:5 잠깐 멈춘 뒤 몸통을 왼쪽으로 비틀어 공을 몸 왼쪽으로 이동시킨다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MU9HnE7', '가중 벤치 딥', 'https://static.exercisedb.dev/media/MU9HnE7.gif', '삼두근', '상완이두근', '가중', '가슴,어깨', 'Step:1 벤치에 앉아 손으로 가장자리를 잡되 손가락이 앞을 향하게 한다.,Step:2 엉덩이를 벤치에서 앞으로 빼고 팔로 체중을 지지한다.,Step:3 팔꿈치를 굽혀 상완이 바닥과 평행해질 때까지 몸을 내린다.,Step:4 팔을 펴서 몸을 다시 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zFzbBfL', '밴드 푸쉬 윗몸일으키기', 'https://static.exercisedb.dev/media/zFzbBfL.gif', '복근', '허리', '밴드', '어깨,가슴', 'Step:1 밴드를 단단한 고정 지점에 안전하게 고정한다.,Step:2 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:3 밴드를 양손으로 잡고 팔을 천장을 향해 곧게 뻗는다.,Step:4 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 될 때까지 말아 올린다.,Step:5 위에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ziFKQXP', '짐 볼에 덤벨 원 암 프렌치 프레스', 'https://static.exercisedb.dev/media/ziFKQXP.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 짐볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손에 덤벨을 들고 손바닥이 위를 향하게 한 채 팔꿈치를 90도로 굽힌다.,Step:3 팔꿈치를 고정한 채 팔을 천장을 향해 곧게 편다.,Step:4 덤벨을 천천히 내려 시작 위치로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('S1JXDAG', '밴드 시트 트위스트', 'https://static.exercisedb.dev/media/S1JXDAG.gif', '복근', '허리', '밴드', '복사근', 'Step:1 다리를 앞으로 뻗고 등을 곧게 편 채 바닥에 앉는다.,Step:2 밴드를 허리에 감고 양손으로 끝을 잡는다.,Step:3 복근에 힘을 주고 등을 곧게 유지하며 몸통을 한쪽으로 천천히 비튼다.,Step:4 비틀어진 끝 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 비튼다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9IxJdtC', '누워서 다리 힙 올리기', 'https://static.exercisedb.dev/media/9IxJdtC.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 바닥에 대고 누워 다리를 곧게 뻗고 팔은 몸 옆에 둔다.,Step:2 손을 엉덩이 아래에 넣어 지지한다.,Step:3 코어에 힘을 주고 다리를 들어 올려 천장을 향하게 한다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4KJEpzb', '케틀벨은 행 포지션에서 깨끗하게 바닥을 위로 올라간다', 'https://static.exercisedb.dev/media/4KJEpzb.gif', '이두근', '상완이두근', '케틀벨', '전완근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 케틀벨을 오버핸드 그립으로 잡는다.,Step:2 무릎을 약간 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 편다.,Step:3 팔을 완전히 편 채 케틀벨이 다리 사이로 자연스럽게 내려오게 한다.,Step:4 한 번의 부드러운 동작으로 엉덩이와 무릎을 폭발적으로 펴면서 케틀벨을 어깨 쪽으로 끌어올린다.,Step:5 케틀벨이 어깨 높이에 도달하면 손목을 회전시켜 케틀벨의 바닥이 위를 향하게 한다.,Step:6 팔꿈치를 굽힌 채 어깨 높이에서 케틀벨을 받아 손바닥이 위를 향하게 한다.,Step:7 동작을 역으로 따라 케틀벨을 시작 자세로 다시 내린다.,Step:8 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZgwWBoC', '케이블 티보도 카약 로우', 'https://static.exercisedb.dev/media/ZgwWBoC.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 낮은 풀리에 케이블 손잡이를 연결하고 머신을 향해 앉아 발을 바닥에 둔다.,Step:2 오른손으로 손잡이를 잡고 팔을 거의 완전히 펴되 팔꿈치는 약간 굽힌다.,Step:3 엉덩이에서 접어 상체를 앞으로 기울이되 등을 곧게 펴고 복부에 힘을 준다.,Step:4 견갑골을 뒤로 당기며 팔꿈치를 굽혀 손잡이를 몸통 쪽으로 당기되 팔은 몸에 가깝게 유지한다.,Step:5 위에서 등 근육을 조이며 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 왼쪽 팔로 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0rHfvy9', '인버스 레그 컬(풀업 케이블 머신)', 'https://static.exercisedb.dev/media/0rHfvy9.gif', '햄스트링', '허벅지', '맨몸', '둔근,종아리근', 'Step:1 케이블 머신의 발목 스트랩을 가장 낮은 위치로 조절한다.,Step:2 벤치에 엎드려 다리를 곧게 뻗고 발목 스트랩을 발에 착용한다.,Step:3 벤치 손잡이를 잡아 몸을 고정한다.,Step:4 무릎을 굽혀 발을 엉덩이 쪽으로 말아 올리며 햄스트링을 수축한다.,Step:5 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('641mIfk', '바벨 인클라인 리버스 그립 프레스', 'https://static.exercisedb.dev/media/641mIfk.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 누워 바벨을 리버스 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 바벨을 랙에서 꺼내 가슴 윗부분 쪽으로 천천히 내리되 팔꿈치를 몸 쪽으로 모은다.,Step:4 아래 지점에서 잠깐 멈춘 뒤 바벨을 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yaAxcQr', '밧줄 오르기', 'https://static.exercisedb.dev/media/yaAxcQr.gif', '등 위쪽', '등', '로프', '전완근,이두근,어깨', 'Step:1 로프를 마주보고 발을 어깨너비로 벌리고 선다.,Step:2 양손으로 로프를 잡되 손바닥이 몸 쪽을 향하게 한다.,Step:3 무릎을 약간 굽히고 코어에 힘을 준다.,Step:4 손을 번갈아 위로 옮겨 잡으며 로프를 타고 올라간다.,Step:5 다리로도 보조해 위로 올라가는 동작을 돕는다.,Step:6 원하는 높이 또는 로프 꼭대기에 도달할 때까지 계속 오른다.,Step:7 내려올 때는 손을 번갈아 내리며 하강을 컨트롤한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aDoFKrE', '메디신볼 체스트 패스', 'https://static.exercisedb.dev/media/aDoFKrE.gif', '가슴근육', '가슴', '메디신볼', '어깨,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서 메디신볼을 가슴 높이에서 든다.,Step:2 팔을 앞으로 뻗으며 가슴에서 강하게 밀어 메디신볼을 던진다.,Step:3 공을 놓는 순간 팔과 몸통을 따라가며 뒷발에서 앞발로 체중을 이동한다.,Step:4 공이 벽이나 파트너에게서 튀어 돌아오면 받아서 바로 다음 반복을 수행한다.,Step:5 원하는 반복 횟수만큼 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xi0yckC', '바벨 인클라인 숄더 레이즈', 'https://static.exercisedb.dev/media/xi0yckC.gif', '전거근', '가슴', '바벨', '삼각근,승모근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 앉아 등을 패드에 기대고 발을 바닥에 둔다.,Step:3 오버핸드 그립으로 바벨을 잡되 어깨너비보다 약간 넓게 잡는다.,Step:4 팔꿈치를 약간 굽힌 채 바벨을 어깨 높이까지 들어 올린다.,Step:5 바벨을 머리 위로 천천히 밀어 올려 팔을 완전히 편다.,Step:6 위에서 잠깐 멈춘 뒤 바벨을 천천히 어깨 높이로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('P2nRiUa', '덤벨 서 있는 zottman 설교자 컬', 'https://static.exercisedb.dev/media/P2nRiUa.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 덤벨을 양손에 들고 똑바로 서서 손바닥이 앞을 향하게 한다.,Step:2 상완을 프리처 벤치 패드에 고정하고 팔꿈치를 약간 굽힌다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 손목을 회전해 손바닥이 아래를 향하게 한다.,Step:5 덤벨을 천천히 내리며 손목도 다시 시작 방향으로 회전시킨다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('O8Aq69u', '덤벨 리버스 프리처컬 컬', 'https://static.exercisedb.dev/media/O8Aq69u.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 벤치에 앉아 상완을 패드에 올리고 가슴을 지지대에 댄다.,Step:2 덤벨을 양손에 들고 언더핸드 그립으로 잡아 손바닥이 위를 향하게 한다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:5 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9RT8oQW', '바닥에 벤치 딥', 'https://static.exercisedb.dev/media/9RT8oQW.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 의자 가장자리에 앉아 손으로 가장자리를 잡되 손가락이 앞을 향하게 한다.,Step:2 엉덩이를 앞으로 빼고 팔로 체중을 지지한다.,Step:3 팔꿈치를 굽혀 상완이 바닥과 평행해질 때까지 몸을 내린다.,Step:4 팔을 펴서 몸을 다시 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1GPHRyK', '잔다 윗몸일으키기', 'https://static.exercisedb.dev/media/1GPHRyK.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 될 때까지 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RGLscZM', '스미스 로우바 스쿼트', 'https://static.exercisedb.dev/media/RGLscZM.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 스미스 머신 바가 상부 등에 올리기 편한 높이가 되도록 세팅한다.,Step:2 발을 어깨너비로 벌리고 서서 발끝은 약간 바깥을 향하게 한다.,Step:3 바 아래로 들어가 바를 승모근 위쪽에 올려 위치시킨다.,Step:4 손을 어깨너비보다 약간 넓게 벌려 바를 잡는다.,Step:5 다리를 펴서 바를 랙에서 빼고 랙에서 한 걸음 물러난다.,Step:6 숨을 깊게 들이마시고 코어를 단단히 고정한다.,Step:7 엉덩이를 뒤로 보내며 무릎을 굽혀 스쿼트를 시작한다.,Step:8 허벅지가 바닥과 평행해지거나 가능한 만큼 더 내려간다.,Step:9 동작 내내 가슴을 들고 등을 곧게 유지한다.,Step:10 뒤꿈치로 밀어 일어나며 엉덩이와 무릎을 펴서 선다.,Step:11 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7inpWch', '덤벨 스탠딩 컨센트레이션 컬', 'https://static.exercisedb.dev/media/7inpWch.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 들어 팔을 완전히 편 채 손바닥이 몸 쪽을 향하게 한다.,Step:2 반대쪽 손은 허벅지에 올려 지지한다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:5 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0IgNjSM', '덤벨 스탠딩 리버스 컬', 'https://static.exercisedb.dev/media/0IgNjSM.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 양손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:3 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:4 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5vfAI0I', '덤벨 스캇 프레스', 'https://static.exercisedb.dev/media/5vfAI0I.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 벤치에 앉아 양손에 덤벨을 들고 손바닥이 앞을 향하게 한다.,Step:2 덤벨을 어깨 높이까지 들어 올려 팔꿈치를 굽히고 손바닥이 앞을 보게 한다.,Step:3 팔을 완전히 펼 때까지 덤벨을 위로 밀어 올린다.,Step:4 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 위치로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nAuHPcD', '덤벨 한쪽 팔 삼두근 익스텐션 (벤치에서)', 'https://static.exercisedb.dev/media/nAuHPcD.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 한 손에 덤벨을 들고 다른 손은 벤치에 짚어 지지한다.,Step:3 덤벨을 머리 위로 들어 올리되 상완을 머리 가까이에 두고 팔꿈치를 앞쪽으로 향하게 한다.,Step:4 팔꿈치를 굽혀 덤벨을 머리 뒤로 내리되 상완은 고정한다.,Step:5 팔꿈치를 펴서 덤벨을 시작 위치로 다시 올린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('znP9SIh', '가슴에 포옹', 'https://static.exercisedb.dev/media/znP9SIh.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽혀 스쿼트 자세로 몸을 낮춘다.,Step:3 내려가면서 무릎을 가슴 쪽으로 끌어올려 팔로 감싸 안는다.,Step:4 잠깐 유지한 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8oYqOt9', '케이블 시트 컬', 'https://static.exercisedb.dev/media/8oYqOt9.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 케이블 손잡이를 언더핸드 그립으로 잡아 손바닥이 위를 향하게 하고 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 손잡이를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:5 숨을 들이마시며 손잡이를 천천히 내려 팔을 완전히 펴서 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BwSNDGt', '덤벨 원암 리버스 리스트 컬', 'https://static.exercisedb.dev/media/BwSNDGt.gif', '전완근', '팔 아래', '덤벨', '손목 신근', 'Step:1 벤치나 의자에 앉아 발을 바닥에 둔다.,Step:2 한 손에 덤벨을 오버핸드 그립으로 잡아 손바닥이 아래를 향하게 한다.,Step:3 전완을 허벅지 위에 올리고 손목이 끝에서 밖으로 나오게 둔다.,Step:4 손목을 굽혀 덤벨을 바닥 쪽으로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘 뒤 손목을 말아 올려 덤벨을 몸 쪽으로 천천히 올린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PzNxakt', '벽에 손을 대고 종아리 스트레칭', 'https://static.exercisedb.dev/media/PzNxakt.gif', '종아리근', '종아리', '맨몸', '햄스트링', 'Step:1 벽을 마주보고 발을 엉덩이너비로 벌려 선다.,Step:2 손을 어깨 높이에 두고 벽에 댄다.,Step:3 한쪽 발을 뒤로 내딛고 뒤꿈치를 바닥에 둔 채 다리를 곧게 유지한다.,Step:4 앞쪽 무릎을 살짝 굽히고 상체를 앞으로 기울여 종아리가 늘어나는 것을 느낀다.,Step:5 20–30초 동안 유지한다.,Step:6 다리를 바꿔 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vUTfFHw', '밴드 손목 컬', 'https://static.exercisedb.dev/media/vUTfFHw.gif', '전완근', '팔 아래', '밴드', '이두근,삼두근', 'Step:1 벤치나 의자에 앉아 발을 바닥에 둔다.,Step:2 밴드를 양손으로 잡고 손바닥이 위를 향하게 한 뒤 전완을 허벅지 위에 올린다.,Step:3 손목을 위로 말아 올리며 전완에 힘을 준다.,Step:4 위에서 잠깐 멈춘 뒤 손목을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BbfB8Gb', '기본 발가락 터치(남성)', 'https://static.exercisedb.dev/media/BbfB8Gb.gif', '둔근', '허벅지', '맨몸', '햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 팔은 몸 옆에 둔다.,Step:2 등을 곧게 편 채 허리에서 상체를 앞으로 숙이고 무릎을 약간 굽힌다.,Step:3 가능한 한 다리를 곧게 유지하며 손으로 발가락 쪽으로 내려간다.,Step:4 아래에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TFqbd8t', '아삭아삭 바닥', 'https://static.exercisedb.dev/media/TFqbd8t.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주고 어깨를 바닥에서 들어 올려 무릎 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zGSIWQi', '덤벨 거짓말 원 암 프레스', 'https://static.exercisedb.dev/media/zGSIWQi.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 벤치에 눕고 한 손에 덤벨을 든 채 발을 바닥에 둔다.,Step:2 덤벨을 어깨 높이에서 잡되 손바닥이 앞을 향하게 한다.,Step:3 팔을 완전히 펼 때까지 덤벨을 위로 밀어 올린다.,Step:4 위에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YqJw82s', '바벨 리버스 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/YqJw82s.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 벤치에 눕고 발을 바닥에 두며 등을 벤치에 밀착한다.,Step:2 바벨을 리버스 그립으로 어깨너비로 잡는다.,Step:3 바벨을 랙에서 들어 가슴 위에서 팔을 완전히 편 채 유지한다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 바벨을 가슴 쪽으로 천천히 내린다.,Step:5 바벨이 가슴 바로 위에 왔을 때 잠깐 멈춘다.,Step:6 바벨을 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('M74kdvm', '케틀벨 더블 스내치', 'https://static.exercisedb.dev/media/M74kdvm.gif', '삼각근', '어깨', '케틀벨', '승모근,전완근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 케틀벨을 허벅지 앞쪽에서 팔을 편 채 잡는다.,Step:2 무릎을 약간 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 평평하게 유지하고 가슴을 든다.,Step:3 엉덩이, 무릎, 발목을 폭발적으로 펴면서 동시에 케틀벨을 어깨 쪽으로 끌어올린다.,Step:4 케틀벨이 어깨 높이에 오르면 손목을 회전시키고 케틀벨을 머리 위로 펀치하듯 올려 팔을 완전히 편다.,Step:5 케틀벨을 시작 위치로 다시 내리고 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HsvHqgf', '덤벨 스쿼트', 'https://static.exercisedb.dev/media/HsvHqgf.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들어 몸 옆에 둔다.,Step:2 가슴을 들고 코어에 힘을 준 채 무릎과 엉덩이를 굽혀 의자에 앉듯이 내려간다.,Step:3 허벅지가 바닥과 평행해질 때까지, 또는 가능한 만큼 편하게 내려간다.,Step:4 아래에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ByX0WxV', '덤벨 인클라인 해머 컬', 'https://static.exercisedb.dev/media/ByX0WxV.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 인클라인 벤치에 앉아 양손에 덤벨을 들고 손바닥이 몸을 향하게 한 채 팔을 완전히 편다.,Step:2 등을 벤치에 붙이고 발을 바닥에 둔다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:5 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VtTbiP3', '밴드 풀 스루', 'https://static.exercisedb.dev/media/VtTbiP3.gif', '둔근', '허벅지', '밴드', '햄스트링,허리', 'Step:1 밴드를 바닥 높이의 단단한 고정 지점에 연결한다.,Step:2 고정 지점을 등지고 서서 발을 어깨너비로 벌린다.,Step:3 밴드에 장력이 생기도록 앞으로 한 걸음 나가고 무릎은 약간 굽힌다.,Step:4 엉덩이를 뒤로 보내며 힙힌지를 만들어 상체를 숙이되 무릎의 약간 굽힘은 유지한다.,Step:5 상체가 바닥과 거의 평행해질 때까지 내려가 햄스트링 스트레치를 느낀다.,Step:6 엉덩이를 앞으로 밀고 둔근을 조여 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3d7wHyd', '덤벨 벤치 시티드 프레스', 'https://static.exercisedb.dev/media/3d7wHyd.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 벤치에 앉아 양손에 덤벨을 들고 허벅지 위에 올려둔다.,Step:2 등을 기대며 허벅지를 이용해 덤벨을 하나씩 들어 올려 가슴 옆으로 위치시킨다. 손바닥은 앞을 향하게 한다.,Step:3 덤벨을 위로 밀어 올려 팔을 완전히 편다.,Step:4 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 위치로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yB9SvIF', '스미스 머신 디클라인 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/yB9SvIF.gif', '삼두근', '상완이두근', '스미스 머신', '가슴,어깨', 'Step:1 스미스 머신에서 벤치를 디클라인으로 조절한다.,Step:2 벤치에 누워 발을 바닥에 단단히 고정한다.,Step:3 바벨을 클로즈 그립으로 잡되 어깨너비보다 약간 좁게 잡는다.,Step:4 바벨을 빼서 가슴 쪽으로 천천히 내리되 팔꿈치를 몸에 가깝게 유지한다.,Step:5 바벨이 가슴 바로 위에 왔을 때 잠깐 멈춘다.,Step:6 바벨을 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ThKP69G', '케이블 리버스 그립 삼두근 푸시다운(sz-bar)(암 블래스터 포함)', 'https://static.exercisedb.dev/media/ThKP69G.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 가장 높은 위치로 설정하고 스트레이트 바를 연결한다.,Step:2 발을 어깨너비로 벌리고 케이블 머신을 마주보고 선다.,Step:3 언더핸드 그립으로 바를 잡아 손바닥이 위를 향하게 하고 손은 어깨너비로 둔다.,Step:4 팔꿈치를 몸 옆에 붙이고 상완이 움직이지 않게 유지한다.,Step:5 삼두근에 힘을 주며 바를 아래로 천천히 밀어 팔을 완전히 편다.,Step:6 아래에서 잠깐 멈춘 뒤 바를 천천히 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4OaumBr', '정지된 행', 'https://static.exercisedb.dev/media/4OaumBr.gif', '등 위쪽', '등', '맨몸', '이두근,어깨', 'Step:1 서스펜션 트레이너를 적절한 높이로 설치한다.,Step:2 고정 지점을 향해 서서 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 손잡이를 잡되 손바닥이 서로 마주보게 한다.,Step:4 몸을 곧게 펴고 뒤로 기대며 뒤꿈치는 바닥에 둔다.,Step:5 가슴을 손잡이 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 위에서 잠깐 멈춘 뒤 천천히 내려와 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y4QlY8z', '스미스 토 레이즈', 'https://static.exercisedb.dev/media/Y4QlY8z.gif', '종아리근', '종아리', '스미스 머신', '발목,정강이', 'Step:1 스미스 머신 바를 발을 바닥에 둔 채 편하게 설 수 있는 높이로 조절한다.,Step:2 바 아래로 들어가 어깨가 바 바로 아래에 오게 하고 발을 어깨너비로 둔다.,Step:3 발볼을 받침대나 원판 위에 올리고 뒤꿈치는 가장자리 밖으로 나오게 한다.,Step:4 오버핸드 그립으로 바를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:5 코어에 힘을 주고 등을 곧게 유지한다.,Step:6 뒤꿈치를 가능한 한 높이 들어 올려 발볼로 체중을 싣는다.,Step:7 위에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QLL2gdc', '윗몸일으키기를 거절하다', 'https://static.exercisedb.dev/media/QLL2gdc.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 디클라인 벤치에 누워 발을 고정하고 무릎을 굽힌다.,Step:2 손을 머리 뒤에 두거나 가슴 앞에 교차해 둔다.,Step:3 복근에 힘을 주고 상체를 들어 올려 무릎 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PkCN2lv', '앞 레버', 'https://static.exercisedb.dev/media/PkCN2lv.gif', '복근', '허리', '맨몸', '광배근,어깨,전완근', 'Step:1 오버핸드 그립으로 풀업 바를 어깨너비로 잡고 매달린다.,Step:2 코어에 힘을 주고 견갑골을 아래로 당겨 뒤로 모은다.,Step:3 무릎을 굽혀 가슴 쪽으로 당긴다.,Step:4 동시에 다리를 앞으로 들어 올려 곧게 뻗어 몸이 바닥과 평행하게 되도록 한다.,Step:5 가능한 만큼 유지하며 완전한 프런트 레버 자세를 목표로 한다.,Step:6 풀 때는 다리를 천천히 내리고 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pvBMLHA', '푸시업 플러스', 'https://static.exercisedb.dev/media/pvBMLHA.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 하이 플랭크에서 손을 어깨너비보다 약간 넓게 짚고 머리부터 발뒤꿈치까지 일직선을 만든다.,Step:2 팔꿈치를 굽혀 몸을 내리되 팔꿈치를 몸 가까이 유지한다.,Step:3 가슴이 바닥 바로 위에 오면 손으로 밀어 팔을 펴 상체를 들어 올린다.,Step:4 정점에서 견갑골을 전인시켜 등을 천장 쪽으로 밀어낸다.,Step:5 잠깐 멈춘 뒤 견갑골을 다시 모으며 몸을 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0JtKWum', '덤벨 버피', 'https://static.exercisedb.dev/media/0JtKWum.gif', '심혈관계', '유산소', '덤벨', '대퇴사두근,햄스트링,종아리근,어깨,삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 스쿼트로 내려가 덤벨을 몸 앞 바닥에 놓는다.,Step:3 발을 뒤로 차서 푸시업 자세로 이동하며 몸을 일직선으로 유지한다.,Step:4 푸시업을 수행해 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내린다.,Step:5 발을 다시 손 쪽으로 점프해 스쿼트 자세로 착지한다.,Step:6 폭발적으로 일어서며 덤벨을 들어 올려 어깨 높이로 가져온다.,Step:7 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:8 덤벨을 다시 어깨로 내리고 전체 동작을 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6t00BsF', '케이블 한쪽 팔 인클라인 프레스 짐 볼', 'https://static.exercisedb.dev/media/6t00BsF.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 발을 바닥에 두고 짐볼에 앉아 등을 인클라인 벤치에 기대어 지지한다.,Step:2 한 손으로 케이블 손잡이를 잡고 팔꿈치를 굽혀 팔이 90도가 되게 위치시킨다.,Step:3 손잡이를 앞으로 위로 밀어 팔을 완전히 편다.,Step:4 위에서 잠깐 멈춘 뒤 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('j7XMAyn', '케이블 상부 가슴 크로스오버', 'https://static.exercisedb.dev/media/j7XMAyn.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 손잡이를 케이블에 가슴 높이로 연결한다.,Step:2 케이블 머신 중앙에 서서 한쪽 발을 약간 앞으로 둔다.,Step:3 손바닥이 아래를 향하게 손잡이를 잡고 팔을 옆으로 뻗는다.,Step:4 팔꿈치를 약간 굽힌 채 코어에 힘을 준다.,Step:5 케이블을 몸 앞에서 모으며 서로 교차시키듯 당긴다.,Step:6 정점에서 가슴 근육을 조여 수축을 느낀다.,Step:7 케이블을 천천히 풀어 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Pr9Rhf4', '케이블 스탠딩 플라이', 'https://static.exercisedb.dev/media/Pr9Rhf4.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 손잡이를 케이블에 가슴 높이로 연결한다.,Step:2 발을 어깨너비로 벌리고 케이블 머신을 등지고 선다.,Step:3 오버핸드 그립으로 손잡이를 잡아 손바닥이 앞을 향하게 한다.,Step:4 케이블에 장력이 생기도록 약간 앞으로 나간다.,Step:5 코어에 힘을 주고 등을 곧게 유지한다.,Step:6 팔꿈치를 약간 굽힌 채 팔을 앞으로 모아 가슴 앞에서 붙인다.,Step:7 정점에서 가슴 근육을 조여 수축을 느낀다.,Step:8 동작을 천천히 되돌려 팔을 시작 위치로 돌아온다.,Step:9 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UpAlold', '후방 디클라인 브릿지', 'https://static.exercisedb.dev/media/UpAlold.gif', '둔근', '허벅지', '맨몸', '햄스트링,허리', 'Step:1 등을 바닥에 대고 누워 발을 바닥에 두고 무릎을 굽힌다.,Step:2 팔은 몸 옆에 두고 손바닥이 아래를 향하게 한다.,Step:3 둔근과 햄스트링에 힘을 주고 엉덩이를 들어 무릎부터 어깨까지 일직선이 되게 한다.,Step:4 몇 초간 유지한 뒤 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('h8LFzo9', '바벨 펜들레이 로우', 'https://static.exercisedb.dev/media/r0z6xzQ.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 약간 굽힌다.,Step:2 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 펴고 가슴을 든다.,Step:3 오버핸드 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:4 바벨을 상복부 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 바벨을 다시 바닥 쪽으로 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5bpPTHv', '케틀벨 권총 스쿼트', 'https://static.exercisedb.dev/media/5bpPTHv.gif', '둔근', '허벅지', '케틀벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 케틀벨을 양손으로 가슴 앞에 든다.,Step:2 왼발을 들어 앞으로 뻗어 바닥과 평행하게 유지한다.,Step:3 오른발을 바닥에 둔 채 몸을 천천히 내려 권총 스쿼트 자세를 만든다.,Step:4 스쿼트 바닥 지점에서 잠깐 멈춘 뒤 오른쪽 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rTbyBYV', '짐 볼에 누워서 측면 스트레칭', 'https://static.exercisedb.dev/media/rTbyBYV.gif', '광배근', '등', '스태빌리티 볼', '어깨,삼두근', 'Step:1 옆으로 눕고 다리는 곧게 뻗은 상태에서 머리를 짐볼에 올려 지지한다.,Step:2 위쪽 팔을 볼 위에 두어 안정적으로 지지한다.,Step:3 위쪽 팔을 머리 위로 뻗으며 몸통을 약간 회전시킨다.,Step:4 몸 옆쪽의 광배근이 늘어나는 것을 느낀다.,Step:5 20–30초 동안 유지한 뒤 반대쪽도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Jsgsc27', '바벨 한쪽 팔을 구부린 채 로우', 'https://static.exercisedb.dev/media/Jsgsc27.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 약간 굽힌 채 한 손으로 바벨을 오버핸드 그립으로 잡는다.,Step:2 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 펴고 머리는 중립으로 둔다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 바벨을 가슴 쪽으로 당기고 견갑골을 조인다.,Step:4 바벨을 컨트롤하며 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fNGumX0', '앞뒤로 단계', 'https://static.exercisedb.dev/media/fNGumX0.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 오른발을 앞으로 내딛고 무릎을 굽혀 런지 자세로 내려간다.,Step:3 오른발로 밀어 시작 자세로 돌아온다.,Step:4 왼발로 같은 동작을 반복해 다리를 번갈아 수행한다.,Step:5 일정한 페이스로 앞뒤로 계속 스텝한다.,Step:6 원하는 시간 또는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('aVs3BR3', '케이블 트위스트', 'https://static.exercisedb.dev/media/aVs3BR3.gif', '복근', '허리', '케이블', '복사근', 'Step:1 발을 어깨너비로 벌리고 케이블 머신을 마주보고 선다.,Step:2 케이블 손잡이를 양손으로 가슴 앞에서 잡고 팔은 약간 굽힌다.,Step:3 코어에 힘을 주고 몸통을 오른쪽으로 비틀며 케이블을 몸 가로질러 당긴다.,Step:4 끝 지점에서 잠깐 멈추며 복근과 복사근의 수축을 느낀다.,Step:5 케이블의 당김에 저항하며 천천히 시작 자세로 돌아온다.,Step:6 왼쪽도 같은 방식으로 수행한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5VCj6iH', '바벨 해킹 스쿼트', 'https://static.exercisedb.dev/media/5VCj6iH.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝을 약간 바깥으로 둔다.,Step:2 바벨을 다리 뒤쪽에서 잡아 허벅지 위쪽 뒤에 위치시킨다.,Step:3 무릎과 엉덩이를 굽혀 몸을 내리되 등을 곧게 펴고 가슴을 든다.,Step:4 허벅지가 바닥과 평행해질 때까지, 또는 가능한 만큼 편하게 내려간다.,Step:5 아래에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2KGnL6M', '레버 원 암 숄더 프레스', 'https://static.exercisedb.dev/media/2KGnL6M.gif', '삼각근', '어깨', '레버리지 머신', '삼두근,등 위쪽', 'Step:1 좌석 높이를 조절하고 등받이에 등을 대고 머신에 앉는다.,Step:2 한 손으로 레버 손잡이를 잡고 팔꿈치를 90도로 위치시킨다.,Step:3 레버를 위로 밀어 팔을 머리 위로 완전히 편다.,Step:4 위에서 잠깐 멈춘 뒤 레버를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('a8VDgLw', '고정식 자전거 산책', 'https://static.exercisedb.dev/media/a8VDgLw.gif', '심혈관계', '유산소', '레버리지 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 고정식 자전거의 안장 높이와 자세를 올바르게 정렬되도록 조절한다.,Step:2 발을 페달에 올리고 가능하다면 스트랩으로 고정한다.,Step:3 등을 곧게 펴고 코어에 힘을 준 채 편한 속도로 페달을 밟기 시작한다.,Step:4 필요하면 저항을 올려 강도를 조절하며 일정한 리듬을 유지한다.,Step:5 원하는 시간 동안 유산소 운동을 지속한다.,Step:6 마무리로 속도와 저항을 서서히 낮춰 쿨다운한다.,Step:7 운동 후 다리 근육을 스트레칭해 뻣뻣함을 줄이고 회복을 돕는다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9gbyYKk', '밴드 장착 엉덩이 내부 회전', 'https://static.exercisedb.dev/media/9gbyYKk.gif', '둔근', '허벅지', '밴드', '햄스트링,대퇴사두근', 'Step:1 의자나 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 밴드를 허벅지에 감되 무릎 바로 위에 위치시킨다.,Step:3 무릎을 90도로 굽히고 발은 어깨너비로 둔다.,Step:4 둔근에 힘을 주며 무릎을 바깥쪽으로 천천히 벌려 밴드 저항을 밀어낸다.,Step:5 끝 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('67n3r98', '레버 숄더 프레스', 'https://static.exercisedb.dev/media/67n3r98.gif', '삼각근', '어깨', '레버리지 머신', '삼두근,가슴', 'Step:1 좌석 높이를 조절하고 등받이에 등을 대고 머신에 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡고 손을 어깨 높이에 위치시킨다.,Step:3 팔꿈치를 완전히 잠그지 않는 선에서 손잡이를 위로 밀어 팔을 편다.,Step:4 위에서 잠깐 멈춘 뒤 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bbLR7fB', '밴드 누워 똑바로 다리 올리기', 'https://static.exercisedb.dev/media/bbLR7fB.gif', '복근', '허리', '밴드', '고관절 굴근', 'Step:1 등을 바닥에 대고 누워 다리를 곧게 펴고 발을 모은다.,Step:2 밴드를 발바닥(아치)에 걸고 양손으로 밴드 끝을 잡는다.,Step:3 복근에 힘을 주고 양다리를 들어 올려 바닥과 수직이 될 때까지 올린다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mQ1tBXn', '직선 다리 외부 고관절 외전근', 'https://static.exercisedb.dev/media/mQ1tBXn.gif', '외전근', '허벅지', '맨몸', '둔근,햄스트링', 'Step:1 옆으로 누워 다리를 곧게 펴고 위아래로 겹치게 둔다.,Step:2 아래쪽 팔을 머리 아래에 두어 지지한다.,Step:3 코어에 힘을 주고 골반이 돌아가지 않게 하며 위쪽 다리를 가능한 한 높이 들어 올린다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OIFMAp1', '레버 한쪽 팔 사이드 높은 행', 'https://static.exercisedb.dev/media/OIFMAp1.gif', '등 위쪽', '등', '레버리지 머신', '이두근,어깨', 'Step:1 좌석 높이를 조절하고 머신을 향해 앉는다.,Step:2 한 손으로 손잡이를 잡고 등을 곧게 편다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 손잡이를 몸 쪽으로 당긴다.,Step:4 위에서 등 근육을 조이며 잠깐 멈춘다.,Step:5 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6bOA1Oi', '웨이트 사이드 벤드(스태빌리티 볼)', 'https://static.exercisedb.dev/media/6bOA1Oi.gif', '복근', '허리', '가중', '복사근,허리', 'Step:1 짐볼에 앉아 발을 어깨너비로 벌리고 바닥에 둔다.,Step:2 한 손에 웨이트를 들고 다른 손은 허리에 둔다.,Step:3 코어에 힘을 주고 등을 곧게 유지하며 웨이트 든 쪽으로 천천히 옆으로 기울인다.,Step:4 아래에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BqgCRif', '덤벨 쿠바 프레스 v. 2', 'https://static.exercisedb.dev/media/BqgCRif.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들어 어깨 높이에 두고 손바닥이 아래를 향하게 한다.,Step:2 코어에 힘을 주고 등을 곧게 편 상태를 유지한다.,Step:3 덤벨을 머리 위로 곧게 밀어 올려 팔을 완전히 편다.,Step:4 손목을 회전해 손바닥이 앞을 향하게 한다.,Step:5 덤벨을 어깨 높이로 천천히 내리며 손목도 다시 시작 방향으로 회전시킨다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MSfvriJ', '고양이의 가죽을 벗기다', 'https://static.exercisedb.dev/media/MSfvriJ.gif', '등 위쪽', '등', '맨몸', '어깨,코어', 'Step:1 바에 매달려 팔을 완전히 펴고 몸의 힘을 뺀다.,Step:2 코어에 힘을 주고 다리를 들어 무릎을 가슴 쪽으로 당긴다.,Step:3 다리를 더 들어 올려 머리 위로 넘기며 몸이 팔 사이로 통과하게 한다.,Step:4 다리가 머리 위로 완전히 뻗으면, 다리를 천천히 내려 다시 시작 자세로 돌아오기 시작한다.,Step:5 다리를 내리면서 몸이 다시 팔 사이로 통과해 팔을 완전히 편 채 매달린 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7M66AVi', '바벨 롤아웃', 'https://static.exercisedb.dev/media/7M66AVi.gif', '복근', '허리', '바벨', '허리', 'Step:1 바닥에 무릎을 꿇고 바벨을 어깨너비로 양손으로 잡는다.,Step:2 코어에 힘을 준 채 바벨을 앞으로 굴려 팔을 뻗는다.,Step:3 몸이 완전히 뻗고 팔이 머리 위로 오도록 계속 굴린다.,Step:4 잠깐 멈춘 뒤 바벨을 천천히 무릎 쪽으로 굴려 컨트롤하며 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qOKcgVP', '종아리 스트레칭', 'https://static.exercisedb.dev/media/qOKcgVP.gif', '종아리근', '종아리', '맨몸', '햄스트링,둔근', 'Step:1 벽이나 단단한 지지물을 향해 팔 길이 정도 떨어져 선다.,Step:2 손을 어깨 높이에 두고 벽이나 지지물에 댄다.,Step:3 한쪽 발을 뒤로 내딛고 뒤꿈치를 바닥에 평평하게 둔다.,Step:4 앞쪽 무릎을 살짝 굽히고 상체를 앞으로 기울이며 뒷다리는 곧게 유지한다.,Step:5 종아리 근육이 늘어나는 것을 느낀다.,Step:6 20–30초 동안 유지한다.,Step:7 반대쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KhHJ338', '사이드 플랭크로 푸시업', 'https://static.exercisedb.dev/media/KhHJ338.gif', '복근', '허리', '맨몸', '어깨,가슴,삼두근', 'Step:1 푸시업 자세에서 손을 어깨너비로 짚고 몸을 일직선으로 만든다.,Step:2 팔꿈치를 굽혀 몸을 내리되 코어에 힘을 유지한다.,Step:3 팔을 펴서 시작 자세로 다시 올라온다.,Step:4 체중을 왼손에 싣고 몸을 오른쪽으로 회전시켜 오른팔을 천장 쪽으로 들어 올린다.,Step:5 사이드 플랭크 자세를 몇 초 유지한 뒤 시작 자세로 돌아온다.,Step:6 반대쪽도 같은 방식으로 푸시업 + 사이드 플랭크를 수행한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5uFK1xr', '바벨 시트 오버헤드 삼두근 익스텐션', 'https://static.exercisedb.dev/media/5uFK1xr.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 오버핸드 그립으로 바벨을 어깨너비로 잡고 머리 위로 들어 올린다.,Step:3 상완을 머리 가까이에 두고 팔꿈치를 굽혀 바벨을 머리 뒤로 내린다.,Step:4 잠깐 멈춘 뒤 팔꿈치를 펴서 바벨을 시작 자세로 들어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qi996YS', '바벨 클린그립 프런트 스쿼트', 'https://static.exercisedb.dev/media/qi996YS.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 상부 가슴 위에 올리고 팔꿈치를 앞쪽으로 든다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 보내며 의자에 앉듯이 내려간다.,Step:3 가슴을 들고 등을 곧게 유지하며 내려가고 무릎이 발끝을 과하게 넘지 않게 한다.,Step:4 허벅지가 바닥과 평행해질 때까지, 또는 가능한 만큼 편하게 내려간다.,Step:5 아래에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 일어나며 엉덩이와 무릎을 편다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('78VqWQK', '스미스 인클라인 리버스 그립 프레스', 'https://static.exercisedb.dev/media/78VqWQK.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 스미스 머신 좌석을 편한 인클라인 각도로 조절한다.,Step:2 머신에 앉아 등을 패드에 대고 발을 바닥에 둔다.,Step:3 오버핸드 그립으로 바를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:4 바를 빼서 가슴 쪽으로 천천히 내리되 팔꿈치를 몸 쪽으로 모은다.,Step:5 바가 가슴 바로 위에 왔을 때 잠깐 멈춘다.,Step:6 바를 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4c9BhzB', 'V-바를 사용한 케이블 사이드 풀다운', 'https://static.exercisedb.dev/media/4c9BhzB.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 케이블 풀다운 머신에 앉아 V-바 어태치먼트를 오버핸드 그립으로 잡는다.,Step:2 무릎 패드를 조절해 허벅지가 단단히 고정되게 한다.,Step:3 등을 곧게 펴고 상체를 약간 뒤로 기울인다.,Step:4 팔꿈치를 몸에 가깝게 유지하며 V-바를 위쪽 가슴 쪽으로 당긴다.,Step:5 아래에서 등 근육을 조이며 잠깐 멈춘다.,Step:6 V-바를 천천히 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PM1PZjg', '점프로 런지', 'https://static.exercisedb.dev/media/PM1PZjg.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 오른발을 앞으로 내딛고 런지 자세로 내려간다.,Step:3 오른발로 밀어 공중으로 점프하며 공중에서 발 위치를 바꾼다.,Step:4 왼발이 앞으로 오게 부드럽게 착지하고 즉시 런지로 내려간다.,Step:5 원하는 반복 횟수만큼 점프 런지를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jV65tKx', '견갑골 푸쉬업', 'https://static.exercisedb.dev/media/jV65tKx.gif', '전거근', '가슴', '맨몸', '삼두근,어깨', 'Step:1 하이 플랭크에서 손을 어깨 바로 아래에 두고 몸을 일직선으로 만든다.,Step:2 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리되 팔꿈치를 몸에 가깝게 유지한다.,Step:3 내려가면서 견갑골을 모아 가슴을 앞으로 내민다.,Step:4 아래에서 잠깐 멈춘 뒤 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QOA0FD0', '웨이티드 행잉 레그 힙 레이즈', 'https://static.exercisedb.dev/media/QOA0FD0.gif', '복근', '허리', '가중', '고관절 굴근,허리', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥이 앞쪽을 향하게 한다.,Step:2 코어에 힘을 주고 다리를 앞쪽으로 들어 올리되 다리를 곧게 유지한다.,Step:3 다리가 바닥과 평행하거나 약간 더 높아질 때까지 들어 올린다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fTlkJop', '덤벨 옆으로 누워서 한 손 올리기', 'https://static.exercisedb.dev/media/fTlkJop.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 옆으로 누워 다리를 곧게 뻗고 팔로 머리를 지지한다.,Step:2 위쪽 손에 덤벨을 들고 손바닥이 아래를 향하게 한다.,Step:3 팔을 곧게 유지한 채 덤벨을 어깨 높이까지 들어 올린다.,Step:4 위에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WWD6FzI', '슬레이 45도 한쪽 다리 프레스', 'https://static.exercisedb.dev/media/WWD6FzI.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신을 45도 각도로 세팅한다.,Step:2 머신에 앉아 등을 패드에 대고 발을 발판에 올린다.,Step:3 한 발을 발판에 두고 다리를 펴 슬레이를 밀어낸다.,Step:4 무릎을 천천히 굽혀 슬레이를 시작 자세로 내린다.,Step:5 반대쪽 다리로 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9n2149Z', '슬레이 누워 스쿼트', 'https://static.exercisedb.dev/media/9n2149Z.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신을 원하는 무게로 조절한다.,Step:2 머신에 등을 대고 누워 발을 발판에 둔다.,Step:3 발을 어깨너비로 두고 발끝을 약간 바깥으로 둔다.,Step:4 손잡이를 잡아 몸을 안정적으로 고정한다.,Step:5 둔근과 코어에 힘을 준다.,Step:6 뒤꿈치로 밀어 다리를 펴서 슬레이를 들어 올린다.,Step:7 무릎과 엉덩이를 굽혀 슬레이를 다시 내린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ngPpyRS', '바벨은 머리 밀리터리 프레스 뒤에 장착되어 있습니다.', 'https://static.exercisedb.dev/media/ngPpyRS.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 오버핸드 그립으로 바벨을 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 바벨을 랙에서 들어 머리 뒤쪽 어깨 높이로 내린다.,Step:4 바벨을 위로 밀어 올려 팔을 완전히 편다.,Step:5 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JymLInS', '덤벨 인클라인 슈러그', 'https://static.exercisedb.dev/media/JymLInS.gif', '승모근', '등', '덤벨', '어깨', 'Step:1 인클라인 벤치를 45도로 세팅하고 양손에 덤벨을 들고 앉는다.,Step:2 발을 바닥에 두고 팔을 아래로 늘어뜨리며 손바닥이 몸을 향하게 한다.,Step:3 팔을 곧게 유지한 채 어깨를 가능한 한 귀 쪽으로 끌어올려 으쓱한다.,Step:4 수축을 잠깐 유지한 뒤 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BKa8dmT', '벤치 중립 손목 컬 위에 덤벨', 'https://static.exercisedb.dev/media/BKa8dmT.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 양손에 덤벨을 들며 손바닥이 위를 향하게 한다.,Step:2 전완을 벤치 위에 올려 손목이 가장자리 밖으로 나오게 한다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CggQhII', '레버 밀리터리 프레스', 'https://static.exercisedb.dev/media/CggQhII.gif', '삼각근', '어깨', '레버리지 머신', '삼두근,가슴 위쪽', 'Step:1 좌석 높이를 조절하고 등받이에 등을 대고 머신에 앉는다.,Step:2 오버핸드 그립으로 손잡이를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 팔꿈치를 완전히 잠그지 않는 선에서 손잡이를 위로 밀어 팔을 편다.,Step:4 위에서 잠깐 멈춘 뒤 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9Ap7miY', '위기', 'https://static.exercisedb.dev/media/9Ap7miY.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 디클라인 벤치에 누워 발을 고정하고 무릎을 90도로 굽힌다.,Step:2 손을 머리 뒤에 두거나 가슴 앞에 교차해 둔다.,Step:3 복근에 힘을 주고 상체를 들어 올려 무릎 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('blBXysN', '케틀벨 투 암 밀리터리 프레스', 'https://static.exercisedb.dev/media/blBXysN.gif', '삼각근', '어깨', '케틀벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 케틀벨을 어깨 높이에서 잡고 손바닥이 앞을 향하게 한다.,Step:2 코어에 힘을 주고 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:3 위에서 잠깐 멈춘 뒤 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WgJnBH5', '덤벨 시티드 바이셉스 컬(스태빌리티 볼 위)', 'https://static.exercisedb.dev/media/WgJnBH5.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥이 앞을 향하게 한 채 팔을 완전히 편다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:5 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Mxa7Cr8', '벤치에 거꾸로 된 줄', 'https://static.exercisedb.dev/media/Mxa7Cr8.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 몸이 벤치 아래로 자연스럽게 매달릴 수 있는 높이로 벤치를 준비한다.,Step:2 바닥에 반듯이 누워 머리가 벤치 쪽을 향하게 한다.,Step:3 벤치를 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:4 뒤꿈치를 바닥에 두고 팔을 완전히 편 상태가 되도록 몸을 위치시킨다.,Step:5 코어에 힘을 주고 견갑골을 모으며 가슴을 벤치 쪽으로 끌어올린다.,Step:6 위에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QUDd8WS', '비스듬한 크런치 바닥', 'https://static.exercisedb.dev/media/QUDd8WS.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두거나 가슴 앞에 교차해 둔다.,Step:3 복근에 힘을 주고 어깨를 들어 올리면서 몸통을 한쪽으로 회전한다.,Step:4 잠깐 멈춘 뒤 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 반대쪽도 수행하며 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('i4JkUaL', '바벨 사이드 벤트 v. 2', 'https://static.exercisedb.dev/media/i4JkUaL.gif', '복근', '허리', '바벨', '복사근,허리', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 양손으로 잡아 손바닥이 아래를 향하게 한다.,Step:2 동작 내내 등을 곧게 펴고 코어에 힘을 준다.,Step:3 몸통을 오른쪽으로 천천히 기울여 바벨을 오른쪽 무릎 쪽으로 내린다.,Step:4 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:5 왼쪽도 같은 방식으로 수행한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qEse6fe', '어깨 탭 푸시업', 'https://static.exercisedb.dev/media/qEse6fe.gif', '가슴근육', '가슴', '맨몸', '삼두근,코어', 'Step:1 하이 플랭크에서 손을 어깨너비보다 약간 넓게 짚고 머리부터 발뒤꿈치까지 일직선을 만든다.,Step:2 팔꿈치를 굽혀 몸을 내리되 팔꿈치를 몸에 가깝게 유지한다.,Step:3 밀어 올리며 오른손을 들어 왼쪽 어깨를 탭한다.,Step:4 오른손을 바닥에 다시 짚고 이번에는 푸시업 후 왼손으로 오른쪽 어깨를 탭한다.,Step:5 푸시업마다 어깨 탭을 번갈아 반복한다.,Step:6 코어를 안정적으로 유지하고 골반이 과도하게 회전하지 않게 한다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YPoVrBi', '케이블 장착 어깨 내부 회전', 'https://static.exercisedb.dev/media/YPoVrBi.gif', '삼각근', '어깨', '케이블', '회전근개,삼두근', 'Step:1 케이블 머신을 마주보고 벤치나 의자에 앉아 발을 바닥에 둔다.,Step:2 한 팔을 앞으로 뻗어 케이블 손잡이를 잡고 팔이 바닥과 평행하게 한다.,Step:3 팔꿈치를 약간 굽히고 견갑골을 뒤로 아래로 당겨 고정한다.,Step:4 팔을 안쪽으로 천천히 회전시켜 손잡이를 몸의 중앙 쪽으로 가져온다.,Step:5 끝 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kesXOpB', '케이블 디클라인 시티드 와이드 그립 로우', 'https://static.exercisedb.dev/media/kesXOpB.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 디클라인 벤치에 앉아 케이블 머신을 향하고 발은 발받침에 단단히 둔다.,Step:2 와이드 오버핸드 그립으로 케이블 손잡이를 잡아 손바닥이 아래를 향하게 한다.,Step:3 상체를 약간 뒤로 기울이고 등을 곧게 유지하며 코어에 힘을 준다.,Step:4 케이블을 아래 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 수축 정점에서 잠깐 멈춘 뒤 케이블을 천천히 풀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ms7tjSG', '인버스 레그 컬(벤치 서포트)', 'https://static.exercisedb.dev/media/ms7tjSG.gif', '햄스트링', '허벅지', '맨몸', '둔근,종아리근', 'Step:1 벤치에 엎드려 엉덩이가 벤치 끝에 오게 하고 다리를 뒤로 곧게 뻗는다.,Step:2 벤치를 잡아 몸을 고정한다.,Step:3 상체를 고정한 채 무릎을 굽혀 발을 엉덩이 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 펴서 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1cTf2Ux', 'ez 바 스탠딩 프렌치 프레스', 'https://static.exercisedb.dev/media/1cTf2Ux.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 EZ 바벨을 오버핸드 그립으로 잡는다.,Step:2 팔을 완전히 펴 EZ 바벨을 머리 위로 들어 올린다.,Step:3 상완을 머리 가까이에 둔 채 팔꿈치를 굽혀 EZ 바벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 팔꿈치를 펴서 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vpQaQkH', '스키 에르고미터', 'https://static.exercisedb.dev/media/vpQaQkH.gif', '삼두근', '상완이두근', '스키어 기계', '어깨,전완근', 'Step:1 좌석 높이와 발 받침을 편한 위치로 조절한다.,Step:2 오버핸드 그립으로 손잡이를 잡아 손바닥이 아래를 향하게 한다.,Step:3 등을 곧게 펴고 발을 발 받침에 둔다.,Step:4 팔을 앞으로 곧게 뻗되 팔꿈치는 약간 굽힌다.,Step:5 삼두근에 힘을 주고 손잡이를 허벅지 쪽으로 아래로 밀어 내린다.,Step:6 아래에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pj0X0tF', '행잉 스트레이트 레그 힙 레이즈', 'https://static.exercisedb.dev/media/pj0X0tF.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥이 앞쪽을 향하게 한다.,Step:2 코어에 힘을 주고 다리를 앞쪽으로 들어 올려 바닥과 평행해질 때까지 올린다.,Step:3 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WhuFnR7', '누워서 다리 올리기 플랫 벤치', 'https://static.exercisedb.dev/media/WhuFnR7.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 플랫 벤치에 등을 대고 눕는다.,Step:2 손을 엉덩이 아래에 넣어 지지한다.,Step:3 다리를 곧게 모아 천장을 향해 들어 올린다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nlJsbkW', '덤벨 바이셉스 컬(암 블래스터 포함)', 'https://static.exercisedb.dev/media/nlJsbkW.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 똑바로 서서 양손에 덤벨을 들고 손바닥이 앞을 향하게 한다.,Step:2 팔꿈치를 몸통에 붙이고 상완이 움직이지 않게 고정한다.,Step:3 숨을 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:5 정점에서 이두근을 조이며 잠깐 멈춘다.,Step:6 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MKIelrR', '짐 볼에 케이블 원 암 프레스', 'https://static.exercisedb.dev/media/MKIelrR.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 짐볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손으로 케이블 손잡이를 잡고 팔꿈치를 굽혀 가슴 높이에 위치시킨다.,Step:3 다른 손은 허리에 두어 몸을 안정시킨다.,Step:4 손잡이를 앞으로 밀어 팔을 완전히 편다.,Step:5 잠깐 멈춘 뒤 손잡이를 천천히 되돌려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FAoIFMw', '원 암 딥', 'https://static.exercisedb.dev/media/FAoIFMw.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 의자에서 등을 돌리고 서서 발을 어깨너비로 벌린다.,Step:2 한 손을 뒤의 벤치/의자 위에 올려 손가락이 몸 쪽을 향하게 한다.,Step:3 다리를 앞으로 뻗어 뒤꿈치를 바닥에 둔다.,Step:4 팔꿈치를 굽혀 몸을 내리되 등이 벤치/의자에 가깝게 유지되도록 한다.,Step:5 아래에서 잠깐 멈춘 뒤 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NvfE43H', '케이블 컨센트레이션 컬', 'https://static.exercisedb.dev/media/NvfE43H.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 벤치나 의자에 앉아 발을 바닥에 두고 무릎을 약간 굽힌다.,Step:2 케이블 손잡이를 언더핸드 그립으로 잡고 팔꿈치를 허벅지 안쪽에 댄다.,Step:3 상완을 고정한 채 숨을 내쉬며 손잡이를 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤 숨을 들이마시며 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bRlbdjK', '덤벨 디클라인 슈러그 ??v. 2', 'https://static.exercisedb.dev/media/bRlbdjK.gif', '승모근', '등', '덤벨', '어깨,능형근', 'Step:1 디클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 엎드려 가슴과 배를 벤치에 댄다.,Step:3 양손에 덤벨을 들고 손바닥이 서로 마주보게 한 채 팔을 완전히 편다.,Step:4 팔을 곧게 유지한 채 어깨를 가능한 한 높이 끌어올리며 견갑골을 모아 조인다.,Step:5 수축을 잠깐 유지한 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7jGOBF3', '덤벨 클로즈 그립 프레스', 'https://static.exercisedb.dev/media/7jGOBF3.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 플랫 벤치에 앉아 양손에 덤벨을 들고 허벅지 위에 올려둔다.,Step:2 허벅지를 이용해 덤벨을 하나씩 들어 올려 어깨너비로 앞쪽에 들고 있다.,Step:3 어깨너비 위치에서 손목을 앞으로 회전시켜 손바닥이 앞을 향하게 한다. 이것이 시작 자세다.,Step:4 숨을 들이마시며 덤벨을 천천히 옆으로 내려 가슴 높이 정도까지 내린다.,Step:5 숨을 내쉬며 삼두근을 사용해 덤벨을 들어 올려 시작 자세로 돌아온다. 전완이나 이두근으로 보조하지 않도록 한다.,Step:6 수축 지점에서 잠깐 멈춘 뒤 정해진 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xdYPUtE', '시시 스쿼트', 'https://static.exercisedb.dev/media/xdYPUtE.gif', '대퇴사두근', '허벅지', '맨몸', '종아리근,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝을 약간 바깥으로 둔다.,Step:2 필요하면 균형을 위해 고정된 지지물을 잡는다.,Step:3 상체를 세운 채 무릎을 굽히며 몸을 천천히 내리고 약간 뒤로 기대듯이 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지, 또는 가능한 만큼 편하게 내려간다.,Step:5 아래에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hBGWILP', '케이블 고관절 내전', 'https://static.exercisedb.dev/media/hBGWILP.gif', '내전근', '허벅지', '케이블', '둔근,대퇴사두근', 'Step:1 발목 커프를 발목에 착용하고 케이블 머신을 마주보고 선다.,Step:2 케이블에 장력이 생길 만큼 머신에서 적당히 떨어진다.,Step:3 균형을 위해 손을 머신에 짚는다.,Step:4 다리를 곧게 유지한 채 다리를 몸의 중앙선 쪽으로 천천히 가져온다.,Step:5 끝 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G7xoEzr', '바벨 앉아서 다리 올리기', 'https://static.exercisedb.dev/media/G7xoEzr.gif', '복근', '허리', '바벨', '고관절 굴근', 'Step:1 벤치에 앉아 등을 곧게 펴고 바벨을 허벅지 위에 올려둔다.,Step:2 다리를 곧게 유지한 채 한쪽 다리를 가능한 한 높이 들어 올리고 다른 다리는 바닥에 둔다.,Step:3 들어 올린 다리를 내려 시작 자세로 돌아온 뒤 반대쪽 다리로 반복한다.,Step:4 원하는 반복 횟수만큼 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3omWx6P', '밴드 교대 바이셉스 컬', 'https://static.exercisedb.dev/media/3omWx6P.gif', '이두근', '상완이두근', '밴드', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 밴드를 언더핸드 그립으로 잡아 손바닥이 위를 향하게 한다.,Step:2 팔꿈치를 몸 옆에 붙이고 한쪽 팔을 어깨 쪽으로 천천히 말아 올려 이두근을 조인다.,Step:3 팔을 천천히 내려 시작 자세로 돌아온 뒤 반대쪽 팔로 반복한다.,Step:4 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sVQCCeG', '행진 앉아 (벽)', 'https://static.exercisedb.dev/media/sVQCCeG.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 벽에 등을 대고 서서 발을 엉덩이너비로 둔다.,Step:2 등을 벽을 따라 내리며 무릎이 90도가 될 때까지 앉는다.,Step:3 오른발을 들어 무릎을 가슴 쪽으로 끌어올린다.,Step:4 오른발을 다시 내리고 왼발을 들어 무릎을 가슴 쪽으로 끌어올린다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3uj0Ozg', '다이나믹 체스트 스트레칭(남성)', 'https://static.exercisedb.dev/media/3uj0Ozg.gif', '가슴근육', '가슴', '맨몸', '어깨,삼두근', 'Step:1 발을 어깨너비로 벌리고 곧게 선다.,Step:2 양팔을 바닥과 평행하게 옆으로 곧게 뻗는다.,Step:3 팔을 천천히 앞으로 모아 몸 앞에서 교차시킨다.,Step:4 가슴 근육이 늘어나는 것을 느낀다.,Step:5 10–30초 동안 유지한다.,Step:6 시작 자세로 돌아가 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oHg8eop', '메디신볼 오버헤드 슬램', 'https://static.exercisedb.dev/media/oHg8eop.gif', '등 위쪽', '등', '메디신볼', '어깨,코어', 'Step:1 발을 어깨너비로 벌리고 서서 메디신볼을 머리 위로 양손에 든다.,Step:2 코어에 힘을 주고 등을 곧게 유지한다.,Step:3 무릎을 약간 굽히고 메디신볼을 몸 앞 바닥으로 강하게 내리친다.,Step:4 내리칠 때 어깨와 코어를 포함한 전신을 사용해 힘을 만든다.,Step:5 튀어 오른 공을 잡고 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Yg7MJAT', '지지대를 이용한 덤벨 원 암 사이드 들어올리기', 'https://static.exercisedb.dev/media/Yg7MJAT.gif', '삼각근', '어깨', '덤벨', '승모근,회전근개', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 반대쪽 손은 벤치나 벽 같은 지지대에 짚어 지지한다.,Step:3 등을 곧게 유지하고 코어에 힘을 준다.,Step:4 팔을 곧게 유지한 채 덤벨을 옆으로 들어 올려 손바닥이 아래를 향하게 한다.,Step:5 팔이 바닥과 평행해질 때까지 들어 올린다.,Step:6 위에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tJ5nYqo', 'ez-bar 바이셉스 컬(암 블래스터 포함)', 'https://static.exercisedb.dev/media/tJ5nYqo.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 똑바로 서서 EZ 바벨을 언더핸드 그립으로 잡아 손바닥이 위를 향하게 한다.,Step:2 상완을 암 블래스터에 밀착해 고정한다.,Step:3 팔꿈치를 몸에 가깝게 두고 숨을 내쉬며 바벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 바벨을 천천히 내려 팔을 완전히 펴서 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('u27Kcdz', '벤치 엉덩이 익스텐션', 'https://static.exercisedb.dev/media/u27Kcdz.gif', '둔근', '허벅지', '맨몸', '햄스트링', 'Step:1 벤치에 앉아 등을 벤치에 기대고 발을 바닥에 둔다.,Step:2 손을 벤치에 짚어 지지한다.,Step:3 둔근과 햄스트링에 힘을 주고 엉덩이를 들어 올려 무릎부터 어깨까지 일직선이 되게 한다.,Step:4 위에서 잠깐 멈춘 뒤 엉덩이를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QoHIhPl', '오버헤드 체스트 스트레칭', 'https://static.exercisedb.dev/media/QoHIhPl.gif', '가슴근육', '가슴', '도움을 준', '어깨,삼두근', 'Step:1 발을 어깨너비로 벌리고 곧게 선다.,Step:2 손가락을 머리 뒤에서 깍지 끼고 팔꿈치를 바깥쪽으로 향하게 한다.,Step:3 견갑골을 천천히 조이며 가슴을 앞으로 민다.,Step:4 15–30초 동안 유지한다.,Step:5 풀어준 뒤 원하는 만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7aolH9D', '메디신 볼 가슴 푸시 다중 응답', 'https://static.exercisedb.dev/media/7aolH9D.gif', '가슴근육', '가슴', '메디신볼', '삼두근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 메디신볼을 가슴 높이에서 든다.,Step:2 팔을 앞으로 뻗어 메디신볼을 가슴에서 밀어낸다.,Step:3 잠깐 멈춘 뒤 메디신볼을 천천히 가슴 쪽으로 다시 가져온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HsjbB1z', '스미스 스프린트 런지', 'https://static.exercisedb.dev/media/HsjbB1z.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 스미스 머신 바를 엉덩이 높이로 세팅한다.,Step:2 머신을 등지고 서서 발을 어깨너비로 벌린다.,Step:3 오른발을 뒤로 빼 바 위에 올려 발등이 바에 닿게 한다.,Step:4 왼쪽 무릎을 굽혀 런지 자세로 내려가되 등을 곧게 유지한다.,Step:5 왼쪽 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 반대쪽도 수행해 왼발을 뒤로 올린다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GxDwDX0', '누워서 종아리 스트레칭', 'https://static.exercisedb.dev/media/GxDwDX0.gif', '종아리근', '종아리', '도움을 준', '햄스트링', 'Step:1 다리를 곧게 뻗은 채로 등을 바닥에 대고 눕는다.,Step:2 한쪽 무릎을 굽혀 발을 바닥에 둔다.,Step:3 손이나 수건을 이용해 발가락을 몸 쪽으로 천천히 당겨 종아리가 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 스트레치를 풀고 반대쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rjtuP6X', '일립티컬 크로스 트레이너 걷기', 'https://static.exercisedb.dev/media/rjtuP6X.gif', '심혈관계', '유산소', '타원형 기계', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 일립티컬의 저항과 경사도를 원하는 설정으로 맞춘다.,Step:2 페달 위에 올라서고 손잡이를 가볍게 잡는다.,Step:3 발로 페달을 누르고 손으로 손잡이를 당기며 동작을 시작한다.,Step:4 이 동작을 번갈아 수행해 걷기/달리기처럼 움직인다.,Step:5 운동 내내 일정한 페이스를 유지하고 코어에 힘을 준다.,Step:6 원하는 시간 동안 유산소 운동을 지속한다.,Step:7 마무리로 강도와 속도를 서서히 낮춘 뒤 머신에서 내려온다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LeaZOIz', '덤벨 스탠딩 대체 해머 컬 앤 프레스', 'https://static.exercisedb.dev/media/LeaZOIz.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 똑바로 서서 양손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 팔꿈치를 몸통에 붙이고 등을 곧게 유지한다.,Step:3 숨을 내쉬며 오른손 덤벨을 어깨 쪽으로 말아 올려 상완을 고정한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 오를 때까지 올린다.,Step:5 숨을 들이마시며 오른손 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 왼손으로 해머 컬을 같은 방식으로 수행한다.,Step:7 왼손 컬을 마친 뒤 숨을 내쉬며 오른손 덤벨을 머리 위로 프레스한다.,Step:8 팔을 완전히 펴고 위에서 잠깐 유지한다.,Step:9 숨을 들이마시며 오른손 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:10 왼손도 같은 방식으로 프레스를 수행한다.,Step:11 원하는 반복 횟수만큼 컬과 프레스를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uTBt1HV', '견갑골 풀업', 'https://static.exercisedb.dev/media/uTBt1HV.gif', '승모근', '등', '맨몸', '이두근,능형근,후면 삼각근', 'Step:1 손바닥이 앞을 향하도록 풀업 바에 매달려 팔을 완전히 편다.,Step:2 견갑골을 아래로 당기고 뒤로 모아 견갑을 후인한다.,Step:3 등 근육에 힘을 주고 몸을 바 쪽으로 끌어올리며 견갑골을 조이는 느낌에 집중한다.,Step:4 위에서 잠깐 멈춘 뒤 몸을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gx7s7uF', '바벨 인클라인 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/gx7s7uF.gif', '삼두근', '상완이두근', '바벨', '가슴,어깨', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 누워 발을 바닥에 둔다.,Step:3 바벨을 클로즈 그립으로 잡되 어깨너비보다 약간 좁게 잡는다.,Step:4 바벨을 빼서 가슴 쪽으로 천천히 내리되 팔꿈치를 몸에 가깝게 유지한다.,Step:5 바벨이 가슴에 닿을 때 잠깐 멈춘다.,Step:6 바벨을 밀어 올려 시작 자세로 돌아오며 팔을 완전히 편다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('g9AsZ8P', '케틀벨 원 암 로우', 'https://static.exercisedb.dev/media/g9AsZ8P.gif', '등 위쪽', '등', '케틀벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 케틀벨을 오버핸드 그립으로 잡는다.,Step:2 무릎을 약간 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 펴고 코어에 힘을 준다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 케틀벨을 가슴 쪽으로 당기고 견갑골을 조인다.,Step:4 위에서 잠깐 멈춘 뒤 케틀벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iQ241UP', '반 윗몸일으키기(남성)', 'https://static.exercisedb.dev/media/iQ241UP.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 바닥에 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥으로 향하게 한다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 될 때까지 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZSJNetl', '케이블 하이 로우(무릎꿇기)', 'https://static.exercisedb.dev/media/ZSJNetl.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 케이블 머신에 스트레이트 바를 가슴 높이에 연결한다.,Step:2 케이블 머신 앞에 무릎을 꿇고 바를 오버핸드 그립으로 어깨너비로 잡는다.,Step:3 엉덩이를 뒤로 빼 발뒤꿈치에 앉듯이 하고 등을 곧게 펴며 코어에 힘을 준다.,Step:4 바를 상복부 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 위에서 잠깐 멈춘 뒤 바를 천천히 놓아 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eYnzaCm', '케이블 바 사이드 풀다운', 'https://static.exercisedb.dev/media/eYnzaCm.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 케이블 풀리를 높은 위치로 조절하고 스트레이트 바를 연결한다.,Step:2 케이블 머신을 마주보고 앉아 발을 바닥에 두고 무릎을 약간 굽힌다.,Step:3 바를 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:4 상체를 약간 뒤로 기울이고 가슴을 들어 허리 아래쪽에 약간의 아치를 만든다.,Step:5 팔꿈치를 이끌듯이 바를 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 아래에서 잠깐 멈춘 뒤 바를 천천히 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wfotm7S', '체중 감소 점프 스쿼트', 'https://static.exercisedb.dev/media/wfotm7S.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 보내며 스쿼트로 내려간다.,Step:3 엉덩이, 무릎, 발목을 폭발적으로 펴며 위로 점프한다.,Step:4 공중에서 빠르게 발을 모은다.,Step:5 발볼로 부드럽게 착지한 뒤 즉시 다시 스쿼트로 내려간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VEcJRo2', '매달린 다리 엉덩이 들기', 'https://static.exercisedb.dev/media/VEcJRo2.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥이 앞을 향하게 한다.,Step:2 코어에 힘을 주고 엉덩이와 무릎을 굽혀 다리를 들어 올려 허벅지가 바닥과 평행해질 때까지 올린다.,Step:3 위에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PbzNu7c', '덤벨 인클라인 Y-레이즈', 'https://static.exercisedb.dev/media/PbzNu7c.gif', '등 위쪽', '등', '덤벨', '어깨,후면 삼각근', 'Step:1 인클라인 벤치를 45도로 세팅하고 덤벨을 양손에 든 채 앉아 손바닥이 서로 마주보게 한다.,Step:2 상체를 약간 앞으로 기울이고 팔을 아래로 늘어뜨리며 팔꿈치를 약간 굽힌다.,Step:3 팔을 옆으로 들어 올려 Y자 형태가 되도록 올려 바닥과 평행해질 때까지 든다.,Step:4 위에서 잠깐 멈춘 뒤 팔을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RRWFUcw', '덤벨 런지', 'https://static.exercisedb.dev/media/RRWFUcw.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 오른발을 앞으로 내딛고 런지 자세로 내려간다.,Step:3 내려갈 때 등을 곧게 펴고 가슴을 든다.,Step:4 오른쪽 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:5 왼쪽 다리로 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('A2upspL', '한쪽 다리 당나귀 송아지 들기', 'https://static.exercisedb.dev/media/A2upspL.gif', '종아리근', '종아리', '맨몸', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝은 정면을 향하게 한다.,Step:2 벽이나 바 같은 안정된 지지물에 손을 대고 균형을 잡는다.,Step:3 한쪽 다리를 들어 올리되 무릎은 약간 굽힌다.,Step:4 종아리로 힘을 줘 뒤꿈치를 가능한 한 높이 들어 올린다.,Step:5 위에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('elhhVgj', '바벨 내로우 스탠스 스쿼트', 'https://static.exercisedb.dev/media/elhhVgj.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝을 약간 바깥으로 둔다.,Step:2 바벨을 상부 등에 올려 승모근 또는 후면 삼각근 위에 위치시킨다.,Step:3 코어에 힘을 주고 가슴을 들며 무릎을 굽히고 엉덩이를 뒤로 보내 천천히 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지, 또는 약간 더 내려간다.,Step:5 잠깐 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4dF3maG', '덤벨 원 암 망치 설교자 컬', 'https://static.exercisedb.dev/media/4dF3maG.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 벤치에 앉아 한 손에 덤벨을 들고 상완을 패드에 올린다.,Step:2 중립 그립(손바닥이 몸을 향함)으로 덤벨을 잡는다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈추며 이두근을 조인다.,Step:5 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Hj4FOCd', '바벨 디클라인 와이드 그립 풀오버', 'https://static.exercisedb.dev/media/Hj4FOCd.gif', '광배근', '등', '바벨', '삼두근,가슴', 'Step:1 머리가 엉덩이보다 낮은 디클라인 벤치에 누워 발을 고정한다.,Step:2 와이드 그립으로 바벨을 잡고 가슴 위에서 팔을 곧게 편다.,Step:3 팔을 곧게 유지한 채 바벨을 컨트롤하며 머리 뒤로 내린다.,Step:4 잠깐 멈춘 뒤 바벨을 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yRpV5TC', '어깨 탭', 'https://static.exercisedb.dev/media/yRpV5TC.gif', '복근', '허리', '맨몸', '어깨,삼두근', 'Step:1 하이 플랭크에서 손을 어깨 바로 아래에 두고 몸을 일직선으로 만든다.,Step:2 코어에 힘을 주고 오른손을 들어 왼쪽 어깨를 탭한다.,Step:3 오른손을 다시 바닥에 짚고 왼손으로 오른쪽 어깨를 탭한다.,Step:4 골반과 몸통이 흔들리지 않게 하며 좌우를 번갈아 반복한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0V2YQjW', '풀업(중립 그립)', 'https://static.exercisedb.dev/media/0V2YQjW.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 중립 그립(손바닥이 서로 마주보게)으로 풀업 바에 매달려 팔을 완전히 편다.,Step:2 코어에 힘을 주고 견갑골을 서로 조여준다.,Step:3 팔꿈치를 굽히고 팔꿈치를 엉덩이 쪽으로 아래로 당기며 몸을 바 쪽으로 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 계속 당긴다.,Step:5 정점에서 잠깐 멈춘 뒤, 컨트롤하며 천천히 시작 자세로 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ESOd5Pl', '덤벨 인클라인 플라이', 'https://static.exercisedb.dev/media/ESOd5Pl.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 인클라인 벤치를 45도 각도로 맞춘다.,Step:2 벤치에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:3 벤치에 누워 덤벨을 가슴 바로 위 시작 자세로 밀어 올린다.,Step:4 가슴이 늘어나는 느낌이 들 때까지 덤벨을 넓은 호를 그리며 옆으로 천천히 내린다.,Step:5 잠깐 멈춘 뒤, 가슴에 힘을 주어 덤벨을 시작 자세로 다시 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ktsFQAZ', '바벨 시트 카프 레이즈', 'https://static.exercisedb.dev/media/ktsFQAZ.gif', '종아리근', '종아리', '바벨', '햄스트링,대퇴사두근', 'Step:1 발바닥을 바닥에 붙이고 벤치에 앉아 바벨을 허벅지 위에 올린다.,Step:2 발 앞꿈치를 블록이나 스텝 같은 높은 지지대 위에 둔다.,Step:3 바벨을 허벅지 위에 위치시키고 손으로 단단히 잡아 고정한다.,Step:4 등을 곧게 유지하고 코어에 힘을 준 상태에서 발목을 펴서 뒤꿈치를 들어 올린다.,Step:5 정점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 뒤꿈치를 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KUaoUV8', '밴드 스트레이트 레그 데드리프트', 'https://static.exercisedb.dev/media/KUaoUV8.gif', '척추', '등', '밴드', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 밴드를 발에 걸고 선다.,Step:2 양손으로 밴드를 잡고 손바닥이 몸을 향하도록 하며 팔은 곧게 편다.,Step:3 코어에 힘을 주고 무릎은 살짝 굽힌다.,Step:4 등을 곧게 유지하고 가슴을 들어 올린 채 엉덩이를 접으며(힙 힌지) 상체를 천천히 숙인다.,Step:5 다리는 곧게 유지하면서 밴드를 바닥 쪽으로 천천히 내린다.,Step:6 바닥에서 잠깐 멈춘 뒤, 둔근과 햄스트링에 힘을 주어 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('x0lwvfq', '대체 리베이트 위에 구부러진 덤벨 장착', 'https://static.exercisedb.dev/media/x0lwvfq.gif', '삼두근', '상완이두근', '덤벨', '어깨,등', 'Step:1 벤치에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 허리를 숙여 등을 곧게 펴고 바닥과 평행이 되게 만든다.,Step:3 한쪽 팔을 몸에 가깝게 유지한 채 뒤로 곧게 펴 팔을 완전히 편다.,Step:4 잠깐 멈춘 뒤, 덤벨을 천천히 시작 자세로 내린다.,Step:5 반대쪽 팔로 반복한다.,Step:6 원하는 반복 횟수만큼 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MzNnwx9', '스미스 슈러그', 'https://static.exercisedb.dev/media/MzNnwx9.gif', '승모근', '등', '스미스 머신', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 살짝 굽힌다.,Step:2 바를 오버핸드 그립으로 잡고 손은 어깨너비보다 약간 넓게 둔다.,Step:3 팔은 곧게 편 채 바가 허벅지 앞에서 자연스럽게 늘어지게 한다.,Step:4 어깨를 귀 쪽으로 수직으로 들어 올리며 상부 승모근을 수축한다.,Step:5 잠깐 유지한 뒤, 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Bpkf41o', '덤벨 원 암 가슴 플라이 온 짐 볼', 'https://static.exercisedb.dev/media/Bpkf41o.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐 볼에 앉아 한 손에 덤벨을 들고 발은 바닥에 붙인다.,Step:2 발을 앞으로 걸어 나가며 공을 굴려 상부 등이 공에 지지되게 하고, 머리/목/어깨는 공 밖으로 나오게 한다.,Step:3 덤벨 든 팔을 가슴 위로 곧게 펴 올리고 손바닥은 안쪽을 향하게 한다.,Step:4 팔꿈치를 살짝 굽힌 상태를 유지하며 덤벨을 옆으로 천천히 내린다.,Step:5 팔이 바닥과 평행이 되면 잠깐 멈춘다.,Step:6 가슴에 힘을 주어 덤벨을 시작 자세로 다시 올린다.,Step:7 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EIsE3u8', '한쪽 팔을 줄 위로 구부린 케이블', 'https://static.exercisedb.dev/media/EIsE3u8.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 케이블 머신을 정면으로 바라보고 선다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 유지한다.,Step:3 한 손으로 케이블 핸들을 잡고 손바닥은 안쪽을 향하게 하며 팔을 완전히 편다.,Step:4 팔꿈치를 몸에 가깝게 유지한 채 핸들을 몸 쪽으로 당겨 손이 아래 가슴 위치에 오게 한다.,Step:5 잠깐 멈춘 뒤, 팔을 천천히 펴 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('P9ZRyLT', '하이트 덤벨 플라이', 'https://static.exercisedb.dev/media/P9ZRyLT.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 벤치에 누워 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 팔을 가슴 위로 곧게 펴 올리되 팔꿈치는 살짝 굽힌다.,Step:3 팔꿈치의 살짝 굽힌 각도를 유지한 채 덤벨을 넓은 호를 그리며 옆으로 내려 가슴이 늘어나는 느낌이 들게 한다.,Step:4 잠깐 멈춘 뒤, 동작을 반대로 하여 덤벨을 시작 자세로 되돌린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pmnrOp0', '밴드 무릎 꿇기 원 암 풀다운', 'https://static.exercisedb.dev/media/pmnrOp0.gif', '광배근', '등', '밴드', '이두근,능형근', 'Step:1 머리 위의 단단한 고정 지점에 밴드를 걸어 고정한다.,Step:2 무릎을 꿇고 한 손으로 밴드를 잡되 손바닥이 아래를 향하게 한다.,Step:3 팔을 머리 위로 완전히 뻗고 팔꿈치는 살짝 굽힌다.,Step:4 광배근에 힘을 주어 팔꿈치를 갈비뼈 쪽으로 내리며 밴드를 옆구리 쪽으로 당긴다.,Step:5 아래에서 잠깐 멈춘 뒤, 장력을 천천히 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ocYc6Db', '덤벨 서 원 암 손바닥 프레스', 'https://static.exercisedb.dev/media/ocYc6Db.gif', '삼각근', '어깨', '덤벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 들어 어깨 높이에 두고 손바닥은 안쪽을 향하게 한다.,Step:2 코어에 힘을 주고 등을 곧게 유지한다.,Step:3 팔을 완전히 펴며 덤벨을 위로 밀어 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대 팔로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2gPfomN', '3/4 윗몸일으키기', 'https://static.exercisedb.dev/media/2gPfomN.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발은 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치는 바깥쪽을 향하게 한다.,Step:3 복근에 힘을 주며 상체를 천천히 들어 올려 몸통이 약 45도 각도가 될 때까지 말아 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xHKN2s8', '바벨 원 암 스내치', 'https://static.exercisedb.dev/media/xHKN2s8.gif', '삼각근', '어깨', '바벨', '승모근,전완근,코어', 'Step:1 발을 어깨너비로 벌리고 발끝은 약간 바깥쪽을 향하게 선다.,Step:2 바벨을 오버핸드 그립으로 잡고 손은 어깨너비보다 약간 넓게 둔다.,Step:3 무릎을 굽히고 엉덩이를 낮춰 스쿼트 자세로 내려가며 등을 곧게 펴고 가슴을 든다.,Step:4 엉덩이, 무릎, 발목을 폭발적으로 펴며 바벨을 위로 가속한다.,Step:5 바벨이 가슴 높이에 오면 팔로 바벨을 위로 끌어 올리되 몸에 가깝게 유지한다.,Step:6 팔꿈치를 바 아래로 회전시킨 뒤 팔을 머리 위로 완전히 펴 팔꿈치를 고정한다.,Step:7 바벨을 컨트롤하며 시작 자세로 천천히 내린다.,Step:8 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jdiExfW', '끈이 있는 거꾸로 된 줄', 'https://static.exercisedb.dev/media/jdiExfW.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 서스펜션 트레이너(스트랩)를 가슴 높이에 설치한다.,Step:2 고정 지점을 마주보고 서서 오버핸드 그립으로 손잡이를 잡는다.,Step:3 발을 앞으로 옮겨 몸을 뒤로 기울여 몸이 각도를 이루게 만든다.,Step:4 몸을 일직선으로 유지하고 코어에 힘을 준다.,Step:5 가슴을 손잡이 쪽으로 당기며 견갑골을 조여준다.,Step:6 정점에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dPmaUaU', '덤벨 스탠딩 종아리 올리기', 'https://static.exercisedb.dev/media/dPmaUaU.gif', '종아리근', '종아리', '덤벨', '발목', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 종아리 힘으로 뒤꿈치를 가능한 한 높이 들어 올린다.,Step:3 정점에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6MaEjVA', '스미스 스탠딩 레그 카프 레이즈', 'https://static.exercisedb.dev/media/6MaEjVA.gif', '종아리근', '종아리', '스미스 머신', '햄스트링,둔근', 'Step:1 어깨가 바 아래에 들어가고 발을 바닥에 붙인 채 설 수 있도록 스미스 바 높이를 맞춘다.,Step:2 바 아래에 서서 발을 어깨너비로 두고 발끝은 정면을 향하게 한다.,Step:3 안정성을 위해 손으로 바를 잡는다.,Step:4 종아리에 힘을 주어 뒤꿈치를 천천히 들어 올려 발끝으로 선다.,Step:5 정점에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KZn52RC', '굴곡 다리 윗몸일으키기(팔을 곧게 펴기)', 'https://static.exercisedb.dev/media/KZn52RC.gif', '복근', '허리', '맨몸', '고관절 굴근,대퇴사두근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔은 머리 위로 곧게 뻗는다.,Step:2 복근에 힘을 주며 상체를 들어 올리는 동시에 다리를 가슴 쪽으로 들어 올린다.,Step:3 상체와 다리를 올리며 손을 발끝 쪽으로 뻗는다.,Step:4 정점에서 잠깐 멈춘 뒤, 상체와 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fZFZ704', '가중 러시안 트위스트', 'https://static.exercisedb.dev/media/fZFZ704.gif', '복근', '허리', '가중', '복사근,허리', 'Step:1 바닥에 앉아 무릎을 굽히고 발을 바닥에 둔다.,Step:2 양손으로 웨이트(또는 메디신볼)를 가슴 앞에 든다.,Step:3 등을 곧게 유지한 채 상체를 살짝 뒤로 기울이고 코어에 힘을 준다.,Step:4 몸통을 오른쪽으로 비틀어 웨이트를 오른쪽 바닥 쪽으로 가져간다.,Step:5 잠깐 멈춘 뒤, 몸통을 왼쪽으로 비틀어 웨이트를 왼쪽 바닥 쪽으로 가져간다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PXTIwgu', '곧은 다리를 매달고 있는 팔걸이', 'https://static.exercisedb.dev/media/PXTIwgu.gif', '복근', '허리', '맨몸', '어깨,등', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 다리는 곧게 아래로 둔다.,Step:2 코어에 힘을 주고 다리를 앞쪽으로 들어 올려 바닥과 평행이 되게 한다.,Step:3 정점에서 잠깐 멈춘 뒤, 다리를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QyO6Uma', '스미스 머신 리버스 디클라인 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/QyO6Uma.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 스미스 머신을 디클라인 각도로 맞춘다.,Step:2 벤치에 누워 발을 발걸이 패드 아래에 고정한다.,Step:3 어깨너비보다 약간 좁게 클로즈 그립으로 바를 잡는다.,Step:4 바를 랙에서 빼고 팔꿈치를 몸 쪽으로 모은 채 가슴 쪽으로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘 뒤, 바를 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HtfCpfi', '스타점프(남)', 'https://static.exercisedb.dev/media/HtfCpfi.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 팔은 몸 옆에 둔 채 선다.,Step:2 무릎을 살짝 굽힌 뒤 폭발적으로 점프한다.,Step:3 점프하면서 다리를 벌리고 팔을 옆으로 뻗어 몸이 별 모양이 되게 한다.,Step:4 무릎을 살짝 굽힌 채 발 앞꿈치로 부드럽게 착지한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0jp9Rlz', '한쪽 다리 바닥 종아리 들어올리기', 'https://static.exercisedb.dev/media/0jp9Rlz.gif', '종아리근', '종아리', '맨몸', '발목,피트', 'Step:1 발을 엉덩이너비로 벌리고 서서 균형을 위해 벽이나 단단한 물체에 손을 댄다.,Step:2 한쪽 발을 들어 올리고 다른 발로 균형을 잡는다.,Step:3 지지하는 발의 뒤꿈치를 천천히 들어 올려 발 앞꿈치로 선다.,Step:4 정점에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('J9zIWig', '무릎 높이 들고 걷기 런지', 'https://static.exercisedb.dev/media/J9zIWig.gif', '심혈관계', '유산소', '맨몸', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 발을 엉덩이너비로 벌리고 선다.,Step:2 왼발로 균형을 잡으며 오른 무릎을 가능한 한 높게 가슴 쪽으로 들어 올린다.,Step:3 오른발을 앞으로 내딛고 양 무릎이 90도가 되도록 런지 자세로 내려간다.,Step:4 오른발로 밀어내며 왼 무릎을 가슴 쪽으로 들어 올린다.,Step:5 왼발을 앞으로 내딛고 런지 자세로 내려간다.,Step:6 코어에 힘을 주고 일정한 속도를 유지하며 다리를 번갈아 전진 런지를 이어간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wbUYILZ', '팔꿈치 들어올리기 - 리버스 푸쉬업', 'https://static.exercisedb.dev/media/wbUYILZ.gif', '등 위쪽', '등', '맨몸', '삼두근,어깨', 'Step:1 바닥에 엎드린 상태에서 다리를 뻗고 손을 어깨 바로 아래에 둔다.,Step:2 코어에 힘을 주고 손바닥으로 밀어 상체를 바닥에서 들어 올리되 팔꿈치는 몸 옆에 가깝게 유지한다.,Step:3 위에서 잠깐 멈추며 상부 등의 수축을 느낀다.,Step:4 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fXfqg1E', '가중 한 손 풀업', 'https://static.exercisedb.dev/media/fXfqg1E.gif', '광배근', '등', '가중', '이두근,전완근', 'Step:1 오버핸드 그립으로 풀업 바를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:2 팔을 완전히 편 채 바에 매달리고 몸을 곧게 유지한다.,Step:3 코어에 힘을 주고 팔꿈치를 굽히며 등 근육을 조여 몸을 바 쪽으로 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 계속 당긴다.,Step:5 컨트롤하며 시작 자세로 천천히 내려온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('25GPyDY', '바벨 컬', 'https://static.exercisedb.dev/media/25GPyDY.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 곧게 서서 언더핸드 그립으로 바벨을 잡아 손바닥이 정면을 향하게 한다.,Step:2 팔꿈치를 몸통에 가깝게 붙인다. 숨을 내쉬며 이두근을 수축해 바벨을 들어 올린다.,Step:3 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 수축 지점에서 잠깐 멈추며 이두근을 조여준다.,Step:5 숨을 들이마시며 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('e25F58f', '덤벨 원 암 리버스 플라이(지원 포함)', 'https://static.exercisedb.dev/media/e25F58f.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 벤치에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손에 덤벨을 들고 손바닥은 안쪽을 향하게 한다.,Step:3 상체를 숙이고 반대 손은 벤치에 짚어 지지한다.,Step:4 팔꿈치를 살짝 굽힌 상태로 팔을 옆으로 들어 올려 바닥과 평행이 되게 한다.,Step:5 정점에서 잠깐 멈춘 뒤, 팔을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2NImIAG', '다리를 올린 짐 볼에 덤벨 이두근 컬', 'https://static.exercisedb.dev/media/2NImIAG.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥이 정면을 향하게 하며 팔을 완전히 편다.,Step:3 팔꿈치를 몸 옆에 붙인 채 덤벨을 어깨 쪽으로 천천히 컬한다.,Step:4 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 컬 동작을 수행하는 동안 한쪽 다리를 바닥에서 들어 올려 운동 내내 공중에 유지한다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 다리를 바꿔 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UXpKJoq', '레버 누워 2-1 레그 컬', 'https://static.exercisedb.dev/media/UXpKJoq.gif', '햄스트링', '허벅지', '레버리지 머신', '둔근', 'Step:1 머신을 몸에 맞게 조절하고 등받이에 등을 기대고 앉는다.,Step:2 레버 패드에 다리를 올리되 발목 바로 위에 오게 둔다.,Step:3 옆의 손잡이를 잡아 몸을 고정한다.,Step:4 상체를 고정한 채 숨을 내쉬며 다리를 말아 올려 둔근 쪽으로 당긴다.,Step:5 정점에서 잠깐 멈춘 뒤, 숨을 들이마시며 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VhX2JdE', '케이블 스탠딩 백 리스트 컬', 'https://static.exercisedb.dev/media/VhX2JdE.gif', '전완근', '팔 아래', '케이블', '이두근,상완근', 'Step:1 발을 어깨너비로 벌리고 케이블 머신을 정면으로 바라보고 선다.,Step:2 오버핸드 그립으로 핸들을 잡아 손바닥이 아래를 향하게 한다.,Step:3 팔은 곧게 펴고 팔꿈치는 몸 옆에 가깝게 둔다.,Step:4 손목을 위로 말아 올려 핸들을 몸 쪽으로 끌어온다.,Step:5 정점에서 잠깐 멈춘 뒤, 핸들을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BRImeP8', '레버 장착 딥', 'https://static.exercisedb.dev/media/BRImeP8.gif', '삼두근', '상완이두근', '레버리지 머신', '가슴,어깨', 'Step:1 발을 바닥에 평평하게 두고 무릎이 90도가 되도록 좌석 높이를 맞춘다.,Step:2 손바닥이 아래를 향하도록 레버 손잡이를 잡고 팔을 완전히 편다.,Step:3 팔꿈치를 굽혀 상완이 바닥과 평행이 될 때까지 몸을 천천히 내린다.,Step:4 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XIHEoCG', '서있는 송아지', 'https://static.exercisedb.dev/media/XIHEoCG.gif', '종아리근', '종아리', '맨몸', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝은 정면을 향하게 한다.,Step:2 뒤꿈치를 가능한 한 높이 들어 올려 발끝으로 선다.,Step:3 잠깐 유지한 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8eqjhOl', '인클라인 벤치 프레스의 덤벨 손바닥', 'https://static.exercisedb.dev/media/8eqjhOl.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 인클라인 벤치를 45도 각도로 맞춘다.,Step:2 벤치에 앉아 등을 등받이에 기대고 발을 바닥에 둔다.,Step:3 양손에 덤벨을 잡되 오버핸드 그립으로 손바닥이 안쪽을 향하게 한다.,Step:4 팔을 가슴 위로 곧게 펴 올리되 팔꿈치는 살짝 굽힌다.,Step:5 팔꿈치를 몸에 가깝게 유지하며 덤벨을 어깨 쪽으로 천천히 내린다.,Step:6 아래에서 잠깐 멈춘 뒤, 덤벨을 밀어 올려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yQe5HpE', '바벨 스탠딩 트위스트', 'https://static.exercisedb.dev/media/yQe5HpE.gif', '복근', '허리', '바벨', '복사근,허리', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 가슴 앞에 두 손으로 잡고 손바닥이 아래를 향하게 한다.,Step:2 코어에 힘을 주고 운동 내내 등을 곧게 유지한다.,Step:3 하체는 안정적으로 유지한 채 발과 엉덩이를 축으로 몸통을 오른쪽으로 천천히 비튼다.,Step:4 비튼 끝에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아온다.,Step:5 왼쪽도 같은 방식으로 비튼다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sZOR9EV', '레버 무릎을 꿇고 트위스트', 'https://static.exercisedb.dev/media/sZOR9EV.gif', '복근', '허리', '레버리지 머신', '복사근,허리', 'Step:1 좌석 높이를 조절하고 무릎을 패드에 대고 상체는 정면을 향하게 자세를 잡는다.,Step:2 안정성을 위해 손잡이나 머신 옆을 잡는다.,Step:3 코어에 힘을 준 채 가능한 범위까지 몸통을 한쪽으로 비튼다.,Step:4 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 비튼다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eVxAzgz', '경사 다리 엉덩이 올리기(다리 곧게 펴기)', 'https://static.exercisedb.dev/media/eVxAzgz.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 인클라인 벤치에 누워 등을 벤치에 밀착하고 다리는 앞쪽으로 곧게 편다.,Step:2 지지력을 위해 손으로 벤치 옆을 잡는다.,Step:3 복근에 힘을 주어 다리를 벤치에서 들어 올려 가능한 한 높이 올리되 다리는 곧게 유지한다.,Step:4 정점에서 잠깐 멈춘 뒤, 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('i8BdLTK', '덤벨 스트레이트 암 풀오버', 'https://static.exercisedb.dev/media/i8BdLTK.gif', '가슴근육', '가슴', '덤벨', '광배근,삼두근', 'Step:1 벤치에 누워 머리는 한쪽 끝에 두고 발은 바닥에 단단히 고정한다.,Step:2 양손으로 덤벨을 들고 팔을 가슴 위로 곧게 편다.,Step:3 팔을 곧게 유지한 채 덤벨을 호를 그리며 머리 뒤쪽으로 천천히 내린다.,Step:4 잠깐 멈춘 뒤, 덤벨을 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yn8yg1r', '덤벨 고블릿 스쿼트', 'https://static.exercisedb.dev/media/yn8yg1r.gif', '대퇴사두근', '허벅지', '덤벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 덤벨을 세로로 가슴 앞에 두 손으로 잡는다.,Step:2 가슴을 들고 코어에 힘을 준 상태에서 엉덩이를 뒤로 빼고 무릎을 굽혀 스쿼트로 내려간다.,Step:3 허벅지가 바닥과 평행이 되거나 가능한 범위까지 계속 내려간다.,Step:4 아래에서 잠깐 멈춘 뒤, 뒤꿈치로 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GrO65fd', '바벨 디클라인 벤치 프레스', 'https://static.exercisedb.dev/media/GrO65fd.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 디클라인 벤치에 누워 발을 고정하고 머리가 엉덩이보다 낮게 위치하게 한다.,Step:2 오버핸드 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 바벨을 랙에서 빼고 팔꿈치를 몸 쪽으로 모은 채 가슴 쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘 뒤, 바벨을 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MaMuGH6', '레버를 이용한 턱걸이', 'https://static.exercisedb.dev/media/MaMuGH6.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 레버리지 머신의 저항을 원하는 수준으로 조절한다.,Step:2 발판 위에 서서 손잡이를 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 편 채 매달려 몸을 곧게 유지한다.,Step:4 등 근육에 힘을 주어 가슴을 앞세우며 손잡이 쪽으로 몸을 끌어올린다.,Step:5 턱이 손잡이 위로 올라갈 때까지 계속 당긴다.,Step:6 정점에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('V07qpXy', '레버 교대 다리 프레스', 'https://static.exercisedb.dev/media/V07qpXy.gif', '대퇴사두근', '허벅지', '레버리지 머신', '햄스트링,둔근', 'Step:1 레버리지 머신의 좌석과 발판을 원하는 자세에 맞게 조절한다.,Step:2 등받이에 등을 대고 앉아 발을 발판에 올린다.,Step:3 안정성을 위해 손잡이나 머신 옆을 잡는다.,Step:4 한쪽 발로 발판을 밀어 다리를 거의 완전히 펼 때까지 뻗는다.,Step:5 잠깐 멈춘 뒤, 다리를 굽혀 천천히 시작 자세로 돌아온다.,Step:6 반대쪽 다리로 반복한다.,Step:7 원하는 반복 횟수만큼 양쪽을 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7E06s6d', '가슴 탭 푸쉬업(남자)', 'https://static.exercisedb.dev/media/7E06s6d.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 하이 플랭크 자세에서 손을 어깨너비보다 약간 넓게 두고 몸을 일직선으로 만든다.,Step:2 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 팔꿈치는 몸 옆으로 가깝게 유지한다.,Step:3 내려가면서 오른손으로 가슴을 톡 친다.,Step:4 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 이번에는 왼손으로 가슴을 톡 친다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7D5bgLT', '덤벨 시티드 프리처 컬', 'https://static.exercisedb.dev/media/7D5bgLT.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 컬 벤치에 앉아 발을 바닥에 둔다.,Step:2 한 손에 덤벨을 언더핸드 그립으로 잡고 상완을 패드에 댄다.,Step:3 상완을 고정한 채 숨을 내쉬며 덤벨을 어깨 쪽으로 컬한다.,Step:4 정점에서 잠깐 멈춘 뒤, 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('e4aFmFY', '웨이티드 프론트 레이즈', 'https://static.exercisedb.dev/media/e4aFmFY.gif', '삼각근', '어깨', '가중', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥이 허벅지를 향하게 한다.,Step:2 팔을 곧게 편 채 숨을 내쉬며 덤벨을 앞쪽으로 들어 올려 어깨 높이까지 올린다.,Step:3 정점에서 잠깐 멈춘 뒤, 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NZ5Qqkz', '리버스 딥스', 'https://static.exercisedb.dev/media/NZ5Qqkz.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 평행봉 사이에 서서 팔을 완전히 편 상태로 몸을 곧게 만든다.,Step:2 팔꿈치를 굽혀 상완이 바닥과 평행이 될 때까지 몸을 내린다.,Step:3 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 밀어 올린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5fKX7wi', '덤벨 시티드 리버스 그립 원 암 오버헤드 삼두근 익스텐션', 'https://static.exercisedb.dev/media/5fKX7wi.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 덤벨을 언더핸드 그립으로 잡고 팔을 머리 위로 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤, 팔을 펴 덤벨을 시작 자세로 올린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('osdXT3K', '케틀벨 원 암 푸시 프레스', 'https://static.exercisedb.dev/media/osdXT3K.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 케틀벨을 들어 어깨 높이에 둔다.,Step:2 무릎을 살짝 굽히고 코어에 힘을 준다.,Step:3 다리를 펴며 동시에 팔을 뻗어 케틀벨을 머리 위로 밀어 올린다.,Step:4 무릎을 굽히며 케틀벨을 어깨로 되돌려 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6em2Dxj', '덤벨 대체 착석 해머 컬', 'https://static.exercisedb.dev/media/6em2Dxj.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 벤치에 앉아 양손에 덤벨을 들고 손바닥이 몸을 향하게 한 채 팔을 아래로 늘어뜨린다.,Step:2 등을 곧게 펴고 팔꿈치를 몸통에 가깝게 둔다.,Step:3 숨을 내쉬며 오른손 덤벨을 어깨 쪽으로 컬하되 상완은 고정한다.,Step:4 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:5 잠깐 멈춘 뒤, 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 왼팔도 같은 방식으로 수행한다.,Step:7 원하는 반복 횟수만큼 양팔을 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YAk5dIw', '리버스 그립 풀업', 'https://static.exercisedb.dev/media/YAk5dIw.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 언더핸드 그립으로 풀업 바를 어깨너비로 잡는다.,Step:2 팔을 완전히 편 채 바에 매달리고 몸을 곧게 유지한다.,Step:3 등 근육에 힘을 주어 가슴을 앞세우며 몸을 바 쪽으로 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 계속 당긴다.,Step:5 정점에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('weoDEpH', '캡틴 체어 직선 다리 올리기', 'https://static.exercisedb.dev/media/weoDEpH.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 Sit on the captain\'s chair with your back against the backrest and your forearms resting on the arm pads.,Step:2 Keep your upper body stable and your back straight.,Step:3 Engage your abs and lift your legs up in front of you, keeping them straight.,Step:4 Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.,Step:5 Pause for a moment at the top, then slowly lower your legs back down to the starting position.,Step:6 Repeat for the desired number of repetitions.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SiWCcTN', '파워 클린', 'https://static.exercisedb.dev/media/SiWCcTN.gif', '햄스트링', '허벅지', '바벨', '둔근,대퇴사두근,종아리근', 'Step:1 바벨을 앞에 두고 발을 어깨너비로 벌린 채 선다.,Step:2 상체를 숙여 바벨을 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 등을 곧게 펴고 가슴을 든 채 엉덩이와 무릎을 펴며 바벨을 들어 올린다.,Step:4 바벨이 허벅지 중간 높이에 오면 폭발적으로 끌어올리며 어깨를 으쓱하고 팔꿈치를 높게 옆으로 당긴다.,Step:5 바벨이 최고점에 도달하면 빠르게 아래로 들어가 팔꿈치를 회전시키며 프런트 스쿼트 자세로 어깨에 바벨을 받는다.,Step:6 일어서며 엉덩이와 무릎을 완전히 펴준다.,Step:7 무게를 컨트롤하며 바벨을 시작 자세로 내려놓는다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Dsfz0Id', 'ez 바 시티드 클로즈 그립 컨센트레이션 컬', 'https://static.exercisedb.dev/media/Dsfz0Id.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 벤치에 앉아 언더핸드 그립으로 EZ 바를 잡는다.,Step:2 팔꿈치를 허벅지 안쪽(무릎 바로 위)에 댄다.,Step:3 상완을 고정한 채 EZ 바를 어깨 쪽으로 컬한다.,Step:4 정점에서 이두근을 조여준 뒤, EZ 바를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kMzUs9Y', '포워드 런지(남성)', 'https://static.exercisedb.dev/media/kMzUs9Y.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 엉덩이너비로 벌리고 서서 손은 허리에 둔다.,Step:2 오른발을 크게 앞으로 내딛으며 런지 자세로 내려간다.,Step:3 오른 무릎을 약 90도로 굽히고 무릎이 발목 위에 오도록 정렬한다.,Step:4 오른발로 밀어내며 시작 자세로 돌아온다.,Step:5 왼발로 반복하며 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Zwiw7XR', '짐 볼 위에 다리를 올린 덤벨 ??교대 바이셉스 컬', 'https://static.exercisedb.dev/media/Zwiw7XR.gif', '이두근', '상완이두근', '덤벨', '전완근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥이 정면을 향하게 한다.,Step:2 뒤에 짐 볼을 두고 한쪽 발을 공 위에 올려 균형을 잡는다.,Step:3 팔을 완전히 편 채 팔꿈치를 몸 옆에 붙이고, 한쪽 덤벨을 어깨 쪽으로 컬하며 상완은 고정한다.,Step:4 덤벨을 천천히 내려 시작 자세로 돌아온 뒤 반대 팔로 반복한다.,Step:5 원하는 반복 횟수만큼 양팔을 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('X6C6i5Y', '삼두근 딥', 'https://static.exercisedb.dev/media/X6C6i5Y.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치/의자 끝에 앉아 손으로 끝을 잡고 손가락이 정면을 향하게 한다.,Step:2 엉덩이를 벤치 밖으로 빼고 손으로 체중을 지탱한다.,Step:3 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 등을 벤치에 가깝게 유지한다.,Step:4 아래에서 잠깐 멈춘 뒤, 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7I6LNUG', '레버 좌석 행', 'https://static.exercisedb.dev/media/7I6LNUG.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이와 발 지지대를 편한 위치로 조절한다.,Step:2 가슴을 패드에 대고 앉아 발을 발 지지대에 둔다.,Step:3 손잡이를 오버핸드 그립으로 어깨너비로 잡는다.,Step:4 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 손잡이를 몸 쪽으로 당기며 견갑골을 조여준다.,Step:6 수축 지점에서 잠깐 멈춘다.,Step:7 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DgZQ11d', 'ez 바벨 디클라인 클로즈 그립 페이스 프레스', 'https://static.exercisedb.dev/media/DgZQ11d.gif', '삼두근', '상완이두근', 'EZ 바벨', '가슴,어깨', 'Step:1 디클라인 벤치에 누워 머리가 발보다 낮게 오게 한다.,Step:2 손바닥이 서로 마주보게 클로즈 그립으로 EZ 바를 잡는다.,Step:3 팔을 가슴 위로 곧게 펴 올리되 팔꿈치는 몸에 가깝게 둔다.,Step:4 팔꿈치를 굽혀 EZ 바를 이마 쪽으로 천천히 내린다.,Step:5 잠깐 멈춘 뒤, EZ 바를 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9GXrTE6', '스미스 원 레그 플로어 카프 레이즈', 'https://static.exercisedb.dev/media/9GXrTE6.gif', '종아리근', '종아리', '스미스 머신', '햄스트링,둔근', 'Step:1 스미스 바 아래 바닥에 위치하되 머신을 등지고 선다.,Step:2 발 앞꿈치를 원판이나 블록 같은 높은 지지대에 둔다.,Step:3 스미스 바를 발목 바로 위(종아리 아래쪽) 다리 위에 올린다.,Step:4 안정성을 위해 손으로 바를 잡는다.,Step:5 발목을 펴서 뒤꿈치를 들어 올린다.,Step:6 정점에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Q6bvyen', '똑바로 매달기 비틀기 다리 엉덩이 올리기', 'https://static.exercisedb.dev/media/Q6bvyen.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 다리는 곧게 편다.,Step:2 코어에 힘을 주고 다리를 가슴 쪽으로 들어 올리되 다리는 곧게 유지한다.,Step:3 다리가 바닥과 평행이 되면 엉덩이를 한쪽으로 비틀어 다리를 그쪽으로 가져간다.,Step:4 잠깐 멈춘 뒤 시작 자세로 돌아온다.,Step:5 이번에는 반대쪽으로 엉덩이를 비틀어 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZnJHhMk', '레버 시트 크런치(가슴 패드)', 'https://static.exercisedb.dev/media/ZnJHhMk.gif', '복근', '허리', '레버리지 머신', '복사근', 'Step:1 좌석 높이와 가슴 패드 위치를 편한 상태로 조절한다.,Step:2 가슴 패드에 등을 대고 앉아 발을 바닥에 둔다.,Step:3 안정성을 위해 손잡이나 옆 바를 잡는다.,Step:4 복근에 힘을 주고 천천히 뒤로 기울여 가슴 패드가 함께 움직이게 한다.,Step:5 최대 수축 지점에서 잠깐 멈추며 복근의 긴장을 느낀다.,Step:6 복근을 수축해 상체를 다시 끌어올리며 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hHy8tQG', '짐 볼에 케이블 원 암 플라이', 'https://static.exercisedb.dev/media/hHy8tQG.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손으로 케이블 핸들을 잡고 팔을 옆으로 뻗어 바닥과 평행이 되게 한다.,Step:3 팔꿈치를 살짝 굽히고 손바닥은 정면을 향하게 한다.,Step:4 팔을 몸 앞으로 가져오며 가슴을 수축한다.,Step:5 끝 지점에서 잠깐 멈춘 뒤, 팔을 천천히 되돌려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cJgSTmh', '오블리크 크런치 v. 2', 'https://static.exercisedb.dev/media/cJgSTmh.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두거나 가슴 위에 교차해 둔다.,Step:3 복근에 힘을 주고 어깨를 바닥에서 들어 올리며 몸통을 한쪽으로 회전한다.,Step:4 잠깐 멈춘 뒤, 어깨를 천천히 내려 시작 자세로 돌아온다.,Step:5 반대쪽도 같은 방식으로 수행한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0CXGHya', '케이블 크로스오버 변형', 'https://static.exercisedb.dev/media/0CXGHya.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 풀리를 가슴 높이에 맞춘다.,Step:2 케이블 머신 중앙에 서서 한 발을 앞으로 둔다.,Step:3 손바닥이 아래를 향하도록 손잡이를 잡고 팔을 옆으로 벌려 뻗는다.,Step:4 한 걸음 앞으로 나가되 팔꿈치는 살짝 굽힌 상태를 유지한다.,Step:5 팔꿈치를 살짝 굽힌 채 양손을 가슴 앞에서 모은다.,Step:6 잠깐 멈춘 뒤, 팔을 천천히 벌려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('D1xYJAU', '벤치 손목 컬 위의 덤벨', 'https://static.exercisedb.dev/media/D1xYJAU.gif', '전완근', '팔 아래', '덤벨', '이두근,상완근', 'Step:1 벤치에 앉아 전완을 벤치 위에 두고 손바닥이 위를 향하게 하여 덤벨을 잡는다.,Step:2 손목이 벤치 끝 밖으로 나오게 둔다.,Step:3 손목을 위로 말아 올려 전완을 수축한다.,Step:4 정점에서 잠깐 멈춘 뒤, 손목을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gGNQmVt', '바벨 싱글 레그 스플릿 스쿼트', 'https://static.exercisedb.dev/media/gGNQmVt.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 상부 등에 올린다.,Step:2 한쪽 다리를 크게 앞으로 내딛고 상체를 곧게 유지한다.,Step:3 앞다리의 무릎과 고관절을 굽혀 내려가되 뒷다리는 곧게 유지한다.,Step:4 앞 허벅지가 바닥과 평행이 될 때까지 내려간다.,Step:5 잠깐 멈춘 뒤, 앞발 뒤꿈치로 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6MfS53i', '덤벨 거짓말 단일 익스텐션', 'https://static.exercisedb.dev/media/6MfS53i.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 누워 한 손에 덤벨을 들고 팔을 가슴 위로 완전히 편다.,Step:2 상완을 고정한 채 덤벨을 이마 쪽으로 컨트롤하며 천천히 내린다.,Step:3 아래 지점에서 잠깐 멈춘 뒤, 팔을 펴 덤벨을 시작 자세로 올린다.,Step:4 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LL1UiTX', '덤벨 인클라인 원 암 해머 프레스', 'https://static.exercisedb.dev/media/LL1UiTX.gif', '삼두근', '상완이두근', '덤벨', '어깨,가슴', 'Step:1 인클라인 벤치에 앉아 한 손에 덤벨을 들고 허벅지 위에 올려둔다.,Step:2 벤치에 기대며 허벅지로 덤벨을 보조해 어깨 높이까지 올린다.,Step:3 손목을 회전해 손바닥이 몸 안쪽을 향하게 한다.,Step:4 팔을 위로 밀어 올리고 몸에서 약간 바깥쪽으로 보내며 완전히 편다.,Step:5 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qCNVnaU', '슬레이 45° 종아리 프레스', 'https://static.exercisedb.dev/media/qCNVnaU.gif', '종아리근', '종아리', '슬레이 기계', '햄스트링', 'Step:1 슬레이 머신을 45도 각도로 맞춘다.,Step:2 발을 슬레이 발판에 올리고 발끝은 정면을 향하게 둔다.,Step:3 발목을 펴 종아리로 발판을 밀어낸다.,Step:4 정점에서 잠깐 멈춘 뒤, 발판을 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XPUDTt7', '파이크 투 코브라 푸시업', 'https://static.exercisedb.dev/media/XPUDTt7.gif', '둔근', '허벅지', '맨몸', '코어,어깨,삼두근', 'Step:1 푸쉬업 자세에서 손은 어깨너비보다 약간 넓게, 발은 모아 둔다.,Step:2 코어에 힘을 주고 엉덩이를 천장 쪽으로 들어 올려 몸이 역V(파이크) 형태가 되게 한다.,Step:3 팔꿈치를 굽혀 상체를 바닥 쪽으로 내리되 팔꿈치는 몸에 가깝게 유지한다.,Step:4 내려가며 체중을 앞으로 이동시키고 팔을 펴 가슴을 들어 올려 코브라 자세로 전환한다.,Step:5 팔꿈치를 굽혀 가슴을 다시 바닥 쪽으로 내리며 동작을 되돌린다.,Step:6 손으로 바닥을 밀어 역V 자세로 돌아온다.,Step:7 엉덩이를 다시 내려 푸쉬업 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kTbSH9h', '바벨 시티드 오버헤드 프레스', 'https://static.exercisedb.dev/media/kTbSH9h.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 바벨을 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 바벨을 랙에서 빼 어깨 높이에 두고 팔꿈치는 굽힌 채 손바닥이 정면을 향하게 한다.,Step:4 팔을 완전히 펴며 바벨을 머리 위로 밀어 올린다.,Step:5 정점에서 잠깐 멈춘 뒤, 바벨을 천천히 내려 어깨 높이로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('903mzG8', '스미스 숄더 프레스', 'https://static.exercisedb.dev/media/903mzG8.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 좌석 높이를 조절하고 스미스 머신 아래에 자리 잡은 뒤 발을 어깨너비로 둔다.,Step:2 바를 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 바를 랙에서 빼 어깨 높이에 두고 팔꿈치는 굽힌 채 손바닥이 정면을 향하게 한다.,Step:4 팔을 완전히 펴며 바를 위로 밀어 올린다.,Step:5 정점에서 잠깐 멈춘 뒤, 바를 천천히 내려 어깨 높이로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PskORrA', '케이블 푸시다운(스트레이트 암) v. 2', 'https://static.exercisedb.dev/media/PskORrA.gif', '광배근', '등', '케이블', '삼두근,어깨', 'Step:1 하이 풀리 케이블 머신에 스트레이트 바를 연결한다.,Step:2 머신을 마주보고 서서 발을 어깨너비로 두고 무릎을 살짝 굽힌다.,Step:3 오버핸드 그립으로 바를 잡고 팔을 곧게 펴 손바닥이 아래를 향하게 한다.,Step:4 코어에 힘을 주고 등을 곧게 유지한 채 숨을 내쉬며 바를 허벅지 쪽으로 아래로 밀어 내린다.,Step:5 아래에서 잠깐 멈춘 뒤, 숨을 들이마시며 바를 천천히 시작 자세로 되돌린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8urJS9b', '가중 하이퍼신전(안정성 공)', 'https://static.exercisedb.dev/media/8urJS9b.gif', '척추', '등', '가중', '둔근,햄스트링', 'Step:1 안정성 공 위에 엎드려 골반을 공에 올리고, 안정성을 위해 발을 벽에 댄다.,Step:2 손을 머리 뒤에 두거나 가슴 위에 교차해 둔다.,Step:3 코어에 힘을 주고 상체를 천천히 들어 올려 등을 펴며 몸이 일직선이 되게 한다.,Step:4 정점에서 잠깐 멈춘 뒤, 상체를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7gdLIXa', '덤벨 라이 해머 프레스', 'https://static.exercisedb.dev/media/7gdLIXa.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 벤치에 누워 양손에 덤벨을 들고 손바닥이 서로 마주보게 하여 팔을 가슴 위로 곧게 편다.,Step:2 팔꿈치를 90도로 유지하며 덤벨을 가슴 옆으로 내린다.,Step:3 팔을 펴며 덤벨을 다시 시작 자세로 밀어 올린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bQy2Eni', '덤벨 한쪽 팔 리베이트', 'https://static.exercisedb.dev/media/bQy2Eni.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 오른손에 덤벨을 든다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 유지한다.,Step:3 오른 팔꿈치를 몸 옆으로 들어 올려 90도로 굽힌다.,Step:4 오른팔을 뒤로 곧게 펴며 삼두근을 수축한다.,Step:5 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Uto7l43', '가슴과 어깨 앞쪽 스트레칭', 'https://static.exercisedb.dev/media/Uto7l43.gif', '가슴근육', '가슴', '맨몸', '삼각근', 'Step:1 발을 어깨너비로 벌리고 곧게 선다.,Step:2 팔을 어깨 높이에서 앞으로 곧게 뻗는다.,Step:3 팔을 몸 앞에서 교차해 오른팔이 왼팔 위로 가게 한다.,Step:4 손가락을 깍지 끼고 손바닥을 서로 맞댄다.,Step:5 견갑골을 부드럽게 조이며 두 손을 앞으로 밀어 가슴과 어깨 앞쪽이 늘어나는 것을 느낀다.,Step:6 20–30초 동안 유지한 뒤 풀어준다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('laVRfDf', '덤벨 스탠딩 프론트 레이즈 머리 위로', 'https://static.exercisedb.dev/media/laVRfDf.gif', '삼각근', '어깨', '덤벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 양손에 덤벨을 든다.,Step:2 팔을 곧게 편 채 덤벨을 앞쪽으로 들어 올려 머리 위까지 올린다.,Step:3 정점에서 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('uL9CsKm', '발목 서클', 'https://static.exercisedb.dev/media/uL9CsKm.gif', '종아리근', '종아리', '맨몸', '발목 안정 장치', 'Step:1 바닥에 앉아 다리를 앞쪽으로 곧게 뻗는다.,Step:2 한쪽 다리를 바닥에서 들어 올리고 발목을 원을 그리며 회전시킨다.,Step:3 원하는 횟수만큼 한 방향으로 돌린 뒤 반대 방향으로도 수행한다.,Step:4 반대쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0L2KwtI', '롤러 힙 랫 스트레칭', 'https://static.exercisedb.dev/media/0L2KwtI.gif', '둔근', '허벅지', '롤러', '햄스트링,대퇴사두근', 'Step:1 롤러를 엉덩이 아래에 둔 상태로 바닥에 무릎을 꿇는다.,Step:2 손을 롤러 위에 두어 지지한다.,Step:3 롤러를 천천히 앞으로 굴리며 엉덩이를 신전해 둔부가 늘어나도록 한다.,Step:4 몇 초간 유지한 뒤 롤러를 굴려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yaMIo4D', '케이블 인클라인 벤치 로우', 'https://static.exercisedb.dev/media/yaMIo4D.gif', '등 위쪽', '등', '케이블', '이두근,후면 삼각근', 'Step:1 인클라인 벤치를 45도 각도로 세팅하고 로우 풀리에 케이블 핸들을 연결한다.,Step:2 케이블 머신을 향해 벤치에 앉아 발을 바닥에 두고 무릎을 살짝 굽힌다.,Step:3 오버핸드 그립으로 핸들을 잡고 팔을 앞쪽으로 완전히 편다.,Step:4 등을 곧게 유지하고 코어에 힘을 준 채 고관절에서 약간 앞으로 기울인다.,Step:5 견갑골을 모으며 팔꿈치를 굽혀 핸들을 가슴 쪽으로 당긴다.,Step:6 정점에서 등을 수축한 뒤, 팔을 천천히 펴 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('X3cqyXz', '레버가 줄 위로 구부러져 있음', 'https://static.exercisedb.dev/media/X3cqyXz.gif', '등 위쪽', '등', '바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 바벨을 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 엉덩이를 접어 상체를 숙이되 등을 곧게 펴고 가슴을 든다.,Step:4 바벨을 아래 가슴 쪽으로 당기며 견갑골을 조여준다.,Step:5 정점에서 잠깐 멈춘 뒤, 바벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Kyd9Rz5', '바벨 스탠딩 와이드 밀리터리 프레스', 'https://static.exercisedb.dev/media/Kyd9Rz5.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 오버핸드 그립으로 어깨너비보다 약간 넓게 잡는다.,Step:2 바벨을 어깨 높이로 들어 올리고 팔꿈치는 바 앞쪽에 약간 위치하게 한다.,Step:3 바벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:4 바벨을 다시 어깨 높이로 내려 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BCs0G2F', '바벨 앉아서 교대로 다리 올리기(여성)', 'https://static.exercisedb.dev/media/BCs0G2F.gif', '복근', '허리', '바벨', '고관절 굴근,대퇴사두근', 'Step:1 벤치에 앉아 등을 곧게 펴고 바벨을 허벅지 위에 둔다.,Step:2 지지력을 위해 손으로 벤치 옆을 잡는다.,Step:3 다리를 곧게 편 채 한쪽 다리를 가능한 한 높이 들어 올리되 바닥과 평행이 되게 한다.,Step:4 다리를 내려 시작 자세로 돌아온 뒤 반대쪽 다리로 반복한다.,Step:5 원하는 반복 횟수만큼 양쪽을 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jtFKbt5', 'ez 바벨 시티드 컬', 'https://static.exercisedb.dev/media/jtFKbt5.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 벤치에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 언더핸드 그립으로 EZ 바를 잡고 손바닥이 위를 향하게 하며 손은 어깨너비로 둔다.,Step:3 상완을 허벅지에 대어 EZ 바가 앞쪽으로 늘어지게 한다.,Step:4 상완을 고정한 채 숨을 내쉬며 EZ 바를 어깨 쪽으로 컬한다.,Step:5 정점에서 잠깐 멈추며 이두근을 조여준다.,Step:6 숨을 들이마시며 EZ 바를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vrhHa6D', '보조 평행 클로즈 그립 풀업', 'https://static.exercisedb.dev/media/vrhHa6D.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 머신의 무게(보조)를 원하는 수준으로 조절하고 높이를 맞춘다.,Step:2 평행봉을 손바닥이 서로 마주보게 클로즈 그립으로 잡는다.,Step:3 팔을 완전히 편 채 매달리고 발은 바닥에서 떼어 둔다.,Step:4 등 근육에 힘을 주고 팔꿈치를 몸에 가깝게 유지하며 몸을 위로 끌어올린다.,Step:5 턱이 봉 위로 올라갈 때까지 계속 당긴다.,Step:6 정점에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FQXdXzY', '덤벨 시티드 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/FQXdXzY.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 둔다.,Step:2 양손으로 덤벨을 오버핸드 그립으로 잡아 머리 위로 들어 올린다.,Step:3 팔꿈치를 굽혀 덤벨을 머리 뒤로 내리되 상완은 귀 옆에 가깝게 둔다.,Step:4 팔을 펴 덤벨을 시작 자세로 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nuBF9MO', '길로틴 파이크(약하게)', 'https://static.exercisedb.dev/media/nuBF9MO.gif', '복근', '허리', '맨몸', '고관절 굴근,어깨', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥이 정면을 향하게 한다.,Step:2 코어에 힘을 주고 다리를 바 쪽으로 들어 올리되 다리는 곧게 유지한다.,Step:3 몸이 V자 형태가 되고 다리가 바닥과 평행이 될 때까지 계속 들어 올린다.,Step:4 잠깐 유지한 뒤, 다리를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bjqbauy', '가중 스탠딩 핸드 스퀴즈', 'https://static.exercisedb.dev/media/bjqbauy.gif', '전완근', '팔 아래', '가중', '이두근,삼두근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 웨이트를 든다.,Step:2 팔을 앞쪽으로 곧게 뻗고 손바닥이 서로 마주보게 한다.,Step:3 손을 가능한 한 강하게 쥐어 전완에 힘을 준다.,Step:4 몇 초간 유지한 뒤 힘을 푼다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NbVPDMW', '덤벨 바이셉스 컬', 'https://static.exercisedb.dev/media/NbVPDMW.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 곧게 서서 손바닥이 정면을 향하게 하고 팔을 완전히 편다.,Step:2 상완을 고정한 채 숨을 내쉬며 덤벨을 컬하며 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:4 수축 지점에서 잠깐 멈추며 이두근을 조여준다.,Step:5 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DT14T9T', '케이블 스트레이트 암 풀다운(로프 포함)', 'https://static.exercisedb.dev/media/DT14T9T.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 케이블 머신의 가장 높은 위치에 로프를 연결한다.,Step:2 발을 어깨너비로 벌리고 머신을 마주보고 선다.,Step:3 양손으로 로프를 잡고 손바닥이 아래를 향하게 한다.,Step:4 팔을 앞쪽으로 완전히 뻗되 팔꿈치는 살짝 굽힌다.,Step:5 광배근에 힘을 주고 팔을 곧게 유지한 채 로프를 허벅지 쪽으로 천천히 내린다.,Step:6 아래에서 잠깐 멈춘 뒤, 장력을 천천히 풀며 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IGjKj1v', '레버 클로즈 그립 시티드 행잉', 'https://static.exercisedb.dev/media/IGjKj1v.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 올바른 자세가 나오도록 좌석 높이와 발 지지대를 조절한다.,Step:2 발을 발 지지대에 두고 앉아 무릎을 살짝 굽힌다.,Step:3 손바닥이 서로 마주보게 좁은 그립으로 손잡이를 잡는다.,Step:4 등을 곧게 펴고 상체를 약간 앞으로 기울인다.,Step:5 손잡이를 몸통 쪽으로 당기며 견갑골을 조여준다.,Step:6 수축 지점에서 잠깐 멈춘다.,Step:7 손잡이를 천천히 놓아 시작 자세로 돌아온다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iPm26QU', '한쪽 다리를 안정화한 채로 박스 점프 다운', 'https://static.exercisedb.dev/media/iPm26QU.gif', '종아리근', '종아리', '맨몸', '대퇴사두근,햄스트링,둔근', 'Step:1 박스/플랫폼 앞에 서서 발을 어깨너비로 둔다.,Step:2 무릎을 굽힌 뒤 박스 위로 점프해 한쪽 발은 박스 위에, 반대 발은 가장자리 밖으로 두고 부드럽게 착지한다.,Step:3 박스 위에 올라간 발로 균형을 잡고, 종아리에 힘을 주어 자세를 안정화한다.,Step:4 몇 초간 유지한다.,Step:5 박스 위에 있던 발로 천천히 내려와 시작 자세로 돌아온다.,Step:6 반대 다리로도 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('en550rk', '덤벨 리베이트(2)', 'https://static.exercisedb.dev/media/en550rk.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 벤치에 앉아 발을 바닥에 두고 양손에 덤벨을 든다.,Step:2 무릎을 살짝 굽히고 고관절에서 상체를 숙이되 등을 곧게 편다.,Step:3 상완을 몸 옆에 붙이고 팔꿈치를 90도로 굽힌다.,Step:4 팔을 뒤로 곧게 펴며 삼두근을 수축한다.,Step:5 잠깐 멈춘 뒤, 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7Hg55JG', '덤벨 클린', 'https://static.exercisedb.dev/media/7Hg55JG.gif', '둔근', '허벅지', '덤벨', '햄스트링,대퇴사두근,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 양손에 덤벨을 든다.,Step:2 무릎을 굽혀 엉덩이를 낮추고 등을 곧게 유지하며 스쿼트 자세로 내려간다.,Step:3 뒤꿈치로 강하게 밀며 엉덩이와 무릎을 폭발적으로 펴 점프하듯 일어선다.,Step:4 점프하면서 어깨를 으쓱하고 덤벨을 몸에 가깝게 유지한 채 어깨 높이까지 끌어올린다.,Step:5 덤벨을 어깨 높이에서 받되 팔꿈치는 앞을 향하고 손바닥은 위를 향하게 한다.,Step:6 동작을 반대로 하여 덤벨을 시작 자세로 내려놓는다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jvp6DiD', '팔꿈치부터 무릎까지', 'https://static.exercisedb.dev/media/jvp6DiD.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 등을 대고 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치는 바깥쪽을 향하게 한다.,Step:3 복근에 힘을 주고 상체를 들어 올리며 오른쪽 팔꿈치를 왼쪽 무릎 쪽으로 가져간다.,Step:4 동시에 왼쪽 무릎을 오른쪽 팔꿈치 쪽으로 끌어올려 비틀림을 만든다.,Step:5 정점에서 잠깐 멈춘 뒤, 상체를 내리고 다리를 펴 시작 자세로 돌아온다.,Step:6 이번에는 왼쪽 팔꿈치-오른쪽 무릎으로 반대쪽도 수행한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('myfUsKf', '레버 장착 리버스 플라이', 'https://static.exercisedb.dev/media/myfUsKf.gif', '삼각근', '어깨', '레버리지 머신', '승모근,능형근', 'Step:1 좌석 높이를 조절하고 가슴을 패드에 대고 발은 바닥에 둔다.,Step:2 오버핸드 그립으로 손잡이를 잡고 팔꿈치는 살짝 굽힌다.,Step:3 숨을 내쉬며 손잡이를 뒤/바깥쪽으로 당겨 견갑골을 조여준다.,Step:4 최대 수축 지점에서 잠깐 멈춘 뒤, 숨을 들이마시며 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Nu7jqFE', '저항 밴드는 바로 뒷줄에 앉아 있습니다.', 'https://static.exercisedb.dev/media/Nu7jqFE.gif', '등 위쪽', '등', '저항 밴드', '이두근,어깨', 'Step:1 바닥에 앉아 다리를 뻗고 저항 밴드를 발에 걸어 고정한다.,Step:2 양손으로 밴드 끝을 잡고 손바닥이 서로 마주보게 한다.,Step:3 등을 곧게 펴고 상체를 약간 뒤로 기울이며 코어에 힘을 준다.,Step:4 밴드를 가슴 쪽으로 당기며 견갑골을 조여준다.,Step:5 정점에서 잠깐 멈춘 뒤, 장력을 천천히 풀며 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YIUAtYf', '가중 러시안 트위스트 v. 2', 'https://static.exercisedb.dev/media/YIUAtYf.gif', '복근', '허리', '가중', '복사근,허리', 'Step:1 바닥에 앉아 무릎을 굽히고 발을 바닥에 둔다.,Step:2 양손으로 웨이트를 가슴 앞에 든다.,Step:3 상체를 살짝 뒤로 기울여 코어를 활성화한다.,Step:4 몸통을 오른쪽으로 비틀어 웨이트를 몸 오른쪽으로 가져간다.,Step:5 잠깐 멈춘 뒤, 몸통을 왼쪽으로 비틀어 웨이트를 몸 왼쪽으로 가져간다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jHAnWmT', '레버 인클라인 체스트 프레스', 'https://static.exercisedb.dev/media/jHAnWmT.gif', '가슴근육', '가슴', '레버리지 머신', '어깨,삼두근', 'Step:1 레버리지 머신의 좌석과 등받이를 편한 위치로 조절한다.,Step:2 등받이에 등을 대고 앉아 발을 바닥에 둔다.,Step:3 오버핸드 그립으로 손잡이를 잡고 손 위치는 어깨너비보다 약간 넓게 둔다.,Step:4 손잡이를 앞으로 밀어 팔을 완전히 편다.,Step:5 잠깐 멈춘 뒤, 팔꿈치를 굽혀 손잡이를 가슴 쪽으로 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G08RZcQ', '케이블 컬', 'https://static.exercisedb.dev/media/G08RZcQ.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신을 마주보고 서서 발을 어깨너비로 벌린다.,Step:2 언더핸드 그립으로 케이블 손잡이를 잡아 손바닥이 위를 향하게 한다.,Step:3 팔꿈치를 몸 옆에 붙이고 상완을 고정한다.,Step:4 숨을 내쉬며 손잡이를 어깨 쪽으로 컬하며 이두근을 수축한다.,Step:5 정점에서 잠깐 멈추며 이두근을 조여준다.,Step:6 숨을 들이마시며 손잡이를 천천히 내려 시작 자세로 돌아온다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gm2Uv1z', '짐볼 앙와위 삼두근 익스텐션', 'https://static.exercisedb.dev/media/Gm2Uv1z.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 짐 볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 양손으로 덤벨을 들고 팔을 천장 쪽으로 곧게 편다.,Step:3 팔꿈치를 귀 옆에 가깝게 유지하며 덤벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤, 덤벨을 다시 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('C0eCeEt', '비틀린 다리 올리기', 'https://static.exercisedb.dev/media/C0eCeEt.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔은 몸 옆에 둔다.,Step:2 지지를 위해 손을 둔근 아래에 둔다.,Step:3 복근에 힘을 주고 양다리를 곧게 유지한 채 바닥에서 들어 올린다.,Step:4 다리를 올리며 엉덩이를 한쪽으로 비틀어 반대쪽 어깨 방향으로 다리를 가져간다.,Step:5 정점에서 잠깐 멈춘 뒤, 다리를 천천히 내려 시작 자세로 돌아온다.,Step:6 이번에는 반대쪽으로 엉덩이를 비틀어 반복한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qatbkEd', '케이블 사이드 벤드 크런치(보수볼)', 'https://static.exercisedb.dev/media/qatbkEd.gif', '복근', '허리', '케이블', '복사근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 케이블 손잡이를 잡는다.,Step:2 반대 손은 허리에 둔다.,Step:3 코어에 힘을 주고 등을 곧게 유지한 채 케이블을 잡은 쪽으로 옆구리를 천천히 굽힌다.,Step:4 아래 지점에서 잠깐 멈춘 뒤, 천천히 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 수행한 뒤 반대쪽도 실시한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ye5Qxb0', 'ez 바벨 스파이더 컬', 'https://static.exercisedb.dev/media/Ye5Qxb0.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 언더핸드 그립으로 EZ 바를 잡아 손바닥이 위를 향하게 한다.,Step:2 상완을 프리처 벤치나 안정성 볼 위에 올려 팔꿈치가 아래로 자연스럽게 떨어지게 한다.,Step:3 상완을 고정한 채 숨을 내쉬며 EZ 바를 어깨 쪽으로 컬한다.,Step:4 정점에서 잠깐 멈추며 이두근을 조여준다.,Step:5 숨을 들이마시며 EZ 바를 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('wigSg76', '박수치기', 'https://static.exercisedb.dev/media/wigSg76.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 하이 플랭크 자세에서 손을 어깨너비보다 약간 넓게 둔다.,Step:2 코어에 힘을 준 채 팔꿈치를 굽혀 몸을 바닥 쪽으로 내린다.,Step:3 손바닥으로 강하게 밀어 몸을 바닥에서 띄운다.,Step:4 공중에서 양손을 모아 박수를 친 뒤 시작 자세로 착지한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('slDvUAU', '덤벨 해머 컬', 'https://static.exercisedb.dev/media/slDvUAU.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 곧게 서서 손바닥이 몸을 향하게 한다.,Step:2 팔꿈치를 몸통에 가깝게 유지하며 손바닥을 회전해 정면을 향하게 한다.,Step:3 이것이 시작 자세이다.,Step:4 상완을 고정한 채 숨을 내쉬며 덤벨을 컬하며 이두근을 수축한다.,Step:5 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 들어 올린다.,Step:6 수축 지점에서 잠깐 멈추며 이두근을 조여준다.,Step:7 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:8 권장 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CbFSYC1', '후면 풀업', 'https://static.exercisedb.dev/media/CbFSYC1.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 오버핸드 그립으로 풀업 바를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:2 팔을 완전히 편 채 바에 매달리고 몸을 곧게 유지한다.,Step:3 등 근육에 힘을 주고 팔꿈치를 몸에 가깝게 유지하며 몸을 바 쪽으로 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 계속 당긴다.,Step:5 정점에서 잠깐 멈춘 뒤, 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sxY5Biu', '덤벨 원 암 zottman 설교자 컬', 'https://static.exercisedb.dev/media/sxY5Biu.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 프리처 컬 벤치에 앉아 한 손에 덤벨을 언더핸드 그립으로 잡는다.,Step:2 상완을 패드에 대고 팔이 완전히 펴지게 둔다.,Step:3 상완을 고정한 채 덤벨을 어깨 쪽으로 컬한다.,Step:4 컬의 정점에서 손목을 회전해 손바닥이 위를 향하게 한다.,Step:5 손목을 다시 회전시키며 덤벨을 천천히 내려 시작 자세로 돌아온다.,Step:6 원하는 반복 횟수만큼 수행한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('py1HSzx', '바벨 사이드 런지', 'https://static.exercisedb.dev/media/py1HSzx.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 바벨을 상부 등에 올린다.,Step:2 오른발을 옆으로 크게 내딛고 왼발은 고정한다.,Step:3 오른 무릎을 굽혀 런지로 내려가되 왼다리는 곧게 유지한다.,Step:4 오른발로 밀어내며 시작 자세로 돌아온다.,Step:5 왼쪽도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('W8KAlkI', '푸쉬업 메디신볼', 'https://static.exercisedb.dev/media/W8KAlkI.gif', '가슴근육', '가슴', '메디신볼', '삼두근,어깨,코어', 'Step:1 메디신볼 위에 손을 올리고 하이 플랭크 자세를 취하되 손 너비는 어깨너비로 둔다.,Step:2 코어에 힘을 주고 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 등을 곧게 유지한다.,Step:3 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ykUOVze', '레버 스탠딩 종아리 들어올리기', 'https://static.exercisedb.dev/media/ykUOVze.gif', '종아리근', '종아리', '레버리지 머신', '가자미근,발목 안정 장치', 'Step:1 키에 맞게 머신을 조절하고 발을 어깨너비로 벌린 채 선다.,Step:2 어깨를 패드 아래에 넣고 안정성을 위해 손잡이를 잡는다.,Step:3 발목을 펴 뒤꿈치를 가능한 한 높이 들어 올린다.,Step:4 정점에서 잠깐 멈춘 뒤, 뒤꿈치를 천천히 내려 시작 자세로 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('I4tibZG', '케틀벨 크로스 클린 행잉', 'https://static.exercisedb.dev/media/I4tibZG.gif', '전완근', '팔 아래', '케틀벨', '어깨,승모근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 양손에 케틀벨을 든다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 숙이되 등을 곧게 펴고 가슴을 든다.,Step:3 팔을 완전히 편 채 케틀벨이 몸 앞에서 자연스럽게 늘어지게 한다.,Step:4 한 동작으로 엉덩이를 폭발적으로 펴며 어깨를 으쓱하고 케틀벨을 어깨 높이까지 끌어올린다.,Step:5 케틀벨이 어깨 높이에 오면 손목을 회전시켜 랙 포지션에서 받되 손바닥은 안쪽을 향하고 케틀벨은 전완 바깥쪽에 놓이게 한다.,Step:6 케틀벨을 다시 시작 자세로 내리고 반대 팔로 반복한다.,Step:7 원하는 반복 횟수만큼 양팔을 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EKXOMEh', '덤벨 리어 델트 (하부견갑)', 'https://static.exercisedb.dev/media/EKXOMEh.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 양손에 덤벨을 들고 손바닥이 몸을 향하게 잡는다.,Step:3 허리에서 상체를 앞으로 숙이되 등을 곧게 유지하고 코어에 힘을 준다.,Step:4 팔을 바닥 쪽으로 곧게 늘어뜨리되 팔꿈치는 살짝 굽힌다.,Step:5 덤벨을 양옆으로 들어올리며 견갑골을 모아 어깨뼈를 조인다.,Step:6 최상단에서 잠깐 멈춘 뒤 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eYmsEPR', '케이블 리버스 리스트 컬', 'https://static.exercisedb.dev/media/eYmsEPR.gif', '전완근', '팔 아래', '케이블', '전완근,손목', 'Step:1 낮은 풀리에 케이블을 연결하고 벤치에 앉아 케이블 머신을 마주본다.,Step:2 오버핸드 그립으로 핸들을 잡아 손바닥이 아래를 보게 한다.,Step:3 전완을 허벅지 위에 올리고 손목이 가장자리 밖으로 나오게 둔다.,Step:4 전완은 고정한 채 숨을 내쉬며 손목을 위로 최대한 말아 올린다.,Step:5 최상단에서 잠깐 멈춘 뒤 숨을 들이마시며 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XU3ePuv', '케이블 스탠딩 크런치(로프 부착 포함)', 'https://static.exercisedb.dev/media/XU3ePuv.gif', '복근', '허리', '케이블', '복사근', 'Step:1 가슴 높이에 케이블 머신에 로프를 부착한다.,Step:2 머신을 등지고 서서 발을 어깨너비로 벌린다.,Step:3 로프를 양손으로 잡아 머리 뒤로 가져가고 팔꿈치는 굽힌다.,Step:4 복근에 힘을 주고 상체를 천천히 말아 내려 팔꿈치가 무릎 쪽으로 향하게 한다.,Step:5 크런치 최하단에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Kal9cQQ', '어드밴스드 케틀벨 윈드밀', 'https://static.exercisedb.dev/media/Kal9cQQ.gif', '복근', '허리', '케틀벨', '복사근,어깨', 'Step:1 발을 어깨너비보다 넓게 벌리고 발끝을 약간 바깥으로 둔다.,Step:2 오른손에 케틀벨을 들고 팔을 머리 위로 곧게 뻗어 손바닥이 앞을 보게 한다.,Step:3 왼발을 오른쪽으로 약간 회전시키고 체중을 왼다리에 싣는다.,Step:4 왼쪽 무릎을 굽히고 힙 힌지를 하며 상체를 왼쪽으로 내려간다.,Step:5 오른팔은 머리 위로 곧게 유지하고 시선은 케틀벨에 둔다.,Step:6 상체를 내리면서 오른다리는 펴지고 오른발은 약간 회전하도록 둔다.,Step:7 왼쪽 햄스트링이 늘어나는 느낌이 들고 오른팔이 바닥을 향할 때까지 상체를 내린다.,Step:8 잠깐 멈춘 뒤 코어에 힘을 주고 왼발 뒤꿈치로 밀어 시작 자세로 돌아간다.,Step:9 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xTjr103', '스트랩을 이용한 스탠딩 햄스트링 및 종아리 스트레칭', 'https://static.exercisedb.dev/media/xTjr103.gif', '햄스트링', '허벅지', '로프', '종아리근', 'Step:1 발을 어깨너비로 벌리고 곧게 선다.,Step:2 양손으로 스트랩을 잡아 발앞쪽 볼 부분에 건다.,Step:3 다리를 곧게 유지한 채 엉덩이를 기준으로 상체를 천천히 앞으로 기울이며 등을 곧게 유지한다.,Step:4 햄스트링과 종아리가 늘어나는 것을 느낀다.,Step:5 20–30초 동안 유지한다.,Step:6 스트레치를 풀고 반대쪽 다리도 반복한다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CFN9P8G', '짐 볼에 ez 바 프렌치 프레스', 'https://static.exercisedb.dev/media/CFN9P8G.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 짐볼에 앉아 EZ 바벨을 오버핸드 그립으로 잡는다.,Step:2 팔을 머리 위로 곧게 뻗고 팔꿈치를 머리 가까이에 둔다.,Step:3 팔꿈치를 굽혀 바벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 팔을 펴서 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LNE3wfo', '단일 다리 플랫폼 슬라이드', 'https://static.exercisedb.dev/media/LNE3wfo.gif', '햄스트링', '허벅지', '맨몸', '둔근,대퇴사두근', 'Step:1 한쪽 발을 플랫폼 또는 슬라이드 보드 위에 올리고 선다.,Step:2 무릎을 살짝 굽힌 뒤 발을 뒤로 미끄러뜨리며 다리를 펴 준다.,Step:3 코어에 힘을 주고 동작 내내 자세를 곧게 유지한다.,Step:4 발을 다시 미끄러뜨려 시작 자세로 천천히 돌아온다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tTuZSDT', '레버 한쪽 팔 사이드 와이드 풀다운', 'https://static.exercisedb.dev/media/tTuZSDT.gif', '광배근', '등', '레버리지 머신', '이두근,능형근,후면 삼각근', 'Step:1 시트 높이를 조절하고 가슴을 패드에 대고 앉아 발을 바닥에 둔다.,Step:2 오버핸드 그립으로 핸들을 잡고 팔을 거의 완전히 펴되 팔꿈치는 살짝 굽힌다.,Step:3 핸들을 아래로 당겨 반대쪽 엉덩이 방향으로 가로질러 내리며 광배근을 수축한다.,Step:4 핸들을 천천히 시작 자세로 돌려 팔을 다시 펴 준다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fgc9Xdl', '케이블 스탠딩 한쪽 다리 종아리 들어올리기', 'https://static.exercisedb.dev/media/fgc9Xdl.gif', '종아리근', '종아리', '케이블', '발목,피트', 'Step:1 케이블 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:2 균형을 위해 머신을 잡는다.,Step:3 한쪽 다리를 들어 바닥에서 떼고 다른 다리로 선다.,Step:4 뒤꿈치를 천천히 들어 올려 발끝으로 올라선다.,Step:5 최상단에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('RVwzP10', '케이블 풀다운', 'https://static.exercisedb.dev/media/RVwzP10.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 좌석이 편한 높이가 되도록 조절하고 무릎 패드를 고정한다.,Step:2 허리를 곧게 펴고 앉아 발을 바닥에 둔다.,Step:3 어깨너비보다 약간 넓게 오버핸드 그립으로 바를 잡는다.,Step:4 상체를 약간 뒤로 기울이고 코어에 힘을 준다.,Step:5 바를 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 최하단에서 잠깐 멈춘 뒤 바를 천천히 올려 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G8dXpNG', 'ez 바 리버스 그립 벤트 오버 로우', 'https://static.exercisedb.dev/media/G8dXpNG.gif', '등 위쪽', '등', 'EZ 바벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 언더핸드 그립으로 EZ 바를 잡아 손바닥이 위를 보게 하고 손은 어깨너비로 둔다.,Step:3 엉덩이에서 힌지해 상체를 숙이되 등을 곧게, 가슴은 들어 바닥과 거의 평행이 되게 한다.,Step:4 EZ 바를 아랫가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 최상단에서 잠깐 멈춘 뒤 EZ 바를 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9JprnPh', '밴드 싱글 레그 카프 레이즈', 'https://static.exercisedb.dev/media/9JprnPh.gif', '종아리근', '종아리', '밴드', '발목,피트', 'Step:1 발을 골반너비로 벌리고 선 뒤 밴드를 왼발의 앞꿈치(볼) 부분에 건다.,Step:2 필요하면 균형을 위해 고정된 물체를 잡는다.,Step:3 왼쪽 뒤꿈치를 천천히 들어 올려 발앞꿈치에 체중을 싣는다.,Step:4 최상단에서 잠깐 멈춘 뒤 왼쪽 뒤꿈치를 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 오른쪽으로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DKBwJrL', '밴드 한쪽 팔 트위스트 시트 로우', 'https://static.exercisedb.dev/media/DKBwJrL.gif', '등 위쪽', '등', '밴드', '이두근,어깨', 'Step:1 벤치나 의자에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손으로 밴드를 잡고 팔을 앞쪽으로 완전히 뻗는다.,Step:3 등을 곧게 유지한 채 팔꿈치를 굽혀 밴드를 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:4 당기는 팔 쪽으로 상체를 함께 비튼다.,Step:5 최상단에서 잠깐 멈춘 뒤 밴드의 장력을 천천히 풀고 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FSD6PGL', '짐 볼에 덤벨 풀오버', 'https://static.exercisedb.dev/media/FSD6PGL.gif', '가슴근육', '가슴', '덤벨', '삼두근,광배근', 'Step:1 짐볼에 앉아 양손으로 덤벨을 가슴 위로 들어 팔을 뻗는다.,Step:2 팔을 곧게 유지한 채 덤벨을 머리 뒤로 천천히 내린다.,Step:3 잠깐 멈춘 뒤 덤벨을 시작 자세로 다시 들어 올린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('enxnJcM', '쿼터 윗몸일으키기', 'https://static.exercisedb.dev/media/enxnJcM.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 무릎을 굽혀 발을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치는 바깥으로 향하게 한다.,Step:3 복근에 힘을 주고 상체를 천천히 들어 올려 몸통이 약 45도 각도가 될 때까지 말아 올린다.,Step:4 최상단에서 잠깐 멈춘 뒤 상체를 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qBcKorM', '네 발로 하는 스쿼드 스트레칭', 'https://static.exercisedb.dev/media/qBcKorM.gif', '대퇴사두근', '허벅지', '맨몸', '햄스트링,둔근', 'Step:1 손은 어깨 아래, 무릎은 엉덩이 아래에 두고 네발기기 자세로 시작한다.,Step:2 한쪽 다리를 뒤로 곧게 뻗되 무릎은 굽힌 상태로 두고 발끝은 당긴다.,Step:3 엉덩이를 천천히 바닥 쪽으로 낮춰 대퇴근이 늘어나는 것을 느낀다.,Step:4 20–30초 동안 유지한다.,Step:5 반대쪽 다리도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xiHiJcA', '레버 시트 리버스 플라이(평행 그립)', 'https://static.exercisedb.dev/media/xiHiJcA.gif', '삼각근', '어깨', '레버리지 머신', '승모근,능형근', 'Step:1 시트 높이를 조절하고 가슴을 패드에 대고 앉아 발을 바닥에 둔다.,Step:2 평행 그립으로 핸들을 잡아 손바닥이 서로 마주 보게 하고 팔은 약간 굽힌다.,Step:3 숨을 내쉬며 핸들을 뒤쪽·바깥쪽으로 당겨 견갑골을 모아 조인다.,Step:4 수축 지점에서 잠깐 멈춘 뒤 숨을 들이마시며 천천히 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SHUMp5H', '덤벨 쇠퇴 원 암 해머 프레스', 'https://static.exercisedb.dev/media/SHUMp5H.gif', '삼두근', '상완이두근', '덤벨', '가슴,어깨', 'Step:1 디클라인 벤치에 누워 한 손에 덤벨을 들고 가슴 위에 둔다.,Step:2 팔을 위로 뻗어 덤벨을 들어 올리되 팔꿈치는 살짝 굽힌다.,Step:3 팔꿈치를 몸에 가깝게 유지하며 덤벨을 어깨 쪽으로 천천히 내린다.,Step:4 덤벨을 다시 밀어 올려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TDYiji6', '점프 스쿼트 v. 2', 'https://static.exercisedb.dev/media/TDYiji6.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트 자세로 내려간다.,Step:3 엉덩이와 무릎을 완전히 펴며 폭발적으로 점프한다.,Step:4 발앞꿈치로 부드럽게 착지하고 즉시 다시 스쿼트 자세로 내려간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('c3QQLPi', '케이블 후면 드라이브', 'https://static.exercisedb.dev/media/c3QQLPi.gif', '삼두근', '상완이두근', '케이블', '어깨,등', 'Step:1 낮은 풀리에 핸들을 부착하고 머신을 등지고 선다.,Step:2 오버핸드 그립으로 핸들을 잡고 팔을 앞쪽으로 곧게 뻗는다.,Step:3 팔꿈치를 고정한 채 핸들을 몸 쪽으로 뒤로 당기며 삼두근을 수축한다.,Step:4 핸들을 천천히 시작 자세로 돌려 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4Leypho', '바벨 스키어', 'https://static.exercisedb.dev/media/4Leypho.gif', '삼각근', '어깨', '바벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 바벨을 허벅지 앞에서 오버핸드 그립으로 잡는다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 앞으로 숙이되 등을 곧게, 가슴은 들어둔다.,Step:3 가볍게 점프하며 동시에 바벨을 어깨 쪽으로 끌어올린다.,Step:4 최상단에서 즉시 동작을 반전시켜 바벨을 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KI1DjNN', '벤치 위의 덤벨 원 암 손목 컬', 'https://static.exercisedb.dev/media/KI1DjNN.gif', '전완근', '팔 아래', '덤벨', '이두근,어깨', 'Step:1 벤치에 앉아 한 손에 덤벨을 들고 손바닥이 아래를 보게 한다.,Step:2 전완을 벤치에 올리고 손목이 가장자리 밖으로 나오게 둔다.,Step:3 손목을 천천히 위로 말아 올려 덤벨을 전완 쪽으로 가져온다.,Step:4 최상단에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 손을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ns0SIbU', '덤벨 인클라인 벤치프레스', 'https://static.exercisedb.dev/media/ns0SIbU.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 인클라인 벤치를 45도 각도로 세팅한다.,Step:2 벤치에 앉아 발을 바닥에 두고 등을 벤치에 단단히 밀착한다.,Step:3 양손에 덤벨을 들고 손바닥이 앞을 보게 하여 어깨 높이까지 든다.,Step:4 덤벨을 가슴 옆으로 천천히 내리되 팔꿈치는 90도 정도가 되게 한다.,Step:5 덤벨을 다시 밀어 올려 팔을 펴서 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SJqRxOt', '케이블 로프 좌석 행', 'https://static.exercisedb.dev/media/SJqRxOt.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 로잉 머신(시티드 로우)에 앉아 발을 발판에 두고 무릎을 살짝 굽힌다.,Step:2 오버핸드 그립으로 케이블 로프를 잡아 손바닥이 서로 마주 보게 한다.,Step:3 등을 곧게 펴고 상체를 약간 앞으로 기울이되 팔꿈치는 살짝 굽힌 상태로 유지한다.,Step:4 로프를 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 최상단에서 잠깐 멈춘 뒤 장력을 천천히 풀며 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gpn4ADc', '스미스 비하인드 넥 프레스', 'https://static.exercisedb.dev/media/Gpn4ADc.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 스미스 머신 시트 높이를 바가 어깨 높이가 되도록 조절한다.,Step:2 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:3 어깨너비보다 약간 넓게 오버핸드 그립으로 바를 잡는다.,Step:4 바를 랙에서 들어 올리고 뒤로 한 걸음 물러나 안정적인 자세를 만든다.,Step:5 팔꿈치를 앞쪽으로 향하게 유지하며 바를 목 뒤쪽으로 천천히 내린다.,Step:6 팔을 펴 바를 머리 위로 밀어 올려 완전히 들어 올린다.,Step:7 최상단에서 잠깐 멈춘 뒤 바를 천천히 다시 시작 자세로 내린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('f7fnAIB', '케이블 스쿼트 로우(로프 부착 포함)', 'https://static.exercisedb.dev/media/f7fnAIB.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 허리 높이에 케이블 머신에 로프를 부착한다.,Step:2 케이블 머신을 마주보고 발을 어깨너비로 벌리고 선다.,Step:3 무릎을 굽혀 스쿼트 자세로 내려가되 등을 곧게, 가슴은 들어둔다.,Step:4 오버핸드 그립으로 로프를 잡되 손은 어깨너비로 둔다.,Step:5 코어에 힘을 주고 로프를 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 팔꿈치를 몸에 가깝게 유지하고 손이 가슴에 올 때까지 당긴다.,Step:7 최상단에서 잠깐 멈춘 뒤 로프를 천천히 풀어 팔을 펴며 시작 자세로 돌아간다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Tq6gbK6', '케이블 스트레이트 뒷좌석 행', 'https://static.exercisedb.dev/media/Tq6gbK6.gif', '등 위쪽', '등', '케이블', '이두근,전완근,어깨', 'Step:1 케이블 로우 머신에 앉아 발을 발판에 두고 무릎을 살짝 굽힌다.,Step:2 오버핸드 그립으로 핸들을 잡아 손바닥이 아래를 보게 한다.,Step:3 등을 곧게 펴고 엉덩이에서 약간 앞으로 기울인다.,Step:4 핸들을 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 최상단에서 잠깐 멈춘 뒤 핸들을 천천히 풀어 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vsVoPHt', '레버 디클릿 체스트 프레스', 'https://static.exercisedb.dev/media/vsVoPHt.gif', '가슴근육', '가슴', '레버리지 머신', '삼두근,어깨', 'Step:1 시트 높이와 등받이를 편한 위치로 조절한다.,Step:2 등받이에 등을 대고 앉아 발을 바닥에 둔다.,Step:3 오버핸드 그립으로 핸들을 잡고 손을 어깨너비보다 약간 넓게 둔다.,Step:4 핸들을 앞으로 밀어 팔을 펴되 팔꿈치는 완전히 잠그지 않는다.,Step:5 핸들을 천천히 가슴 쪽으로 내리며 팔꿈치를 살짝 굽힌 상태를 유지한다.,Step:6 최하단에서 잠깐 멈춘 뒤 핸들을 다시 밀어 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dRTfGZT', '레버 사이드 상승', 'https://static.exercisedb.dev/media/dRTfGZT.gif', '삼각근', '어깨', '레버리지 머신', '승모근,등 위쪽', 'Step:1 시트 높이를 조절하고 등받이에 등을 대고 앉는다.,Step:2 오버핸드 그립으로 핸들을 잡고 팔을 곧게 편다.,Step:3 숨을 내쉬며 팔을 옆으로 들어 올려 바닥과 평행이 될 때까지 올린다.,Step:4 최상단에서 잠깐 멈춘 뒤 숨을 들이마시며 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TV87DNB', '인치웜 v. 2', 'https://static.exercisedb.dev/media/TV87DNB.gif', '복근', '허리', '맨몸', '어깨,햄스트링', 'Step:1 발을 골반너비로 벌리고 선다.,Step:2 허리에서 상체를 숙여 손을 앞쪽 바닥에 짚는다.,Step:3 손을 앞으로 걸어 하이 플랭크 자세가 되도록 한다(머리부터 발끝까지 일직선).,Step:4 다리를 편 상태로 발을 손 쪽으로 걸어오며 엉덩이를 위로 올린다.,Step:5 원하는 반복 횟수만큼 손을 앞으로 걸어가는 동작을 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('h1ezqSu', '무릎을 꿇고 플랭크 탭 숄더(남성)', 'https://static.exercisedb.dev/media/h1ezqSu.gif', '복근', '허리', '맨몸', '어깨,삼두근', 'Step:1 무릎을 꿇고 손을 어깨너비로 바닥에 둔다.,Step:2 다리를 뒤로 뻗어 발끝으로 지지하고 플랭크 자세를 만든다.,Step:3 코어에 힘을 주고 골반이 흔들리지 않게 유지한 채 한 손을 들어 반대쪽 어깨를 터치한다.,Step:4 손을 바닥에 다시 두고 반대쪽도 반복한다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rQxwMxO', '물구나무서기 푸쉬업', 'https://static.exercisedb.dev/media/rQxwMxO.gif', '삼두근', '상완이두근', '맨몸', '어깨,가슴,코어', 'Step:1 벽을 찾고 벽을 등지도록 몇 걸음 떨어져 선다.,Step:2 손을 어깨너비로 바닥에 짚고 발을 차올려 벽에 기대어 물구나무 자세를 만든다.,Step:3 팔꿈치를 굽혀 머리를 바닥 쪽으로 내리되 몸은 일직선을 유지한다.,Step:4 손바닥으로 밀어 팔을 펴 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gf3ZjB9', '클로저 해킹 스쿼트', 'https://static.exercisedb.dev/media/gf3ZjB9.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신을 적절한 무게로 설정하고 등을 패드에 대고 선다/앉는다.,Step:2 발을 어깨너비로 플랫폼에 올리고 발끝은 약간 바깥으로 둔다.,Step:3 안정성을 위해 옆 손잡이를 잡는다.,Step:4 코어에 힘을 주고 무릎과 엉덩이를 굽혀 천천히 내려간다.,Step:5 허벅지가 바닥과 평행(또는 약간 더 아래)일 때까지 내려간다.,Step:6 최하단에서 잠깐 멈춘 뒤 뒤꿈치로 밀어 다리를 펴 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mu5Guxt', '덤벨 리어 델트 레이즈', 'https://static.exercisedb.dev/media/mu5Guxt.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 발을 어깨너비로 벌리고 양손에 덤벨을 들어 손바닥이 몸을 향하게 한다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 앞으로 숙이되 등을 곧게 유지한다.,Step:3 팔꿈치를 살짝 굽힌 채 팔을 옆으로 들어 올려 바닥과 평행이 될 때까지 올린다.,Step:4 최상단에서 잠깐 멈춘 뒤 팔을 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jeHtrlO', '메디신 볼 가슴 푸시 단일 응답', 'https://static.exercisedb.dev/media/jeHtrlO.gif', '가슴근육', '가슴', '메디신볼', '삼두근,어깨', 'Step:1 발을 어깨너비로 벌리고 서서 메디신볼을 가슴 높이에서 잡는다.,Step:2 팔을 앞으로 뻗어 메디신볼을 가슴에서 멀리 밀어낸다.,Step:3 잠깐 멈춘 뒤 메디신볼을 천천히 가슴 쪽으로 다시 가져온다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1TkiAFK', '덤벨 원암 숄더 프레스 v. 2', 'https://static.exercisedb.dev/media/1TkiAFK.gif', '삼각근', '어깨', '덤벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 한 손에 덤벨을 어깨 높이에서 잡고 손바닥이 앞을 보게 한다.,Step:2 코어에 힘을 주고 덤벨을 머리 위로 곧게 밀어 올려 팔을 완전히 편다.,Step:3 최상단에서 잠깐 멈춘 뒤 덤벨을 천천히 어깨 높이로 내린다.,Step:4 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QjE2DcA', '덤벨 스텝업 스플릿 스쿼트', 'https://static.exercisedb.dev/media/QjE2DcA.gif', '대퇴사두근', '허벅지', '덤벨', '둔근,햄스트링,종아리근', 'Step:1 벤치/스텝 앞에 서서 양손에 덤벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 오른발을 벤치/스텝 위에 올려 발 전체가 닿게 한다.,Step:3 오른발 뒤꿈치로 밀어 몸을 들어 올려 스텝 위로 올라간다.,Step:4 올라가면서 왼쪽 무릎을 가슴 쪽으로 들어 올린다.,Step:5 최상단에서 잠깐 멈춘 뒤 오른발은 스텝 위에 둔 채 왼발을 천천히 바닥으로 내린다.,Step:6 왼발을 스텝 위에 올려 같은 동작을 수행한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xDh0lJr', '비하인드 넥 프레스', 'https://static.exercisedb.dev/media/xDh0lJr.gif', '삼각근', '어깨', '바벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 바벨을 목 뒤에서 오버핸드 그립으로 잡는다.,Step:2 등을 곧게 펴고 코어에 힘을 준다.,Step:3 팔을 펴며 바벨을 머리 위로 밀어 올려 팔꿈치를 완전히 편다.,Step:4 최상단에서 잠깐 멈춘 뒤 바벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('50BETrz', '바이셉스 클로즈드 풀업', 'https://static.exercisedb.dev/media/50BETrz.gif', '이두근', '상완이두근', '맨몸', '전완근,어깨', 'Step:1 손바닥이 자신을 향하게 하여 어깨너비로 풀업 바에 매단다.,Step:2 코어에 힘을 주고 이두근으로 몸을 끌어올린다는 느낌으로 턱이 바에 가까워지게 당긴다.,Step:3 최상단에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아간다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('B5xca8s', '두 손을 맞잡은 원형 발가락 터치(남성)', 'https://static.exercisedb.dev/media/B5xca8s.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근,종아리근', 'Step:1 발을 어깨너비로 벌리고 선 뒤 손을 가슴 앞에서 맞잡는다.,Step:2 무릎을 살짝 굽히고 힙 힌지로 상체를 앞으로 숙이되 등을 곧게 유지한다.,Step:3 무리하지 않는 범위에서 손을 원을 그리듯 아래로 내려 발가락 쪽으로 가져간다.,Step:4 최하단에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('d1GgzTU', 'L-풀업', 'https://static.exercisedb.dev/media/d1GgzTU.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 어깨너비보다 약간 넓게 오버핸드 그립으로 풀업 바를 잡는다.,Step:2 팔을 완전히 편 채 매달리고 몸을 곧게 만든다.,Step:3 광배근과 이두근에 힘을 주어 팔꿈치를 몸에 가깝게 유지하며 몸을 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 당긴다.,Step:5 최상단에서 잠깐 멈춘 뒤 천천히 내려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7zdxRTl', '스미스 레그 프레스', 'https://static.exercisedb.dev/media/7zdxRTl.gif', '둔근', '허벅지', '스미스 머신', '대퇴사두근,햄스트링,종아리근', 'Step:1 스미스 머신의 시트와 발판을 편한 위치로 조절한다.,Step:2 등받이에 등을 대고 앉아 발을 어깨너비로 발판에 둔다.,Step:3 안정성을 위해 손잡이 또는 머신 측면을 잡는다.,Step:4 등을 등받이에 붙인 채 다리를 펴 발판을 밀어낸다.,Step:5 완전히 펴진 지점에서 잠깐 멈춘다.,Step:6 무릎을 굽혀 발판을 천천히 되돌려 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Nh3mvOO', '덤벨 리버스 그립 로우(여성)', 'https://static.exercisedb.dev/media/Nh3mvOO.gif', '등 위쪽', '등', '덤벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:2 오버핸드 그립으로 양손에 덤벨을 잡아 손바닥이 몸을 향하게 한다.,Step:3 허리에서 상체를 숙이되 등을 곧게 유지하고 코어에 힘을 준다.,Step:4 팔을 아래로 늘어뜨려 완전히 펴고 팔꿈치는 살짝 굽힌다.,Step:5 덤벨을 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 최상단에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ywaNfuh', '스미스 리버스 카프 레이즈', 'https://static.exercisedb.dev/media/ywaNfuh.gif', '종아리근', '종아리', '스미스 머신', '햄스트링', 'Step:1 스미스 바를 어깨 바로 아래 높이로 맞춘다.,Step:2 바를 마주보고 서서 발을 골반너비로 두고 발끝을 정면으로 둔다.,Step:3 스텝/플랫폼 가장자리에 발앞꿈치(볼)를 올리고 뒤꿈치는 밖으로 두어 늘어뜨린다.,Step:4 지지를 위해 바를 잡고 등을 곧게, 코어에 힘을 준다.,Step:5 뒤꿈치를 최대한 들어 올려 발앞꿈치에 체중을 싣는다.,Step:6 최상단에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내려 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UIbGx6H', '덤벨 리버스 벤치 프레스', 'https://static.exercisedb.dev/media/UIbGx6H.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨', 'Step:1 벤치에 등을 대고 눕고 발을 바닥에 두고 무릎을 굽힌다.,Step:2 양손에 덤벨을 오버핸드 그립으로 잡아 손바닥이 발 쪽을 향하게 한다.,Step:3 팔을 위로 뻗어 덤벨을 들어 올리되 팔꿈치는 살짝 굽힌다.,Step:4 덤벨을 가슴 쪽으로 천천히 내리며 팔꿈치는 옆으로 자연스럽게 벌어지게 한다.,Step:5 최하단에서 잠깐 멈춘 뒤 덤벨을 다시 밀어 올려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HDYiZcY', '덤벨 크로스 바디 해머 컬 v. 2', 'https://static.exercisedb.dev/media/HDYiZcY.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 곧게 서서 손바닥이 몸을 향하게 한다.,Step:2 팔꿈치를 몸통에 붙이고 위팔은 고정한다.,Step:3 숨을 내쉬며 덤벨을 들어 올려 반대쪽 어깨에 가깝게 가져오며 이두근을 수축한다.,Step:4 수축 지점에서 잠깐 멈추며 이두근에 힘을 준다.,Step:5 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mym4hJo', '덤벨 거짓말하는 내전', 'https://static.exercisedb.dev/media/mym4hJo.gif', '전완근', '팔 아래', '덤벨', '이두근,어깨', 'Step:1 벤치에 엎드려 가슴이 아래를 향하게 하고 팔을 아래로 곧게 늘어뜨린 채 양손에 덤벨을 잡는다.,Step:2 손바닥이 위를 보게 회전한다.,Step:3 위팔을 고정한 채 숨을 내쉬며 덤벨을 컬링하면서 손바닥을 아래로 회전한다.,Step:4 숨을 들이마시며 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KWdF2JI', '케이블 닐링 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/KWdF2JI.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 로프 핸들을 상단 풀리에 부착하고 케이블 머신을 향해 무릎을 꿇는다.,Step:2 뉴트럴 그립(손바닥이 서로 마주 보게)으로 로프를 잡고 손을 머리 옆으로 가져간다.,Step:3 팔꿈치를 머리 가까이에 두고 위팔은 동작 내내 고정한다.,Step:4 삼두근에 힘을 주어 전완을 펴 팔을 완전히 편다.,Step:5 잠깐 멈춘 뒤 팔꿈치를 굽혀 천천히 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NL6YBwN', '덤벨 디클라인 원암 플라이', 'https://static.exercisedb.dev/media/NL6YBwN.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 디클라인 벤치에 누워 한 손에 덤벨을 들고 허벅지 위에 둔다.,Step:2 허벅지로 덤벨을 보조해 들어 올려 손바닥이 몸통을 향한 상태로 어깨너비 위치에 둔다.,Step:3 손목을 회전해 손바닥이 앞을 보게 한다.,Step:4 숨을 들이마시며 덤벨을 옆으로 천천히 내려 가슴이 늘어나는 느낌을 받는다.,Step:5 숨을 내쉬며 가슴 근육으로 덤벨을 다시 들어 올려 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BL3GHeY', '스트래들 플란체', 'https://static.exercisedb.dev/media/BL3GHeY.gif', '복근', '허리', '맨몸', '어깨,삼두근,가슴', 'Step:1 푸쉬업 자세에서 손을 어깨너비로 두고 발을 넓게 벌린다.,Step:2 코어에 힘을 주고 체중을 천천히 앞으로 이동해 어깨가 손 위로 오게 한다.,Step:3 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 팔꿈치는 몸통 가까이에 둔다.,Step:4 최하단에서 잠깐 멈춘 뒤 손으로 밀어 팔을 펴며 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('GwYwElT', '셀프 어시스트 인버스 레그 컬', 'https://static.exercisedb.dev/media/GwYwElT.gif', '햄스트링', '허벅지', '맨몸', '둔근,종아리근', 'Step:1 매트/벤치에 등을 대고 눕고 다리를 곧게 편다.,Step:2 손은 옆에 두거나 둔근 아래에 두어 지지한다.,Step:3 무릎을 굽혀 발을 바닥에서 떼고 허벅지를 가슴 쪽으로 가져온다.,Step:4 최상단에서 잠깐 멈춘 뒤 다리를 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('HPlPoQA', '케이블 해머 컬(로프 포함)', 'https://static.exercisedb.dev/media/HPlPoQA.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 살짝 굽힌다.,Step:2 언더핸드 그립으로 로프 어태치먼트를 잡되 손바닥이 서로 마주 보게 하고 팔을 완전히 편다.,Step:3 위팔을 고정한 채 숨을 내쉬며 당겨 이두근을 수축한다.,Step:4 로프가 어깨 높이에 오고 이두근이 완전히 수축될 때까지 올린다.,Step:5 잠깐 멈추며 이두근에 힘을 준다.,Step:6 숨을 들이마시며 로프를 천천히 내려 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SP3hUez', '수영 킥 v. 2 (남성)', 'https://static.exercisedb.dev/media/SP3hUez.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근,종아리근', 'Step:1 매트에 엎드려 팔을 머리 위로 뻗는다.,Step:2 코어에 힘을 주고 가슴과 다리를 동시에 바닥에서 들어 올린다.,Step:3 수영하듯 다리를 위아래로 빠르게 차는 플러터 킥을 한다.,Step:4 원하는 반복 횟수만큼 계속한다.,Step:5 가슴과 다리를 다시 바닥에 내려 시작 자세로 돌아간다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('zILLZ98', '스미스 머신 바이셉 컬', 'https://static.exercisedb.dev/media/zILLZ98.gif', '이두근', '상완이두근', '스미스 머신', '전완근', 'Step:1 스미스 바 높이를 허리 높이로 조절한다.,Step:2 스미스 머신을 마주보고 발을 어깨너비로 벌린다.,Step:3 언더핸드 그립으로 바를 잡되 손은 어깨너비보다 약간 넓게 둔다.,Step:4 팔꿈치를 몸통에 붙이고 위팔을 고정한다.,Step:5 숨을 내쉬며 바를 어깨 쪽으로 말아 올리며 이두근을 수축한다.,Step:6 최상단에서 잠깐 멈추며 이두근에 힘을 준다.,Step:7 숨을 들이마시며 바를 천천히 내려 시작 자세로 돌아간다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pH2x2jj', '짐 볼에 덤벨 한쪽 다리 플라이', 'https://static.exercisedb.dev/media/pH2x2jj.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐볼에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주 보게 한다.,Step:2 한쪽 발은 바닥에 두고 반대쪽 다리는 앞으로 곧게 뻗는다.,Step:3 상체를 약간 앞으로 기울이고 팔을 옆으로 벌리되 팔꿈치는 살짝 굽힌다.,Step:4 덤벨을 천천히 내려 가슴이 늘어나는 느낌을 받는다.,Step:5 최하단에서 잠깐 멈춘 뒤 가슴 근육으로 덤벨을 다시 들어 올린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lJJ7Yq8', '케이블 라이 플라이', 'https://static.exercisedb.dev/media/lJJ7Yq8.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블에 핸들을 연결하고 벤치에 등을 대고 눕고 발을 바닥에 둔다.,Step:2 손바닥이 서로 마주 보게 핸들을 잡고 팔을 가슴 위로 곧게 뻗는다.,Step:3 팔꿈치를 살짝 굽힌 상태로 유지하며 팔을 큰 원을 그리듯 옆으로 벌려 가슴이 늘어나는 지점까지 내린다.,Step:4 최하단에서 잠깐 멈춘 뒤 가슴 근육으로 팔을 모아 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('BLCvwr2', '덤벨 리버스 리스트 컬', 'https://static.exercisedb.dev/media/BLCvwr2.gif', '전완근', '팔 아래', '덤벨', '이두근,상완근', 'Step:1 벤치/의자에 앉아 양손에 덤벨을 오버핸드 그립으로 잡아 손바닥이 아래를 보게 한다.,Step:2 전완을 허벅지 위에 올리고 손목이 가장자리 밖으로 나오게 둔다.,Step:3 손목을 천천히 위로 말아 올려 덤벨을 몸 쪽으로 가져온다.,Step:4 최상단에서 잠깐 멈춘 뒤 덤벨을 천천히 내려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('bQHPBU3', '짐 볼에 덤벨 한쪽 팔 풀오버', 'https://static.exercisedb.dev/media/bQHPBU3.gif', '가슴근육', '가슴', '덤벨', '삼두근,광배근,능형근', 'Step:1 짐볼에 앉아 발을 바닥에 두고 무릎을 90도로 굽힌다.,Step:2 한 손으로 덤벨을 잡고 팔을 가슴 위로 곧게 뻗는다.,Step:3 팔을 곧게 유지한 채 덤벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 덤벨을 다시 들어 올려 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XaaRnRn', '인클라인 리버스 그립 푸쉬업', 'https://static.exercisedb.dev/media/XaaRnRn.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 벤치/높은 지면 가장자리에 손을 어깨너비보다 약간 넓게 짚는다.,Step:2 다리를 뒤로 뻗어 발앞꿈치로 지지하고 머리부터 발끝까지 일직선을 만든다.,Step:3 팔꿈치를 굽혀 가슴을 벤치 쪽으로 내리되 팔꿈치는 몸통 가까이에 둔다.,Step:4 최하단에서 잠깐 멈춘 뒤 팔을 펴서 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6YUfHPL', '쿼드', 'https://static.exercisedb.dev/media/6YUfHPL.gif', '대퇴사두근', '허벅지', '맨몸', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 의자에 앉듯이 몸을 내린다.,Step:3 가슴을 펴고 등을 곧게 유지한다.,Step:4 허벅지가 바닥과 평행해질 때까지 내려간다.,Step:5 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('L4ay0PW', '케틀벨 그립 8', 'https://static.exercisedb.dev/media/L4ay0PW.gif', '복근', '허리', '케틀벨', '어깨,전완근', 'Step:1 발을 어깨너비로 벌리고 한 손에 케틀벨을 든 채 선다.,Step:2 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:3 케틀벨을 다리 사이로 보내 뒤쪽에서 반대 손으로 바꿔 잡는다.,Step:4 케틀벨이 앞으로 나오면 다시 다리 사이에서 다른 손으로 넘겨 잡는다.,Step:5 그림 8 모양으로 다리 사이에서 케틀벨을 계속 넘긴다.,Step:6 일정한 속도를 유지하고 동작 내내 코어에 힘을 준다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qAmNMJY', '덤벨 하이 컬', 'https://static.exercisedb.dev/media/qAmNMJY.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 손바닥이 앞을 보도록 하여 곧게 선다.,Step:2 위팔은 고정한 채 이두근에 힘을 주며 덤벨을 가능한 높이까지 말아 올린다.,Step:3 정점에서 잠시 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('rbu5UUb', '크로스 바디 크런치', 'https://static.exercisedb.dev/media/rbu5UUb.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥쪽으로 향하게 한다.,Step:3 복근에 힘을 주어 상체를 들어 올리며 비틀어 오른쪽 팔꿈치를 왼쪽 무릎 쪽으로 가져간다.,Step:4 정점에서 잠시 멈춘 뒤 상체를 천천히 시작 자세로 내린다.,Step:5 반대쪽도 동일하게 왼쪽 팔꿈치를 오른쪽 무릎 쪽으로 가져간다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ZfyAGhK', '케이블 스탠딩 리어 델트 로우(로프 포함)', 'https://static.exercisedb.dev/media/ZfyAGhK.gif', '삼각근', '어깨', '케이블', '승모근,능형근,이두근', 'Step:1 케이블 머신을 마주 보고 발을 어깨너비로 벌리고 선다.,Step:2 양손으로 어태치먼트를 잡고 손바닥이 서로 마주보게 한 뒤, 케이블에 긴장이 생기도록 뒤로 한 걸음 물러선다.,Step:3 등을 곧게 세우고 코어에 힘을 준다.,Step:4 케이블을 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 동작의 정점에서 잠시 멈춘 뒤 케이블을 천천히 시작 자세로 되돌린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XVDdcoj', '러시안 트위스트', 'https://static.exercisedb.dev/media/XVDdcoj.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 바닥에 앉아 무릎을 굽히고 발을 바닥에 둔다.,Step:2 등을 곧게 유지한 채 상체를 약간 뒤로 기울이며 코어에 힘을 준다.,Step:3 가슴 앞에서 손을 모으거나 원하면 중량을 잡는다.,Step:4 발을 바닥에서 들어 좌골로 균형을 잡는다.,Step:5 상체를 오른쪽으로 비틀어 손 또는 중량을 몸의 오른쪽으로 가져간다.,Step:6 잠시 멈춘 뒤 상체를 왼쪽으로 비틀어 손 또는 중량을 몸의 왼쪽으로 가져간다.,Step:7 원하는 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fprd84i', 'ez 바벨 반중력 프레스', 'https://static.exercisedb.dev/media/fprd84i.gif', '삼각근', '어깨', 'EZ 바벨', '삼두근,가슴', 'Step:1 발을 어깨너비로 벌리고 선 채 오버핸드 그립으로 EZ 바벨을 잡는다.,Step:2 팔꿈치를 약간 굽힌 상태로 바벨을 어깨 높이까지 들어 올리고 손바닥이 앞을 보게 한다.,Step:3 팔을 완전히 펴며 바벨을 머리 위로 밀어 올린다.,Step:4 바벨을 어깨 높이로 다시 내리고 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('SaDOwk7', '백워드 점프', 'https://static.exercisedb.dev/media/SaDOwk7.gif', '대퇴사두근', '허벅지', '맨몸', '햄스트링,둔근,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 무릎을 살짝 굽힌다.,Step:3 양발로 힘차게 밀어 뒤로 점프한다.,Step:4 발볼로 부드럽게 착지하며 충격을 흡수하도록 무릎을 굽힌다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('yWxMvB5', '케틀벨 스러스터', 'https://static.exercisedb.dev/media/yWxMvB5.gif', '삼각근', '어깨', '케틀벨', '대퇴사두근,둔근,코어', 'Step:1 발을 어깨너비로 벌리고 선 채 양손으로 케틀벨을 가슴 앞에 들고 손바닥이 서로 마주보게 한다.,Step:2 무릎을 굽히고 엉덩이를 뒤로 빼며 스쿼트 자세로 내려가되 가슴을 펴고 등을 곧게 유지한다.,Step:3 스쿼트 바닥 지점에서 뒤꿈치로 폭발적으로 밀어 일어서며 동시에 케틀벨을 머리 위로 밀어 올린다.,Step:4 팔꿈치를 완전히 펴 정점에서 잠근다.,Step:5 팔꿈치를 굽혀 케틀벨을 가슴 쪽으로 내리며 시작 자세로 되돌린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('za9Ni4z', '바벨 랙 풀', 'https://static.exercisedb.dev/media/za9Ni4z.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 바벨을 랙에 무릎 높이로 세팅한다.,Step:2 발을 어깨너비로 벌리고 발끝을 약간 바깥쪽으로 향하게 선다.,Step:3 엉덩이와 무릎을 굽혀 내려가 오버핸드 그립으로 바벨을 어깨너비로 잡는다.,Step:4 코어에 힘을 주고 엉덩이와 무릎을 펴며 바벨을 들어 올리면서 어깨를 뒤로 당기고 정점에서 둔근을 조인다.,Step:5 엉덩이와 무릎을 굽혀 바벨을 다시 시작 위치로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('S93zLTG', '저항 밴드 장착 숄더 프레스', 'https://static.exercisedb.dev/media/S93zLTG.gif', '삼각근', '어깨', '저항 밴드', '삼두근,등 위쪽', 'Step:1 등을 곧게 세우고 의자나 벤치에 앉아 발을 바닥에 평평하게 둔다.,Step:2 양손으로 저항 밴드를 잡고 손바닥이 앞을 보게 하여 어깨 높이까지 올린다.,Step:3 팔을 완전히 펴며 밴드를 머리 위로 밀어 올린다.,Step:4 정점에서 잠시 멈춘 뒤 밴드를 천천히 어깨 높이로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fSrPP6B', '삼두근 프레스', 'https://static.exercisedb.dev/media/fSrPP6B.gif', '삼두근', '상완이두근', '맨몸', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 살짝 굽힌다.,Step:2 팔을 앞으로 곧게 뻗어 바닥과 평행하게 한다.,Step:3 팔꿈치를 굽히며 몸을 바닥 쪽으로 내리되 위팔을 몸통 가까이에 유지한다.,Step:4 바닥 지점에서 잠시 멈춘 뒤 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o5Jsk92', '덤벨 원암 벤치 플라이', 'https://static.exercisedb.dev/media/o5Jsk92.gif', '가슴근육', '가슴', '덤벨', '어깨', 'Step:1 한 손에 덤벨을 들고 플랫 벤치에 앉아 덤벨을 허벅지 위에 올려 둔다.,Step:2 벤치에 등을 대고 눕되 덤벨을 허벅지에 밀착해 유지한다.,Step:3 반대 손으로 덤벨을 들어 올려 시작 자세로 올리는 것을 보조한다.,Step:4 덤벨을 어깨 위에 두고 팔을 뻗은 채 손바닥이 안쪽을 보게 한다.,Step:5 팔꿈치를 약간 굽힌 상태로 큰 원을 그리며 덤벨을 옆으로 내린다.,Step:6 팔이 바닥과 평행해질 때 잠시 멈춘 뒤 반대 방향으로 움직여 덤벨을 시작 자세로 가져온다.,Step:7 원하는 횟수만큼 반복한 뒤 팔을 바꿔 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('NAkmgdx', '팔을 머리 위로 올려 윗몸일으키기(남성)', 'https://static.exercisedb.dev/media/NAkmgdx.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 팔을 머리 위로 곧게 뻗는다.,Step:3 복근에 힘을 주어 상체를 천천히 들어 올려 몸통이 세워질 때까지 말아 올린다.,Step:4 정점에서 잠시 멈춘 뒤 상체를 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('05Cf2v8', '임파서블 딥스', 'https://static.exercisedb.dev/media/05Cf2v8.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 평행봉 사이에 위치해 팔을 완전히 편 상태로 몸을 공중에 띄운다.,Step:2 무릎을 굽히고 발목을 교차한다.,Step:3 팔꿈치를 굽혀 위팔이 바닥과 평행해질 때까지 몸을 내린다.,Step:4 잠시 멈춘 뒤 팔을 펴며 몸을 다시 들어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KwFGiEP', '덤벨 누워서 원 암 뒤로 옆으로 올리기', 'https://static.exercisedb.dev/media/KwFGiEP.gif', '삼각근', '어깨', '덤벨', '승모근,능형근', 'Step:1 플랫 벤치에 엎드려 한 손에 덤벨을 들고 바닥을 향해 늘어뜨린다.,Step:2 팔을 곧게 편 채 덤벨을 몸 옆으로 들어 올린다.,Step:3 정점에서 잠시 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:4 원하는 횟수만큼 반복한 뒤 반대 팔로 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('O8o7q4d', '짐 볼에 덤벨 프레스', 'https://static.exercisedb.dev/media/O8o7q4d.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐볼에 앉아 발을 바닥에 평평하게 두고 양손에 덤벨을 쥔 채 허벅지 위에 올려 둔다.,Step:2 발을 천천히 앞으로 걸어 짐볼을 굴려 허리가 공에 지지되고 무릎이 90도가 되게 한다.,Step:3 덤벨을 어깨 높이로 올리고 손바닥이 앞을 보게 한다.,Step:4 팔을 완전히 펴며 덤벨을 위로 밀어 올린다.,Step:5 정점에서 잠시 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ie9UGty', '레버 시트 카프 프레스', 'https://static.exercisedb.dev/media/Ie9UGty.gif', '종아리근', '종아리', '레버리지 머신', '가자미근,햄스트링', 'Step:1 레버 패드가 어깨와 정렬되도록 좌석을 조절한다.,Step:2 발끝을 플랫폼의 아래쪽에 두고 무릎을 레버 패드 아래에 위치시킨다.,Step:3 안정적으로 고정하기 위해 좌석 옆 손잡이를 잡는다.,Step:4 발목을 펴며 레버 패드를 아래로 눌러 뒤꿈치를 가능한 높이 들어 올린다.,Step:5 정점에서 잠시 멈춘 뒤 뒤꿈치를 천천히 시작 위치로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('izMnLqz', '덤벨 얼터너티브 사이드 프레스', 'https://static.exercisedb.dev/media/izMnLqz.gif', '삼각근', '어깨', '덤벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 어깨 높이로 든다.,Step:2 한쪽 덤벨을 머리 위로 밀어 올리는 동안 다른 덤벨은 어깨 높이에 유지한다.,Step:3 올린 덤벨을 어깨 높이로 내리면서 반대쪽 덤벨을 머리 위로 밀어 올린다.,Step:4 원하는 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('G1qWW6M', '매크로 스타일 가중 한 손 풀업', 'https://static.exercisedb.dev/media/G1qWW6M.gif', '광배근', '등', '가중', '이두근,전완근', 'Step:1 오버핸드 그립으로 풀업 바를 어깨너비보다 약간 넓게 잡는다.,Step:2 팔을 완전히 편 상태로 매달려 몸을 곧게 유지한다. 매크로 강도로 수행한다.,Step:3 코어에 힘을 주고 팔꿈치를 굽히며 등 근육을 조여 몸을 위로 끌어올린다.,Step:4 턱이 바 위로 올라갈 때까지 계속 당긴다.,Step:5 통제하며 몸을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MRaFiZP', '인버티드 스타일 스미스 시티드 숄더 프레스', 'https://static.exercisedb.dev/media/MRaFiZP.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 손잡이가 어깨 높이에 오도록 좌석 높이를 조절한다.,Step:2 패드에 등을 대고 앉아 발을 바닥에 평평하게 둔다.,Step:3 오버핸드 그립으로 손잡이를 잡고 지지대에서 들어 올리며 팔을 완전히 편다.,Step:4 팔꿈치를 약간 굽힌 상태로 손잡이를 어깨 높이까지 내린다.,Step:5 팔을 완전히 펴며 손잡이를 머리 위로 밀어 올린다.,Step:6 정점에서 잠시 멈춘 뒤 손잡이를 천천히 어깨 높이로 내린다. 동작 내내 인버티드 폼을 유지한다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WM6TvvW', '케이블 낮은 좌석 열 제어', 'https://static.exercisedb.dev/media/WM6TvvW.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 발을 풋레스트에 두고 무릎을 살짝 굽힌 채 머신에 앉는다.,Step:2 손바닥이 아래를 보도록 오버핸드 그립으로 손잡이를 잡는다.,Step:3 등을 곧게 세우고 상체를 약간 앞으로 기울이되 팔꿈치에 약간의 굽힘을 유지한다. 동작 내내 통제된 폼을 유지한다.,Step:4 손잡이를 몸 쪽으로 당기며 견갑골을 모아 조인다.,Step:5 정점에서 잠시 멈춘 뒤 손잡이를 천천히 시작 위치로 되돌린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ookVu2D', '짐 볼에 벽 스타일 덤벨 풀오버 엉덩이 익스텐션', 'https://static.exercisedb.dev/media/ookVu2D.gif', '가슴근육', '가슴', '덤벨', '삼두근,어깨,코어', 'Step:1 짐볼에 앉아 발을 바닥에 두고 덤벨을 허벅지 위에 올려 둔다.,Step:2 발을 천천히 앞으로 걸어 짐볼을 굴려 머리, 목, 등 상부가 공에 지지되게 한다.,Step:3 양손으로 덤벨을 잡고 팔꿈치를 약간 굽힌 채 가슴 위로 곧게 뻗는다.,Step:4 통제하며 덤벨을 머리 뒤로 내린다.,Step:5 잠시 멈춘 뒤 덤벨을 시작 자세로 다시 들어 올린다.,Step:6 팔을 편 상태를 유지하며 엉덩이를 들어 올려 둔근을 조이고 코어에 힘을 준다.,Step:7 (벽 변형) 엉덩이를 시작 자세로 다시 내린다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('CUmLRTA', '케이블 닐링 크런치 - 부드러운 변형', 'https://static.exercisedb.dev/media/CUmLRTA.gif', '복근', '허리', '케이블', '복사근', 'Step:1 하이 풀리에 로프 핸들을 연결하고 머신을 등지고 무릎을 꿇는다.,Step:2 로프를 양손으로 잡아 머리 뒤에 두고 팔꿈치를 옆으로 벌린다.,Step:3 엉덩이는 고정한 채 허리를 굽혀 상체를 허벅지 쪽으로 말아 내린다.,Step:4 바닥 지점에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다. 동작 내내 부드러운 폼을 유지한다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3pqGMQj', '간단한 밴드와 v-up을 번갈아 사용하는 밴드', 'https://static.exercisedb.dev/media/3pqGMQj.gif', '복근', '허리', '밴드', '고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 밴드를 잡은 채 팔을 머리 위로 뻗는다.,Step:2 복근에 힘을 주어 다리와 상체를 동시에 들어 올리며 손을 발끝 쪽으로 뻗는다.,Step:3 다리와 상체를 다시 내리면서 다리 위치를 바꿔 한쪽 다리를 다른 쪽 위로 교차한다. 간단한 움직임에 집중한다.,Step:4 동작을 반복하며 매 반복마다 다리의 교차 위치를 번갈아 바꾼다.,Step:5 원하는 횟수만큼 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('M8IolhQ', 'ez 바벨 클로즈 그립 프리처 컬 - 정밀 변형', 'https://static.exercisedb.dev/media/M8IolhQ.gif', '이두근', '상완이두근', 'EZ 바벨', '전완근', 'Step:1 프리처 컬 벤치에 앉아 상완을 패드에 올리고 언더핸드 그립으로 EZ 바벨을 잡는다.,Step:2 삼두근이 패드에 닿게 두고 등을 곧게 유지한 채 팔을 완전히 편다.,Step:3 이두근에 힘을 주며 바벨을 천천히 어깨 쪽으로 말아 올린다.,Step:4 정점에서 잠시 멈추며 이두근을 조인다.,Step:5 팔을 완전히 펴며 바벨을 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다. 정밀한 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gdPIyyO', '스트롱 파이크 행잉', 'https://static.exercisedb.dev/media/gdPIyyO.gif', '복근', '허리', '맨몸', '고관절 굴근,어깨', 'Step:1 팔을 완전히 편 채 풀업 바에 매달리고 손바닥이 바깥을 보게 한다.,Step:2 코어에 힘을 주고 다리를 곧게 편 채 바 쪽으로 들어 올린다.,Step:3 (강렬한 변형) 다리를 들어 올려 몸이 v 모양이 되도록 하며 다리가 바닥과 평행해지게 한다.,Step:4 잠시 자세를 유지한 뒤 다리를 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('N6dZN2I', '사이드 케이블 하이 로우(무릎꿇기)', 'https://static.exercisedb.dev/media/N6dZN2I.gif', '등 위쪽', '등', '케이블', '이두근,어깨', 'Step:1 가슴 높이에 케이블 머신에 스트레이트 바를 연결한다.,Step:2 케이블 머신 앞에서 무릎을 꿇고 오버핸드 그립으로 바를 어깨너비로 잡는다.,Step:3 등을 곧게 세우고 코어에 힘을 주며 엉덩이를 뒤로 빼 발뒤꿈치에 앉는다.,Step:4 견갑골을 모아 조이며 바를 상복부 쪽으로 당긴다.,Step:5 정점에서 잠시 멈춘 뒤 바를 천천히 시작 자세로 되돌린다.,Step:6 원하는 횟수만큼 반복한다. 동작 내내 사이드 폼을 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vN5HB0s', '블런트 케이블 스탠딩 크런치', 'https://static.exercisedb.dev/media/vN5HB0s.gif', '복근', '허리', '케이블', '복사근', 'Step:1 하이 풀리에 케이블 핸들을 연결하고 머신을 등지고 선다.,Step:2 양손으로 핸들을 잡아 머리 뒤에 두고 팔꿈치를 굽힌다.,Step:3 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:4 복근에 힘을 주고 내쉬며 상체를 무릎 쪽으로 말아 내리며 팔꿈치를 허벅지 쪽으로 가져간다.,Step:5 바닥 지점에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다. 단단한 컨트롤을 강조한다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1TVoin7', '바벨 라이닝 삼두근 익스텐션 더블', 'https://static.exercisedb.dev/media/1TVoin7.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 등을 대고 누워 발을 바닥에 평평하게 두며 머리는 벤치 끝쪽에 둔다.,Step:2 오버핸드 그립으로 바벨을 어깨너비로 잡고 가슴 위로 팔을 곧게 뻗는다.,Step:3 위팔은 고정한 채 팔꿈치를 굽혀 바벨을 이마 쪽으로 천천히 내린다. 더블 동작에 집중한다.,Step:4 바닥 지점에서 잠시 멈춘 뒤 팔을 펴며 시작 자세로 되돌린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('F56Xpw3', '강렬한 웨이트 스트레이트 바 딥', 'https://static.exercisedb.dev/media/F56Xpw3.gif', '가슴근육', '가슴', '가중', '삼두근,어깨', 'Step:1 평행봉 사이에 위치해 팔을 완전히 편 상태로 몸을 곧게 유지한다.,Step:2 팔꿈치를 굽혀 위팔이 바닥과 평행해질 때까지 몸을 내린다.,Step:3 잠시 멈춘 뒤 팔을 펴며 시작 자세로 돌아온다.,Step:4 (강렬한 변형) 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xcLntTC', '플랫 벤치에서 슬로우 레그 풀(Slow Leg Pull)', 'https://static.exercisedb.dev/media/xcLntTC.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 플랫 벤치에 앉아 다리를 앞으로 곧게 뻗는다.,Step:2 손을 엉덩이 옆 벤치에 두어 지지한다.,Step:3 복근에 힘을 주고 다리를 들어 무릎을 가슴 쪽으로 당긴다.,Step:4 정점에서 잠시 멈춘 뒤 다리를 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다. 동작 내내 느린 폼을 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3nvEbbF', '강화된 케이블 트위스트 풀', 'https://static.exercisedb.dev/media/3nvEbbF.gif', '광배근', '등', '케이블', '어깨,이두근', 'Step:1 로우 풀리에 케이블 핸들을 연결하고 머신을 마주 보고 선다.,Step:2 왼손으로 핸들을 잡고 머신에서 한 걸음 물러나 팔을 완전히 편다.,Step:3 발을 어깨너비로 벌리고 무릎을 살짝 굽힌다.,Step:4 동작 내내 등을 곧게 세우고 코어에 힘을 준다.,Step:5 핸들을 몸 쪽으로 당기면서 상체를 오른쪽으로 회전한다.,Step:6 동작 끝에서 등 근육을 조여 수축한다.,Step:7 케이블의 긴장을 유지하며 천천히 시작 자세로 돌아온다.,Step:8 (강화 변형) 원하는 횟수만큼 반복한 뒤, 오른손으로 바꿔 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vpleANJ', '경사형 골반이 브릿지로 기울어지는 형태', 'https://static.exercisedb.dev/media/vpleANJ.gif', '둔근', '허벅지', '맨몸', '햄스트링,코어', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 팔을 몸 옆에 두고 손바닥이 바닥을 향하게 한다.,Step:3 둔근과 코어에 힘을 준다.,Step:4 골반을 말아 올리며 엉덩이를 들어 올린다. 경사 컨트롤을 강조한다.,Step:5 브릿지 자세를 몇 초간 유지한다.,Step:6 엉덩이를 천천히 시작 자세로 내린다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('sJElUUI', '덤벨 인클라인 한쪽 팔 프레스 짐 볼 수정됨', 'https://static.exercisedb.dev/media/sJElUUI.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐볼에 앉아 한 손에 덤벨을 들고 발을 바닥에 둔다.,Step:2 발을 천천히 앞으로 걸어 짐볼을 굴려 머리, 목, 등 상부가 공에 지지되게 한다.,Step:3 손바닥이 앞을 보게 하여 덤벨을 어깨 높이에 둔다.,Step:4 팔을 완전히 펴며 덤벨을 위로 밀어 올린다.,Step:5 정점에서 잠시 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다. 수정된 컨트롤을 강조한다.,Step:6 원하는 횟수만큼 반복한 뒤 반대 팔로 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('eZ79rbI', '무릎을 꿇은 케이블 후방 삼각근(로프 포함)(수컷) 익스텐션', 'https://static.exercisedb.dev/media/eZ79rbI.gif', '삼각근', '어깨', '케이블', '승모근,능형근,이두근', 'Step:1 로우 풀리에 로프 핸들을 연결하고 머신을 마주 보고 무릎을 꿇는다.,Step:2 (익스텐션 변형) 로프를 뉴트럴 그립(손바닥이 서로 마주보게)으로 잡고 팔을 앞쪽으로 완전히 편다.,Step:3 등을 곧게 유지하고 코어에 힘을 준 채 견갑골을 모으며 로프를 몸 쪽으로 당긴다.,Step:4 동작 끝에서 견갑골을 조여 수축하고 잠시 유지한다.,Step:5 긴장을 천천히 풀며 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('syUwUKY', '회전 덤벨 프로네이트 그립 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/syUwUKY.gif', '삼두근', '상완이두근', '덤벨', '전완근', 'Step:1 등을 곧게 세우고 벤치나 의자에 앉아 발을 바닥에 평평하게 둔다.,Step:2 손바닥이 아래를 보도록 양손으로 덤벨을 잡고 팔을 머리 위로 곧게 뻗는다.,Step:3 위팔을 머리 가까이에 두고 팔꿈치가 앞을 향하게 한 채 팔꿈치를 굽혀 덤벨을 머리 뒤로 천천히 내린다.,Step:4 잠시 멈춘 뒤 팔을 펴며 시작 자세로 되돌린다.,Step:5 원하는 횟수만큼 반복한다. 회전 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4H86mXM', '슬레이 45도 한쪽 다리 프레스 포인티드', 'https://static.exercisedb.dev/media/4H86mXM.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신 각도를 45도로 조절한다.,Step:2 패드에 등을 대고 앉아 발을 풋플레이트에 둔다. 포인티드 강도로 수행한다.,Step:3 한쪽 발을 풋플레이트에 두고 다리를 펴며 슬레이를 밀어낸다.,Step:4 무릎을 천천히 굽혀 슬레이를 시작 위치로 내린다.,Step:5 반대쪽 다리로 반복한다.,Step:6 원하는 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mAYqY4M', '쭉 뻗은 풀 플란체 푸쉬업', 'https://static.exercisedb.dev/media/mAYqY4M.gif', '가슴근육', '가슴', '맨몸', '어깨,삼두근,코어', 'Step:1 손을 어깨너비보다 약간 넓게 두고 푸쉬업 자세로 시작한다.,Step:2 코어에 힘을 주고 팔꿈치를 몸통 가까이에 유지하며 몸을 바닥 쪽으로 내린다.,Step:3 내려가면서 상체를 앞으로 기울이고 발을 바닥에서 들어 손으로 균형을 잡는다. 쭉 뻗은 강도로 수행한다.,Step:4 가슴이 바닥 바로 위에 올 때까지 계속 내려간다.,Step:5 손으로 밀어 팔을 펴며 몸을 시작 자세로 들어 올린다.,Step:6 동작 내내 머리부터 발끝까지 일직선을 유지한다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vobtVkm', '벽에 손을 대고 종아리 푸시 스트레칭 엘리트', 'https://static.exercisedb.dev/media/vobtVkm.gif', '종아리근', '종아리', '맨몸', '햄스트링', 'Step:1 벽을 마주보고 발을 엉덩이너비로 벌려 선다.,Step:2 손을 어깨 높이에 두고 벽에 댄다.,Step:3 한쪽 발을 뒤로 내딛고 뒤꿈치를 바닥에 둔 채 다리를 곧게 유지한다.,Step:4 앞쪽 무릎을 살짝 굽히고 상체를 앞으로 기울여 종아리가 늘어나는 것을 느낀다.,Step:5 20–30초 동안 유지한다.,Step:6 다리를 바꿔 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xOXZJRZ', '클락 푸쉬업 익스트림', 'https://static.exercisedb.dev/media/xOXZJRZ.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 손을 어깨 바로 아래에 두고 몸이 일직선이 되도록 하이 플랭크 자세로 시작한다.,Step:2 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 팔꿈치를 몸통 가까이에 유지한다.,Step:3 내려가면서 몸을 왼쪽으로 회전해 왼팔을 옆으로 곧게 뻗는다. 극한 동작에 집중한다.,Step:4 몸을 중앙으로 회전시키며 밀어 올려 시작 자세로 돌아온다.,Step:5 이번에는 오른쪽으로 회전해 오른팔을 옆으로 곧게 뻗으며 푸쉬업을 반복한다.,Step:6 매 반복마다 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('V7rWsT5', '스트롱 레버 밀리터리 프레스', 'https://static.exercisedb.dev/media/V7rWsT5.gif', '삼각근', '어깨', '레버리지 머신', '삼두근,가슴 위쪽', 'Step:1 좌석 높이를 조절하고 머신에 앉아 등을 등받이에 붙인다.,Step:2 오버핸드 그립으로 손잡이를 잡고 손 너비를 어깨너비보다 약간 넓게 둔다.,Step:3 팔을 완전히 펴되 팔꿈치를 잠그지 말고 손잡이를 위로 밀어 올린다.,Step:4 (근력 변형) 정점에서 잠시 멈춘 뒤 손잡이를 천천히 시작 위치로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('omsF3RN', '다이나믹 스타일 밴드 사이드 트라이셉스 익스텐션', 'https://static.exercisedb.dev/media/omsF3RN.gif', '삼두근', '상완이두근', '밴드', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 양손으로 밴드를 잡고 손바닥이 아래를 보게 한다.,Step:2 팔을 옆으로 곧게 뻗어 바닥과 평행하게 유지한다.,Step:3 위팔을 고정한 채 팔꿈치를 천천히 굽혀 손을 어깨 쪽으로 가져간다.,Step:4 잠시 멈춘 뒤 팔을 천천히 펴 시작 자세로 돌아온다.,Step:5 (다이나믹 변형) 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pNIKolI', '짐 볼 라잉 삼두근 스트레칭', 'https://static.exercisedb.dev/media/pNIKolI.gif', '삼두근', '상완이두근', '스태빌리티 볼', '어깨', 'Step:1 발을 바닥에 두고 등을 곧게 편 상태로 짐볼에 앉는다.,Step:2 한 손에 덤벨을 들고 팔을 머리 위로 곧게 뻗는다.,Step:3 팔꿈치를 굽혀 덤벨을 머리 뒤로 내리되 위팔은 귀 가까이에 두고 전체 동작 동안 넓은 폼을 유지한다.,Step:4 몇 초간 유지한 뒤 시작 자세로 돌아온다.,Step:5 반대쪽 팔도 같은 방식으로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0I5fUyn', '클래식 밴드 언더핸드 풀다운', 'https://static.exercisedb.dev/media/0I5fUyn.gif', '광배근', '등', '밴드', '이두근,전완근', 'Step:1 풀업 바나 튼튼한 빔 등 높은 고정 지점에 밴드를 고정한다.,Step:2 고정 지점을 마주 보고 발을 어깨너비로 벌리고 선다.,Step:3 언더핸드 그립으로 밴드를 잡되 손 너비는 어깨너비보다 약간 넓게 한다. 클래식 컨트롤을 강조한다.,Step:4 팔을 머리 위로 완전히 뻗되 팔꿈치를 약간 굽힌다.,Step:5 광배근에 힘을 주고 밴드를 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 바닥 지점에서 잠시 멈춘 뒤 긴장을 천천히 풀며 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('W1p7BND', '운동공을 이용한 가슴 스트레칭 부분', 'https://static.exercisedb.dev/media/W1p7BND.gif', '가슴근육', '가슴', '스태빌리티 볼', '어깨,삼두근', 'Step:1 발을 바닥에 두고 등을 곧게 편 상태로 짐볼에 앉는다.,Step:2 양손으로 짐볼을 잡고 팔을 앞으로 곧게 뻗는다. 부분 가동범위에 집중한다.,Step:3 짐볼을 천천히 가슴 쪽으로 가져와 가슴 근육이 늘어나는 것을 느낀다.,Step:4 몇 초간 유지한 뒤 천천히 시작 자세로 돌아간다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9vz4JlC', '스윙을 비틀어 가중 런지', 'https://static.exercisedb.dev/media/9vz4JlC.gif', '둔근', '허벅지', '가중', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 중량을 든다.,Step:2 오른발을 앞으로 내딛고 런지 자세로 몸을 내린다.,Step:3 런지로 내려가며 팔을 곧게 편 채 중량을 앞으로 위로 스윙한다.,Step:4 오른발로 밀어 시작 자세로 돌아오며 중량을 다시 아래로 스윙한다.,Step:5 (비틀림 변형) 왼발로 반복하고 원하는 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PDHE73u', '제어된 밴드 스트레이트 백 뻣뻣한 다리 데드리프트', 'https://static.exercisedb.dev/media/PDHE73u.gif', '둔근', '허벅지', '밴드', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 서서 밴드를 허벅지 위쪽에 걸어 둔다.,Step:2 양손으로 밴드를 허벅지 앞에서 잡고 손바닥이 몸을 향하게 한다.,Step:3 등을 곧게 유지하고 무릎을 살짝 굽힌 채 엉덩이를 접어 밴드를 바닥 쪽으로 내린다. 통제된 동작에 집중한다.,Step:4 내려가며 햄스트링이 늘어나는 느낌을 받는다.,Step:5 둔근과 햄스트링에 힘을 주어 몸을 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vocve3e', '짐 볼에 부드러운 스타일의 덤벨 한쪽 다리 플라이', 'https://static.exercisedb.dev/media/vocve3e.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐볼에 앉아 양손에 덤벨을 들고 손바닥이 서로 마주보게 한다.,Step:2 한쪽 발은 바닥에 두고 반대쪽 다리는 앞으로 곧게 뻗는다.,Step:3 상체를 약간 앞으로 기울이고 팔을 옆으로 벌리되 팔꿈치를 살짝 굽힌다.,Step:4 가슴이 늘어나는 느낌을 받으며 덤벨을 천천히 옆 아래로 내린다.,Step:5 (부드러운 변형) 바닥 지점에서 잠시 멈춘 뒤 가슴 근육을 조여 덤벨을 시작 자세로 들어 올린다.,Step:6 원하는 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('u3UuCZu', '강렬한 케틀벨 투 암 로우', 'https://static.exercisedb.dev/media/u3UuCZu.gif', '등 위쪽', '등', '케틀벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 무릎을 살짝 굽힌 채 양손에 케틀벨을 들고 손바닥이 몸을 향하게 한다.,Step:2 엉덩이를 접어 상체를 앞으로 숙이되 등을 곧게 유지하고 코어에 힘을 준다.,Step:3 케틀벨을 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:4 정점에서 잠시 멈춘 뒤 케틀벨을 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다. 동작 내내 강렬한 폼을 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('j6uIfep', '바닥에 수축된 케틀벨 익스텐션 범위 원 암 프레스', 'https://static.exercisedb.dev/media/j6uIfep.gif', '가슴근육', '가슴', '케틀벨', '삼두근,어깨', 'Step:1 등을 대고 바닥에 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 한 손에 케틀벨을 들고 손바닥이 발 쪽을 향하게 한다.,Step:3 팔꿈치를 잠근 채 손목을 곧게 유지하며 팔을 천장 쪽으로 곧게 뻗는다.,Step:4 동작을 통제하며 케틀벨을 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한 뒤 반대 팔로 바꿔 수행한다. 수축 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Dx2RIva', '트리플 스타일 슬레이 한쪽 다리 종아리 프레스 온 레그 프레스', 'https://static.exercisedb.dev/media/Dx2RIva.gif', '종아리근', '종아리', '슬레이 기계', '햄스트링,둔근', 'Step:1 레그 프레스 머신 좌석을 조절해 발을 슬레이에 뒀을 때 무릎이 약간 굽혀지게 한다.,Step:2 등받이에 등을 대고 앉아 발을 어깨너비로 슬레이에 둔다.,Step:3 발끝과 발볼만 슬레이에 두고 뒤꿈치를 들어 올린다.,Step:4 무릎을 약간 굽힌 채 발목을 펴며 슬레이를 밀어 올린다.,Step:5 정점에서 잠시 멈춘 뒤 발목을 굽혀 슬레이를 천천히 내린다.,Step:6 원하는 횟수만큼 반복한다. 트리플 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ul5OFSV', '저항 밴드 다리 익스텐션이 거부되었습니다.', 'https://static.exercisedb.dev/media/Ul5OFSV.gif', '대퇴사두근', '허벅지', '저항 밴드', '햄스트링', 'Step:1 저항 밴드를 튼튼한 고정 지점에 연결하고 발목에 고정한다.,Step:2 고정 지점을 마주 보고 발을 어깨너비로 벌리고 선다.,Step:3 코어에 힘을 주고 상체를 안정적으로 유지한 채 다리를 앞쪽으로 곧게 뻗는다.,Step:4 정점에서 잠시 멈춘 뒤 다리를 천천히 시작 자세로 되돌린다. 디클라인 동작에 집중한다.,Step:5 원하는 횟수만큼 반복한 뒤 다리를 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1RIkUHT', '덤벨 아이언 크로스 - 향상된 변형', 'https://static.exercisedb.dev/media/1RIkUHT.gif', '삼각근', '어깨', '덤벨', '삼두근,가슴', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 몸 옆에 든다.,Step:2 팔을 옆으로 들어 바닥과 평행하게 하여 몸과 T자를 만든다. 향상된 강도로 수행한다.,Step:3 잠시 멈춘 뒤 팔을 천천히 내려 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IBj3nsn', '구불구불 풋 워크 v. 2', 'https://static.exercisedb.dev/media/IBj3nsn.gif', '대퇴사두근', '허벅지', '맨몸', '종아리근,햄스트링', 'Step:1 발을 어깨너비로 벌리고 서서 팔을 몸 옆에 둔다.,Step:2 제자리에서 달리듯 발을 빠르게 위아래로 움직이기 시작한다.,Step:3 발볼로 가볍게 디디며 빠르고 가벼운 움직임을 유지한다.,Step:4 원하는 시간 또는 반복 횟수만큼 계속한다. 굽힌 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('3QgteDK', '바벨 와이드 리버스 그립 벤치 프레스 수평', 'https://static.exercisedb.dev/media/3QgteDK.gif', '가슴근육', '가슴', '바벨', '삼두근,어깨', 'Step:1 벤치에 등을 대고 누워 발을 바닥에 평평하게 두며 등을 벤치에 밀착한다.,Step:2 손바닥이 자신을 향하는 와이드 리버스 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 랙에서 바벨을 들어 올려 가슴 위에 팔을 완전히 편 채 유지한다.,Step:4 팔꿈치를 몸통 가까이에 두고 손목을 곧게 유지하며 바벨을 천천히 가슴 쪽으로 내린다. 수평 동작에 집중한다.,Step:5 바벨이 가슴에 닿으면 잠시 멈춘 뒤 바벨을 밀어 올려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DoEYq4s', '시시 스쿼트 격리', 'https://static.exercisedb.dev/media/DoEYq4s.gif', '대퇴사두근', '허벅지', '맨몸', '종아리근,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 발끝을 약간 바깥쪽으로 향하게 한다.,Step:2 필요하면 균형을 위해 안정적인 물체를 잡는다.,Step:3 상체를 세운 채 무릎을 굽히고 몸을 뒤로 기울이며 천천히 내려간다.,Step:4 허벅지가 바닥과 평행해질 때까지 또는 가능한 범위까지 내려간다.,Step:5 잠시 멈춘 뒤 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다. 격리 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8yBgwBS', '케이블 컨센트레이션 컬 템포', 'https://static.exercisedb.dev/media/8yBgwBS.gif', '이두근', '상완이두근', '케이블', '전완근', 'Step:1 벤치나 의자에 앉아 발을 바닥에 두고 무릎을 살짝 굽힌다.,Step:2 언더핸드 그립으로 케이블 핸들을 잡고 팔꿈치를 허벅지 안쪽에 고정한다. 템포 동작에 집중한다.,Step:3 위팔은 고정한 채 내쉬며 핸들을 어깨 쪽으로 말아 올려 이두근을 수축한다.,Step:4 정점에서 잠시 멈춘 뒤 들이마시며 핸들을 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('oMwyl17', '강렬한 바벨 스트레이트 레그 데드리프트', 'https://static.exercisedb.dev/media/oMwyl17.gif', '햄스트링', '허벅지', '바벨', '둔근,허리', 'Step:1 발을 어깨너비로 벌리고 발끝을 정면으로 향하게 선다.,Step:2 오버핸드 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:3 엉덩이를 접어 바벨을 바닥 쪽으로 내리되 등을 곧게 유지하고 무릎을 살짝 굽힌다.,Step:4 햄스트링이 늘어나는 지점까지 바벨을 내린다. 동작 내내 강렬한 폼을 유지한다.,Step:5 햄스트링과 둔근에 힘을 주어 바벨을 들어 올려 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KWyEjtI', 'V바가 있는 정밀 스타일 레버 벤트오버 로우', 'https://static.exercisedb.dev/media/KWyEjtI.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이를 조절하고 머신을 마주 보며 자세를 잡는다.,Step:2 오버핸드 그립으로 V바를 잡고 등을 곧게 유지하며 무릎을 살짝 굽힌다.,Step:3 V바를 복부 쪽으로 당기며 견갑골을 모아 조인다.,Step:4 정점에서 잠시 멈춘 뒤 중량을 천천히 시작 위치로 되돌린다. 정밀한 컨트롤을 강조한다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gMyx3Qn', '하이 스타일 견갑골 푸쉬업', 'https://static.exercisedb.dev/media/gMyx3Qn.gif', '전거근', '가슴', '맨몸', '삼두근,어깨', 'Step:1 손을 어깨 바로 아래에 두고 몸이 일직선이 되도록 하이 플랭크 자세로 시작한다.,Step:2 팔꿈치를 몸통 가까이에 두고 가슴을 바닥 쪽으로 내린다.,Step:3 내려가면서 견갑골을 모아 조이고 가슴을 앞으로 내민다. 하이 동작에 집중한다.,Step:4 바닥 지점에서 잠시 멈춘 뒤 밀어 올려 시작 자세로 돌아온다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EqHIIjJ', '바벨 리버스 프리처 컬 인클라인', 'https://static.exercisedb.dev/media/EqHIIjJ.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 프리처 벤치에 앉아 가슴을 패드에 대고 오버핸드 그립으로 바벨을 잡은 채 팔을 아래로 곧게 뻗는다.,Step:2 위팔을 고정한 채 내쉬며 바벨을 위로 말아 올려 이두근을 수축한다.,Step:3 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 계속 들어 올린다. 경사 강도로 수행한다.,Step:4 수축 지점에서 잠시 멈추며 이두근을 조인다.,Step:5 들이마시며 바벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7y9JIMj', '레버 리버스 그립 프리처 컬 정밀함', 'https://static.exercisedb.dev/media/7y9JIMj.gif', '이두근', '상완이두근', '레버리지 머신', '전완근', 'Step:1 좌석 높이를 조절하고 레버리지 머신에 자세를 잡는다.,Step:2 손바닥이 위를 보도록 언더핸드 그립으로 손잡이를 잡는다.,Step:3 상완을 프리처 패드에 대고 팔꿈치를 완전히 편다. 동작 내내 정밀한 폼을 유지한다.,Step:4 위팔을 고정한 채 내쉬며 손잡이를 어깨 쪽으로 말아 올린다.,Step:5 정점에서 잠시 멈추며 이두근을 조인다.,Step:6 들이마시며 손잡이를 천천히 시작 자세로 내리고 팔꿈치를 완전히 편다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('58rdhvL', '내로우 스타일 밴드 잭나이프 윗몸일으키기', 'https://static.exercisedb.dev/media/58rdhvL.gif', '복근', '허리', '밴드', '고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 밴드를 잡은 채 팔을 머리 위로 뻗는다.,Step:2 복근에 힘을 주어 다리와 상체를 동시에 들어 올리며 손을 발 쪽으로 가져간다.,Step:3 정점에서 잠시 멈춘 뒤 다리와 상체를 천천히 시작 자세로 내린다.,Step:4 원하는 횟수만큼 반복한다. 내로우 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Ql4g5s8', '벤치를 이용한 포워드 런지(남자)', 'https://static.exercisedb.dev/media/Ql4g5s8.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 엉덩이너비로 벌리고 서서 손을 허리에 둔다.,Step:2 오른발을 크게 앞으로 내딛고 런지 자세로 몸을 내린다.,Step:3 오른쪽 무릎을 약 90도로 굽혀 무릎이 발목 위에 오도록 정렬한다.,Step:4 오른발로 밀어 시작 자세로 돌아온다. 벤치 동작에 집중한다.,Step:5 왼쪽 다리로 반복하며 좌우를 번갈아 원하는 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gTGciXz', '크로스 베어 크롤링', 'https://static.exercisedb.dev/media/gTGciXz.gif', '심혈관계', '유산소', '맨몸', '코어,어깨,삼두근', 'Step:1 손은 어깨 바로 아래, 무릎은 엉덩이 바로 아래에 두고 네발기기 자세로 시작한다.,Step:2 등을 평평하게 유지하고 코어에 힘을 준 채 무릎을 바닥에서 살짝 들어 올린다.,Step:3 오른손과 왼발을 동시에 앞으로 옮긴 뒤 왼손과 오른발을 옮긴다.,Step:4 손과 발을 번갈아 움직이며 앞으로 기어간다.,Step:5 일정한 속도를 유지하고 동작 내내 코어를 단단히 유지한다.,Step:6 (교대 변형) 원하는 거리 또는 시간만큼 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8gQo5Ss', '싱글 스타일 케이블 스탠딩 크런치(로프 부착 포함)', 'https://static.exercisedb.dev/media/8gQo5Ss.gif', '복근', '허리', '케이블', '복사근', 'Step:1 가슴 높이에 케이블 머신에 로프를 연결한다.,Step:2 머신을 등지고 서서 발을 어깨너비로 벌린다. 싱글 동작에 집중한다.,Step:3 양손으로 로프를 잡아 머리 뒤로 가져가며 팔꿈치를 굽힌다.,Step:4 복근에 힘을 주고 상체를 천천히 앞으로 말아 내리며 팔꿈치를 무릎 쪽으로 가져간다.,Step:5 크런치 정점에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PKlXuJW', '러프 밴드 푸쉬 윗몸일으키기', 'https://static.exercisedb.dev/media/PKlXuJW.gif', '복근', '허리', '밴드', '어깨,가슴', 'Step:1 밴드를 안정적인 고정 지점에 단단히 고정한다.,Step:2 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:3 양손으로 밴드를 잡고 팔을 천장 쪽으로 곧게 뻗는다. 러프 동작에 집중한다.,Step:4 복근에 힘을 주고 상체를 천천히 들어 올려 몸통이 약 45도가 될 때까지 말아 올린다.,Step:5 정점에서 잠시 멈춘 뒤 상체를 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Qj0HRAZ', '패스트 스타일 저항 밴드 장착 엉덩이 외전', 'https://static.exercisedb.dev/media/Qj0HRAZ.gif', '외전근', '허벅지', '저항 밴드', '둔근,햄스트링', 'Step:1 등을 곧게 세우고 의자나 벤치에 앉아 발을 바닥에 평평하게 둔다.,Step:2 저항 밴드를 허벅지에 감아 무릎 바로 위에 위치시킨다.,Step:3 지지를 위해 의자나 벤치 옆을 손으로 잡는다.,Step:4 (빠른 변형) 허벅지 바깥쪽 근육(외전근)에 힘을 주어 무릎을 밴드 저항에 대항해 천천히 벌린다.,Step:5 끝 지점에서 잠시 멈춘 뒤 무릎을 천천히 다시 모은다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IU4QNJ6', '퓨어 풀업', 'https://static.exercisedb.dev/media/IU4QNJ6.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 손바닥이 자신을 향하게 하여 어깨너비로 풀업 바에 매달린다.,Step:2 코어에 힘을 주고 가슴을 리드하며 몸을 바 쪽으로 끌어올린다. 순수한 컨트롤을 강조한다.,Step:3 턱이 바 위로 올라갈 때까지 계속 당긴다.,Step:4 정점에서 잠시 멈춘 뒤 몸을 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('numr601', '라이트 레버 스탠딩 체스트 프레스', 'https://static.exercisedb.dev/media/numr601.gif', '가슴근육', '가슴', '레버리지 머신', '어깨,삼두근', 'Step:1 좌석 높이를 조절하고 머신에 앉아 발을 바닥에 평평하게 둔다.,Step:2 오버핸드 그립으로 손잡이를 잡고 손을 가슴 높이에 위치시킨다. 동작 내내 라이트 폼을 유지한다.,Step:3 팔꿈치를 약간 굽힌 채 팔을 완전히 펴며 손잡이를 앞으로 민다.,Step:4 잠시 멈춘 뒤 손잡이를 천천히 가슴 쪽으로 되돌리며 통제한다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hTLtkXL', '거부된 저항 밴드 장착 숄더 프레스', 'https://static.exercisedb.dev/media/hTLtkXL.gif', '삼각근', '어깨', '저항 밴드', '삼두근,등 위쪽', 'Step:1 등을 곧게 세우고 의자나 벤치에 앉아 발을 바닥에 평평하게 둔다.,Step:2 양손으로 저항 밴드를 잡고 손바닥이 앞을 보게 하여 어깨 높이까지 올린다.,Step:3 팔을 완전히 펴며 밴드를 머리 위로 밀어 올린다.,Step:4 정점에서 잠시 멈춘 뒤 밴드를 천천히 어깨 높이로 내린다. 디클라인 컨트롤을 강조한다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Um8xUAc', '인클라인 컬과 바벨 프론 인클라인 컬', 'https://static.exercisedb.dev/media/Um8xUAc.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 인클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 엎드려 가슴과 복부를 벤치에 밀착한다.,Step:3 언더핸드 그립으로 바벨을 어깨너비로 잡는다.,Step:4 팔을 완전히 펴 바벨이 바닥 쪽으로 늘어지게 한다.,Step:5 위팔을 고정한 채 내쉬며 바벨을 말아 올려 이두근을 수축한다.,Step:6 이두근이 완전히 수축되고 바벨이 어깨 높이에 올 때까지 계속 들어 올린다.,Step:7 (집중 변형) 수축 지점에서 잠시 멈추며 이두근을 조인다.,Step:8 들이마시며 바벨을 천천히 시작 자세로 내리기 시작한다.,Step:9 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AdxxqfF', '바벨 스탠딩 리버스 그립 컬 저항', 'https://static.exercisedb.dev/media/AdxxqfF.gif', '이두근', '상완이두근', '바벨', '전완근', 'Step:1 발을 어깨너비로 벌리고 서서 언더핸드 그립으로 바벨을 잡고 손바닥이 위를 향하게 한다.,Step:2 팔꿈치를 몸통에 붙이고 위팔을 고정한다.,Step:3 내쉬며 바벨을 말아 올려 이두근을 수축하고 바벨을 어깨에 가깝게 가져간다.,Step:4 수축 지점에서 잠시 멈추며 이두근을 조인다.,Step:5 들이마시며 바벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다. 저항 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('8IbNZwc', '러프 밴드 힙 리프트', 'https://static.exercisedb.dev/media/8IbNZwc.gif', '둔근', '허벅지', '밴드', '햄스트링,대퇴사두근', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 저항 밴드를 무릎 바로 위에 둔다.,Step:3 둔근과 코어에 힘을 준다.,Step:4 뒤꿈치로 바닥을 누르며 엉덩이를 들어 올려 정점에서 둔근을 조인다.,Step:5 정점에서 잠시 멈춘 뒤 엉덩이를 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다. 러프 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fBnPpzd', '유연한 보조 엎드린 햄스트링', 'https://static.exercisedb.dev/media/fBnPpzd.gif', '햄스트링', '허벅지', '도움을 준', '둔근,허리', 'Step:1 매트나 벤치에 엎드려 다리를 완전히 편다.,Step:2 (유연한 변형) 파트너가 발목을 잡아주거나 저항 밴드로 발목을 고정한다.,Step:3 햄스트링에 힘을 주어 무릎을 편 상태로 다리를 둔근 쪽으로 들어 올린다.,Step:4 정점에서 잠시 멈춘 뒤 다리를 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('woLo1QN', '인클라인 푸쉬업(온박스) - 활성 변형', 'https://static.exercisedb.dev/media/woLo1QN.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 상자나 높은 지면 가장자리에 손을 어깨너비보다 약간 넓게 올린다.,Step:2 다리를 뒤로 뻗고 발볼로 지지해 머리부터 발끝까지 일직선을 만든다.,Step:3 팔꿈치를 굽혀 가슴을 상자 쪽으로 내리되 몸을 일직선으로 유지한다.,Step:4 바닥 지점에서 잠시 멈춘 뒤 팔을 펴며 시작 자세로 돌아온다.,Step:5 (활성 변형) 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EnPivTL', '바벨 벤트 암 풀오버 - 강력한 변형', 'https://static.exercisedb.dev/media/EnPivTL.gif', '광배근', '등', '바벨', '삼두근,가슴', 'Step:1 벤치에 등을 대고 누워 머리는 한쪽 끝에 두고 발은 바닥에 둔다.,Step:2 어깨너비 그립으로 바벨을 잡고 가슴 위로 팔을 곧게 뻗는다.,Step:3 팔을 약간 굽힌 채 바벨을 머리 뒤로 내린다.,Step:4 잠시 멈춘 뒤 바벨을 다시 시작 자세로 들어 올린다.,Step:5 원하는 횟수만큼 반복한다. 강력한 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1oE78pm', '코어 바벨 업라이트 로우 v. 2', 'https://static.exercisedb.dev/media/1oE78pm.gif', '삼각근', '어깨', '바벨', '승모근,이두근', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 바벨을 어깨너비보다 약간 넓게 잡는다.,Step:2 팔을 완전히 편 채 바벨을 허벅지 앞에 둔다. 코어 강도로 수행한다.,Step:3 등을 곧게 유지한 채 내쉬며 팔꿈치를 리드해 바벨을 턱 쪽으로 수직으로 들어 올린다.,Step:4 정점에서 잠시 멈춘 뒤 들이마시며 바벨을 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XE93sQZ', '덤벨 스텝업 싱글 레그 밸런스와 바이셉 컬 - 의자 변형', 'https://static.exercisedb.dev/media/XE93sQZ.gif', '이두근', '상완이두근', '덤벨', '대퇴사두근,둔근,햄스트링', 'Step:1 양손에 덤벨을 들고 손바닥이 몸을 향하게 한 채 스텝이나 플랫폼 앞에 선다.,Step:2 오른발을 스텝 위에 올려 발 전체가 지면에 닿게 한다.,Step:3 코어에 힘을 주고 오른쪽 뒤꿈치로 밀어 몸을 스텝 위로 올리며 왼쪽 무릎을 가슴 쪽으로 들어 올린다.,Step:4 정점에서 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 올리는 바이셉 컬을 수행한다.,Step:5 덤벨을 다시 내리면서 왼발을 바닥으로 내리고 몸을 내려온다.,Step:6 (의자 변형) 반대쪽도 동일하게 왼발로 스텝업하며 바이셉 컬을 수행한다.,Step:7 원하는 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pgIdT6i', '원 암 밴드 서기 낮은 줄 - 사이드 변형', 'https://static.exercisedb.dev/media/pgIdT6i.gif', '등 위쪽', '등', '밴드', '이두근,어깨', 'Step:1 허리 높이의 안정적인 고정 지점에 밴드를 고정한다.,Step:2 고정 지점을 마주 보고 발을 어깨너비로 벌리고 선다.,Step:3 한 손으로 밴드를 잡고 손바닥이 안쪽을 보게 한 채 뒤로 물러나 밴드에 긴장을 만든다.,Step:4 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등을 곧게 유지한다.,Step:5 밴드를 허리 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 정점에서 잠시 멈춘 뒤 밴드를 천천히 시작 자세로 되돌린다.,Step:7 원하는 횟수만큼 반복한 뒤 반대쪽도 수행한다. 측면 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jvEXp4N', '지구력 원 암 딥스', 'https://static.exercisedb.dev/media/jvEXp4N.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치나 의자를 등지고 서서 발을 어깨너비로 벌린다.,Step:2 한 손을 뒤의 벤치나 의자에 올리고 손가락이 몸 쪽을 향하게 한다. 동작 내내 지구력 폼을 유지한다.,Step:3 다리를 앞으로 뻗고 뒤꿈치를 바닥에 둔다.,Step:4 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 벤치/의자에 몸을 가깝게 유지한다.,Step:5 바닥 지점에서 잠시 멈춘 뒤 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한 뒤 팔을 바꿔 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UOphC6N', '케이블 사이드이 부드럽게 구부러짐', 'https://static.exercisedb.dev/media/UOphC6N.gif', '복근', '허리', '케이블', '복사근', 'Step:1 발을 어깨너비로 벌리고 서서 한 손으로 케이블 핸들을 잡는다.,Step:2 등을 곧게 세우고 코어에 힘을 준다.,Step:3 허리를 옆으로 천천히 굽혀 핸들이 무릎 쪽으로 내려가게 한다.,Step:4 잠시 멈춘 뒤 시작 자세로 돌아온다. 부드러운 동작에 집중한다.,Step:5 반대쪽도 동일하게 수행한다.,Step:6 원하는 횟수만큼 좌우를 번갈아 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IH2kr7n', '덤벨 디클라인 슈러그 - 변형', 'https://static.exercisedb.dev/media/IH2kr7n.gif', '승모근', '등', '덤벨', '어깨,능형근', 'Step:1 디클라인 벤치를 45도로 세팅한다.,Step:2 벤치에 엎드려 가슴과 복부를 벤치에 밀착한다.,Step:3 (경직 변형) 양손에 덤벨을 들고 팔을 바닥 쪽으로 완전히 늘어뜨린다.,Step:4 팔을 곧게 편 채 어깨를 귀 쪽으로 가능한 높이 끌어올린다.,Step:5 수축을 잠시 유지한 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('PCUYOMs', '펄스 스타일 워크 일립티컬 크로스 트레이너', 'https://static.exercisedb.dev/media/PCUYOMs.gif', '심혈관계', '유산소', '타원형 기계', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 일립티컬 머신의 저항과 경사도를 원하는 수준으로 조절한다.,Step:2 페달에 올라서고 손잡이를 가볍게 잡는다.,Step:3 발로 페달을 누르면서 동시에 손잡이를 몸 쪽으로 당기는 동작을 시작한다.,Step:4 누르고 당기는 동작을 번갈아 반복해 걷기/달리기와 유사한 움직임을 만든다.,Step:5 일정한 페이스를 유지하고 동작 내내 코어에 힘을 준다. 펄스 컨트롤을 강조한다.,Step:6 원하는 유산소 운동 시간 동안 계속한다.,Step:7 내리기 전에 머신의 강도와 속도를 서서히 낮춘다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('drfGhTV', '밸런스 케이블 인클라인 플라이', 'https://static.exercisedb.dev/media/drfGhTV.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 머신을 낮은 위치로 조절하고 손잡이를 연결한다.,Step:2 인클라인 벤치에 앉아 등을 패드에 대고 발을 바닥에 둔다. 밸런스 강도로 수행한다.,Step:3 오버핸드 그립으로 손잡이를 잡고 팔을 앞으로 곧게 뻗는다.,Step:4 팔꿈치를 약간 굽힌 채 통제하며 팔을 옆으로 벌린다.,Step:5 팔이 충분히 벌어진 지점에서 잠시 멈춘 뒤 천천히 시작 자세로 돌아온다.,Step:6 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7i4msxz', '메가와 고치', 'https://static.exercisedb.dev/media/7i4msxz.gif', '복근', '허리', '맨몸', '고관절 굴근,허리', 'Step:1 등을 대고 누워 무릎을 굽히고 발바닥을 바닥에 둔다.,Step:2 손을 머리 뒤에 두고 팔꿈치를 바깥쪽으로 향하게 한다.,Step:3 복근에 힘을 주어 상체를 천천히 들어 올려 몸통이 약 45도가 될 때까지 말아 올린다.,Step:4 정점에서 잠시 멈춘 뒤 상체를 천천히 시작 자세로 내린다.,Step:5 원하는 횟수만큼 반복한다. 메가 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('dAJscVq', '케이블 인클라인 벤치 로우 - 엘리트 변형', 'https://static.exercisedb.dev/media/dAJscVq.gif', '등 위쪽', '등', '케이블', '이두근,후면 삼각근', 'Step:1 인클라인 벤치를 45도로 세팅하고 로우 풀리에 케이블 핸들을 연결한다.,Step:2 케이블 머신을 마주 보고 벤치에 앉아 발을 바닥에 두고 무릎을 살짝 굽힌다.,Step:3 오버핸드 그립으로 핸들을 잡고 팔을 앞쪽으로 완전히 편다. 엘리트 강도로 수행한다.,Step:4 엉덩이에서 상체를 앞으로 기울이되 등을 곧게 유지하고 코어에 힘을 준다.,Step:5 견갑골을 모으며 팔꿈치를 굽혀 핸들을 가슴 쪽으로 당긴다.,Step:6 정점에서 등 근육을 조인 뒤 팔을 천천히 펴 시작 자세로 돌아온다.,Step:7 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9tvVVM9', '소프트 케이블 삼두근 푸시다운(v-bar)', 'https://static.exercisedb.dev/media/9tvVVM9.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 케이블 머신의 가장 높은 위치에 V바 어태치먼트를 연결한다.,Step:2 발을 어깨너비로 벌리고 케이블 머신을 마주 보고 선다.,Step:3 오버핸드 그립으로 V바를 어깨너비로 잡고 손바닥이 아래를 보게 한다.,Step:4 팔꿈치를 몸통에 붙이고 위팔을 고정한 채 동작한다.,Step:5 삼두근에 힘을 주고 내쉬며 V바를 아래로 밀어 팔을 완전히 편다. 유연한 강도로 수행한다.,Step:6 바닥 지점에서 잠시 멈추며 삼두근을 조인다.,Step:7 들이마시며 V바를 천천히 시작 자세로 올리되 통제한다.,Step:8 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('2Ty4idJ', '어드밴스드 덤벨 스티프 레그 데드리프트', 'https://static.exercisedb.dev/media/2Ty4idJ.gif', '둔근', '허벅지', '덤벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 서서 오버핸드 그립으로 양손에 덤벨을 든다.,Step:2 등을 곧게 유지하고 코어에 힘을 준 채 엉덩이를 접어 덤벨을 바닥 쪽으로 내리며 무릎은 약간만 굽힌다. 어드밴스드 동작에 집중한다.,Step:3 햄스트링이 늘어나는 지점까지 내린 뒤 둔근을 조이고 뒤꿈치로 밀어 시작 자세로 돌아온다.,Step:4 원하는 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('xmWQIlT', '홀드 스타일 덤벨 체인지 짐볼 바이셉스 컬', 'https://static.exercisedb.dev/media/xmWQIlT.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐 볼 위에 앉아 발바닥을 바닥에 붙이고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥이 정면을 보게 한 채 팔을 완전히 편다.,Step:3 상완을 고정한 상태에서 내쉬며 한쪽 덤벨을 말아 올리고, 전완을 회전해 손바닥이 어깨를 향하도록 한다.,Step:4 (홀드 변형) 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:5 반대쪽 팔로 같은 동작을 반복한다.,Step:6 원하는 반복 횟수만큼 번갈아 컬을 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('w7obpWd', '액티브 스타일 케이블 푸시다운', 'https://static.exercisedb.dev/media/w7obpWd.gif', '삼두근', '상완이두근', '케이블', '전완근', 'Step:1 하이 풀리 케이블 머신에 일자 바를 연결한다.,Step:2 머신을 마주 보고 서서 발은 어깨너비로 벌리고 무릎은 살짝 굽힌다.,Step:3 오버핸드 그립으로 바를 잡되 손 간격은 어깨너비로 한다.,Step:4 팔꿈치를 몸통 옆에 붙이고 상완은 고정한다.,Step:5 내쉬며 팔꿈치가 완전히 펴질 때까지 바를 아래로 민다.,Step:6 잠깐 멈춘 뒤 들이마시며 바를 천천히 시작 위치로 되돌린다. 전 과정에서 액티브한 자세를 유지한다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('JxrY9mC', '안정성 스타일 밴드 무릎 꿇기 원 암 풀다운', 'https://static.exercisedb.dev/media/JxrY9mC.gif', '광배근', '등', '밴드', '이두근,능형근', 'Step:1 머리 위 높이에 있는 단단한 고정 지점에 밴드를 걸어 둔다.,Step:2 무릎을 꿇고 한 손으로 밴드를 잡되 손바닥은 아래를 향하게 한다.,Step:3 팔을 머리 위로 완전히 뻗고 팔꿈치는 약간 굽힌다.,Step:4 광배근에 힘을 주며 밴드를 옆구리 쪽으로 끌어내려 팔꿈치가 갈비뼈 쪽으로 오게 한다.,Step:5 아래 지점에서 잠깐 멈춘 뒤 천천히 장력을 풀며 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽으로 바꿔 실시한다. 안정성 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6Wr0F3W', '둥글게 꼬인 레그레이즈(여성)', 'https://static.exercisedb.dev/media/6Wr0F3W.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 등을 대고 바닥에 누워 다리를 곧게 펴고 팔은 몸 옆에 둔다.,Step:2 무릎을 굽혀 다리를 바닥에서 들어 올리고 가슴 쪽으로 당긴다. 둥글게 말아 올리는 컨트롤을 강조한다.,Step:3 다리를 올리며 엉덩이를 한쪽으로 비틀어 무릎이 반대쪽 어깨 방향으로 가게 한다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 시작 자세로 내린다.,Step:5 이번에는 반대쪽으로 엉덩이를 비틀며 같은 동작을 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('FSF9WOs', '높은 평행봉을 이용한 와이드 그립 체스트 딥 - 낮은 변형', 'https://static.exercisedb.dev/media/FSF9WOs.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨', 'Step:1 평행봉 위에 올라 팔을 완전히 펴고 몸을 공중에 띄운다.,Step:2 상체를 약간 앞으로 기울인 뒤 팔꿈치를 굽혀 가슴이 봉 바로 위에 올 때까지 몸을 내린다.,Step:3 (낮은 변형) 잠깐 멈춘 뒤 팔을 펴며 시작 자세로 밀어 올린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QoSZo2Y', '케이블 한쪽 팔 인클라인 프레스(강성)', 'https://static.exercisedb.dev/media/QoSZo2Y.gif', '가슴근육', '가슴', '케이블', '삼각근,삼두근', 'Step:1 케이블 머신을 로우 풀리 위치로 설정한다.,Step:2 인클라인 벤치에 앉되 케이블 머신을 등지고 앉는다.,Step:3 한 손으로 손잡이를 잡고 어깨 높이까지 올린다. 강한 고정 컨트롤을 강조한다.,Step:4 발을 바닥에 단단히 고정하고 자세가 흔들리지 않게 유지한다.,Step:5 손잡이를 전방 위쪽으로 밀어 팔을 완전히 편다.,Step:6 위에서 잠깐 멈춘 뒤 손잡이를 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('b5uBMv2', '빠른 속도로 팔을 번갈아 가며 짐 볼', 'https://static.exercisedb.dev/media/b5uBMv2.gif', '광배근', '등', '스태빌리티 볼', '어깨,코어', 'Step:1 스태빌리티 볼 위에 앉아 발바닥을 바닥에 붙이고 등을 곧게 편다.,Step:2 양손에 덤벨을 들고 손바닥이 안쪽을 보게 한 채 팔을 몸 옆으로 늘어뜨린다.,Step:3 코어에 힘을 주고 한쪽 팔을 어깨 쪽으로 천천히 들어 올리되 팔꿈치는 약간 굽힌다. 빠른 강도로 수행한다.,Step:4 위에서 잠깐 멈춘 뒤 팔을 천천히 시작 자세로 내린다.,Step:5 반대쪽 팔로 같은 동작을 반복한다.,Step:6 원하는 반복 횟수만큼 팔을 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Sa8mzWc', '길로틴 파이크', 'https://static.exercisedb.dev/media/Sa8mzWc.gif', '복근', '허리', '맨몸', '고관절 굴근,어깨', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥은 바깥쪽을 보게 한다.,Step:2 코어에 힘을 주고 다리를 곧게 편 채 바 쪽으로 들어 올린다.,Step:3 몸이 \'V\'자 형태가 되도록 계속 들어 올려 다리가 바닥과 평행해질 때까지 올린다. 약한 컨트롤을 강조한다.,Step:4 자세를 잠깐 유지한 뒤 다리를 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Rsxr3xl', '한쪽 팔을 벽에 대고 압박됨', 'https://static.exercisedb.dev/media/Rsxr3xl.gif', '광배근', '등', '맨몸', '어깨,삼두근', 'Step:1 벽을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:2 한쪽 팔을 앞으로 곧게 뻗어 손바닥을 벽에 댄다.,Step:3 코어에 힘을 주고 몸을 앞으로 기울이되 팔은 곧게, 등은 평평하게 유지한다. 전 과정에서 압박된 자세를 유지한다.,Step:4 손바닥으로 벽을 천천히 밀어 광배근을 활성화한다.,Step:5 몇 초간 유지한 뒤 힘을 풀고 반대쪽 팔로 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('TBNaSNs', 'ez 바벨 디클라인 클로즈 그립 페이스 프레스 - 미니 변형', 'https://static.exercisedb.dev/media/TBNaSNs.gif', '삼두근', '상완이두근', 'EZ 바벨', '가슴,어깨', 'Step:1 머리가 발보다 낮게 되도록 디클라인 벤치에 눕는다.,Step:2 EZ 바벨을 클로즈 그립으로 잡되 손바닥이 서로 마주 보게 한다.,Step:3 팔꿈치를 몸 가까이에 둔 채 팔을 곧게 펴 가슴 위로 바벨을 올린다.,Step:4 팔꿈치를 굽혀 바벨을 이마 쪽으로 천천히 내린다.,Step:5 잠깐 멈춘 뒤 바벨을 시작 자세로 다시 밀어 올린다. 미니 컨트롤을 강조한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('J1vH2X0', '한 손에 무게를 싣고 빠르게 끌어올리기', 'https://static.exercisedb.dev/media/J1vH2X0.gif', '광배근', '등', '가중', '이두근,전완근', 'Step:1 풀업 바를 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:2 팔을 완전히 편 채 바에 매달리고 몸을 곧게 유지한다.,Step:3 코어에 힘을 주고 팔꿈치를 굽히며 등 근육을 조여 몸을 위로 끌어올린다.,Step:4 턱이 바 위로 올라올 때까지 계속 당긴다.,Step:5 (빠른 변형) 컨트롤하며 몸을 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('EpKrFiv', '인클라인 푸쉬업 콤플렉스를 이용한 깊이 점프', 'https://static.exercisedb.dev/media/EpKrFiv.gif', '가슴근육', '가슴', '맨몸', '삼두근,어깨,코어', 'Step:1 벤치나 스텝 같은 높이가 있는 지면을 찾아 가장자리에 손을 어깨너비로 둔다.,Step:2 발을 뒤로 빼 머리부터 발끝까지 일직선이 되게 한다.,Step:3 팔꿈치를 굽혀 가슴을 지지면 가장자리 쪽으로 내리되 몸 정렬을 유지한다. 전 과정에서 콤플렉스한 자세를 유지한다.,Step:4 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아간다.,Step:5 지지면에서 점프해 내려오고 무릎을 살짝 굽혀 부드럽게 착지한다.,Step:6 원하는 반복 횟수만큼 푸시업과 깊이 점프를 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9fCHfSc', '뾰족한 케이블 손바닥 회전 행', 'https://static.exercisedb.dev/media/9fCHfSc.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 허리 높이에 케이블 머신 손잡이를 연결한다.,Step:2 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 손잡이를 잡되 손바닥은 아래를 향하게 한다.,Step:4 뒤로 한 걸음 물러나 케이블에 장력을 만들고, 등은 곧게, 무릎은 살짝 굽힌다. 뾰족한 컨트롤을 강조한다.,Step:5 손잡이를 몸 쪽으로 당기면서 손바닥이 위를 향하도록 회전한다.,Step:6 동작 끝에서 견갑골을 모아 조인다.,Step:7 손잡이를 천천히 시작 자세로 되돌린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('QQwxa8g', '중급 스타일 덤벨 설교자 컬 오버 짐 볼', 'https://static.exercisedb.dev/media/QQwxa8g.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 짐 볼 위에 앉아 발바닥을 바닥에 붙이고 등을 곧게 편다.,Step:2 한 손에 덤벨을 언더핸드 그립으로 잡고 팔꿈치를 짐 볼에 기대어 둔다.,Step:3 (중급자 변형) 상완을 고정한 채 내쉬며 덤벨을 어깨 쪽으로 말아 올린다.,Step:4 위에서 잠깐 멈춘 뒤 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('p5v6rdT', '아이언 크로스 스트레치 - 딥 베리에이션', 'https://static.exercisedb.dev/media/p5v6rdT.gif', '둔근', '허벅지', '맨몸', '햄스트링,대퇴사두근', 'Step:1 등을 대고 누워 팔을 양옆으로 펼친다.,Step:2 다리를 곧게 편 채 천장 방향으로 들어 올린다.,Step:3 다리를 한쪽으로 천천히 내려 발이 바닥에 닿도록 한다.,Step:4 스트레치를 몇 초간 유지한 뒤 다리를 시작 자세로 되돌린다.,Step:5 반대쪽도 같은 방식으로 스트레치를 반복한다. 전 과정에서 깊은 자세를 유지한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('cuC7529', '한쪽 다리 스쿼트 - 익스텐션 변형', 'https://static.exercisedb.dev/media/cuC7529.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 한쪽 다리를 앞으로 뻗어 바닥에서 띄운다.,Step:3 지지하는 다리 무릎을 굽히며 의자에 앉듯이 몸을 아래로 내린다.,Step:4 가슴을 들고 등은 곧게 유지한다.,Step:5 뒤꿈치로 바닥을 밀어 시작 자세로 돌아온다.,Step:6 반대쪽 다리로 반복한다. 전 과정에서 익스텐션된 자세를 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('C8Crfa4', '타겟 스타일 스미스 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/C8Crfa4.gif', '삼두근', '상완이두근', '스미스 머신', '가슴,어깨', 'Step:1 좌석 높이를 조절하고 벤치에 누워 발을 바닥에 고정한다.,Step:2 바벨을 어깨너비보다 약간 좁게 클로즈 그립으로 잡는다.,Step:3 팔꿈치를 몸에 붙인 채 바벨을 가슴 쪽으로 내린다. 타겟 동작에 집중한다.,Step:4 아래에서 잠깐 멈춘 뒤 바벨을 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('XqYQ9JA', '덤벨 원 암 엎드린 해머 컬 - 매크로 변형', 'https://static.exercisedb.dev/media/XqYQ9JA.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 평벤치에 엎드려 한 손에 덤벨을 들고 손바닥이 몸을 보게 한 채 팔을 완전히 편다.,Step:2 상완을 고정하고 덤벨을 어깨 쪽으로 말아 올리며 이두근을 수축한다.,Step:3 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다. 매크로 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qBl14UC', '정적을 이용한 푸시업(벽)', 'https://static.exercisedb.dev/media/qBl14UC.gif', '가슴근육', '가슴', '맨몸', '삼두근,삼각근', 'Step:1 벽을 마주 보고 서서 팔 길이 정도 거리를 둔다.,Step:2 손을 어깨 높이에 두고 어깨너비보다 약간 넓게 벌려 벽에 댄다.,Step:3 발을 조금 뒤로 빼 몸을 곧게 유지하고 발은 골반 너비로 둔다.,Step:4 (정적 변형) 팔꿈치를 굽혀 가슴을 벽 쪽으로 내리되 몸이 일직선이 되게 유지한다.,Step:5 팔을 펴며 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iqH55N8', '맹렬한 스타일의 포워드 런지(남성)', 'https://static.exercisedb.dev/media/iqH55N8.gif', '둔근', '허벅지', '맨몸', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 골반 너비로 벌리고 서서 손은 허리에 둔다.,Step:2 오른발을 크게 앞으로 내딛고 런지 자세로 몸을 내린다.,Step:3 오른쪽 무릎을 약 90도로 굽히되 무릎이 발목 위에 오도록 정렬한다.,Step:4 오른발로 밀어 시작 자세로 돌아온다.,Step:5 (맹렬한 변형) 왼발로 반복하며 좌우를 번갈아 원하는 반복 횟수만큼 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('IxsFgRT', '케이블 유도 플립(스태틱 포함)', 'https://static.exercisedb.dev/media/IxsFgRT.gif', '복근', '허리', '케이블', '복사근,어깨', 'Step:1 케이블 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:2 케이블 손잡이를 양손으로 가슴 높이에서 잡고 손바닥은 아래를 향하게 한다.,Step:3 코어에 힘을 주고 상체를 오른쪽으로 회전하며 케이블을 몸 앞쪽으로 가로질러 당긴다.,Step:4 회전하면서 뒷발을 피벗하고 엉덩이가 자연스럽게 회전하도록 둔다. 정적 컨트롤을 강조한다.,Step:5 팔을 완전히 뻗어 마무리하며 손잡이를 어깨 위로 넘기듯 플립한다.,Step:6 역순으로 움직이며 시작 자세로 돌아오되 상체를 중앙으로 되돌린다.,Step:7 반대쪽도 반복한다.,Step:8 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7AnZtSv', '벤치 위의 덤벨 원 암 손목 컬 - 근력 변화', 'https://static.exercisedb.dev/media/7AnZtSv.gif', '전완근', '팔 아래', '덤벨', '이두근,어깨', 'Step:1 벤치에 앉아 한 손에 덤벨을 들고 손바닥이 아래를 향하게 한다.,Step:2 전완을 벤치 위에 올리고 손목이 가장자리 밖으로 나오게 한다.,Step:3 손목을 천천히 위로 말아 덤벨을 전완 쪽으로 끌어올린다.,Step:4 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다. 전 과정에서 근력 자세를 유지한다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('mpYUPkA', '누워서 다리 엉덩이 올리기 - 수축 변형', 'https://static.exercisedb.dev/media/mpYUPkA.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 등을 대고 누워 다리를 곧게 펴고 팔은 몸 옆에 둔다.,Step:2 지지를 위해 손을 엉덩이 아래에 둔다.,Step:3 코어에 힘을 주고 다리를 바닥에서 들어 올려 천장 쪽으로 올린다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 시작 자세로 내린다. 수축된 컨트롤을 강조한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iFsqlCD', '엎드린 메디신 볼 클로즈 그립 푸쉬업', 'https://static.exercisedb.dev/media/iFsqlCD.gif', '삼두근', '상완이두근', '메디신볼', '가슴,어깨', 'Step:1 하이 플랭크 자세에서 손을 메디신볼 위에 올리고 어깨너비로 둔다.,Step:2 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 팔꿈치는 몸 옆을 따라가게 한다.,Step:3 팔을 완전히 펴며 시작 자세로 밀어 올린다.,Step:4 원하는 반복 횟수만큼 반복한다. 전 과정에서 엎드린 자세를 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9ZGnq1w', '삼두근 딥스(벤치 사이에서) - 극단적인 변형', 'https://static.exercisedb.dev/media/9ZGnq1w.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 벤치에 앉아 손으로 벤치 가장자리를 잡되 손가락은 앞으로 향하게 한다.,Step:2 (극단 변형) 엉덩이를 벤치 밖으로 빼 손으로 체중을 지탱한다.,Step:3 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 등은 벤치에 가깝게 유지한다.,Step:4 아래에서 잠깐 멈춘 뒤 팔을 펴며 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qFHvMnv', '마이크로 스타일 바벨 스피드 스쿼트', 'https://static.exercisedb.dev/media/qFHvMnv.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서되 발끝은 약간 바깥으로 돌린다.,Step:2 바벨을 상부 등(승모근 또는 후면 삼각근)에 얹는다.,Step:3 코어에 힘을 주고 가슴을 든 채 엉덩이를 뒤로 빼며 무릎을 굽혀 내려간다.,Step:4 (마이크로 변형) 허벅지가 바닥과 평행이 될 때까지, 또는 가능한 범위까지 내려간다.,Step:5 뒤꿈치로 바닥을 밀어 일어서며 위에서 둔근을 조인다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('jCBOdh0', '거친 케이블 디클라인 플라이', 'https://static.exercisedb.dev/media/jCBOdh0.gif', '가슴근육', '가슴', '케이블', '어깨,삼두근', 'Step:1 케이블 머신을 디클라인에 맞게 설정한다.,Step:2 머신을 등지고 서서 발을 어깨너비로 벌린다.,Step:3 손바닥이 정면을 보게 손잡이를 잡고 팔을 앞으로 곧게 뻗는다.,Step:4 팔꿈치를 약간 굽힌 채 팔을 좌우로 벌리며 컨트롤한다. 거친 강도로 수행한다.,Step:5 완전히 벌린 지점에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1u36hhy', '안정성 레버 좁은 그립 좌석 행', 'https://static.exercisedb.dev/media/1u36hhy.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 올바른 자세가 나오도록 좌석 높이와 발판을 조절한다.,Step:2 머신에 앉아 발을 발판에 두고 무릎은 살짝 굽힌다.,Step:3 손바닥이 서로 마주 보게 좁은 그립으로 손잡이를 잡는다.,Step:4 등을 곧게 펴고 약간 앞으로 기울인다.,Step:5 손잡이를 몸통 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 동작 최고점에서 잠깐 멈춘다.,Step:7 손잡이를 천천히 풀며 시작 자세로 돌아간다. 안정성 동작에 집중한다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ninBEOY', '좌우로 뒤틀린 턱', 'https://static.exercisedb.dev/media/ninBEOY.gif', '광배근', '등', '맨몸', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 살짝 굽힌다.,Step:2 오버핸드 그립으로 풀업 바를 잡되 손 간격은 어깨너비보다 약간 넓게 한다.,Step:3 팔을 완전히 편 채 바에 매달리고 몸의 힘을 뺀다.,Step:4 팔꿈치를 굽혀 턱을 바 쪽으로 끌어올리되 몸은 곧게 유지한다.,Step:5 턱이 바 위로 올라오면 몸을 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다. 뒤틀린 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('u1iHcoD', '엎드린 덤벨 직립 어깨 외회전', 'https://static.exercisedb.dev/media/u1iHcoD.gif', '삼각근', '어깨', '덤벨', '회전근개,승모근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 들고 손바닥이 몸을 보게 한다.,Step:2 팔을 옆으로 들어 바닥과 평행이 되게 하되 팔꿈치는 약간 굽힌다. 엎드린 컨트롤을 강조한다.,Step:3 팔을 외회전해 덤벨이 머리 쪽으로 올라오게 하되 팔꿈치 위치는 고정한다.,Step:4 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MqNdIbe', '제어식 손목 롤러', 'https://static.exercisedb.dev/media/MqNdIbe.gif', '전완근', '팔 아래', '가중', '이두근,삼두근', 'Step:1 로프나 바 한쪽 끝에 중량을 연결한다.,Step:2 로프나 바의 반대쪽을 양손으로 잡고 손바닥은 아래를 향하게 한다.,Step:3 발을 어깨너비로 벌리고 서서 팔을 앞으로 완전히 뻗는다.,Step:4 손목을 굽혀 무게가 손 쪽으로 감겨 올라오도록 천천히 말아 올린다.,Step:5 위에서 잠깐 멈춘 뒤 무게를 천천히 시작 위치로 풀어 내린다. 제어된 강도로 수행한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('9Z23cLE', '바벨 인클라인 벤치 프레스 앉은 자세', 'https://static.exercisedb.dev/media/9Z23cLE.gif', '가슴근육', '가슴', '바벨', '어깨,삼두근', 'Step:1 인클라인 벤치를 45도 각도로 세팅한다.,Step:2 (앉은 자세 변형) 벤치에 누워 발을 바닥에 고정한다.,Step:3 오버핸드 그립으로 바벨을 잡되 어깨너비보다 약간 넓게 잡는다.,Step:4 바벨을 랙에서 빼고 팔꿈치를 45도 정도로 유지하며 가슴 쪽으로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘 뒤 바벨을 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('ntjtCfu', '바벨 앉아서 교대로 다리 올리기(여성) 중급자 포함', 'https://static.exercisedb.dev/media/ntjtCfu.gif', '복근', '허리', '바벨', '고관절 굴근,대퇴사두근', 'Step:1 벤치에 앉아 등을 곧게 펴고 바벨을 허벅지 위에 올려 둔다.,Step:2 (중급자 변형) 지지를 위해 손을 벤치 옆면에 둔다.,Step:3 다리를 곧게 편 채 한쪽 다리를 가능한 높이까지 들어 올리되 바닥과 평행을 유지한다.,Step:4 다리를 내리고 반대쪽 다리로 반복한다.,Step:5 원하는 반복 횟수만큼 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kk39rUy', '사이드 플랭크로 푸시업 - 운동 변형', 'https://static.exercisedb.dev/media/kk39rUy.gif', '복근', '허리', '맨몸', '어깨,가슴,삼두근', 'Step:1 푸시업 자세에서 손을 어깨너비로 두고 몸을 일직선으로 만든다.,Step:2 팔꿈치를 굽혀 몸을 바닥 쪽으로 내리되 코어를 단단히 유지한다.,Step:3 팔을 펴며 시작 자세로 돌아간다. 운동선수처럼 컨트롤을 강조한다.,Step:4 체중을 왼손에 싣고 몸을 오른쪽으로 회전해 오른팔을 천장 쪽으로 들어 올린다.,Step:5 사이드 플랭크 자세를 몇 초간 유지한 뒤 시작 자세로 돌아간다.,Step:6 반대쪽도 푸시업과 사이드 플랭크를 반복한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('UoX77uR', '덤벨 시트 한쪽 다리 종아리 들어올리기 - 해머 그립 딥', 'https://static.exercisedb.dev/media/UoX77uR.gif', '종아리근', '종아리', '덤벨', '햄스트링,둔근', 'Step:1 벤치나 의자에 앉아 발을 바닥에 두고 덤벨을 허벅지 위에 올린다.,Step:2 한쪽 발을 스텝이나 블록 같은 높은 곳에 올려 뒤꿈치가 가장자리 밖으로 나오게 한다.,Step:3 덤벨을 해머 그립으로 잡는다(손바닥이 서로 마주 보게).,Step:4 코어에 힘을 주고 등을 곧게 유지한 채 발 앞쪽으로 밀어 뒤꿈치를 가능한 높이 들어 올린다.,Step:5 위에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 시작 자세로 내린다.,Step:6 (딥 변형) 원하는 반복 횟수만큼 반복한 뒤 반대쪽 다리로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('0MlxeMn', '케이블 풀다운(Pro Lat Bar)', 'https://static.exercisedb.dev/media/0MlxeMn.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 허벅지가 바닥과 평행이 되도록 좌석 높이를 조절하고 발을 바닥에 고정한다.,Step:2 랫 바를 오버핸드 그립으로 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 앉아서 상체를 살짝 뒤로 기울이고 가슴을 들며 등을 곧게 편다.,Step:4 바를 가슴 쪽으로 당기며 견갑골을 모아 조인다. 전 과정에서 부드러운 자세를 유지한다.,Step:5 아래에서 잠깐 멈춘 뒤 바를 천천히 위로 보내 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('fjjY3N4', '인버티드 스타일 인버스 레그 컬(풀업 케이블 머신에서)', 'https://static.exercisedb.dev/media/fjjY3N4.gif', '햄스트링', '허벅지', '맨몸', '둔근,종아리근', 'Step:1 케이블 머신에서 발목 스트랩이 가장 낮은 위치가 되도록 조절한다.,Step:2 벤치에 엎드려 다리를 곧게 펴고 발에 발목 스트랩을 착용한다.,Step:3 안정성을 위해 벤치 손잡이를 잡는다.,Step:4 무릎을 굽혀 발을 둔근 쪽으로 끌어당기며 햄스트링을 조인다.,Step:5 위에서 잠깐 멈춘 뒤 다리를 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한다. 전 과정에서 인버티드 자세를 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KenZJQV', '바벨 하이바 스쿼트 코어', 'https://static.exercisedb.dev/media/KenZJQV.gif', '둔근', '허벅지', '바벨', '대퇴사두근,햄스트링,종아리근,코어', 'Step:1 발을 어깨너비로 벌리고 서되 발끝은 약간 바깥으로 돌린다.,Step:2 바벨을 상부 등(승모근)에 올려 둔다.,Step:3 코어에 힘을 주고 가슴을 든 채 엉덩이를 뒤로 빼며 무릎을 굽혀 스쿼트한다. 코어 강도로 수행한다.,Step:4 허벅지가 바닥과 평행이 될 때까지, 또는 가능한 범위까지 내려간다.,Step:5 뒤꿈치로 바닥을 밀어 올라오며 엉덩이와 무릎을 편다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LFIOery', '날카로운 스타일의 덤벨 스모 풀스루', 'https://static.exercisedb.dev/media/LFIOery.gif', '둔근', '허벅지', '덤벨', '햄스트링,대퇴사두근,코어', 'Step:1 발을 어깨너비보다 넓게 벌리고 서서 발끝을 바깥으로 향하게 한다.,Step:2 양손으로 덤벨을 몸 앞에서 잡고 팔을 뻗는다.,Step:3 무릎을 굽혀 엉덩이를 낮추며 스쿼트 자세로 내려가되 등은 곧게 유지한다. 날카로운 동작을 강조한다.,Step:4 팔은 곧게 유지한 채 덤벨을 다리 사이로 내린다.,Step:5 뒤꿈치로 바닥을 밀며 엉덩이를 앞으로 펴 덤벨을 위로 끌어올려 몸 앞에 둔다.,Step:6 위에서 둔근을 강하게 조인 뒤 덤벨을 다시 다리 사이로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qU8bYp7', '러프 케이블 스탠딩 원 암 삼두근 익스텐션', 'https://static.exercisedb.dev/media/qU8bYp7.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 케이블 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:2 오른손으로 케이블 손잡이를 잡고 손바닥은 아래를 향하게 하며, 팔이 완전히 펴져 바닥과 평행이 되게 위치시킨다.,Step:3 팔꿈치를 고정하고 몸에 가깝게 유지한다.,Step:4 팔꿈치를 천천히 굽혀 손잡이가 머리 뒤쪽으로 가도록 내린다.,Step:5 아래에서 잠깐 멈춘 뒤 팔을 펴 시작 자세로 되돌린다. 거친 동작에 집중한다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽으로 바꿔 왼팔로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('LlSe9IK', '집중된 자세로 보조 턱걸이', 'https://static.exercisedb.dev/media/LlSe9IK.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 머신의 보조(어시스트) 강도를 원하는 수준으로 설정한다.,Step:2 (집중 변형) 발판 위에 서서 오버핸드 그립으로 손잡이를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 가슴을 들고 어깨를 뒤로 두며 코어에 힘을 주고 무릎을 약간 굽힌다.,Step:4 팔꿈치를 굽히고 팔꿈치를 옆구리 쪽으로 내리며 몸을 끌어올린다.,Step:5 턱이 바 위로 올라올 때까지 계속 당긴다.,Step:6 위에서 잠깐 멈춘 뒤 몸을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VRBGPHB', '싱글 스미스 숄더 프레스', 'https://static.exercisedb.dev/media/VRBGPHB.gif', '삼각근', '어깨', '스미스 머신', '삼두근,등 위쪽', 'Step:1 좌석 높이를 조절하고 스미스 머신에 앉거나 선 상태에서 발을 어깨너비로 둔다.,Step:2 (싱글 변형) 오버핸드 그립으로 바를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 바를 랙에서 빼 어깨 높이에 두고 팔꿈치를 굽혀 손바닥이 정면을 향하게 한다.,Step:4 팔을 완전히 펴며 바를 머리 위로 밀어 올린다.,Step:5 위에서 잠깐 멈춘 뒤 바를 어깨 높이로 천천히 내린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('I6Ca0a7', '컴플리트 스타일 ez 바 라이딩 클로즈 그립 머리 뒤 삼두근 익스텐션', 'https://static.exercisedb.dev/media/I6Ca0a7.gif', '삼두근', '상완이두근', 'EZ 바벨', '어깨', 'Step:1 벤치에 누워 발을 바닥에 고정하고 머리는 벤치 끝쪽에 둔다.,Step:2 EZ 바벨을 클로즈 그립으로 잡되 손바닥이 위를 향하게 하고 팔을 가슴 위로 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바벨을 머리 뒤로 천천히 내린다.,Step:4 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아간다. 전 과정에서 완전한 자세를 유지한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('w44vFvP', '스미스 원 암 로우 리니어', 'https://static.exercisedb.dev/media/w44vFvP.gif', '등 위쪽', '등', '스미스 머신', '이두근,전완근', 'Step:1 스미스 머신 바 높이를 허리 높이로 조절한다.,Step:2 스미스 머신을 마주 보고 서서 발을 어깨너비로 둔다. 선형 컨트롤을 강조한다.,Step:3 무릎을 살짝 굽히고 엉덩이를 접어 상체를 앞으로 기울이되 등은 곧게 편다.,Step:4 한 손으로 바를 오버핸드 그립으로 잡고 손바닥은 아래를 향하게 한다.,Step:5 팔꿈치를 몸에 가깝게 유지하며 바를 허리 쪽으로 당겨 견갑골을 모아 조인다.,Step:6 위에서 잠깐 멈춘 뒤 바를 천천히 시작 위치로 내린다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽 팔로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('5ipN0iE', '보조 풀업 경사', 'https://static.exercisedb.dev/media/5ipN0iE.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 머신의 무게와 높이 설정을 원하는 수준으로 조절한다.,Step:2 오버핸드 그립으로 손잡이를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 편 채 매달리고 발은 바닥에서 띄운다.,Step:4 등 근육에 힘을 주고 팔꿈치를 몸에 붙인 채 손잡이 쪽으로 몸을 끌어올린다.,Step:5 턱이 손잡이 위로 올라올 때까지 계속 당긴다.,Step:6 위에서 잠깐 멈춘 뒤 몸을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다. 전 과정에서 경사 자세를 유지한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('A3P4O0R', '역방향 케이블 장착 행', 'https://static.exercisedb.dev/media/A3P4O0R.gif', '등 위쪽', '등', '케이블', '이두근,전완근', 'Step:1 케이블 로우 머신에 앉아 발을 발판에 두고 무릎을 살짝 굽힌다.,Step:2 오버핸드 그립으로 손잡이를 잡고 등을 곧게 펴며 어깨 힘을 뺀다.,Step:3 손잡이를 몸 쪽으로 당기며 견갑골을 모아 조인다. 역방향 동작에 집중한다.,Step:4 최고점에서 잠깐 멈춘 뒤 손잡이를 천천히 풀어 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('79AmJsI', '전통적인 덤벨 해머 컬', 'https://static.exercisedb.dev/media/79AmJsI.gif', '이두근', '상완이두근', '덤벨', '전완근', 'Step:1 양손에 덤벨을 들고 똑바로 선다. 손바닥은 몸통을 향하게 한다.,Step:2 팔꿈치를 몸통 가까이에 두고 손바닥이 정면을 향하도록 회전한다.,Step:3 이것이 시작 자세다.,Step:4 상완을 고정한 채 내쉬며 덤벨을 말아 올려 이두근을 수축한다.,Step:5 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다.,Step:6 이두근을 조이며 잠깐 멈춘다.,Step:7 들이마시며 덤벨을 천천히 시작 자세로 내린다.,Step:8 권장 반복 횟수만큼 반복한다. 전통 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7WcQgkm', '스미스 머신 인클라인 트라이셉스 익스텐션 - 스트레이트 변형', 'https://static.exercisedb.dev/media/7WcQgkm.gif', '삼두근', '상완이두근', '스미스 머신', '어깨', 'Step:1 스미스 머신 좌석을 조절해 바가 어깨 높이에 오게 한다.,Step:2 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 고정한다.,Step:3 오버핸드 그립으로 바를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:4 팔을 완전히 펴 바를 랙에서 빼고 가슴 위에 위치시킨다. 직선 동작에 집중한다.,Step:5 팔꿈치를 머리 가까이에 두고 바를 이마 쪽으로 천천히 내린다.,Step:6 아래에서 잠깐 멈춘 뒤 바를 시작 자세로 다시 밀어 올린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1IFV9h3', '팔 아래 푸시업 - 저항 변형', 'https://static.exercisedb.dev/media/1IFV9h3.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 플랭크 자세에서 전완을 바닥에 두고 팔꿈치는 어깨 바로 아래에 둔다.,Step:2 코어에 힘을 주고 머리부터 발끝까지 일직선을 유지한다.,Step:3 팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리되 팔꿈치는 몸 옆을 따라가게 한다. 저항 컨트롤을 강조한다.,Step:4 아래에서 잠깐 멈춘 뒤 시작 자세로 밀어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('p0OCXGb', '45в° 레그 와이드 프레스 - 변형', 'https://static.exercisedb.dev/media/p0OCXGb.gif', '둔근', '허벅지', '슬레이 기계', '대퇴사두근,햄스트링,종아리근', 'Step:1 슬레이 머신을 45도 각도로 조절한다.,Step:2 머신에 앉아 등을 패드에 붙이고 발을 발판에 둔다.,Step:3 발을 어깨너비보다 넓게 벌려 둔다.,Step:4 발판을 밀어 다리를 펴고 무릎을 곧게 만든다.,Step:5 동작 끝에서 잠깐 멈춘 뒤 무릎을 천천히 굽혀 시작 자세로 돌아간다. 전 과정에서 무딘 자세를 유지한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Uywa4S5', '단단한 덤벨 런지', 'https://static.exercisedb.dev/media/Uywa4S5.gif', '둔근', '허벅지', '덤벨', '대퇴사두근,햄스트링,종아리근', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 든다.,Step:2 오른발을 앞으로 내딛고 런지 자세로 몸을 내린다.,Step:3 등을 곧게, 가슴을 든 상태로 내려간다. 전 과정에서 단단한 자세를 유지한다.,Step:4 오른발 뒤꿈치로 밀어 시작 자세로 돌아간다.,Step:5 왼발로 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('O3INw8V', '개량된 스핑크스', 'https://static.exercisedb.dev/media/O3INw8V.gif', '척추', '등', '맨몸', '둔근,햄스트링', 'Step:1 엎드려 누워 전완을 바닥에 두고 팔꿈치는 어깨 아래에 둔다.,Step:2 코어에 힘을 주고 가슴을 들어 올리되 전완과 발끝은 바닥에 둔다.,Step:3 목을 중립으로 유지하며 몇 초간 자세를 유지한다.,Step:4 가슴을 천천히 내려 시작 자세로 돌아간다. 개선된 컨트롤을 강조한다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('L68dTQj', '밴드 시트 트위스트 퓨어', 'https://static.exercisedb.dev/media/L68dTQj.gif', '복근', '허리', '밴드', '복사근', 'Step:1 바닥에 앉아 다리를 앞으로 뻗고 등을 곧게 편다.,Step:2 밴드를 허리에 감고 양손으로 끝을 잡는다.,Step:3 복근에 힘을 주고 상체를 한쪽으로 천천히 비틀되 등을 곧게 유지하고 발은 바닥에 둔다.,Step:4 비틀림 끝에서 잠깐 멈춘 뒤 천천히 시작 자세로 돌아간다.,Step:5 (퓨어 변형) 반대쪽으로도 비틀기를 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('pFuK3by', '워크 일립티컬 크로스 트레이너 - 익스텐션된 변형', 'https://static.exercisedb.dev/media/pFuK3by.gif', '심혈관계', '유산소', '타원형 기계', '대퇴사두근,햄스트링,둔근,종아리근', 'Step:1 일립티컬 머신의 저항과 경사도를 원하는 수준으로 조절한다.,Step:2 페달에 올라가 손잡이를 가볍게 잡는다.,Step:3 발로 페달을 누르면서 손잡이를 몸 쪽으로 당기는 동작을 시작한다.,Step:4 걷거나 뛰는 듯한 느낌이 나도록 밀기와 당기기를 번갈아 이어간다. 익스텐션된 컨트롤을 강조한다.,Step:5 운동 내내 코어를 활성화하고 일정한 페이스를 유지한다.,Step:6 원하는 시간 동안 유산소 운동을 지속한다.,Step:7 내리기 전 강도와 속도를 점진적으로 낮춘다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('qlZUaZ8', '덤벨 인클라인 한쪽 팔 프레스 짐 볼 익스텐션', 'https://static.exercisedb.dev/media/qlZUaZ8.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐 볼 위에 앉아 한 손에 덤벨을 들고 발은 바닥에 고정한다.,Step:2 발을 앞으로 천천히 걸어 공을 굴려 머리, 목, 상부 등이 공 위에 지지되게 한다. 익스텐션된 강도로 수행한다.,Step:3 손바닥이 정면을 보게 덤벨을 어깨 높이에 둔다.,Step:4 덤벨을 위로 밀어 팔을 완전히 편다.,Step:5 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 반대쪽으로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('hVzPY5j', '운동 스타일의 배틀 로프', 'https://static.exercisedb.dev/media/hVzPY5j.gif', '삼각근', '어깨', '로프', '전완근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 살짝 굽힌다.,Step:2 양손으로 로프 끝을 잡되 손바닥이 서로 마주 보게 한다.,Step:3 팔을 어깨 높이까지 들어 올리되 팔꿈치는 약간 굽힌다.,Step:4 (운동 변형) 양팔을 번갈아 빠르게 들어 올리고 내리며 로프에 교대 파동을 만든다.,Step:5 원하는 시간 또는 반복 횟수만큼 지속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('KQfySvS', '덤벨 리버스 그립 로우(여성) 홀드', 'https://static.exercisedb.dev/media/KQfySvS.gif', '등 위쪽', '등', '덤벨', '이두근,전완근', 'Step:1 발을 어깨너비로 벌리고 서서 무릎을 살짝 굽힌다.,Step:2 양손에 덤벨을 잡되 오버핸드 그립으로 손바닥이 몸을 향하게 한다. 홀드 강도로 수행한다.,Step:3 허리에서 상체를 숙이되 등은 곧게 펴고 코어를 단단히 유지한다.,Step:4 팔을 아래로 늘어뜨려 완전히 펴고 팔꿈치는 약간 굽힌다.,Step:5 덤벨을 가슴 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 위에서 잠깐 멈춘 뒤 덤벨을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iCPqbki', '레버 내로우 그립 시티드 로우 - 강도 변화', 'https://static.exercisedb.dev/media/iCPqbki.gif', '등 위쪽', '등', '레버리지 머신', '이두근,전완근', 'Step:1 올바른 자세가 나오도록 좌석 높이와 발판을 조절한다.,Step:2 머신에 앉아 발을 발판에 두고 무릎은 살짝 굽힌다.,Step:3 손바닥이 서로 마주 보게 내로우 그립으로 손잡이를 잡는다.,Step:4 등을 곧게 펴고 약간 앞으로 기울인다.,Step:5 손잡이를 몸통 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 최고점에서 잠깐 멈춘다. 전 과정에서 강한 자세를 유지한다.,Step:7 손잡이를 천천히 풀며 시작 자세로 돌아간다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o6LqKKP', '바벨 루마니안 데드리프트', 'https://static.exercisedb.dev/media/o6LqKKP.gif', '둔근', '허벅지', '바벨', '햄스트링,허리', 'Step:1 발을 어깨너비로 벌리고 서서 발끝은 정면을 향하게 한다.,Step:2 오버핸드 그립으로 바벨을 잡되 손 간격은 어깨너비보다 약간 넓게 한다.,Step:3 엉덩이를 접어 상체를 숙이되 등은 곧게, 무릎은 살짝 굽힌다.,Step:4 바벨을 몸 가까이에 두고 바닥 쪽으로 내린다.,Step:5 바벨을 내리며 햄스트링이 늘어나는 느낌을 느낀다.,Step:6 햄스트링에 충분한 스트레치가 느껴지면 엉덩이를 앞으로 밀어 상체를 곧게 세운다.,Step:7 동작 상단에서 둔근을 조인다.,Step:8 바벨을 다시 시작 자세로 내리고 원하는 반복 횟수만큼 반복한다. 전통 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kKYTkjJ', '엑서사이즈볼 한쪽 다리가 엎드려 있는 하체 회전이 치열하다', 'https://static.exercisedb.dev/media/kKYTkjJ.gif', '둔근', '허벅지', '스태빌리티 볼', '햄스트링,대퇴사두근,코어', 'Step:1 스태빌리티 볼 위에 엎드려 엉덩이가 공 위에 오게 하고 다리는 뒤로 곧게 뻗는다.,Step:2 지지를 위해 손을 앞쪽 바닥에 둔다.,Step:3 둔근과 코어에 힘을 주어 몸을 안정화한다.,Step:4 한쪽 다리를 바닥에서 들어 올려 곧게 유지하고 바닥과 평행이 되게 한다.,Step:5 엉덩이와 상체가 흔들리지 않게 유지한 채 다리를 몸 바깥쪽으로 외회전한다.,Step:6 회전 끝에서 잠깐 멈춘 뒤 다리를 천천히 시작 자세로 되돌린다.,Step:7 반대쪽 다리도 반복한다. 치열한 동작에 집중한다.,Step:8 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Mr8d4KA', '케틀벨 아놀드 프레스 - 초급 변형', 'https://static.exercisedb.dev/media/Mr8d4KA.gif', '삼각근', '어깨', '케틀벨', '삼두근,등 위쪽', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 케틀벨을 어깨 높이로 들고 손바닥이 몸 쪽을 보게 한다.,Step:2 코어에 힘을 주고 팔을 펴며 케틀벨을 머리 위로 밀어 올리면서 손바닥이 정면을 보게 회전한다. 초급자 컨트롤을 강조한다.,Step:3 위에서 잠깐 멈춘 뒤 케틀벨을 천천히 시작 자세로 내린다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7858za8', '플루이드 덤벨 스텝업 런지', 'https://static.exercisedb.dev/media/7858za8.gif', '대퇴사두근', '허벅지', '덤벨', '둔근,햄스트링,종아리근', 'Step:1 양손에 덤벨을 들고 스텝 또는 플랫폼 앞에 선다. 손바닥은 몸 옆을 향하게 한다.,Step:2 오른발을 스텝 위에 올려 발 전체가 지지면에 닿게 한다.,Step:3 오른발 뒤꿈치로 밀어 몸을 스텝 위로 올리며 왼발도 함께 올린다.,Step:4 (플루이드 변형) 두 발이 스텝 위에 올라오면 왼발을 다시 내려 시작 자세로 돌아가되 오른발은 스텝 위에 둔다.,Step:5 반복하면서 어떤 발로 올라갈지 번갈아 수행한다.,Step:6 원하는 반복 횟수만큼 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('MDFxU4b', '쿼드 콤플렉스', 'https://static.exercisedb.dev/media/MDFxU4b.gif', '대퇴사두근', '허벅지', '맨몸', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 선다.,Step:2 의자에 앉듯이 무릎을 굽히고 엉덩이를 뒤로 빼며 내려간다.,Step:3 가슴을 들고 등을 곧게 유지한다.,Step:4 허벅지가 바닥과 평행이 될 때까지 내려간다.,Step:5 뒤꿈치로 바닥을 밀어 시작 자세로 돌아간다. 콤플렉스 컨트롤을 강조한다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('N3EirIW', '트위스트를 이용한 레버 보조 턱업', 'https://static.exercisedb.dev/media/N3EirIW.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 레버리지 머신 저항을 원하는 수준으로 조절한다.,Step:2 발판 위에 서서 오버핸드 그립으로 손잡이를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 팔을 완전히 편 채 매달리며 몸을 곧게 유지한다.,Step:4 (트위스트 변형) 등 근육에 힘을 주고 가슴을 앞으로 내세우며 손잡이 쪽으로 몸을 끌어올린다.,Step:5 턱이 손잡이 위로 올라올 때까지 계속 당긴다.,Step:6 위에서 잠깐 멈춘 뒤 몸을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('OJFgZJ0', '다이나믹 스타일 바벨 눕기 삼두근 익스텐션', 'https://static.exercisedb.dev/media/OJFgZJ0.gif', '삼두근', '상완이두근', '바벨', '어깨', 'Step:1 벤치에 누워 발을 바닥에 고정하고 머리는 벤치 끝쪽에 둔다.,Step:2 오버핸드 그립으로 바벨을 어깨너비로 잡고 팔을 가슴 위로 곧게 편다.,Step:3 상완을 고정한 채 팔꿈치를 굽혀 바벨을 머리 뒤로 천천히 내린다. 전 과정에서 다이나믹한 자세를 유지한다.,Step:4 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아간다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Gu2ENkm', '딥 스미스 머신 리버스 디클라인 클로즈 그립 벤치 프레스', 'https://static.exercisedb.dev/media/Gu2ENkm.gif', '가슴근육', '가슴', '스미스 머신', '삼두근,어깨', 'Step:1 스미스 머신을 디클라인에 맞게 설정한다.,Step:2 벤치에 눕고 발을 고정 패드 아래에 끼운다.,Step:3 바를 클로즈 그립으로 잡되 어깨너비보다 약간 좁게 잡는다.,Step:4 바를 랙에서 빼고 팔꿈치를 몸에 붙인 채 가슴 쪽으로 천천히 내린다. 깊은 동작에 집중한다.,Step:5 아래에서 잠깐 멈춘 뒤 바를 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('6vcvsLS', '높이 들어 올려 똑바로 다리 올리기', 'https://static.exercisedb.dev/media/6vcvsLS.gif', '복근', '허리', '맨몸', '고관절 굴근', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥은 바깥쪽을 향하게 한다.,Step:2 코어에 힘을 주고 다리를 앞으로 곧게 들어 올린다.,Step:3 다리가 바닥과 평행이 되거나 가능한 높이까지 계속 올린다. 전 과정에서 높이 든 자세를 유지한다.,Step:4 위에서 잠깐 멈춘 뒤 다리를 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('afv0ZAS', '업라이트 스미스 인클라인 벤치 프레스', 'https://static.exercisedb.dev/media/afv0ZAS.gif', '가슴근육', '가슴', '스미스 머신', '어깨,삼두근', 'Step:1 벤치를 30-45도 인클라인으로 조절한다.,Step:2 벤치에 앉아 등을 패드에 붙이고 발을 바닥에 단단히 둔다.,Step:3 오버핸드 그립으로 바를 어깨너비보다 약간 넓게 잡는다. 업라이트 강도로 수행한다.,Step:4 바를 랙에서 빼고 팔꿈치를 살짝 안쪽으로 두며 상부 가슴 쪽으로 천천히 내린다.,Step:5 아래에서 잠깐 멈춘 뒤 팔을 완전히 펴 바를 시작 자세로 밀어 올린다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('1YUWDNZ', '익스텐션 스타일 반전 행', 'https://static.exercisedb.dev/media/1YUWDNZ.gif', '등 위쪽', '등', '맨몸', '이두근,전완근', 'Step:1 허리 높이에 바를 설치하거나 서스펜션 트레이너를 사용한다.,Step:2 바 또는 트레이너를 마주 보고 서서 발을 어깨너비로 둔다.,Step:3 오버핸드 그립으로 바/손잡이를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:4 몸을 뒤로 기울여 몸통을 곧게 유지하고 뒤꿈치는 바닥에 둔다.,Step:5 가슴을 바/손잡이 쪽으로 당기며 견갑골을 모아 조인다.,Step:6 위에서 잠깐 멈춘 뒤 몸을 천천히 시작 자세로 내린다.,Step:7 원하는 반복 횟수만큼 반복한다. 익스텐션된 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('r4RZKpF', '덤벨 원암 플라이 온 엑서사이즈 볼 개선', 'https://static.exercisedb.dev/media/r4RZKpF.gif', '가슴근육', '가슴', '덤벨', '어깨,삼두근', 'Step:1 짐 볼 위에 앉아 한 손에 덤벨을 들고 발을 바닥에 둔다.,Step:2 발을 앞으로 걸어 공을 굴리며 상부 등이 짐 볼 위에 오게 눕는다.,Step:3 덤벨을 든 팔을 가슴 위로 곧게 뻗어 손바닥이 안쪽을 보게 한다.,Step:4 팔꿈치를 약간 굽힌 채 덤벨을 옆으로 천천히 내린다.,Step:5 잠깐 멈춘 뒤 가슴 근육을 조여 덤벨을 시작 자세로 모은다.,Step:6 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다. 개선된 동작에 집중한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('WFucoe6', '똑바로 매달린 뒤틀린 다리 컴파운드를 이용한 힙 레이즈', 'https://static.exercisedb.dev/media/WFucoe6.gif', '복근', '허리', '맨몸', '복사근,고관절 굴근', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 다리를 곧게 유지한다.,Step:2 코어에 힘을 주고 다리를 곧게 편 채 가슴 쪽으로 들어 올린다. 컴파운드 강도로 수행한다.,Step:3 다리가 바닥과 평행이 되면 엉덩이를 한쪽으로 비틀어 다리가 그 방향으로 가게 한다.,Step:4 잠깐 멈춘 뒤 시작 자세로 돌아간다.,Step:5 이번에는 반대쪽으로 엉덩이를 비틀며 반복한다.,Step:6 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lRcrlH8', '패스트 밴드 스트레이트 레그 데드리프트', 'https://static.exercisedb.dev/media/lRcrlH8.gif', '척추', '등', '밴드', '햄스트링,둔근', 'Step:1 발을 어깨너비로 벌리고 서서 밴드를 발 아래에 걸어 둔다.,Step:2 밴드를 양손으로 잡고 손바닥이 몸을 향하게 하며 팔을 곧게 편다.,Step:3 코어에 힘을 주고 무릎은 살짝 굽힌다.,Step:4 엉덩이를 접어 상체를 앞으로 기울이되 등은 곧게, 가슴은 들어 올린다.,Step:5 다리를 곧게 유지하며 밴드를 바닥 쪽으로 내린다.,Step:6 아래에서 잠깐 멈춘 뒤 둔근과 햄스트링을 조여 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다. 빠른 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('nFHk9fU', '케이블 사이드 풀다운(로프 부착 포함) 코어', 'https://static.exercisedb.dev/media/nFHk9fU.gif', '광배근', '등', '케이블', '이두근,전완근', 'Step:1 케이블 머신 상단에 로프 손잡이를 연결한다.,Step:2 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 로프를 잡되 손바닥이 서로 마주 보게 한다.,Step:4 등을 곧게 펴고 상체를 약간 뒤로 기울인다.,Step:5 로프를 옆구리 쪽으로 당기며 견갑골을 모아 조인다. 코어 컨트롤을 강조한다.,Step:6 아래에서 잠깐 멈춘다.,Step:7 장력을 천천히 풀며 로프를 시작 위치로 되돌린다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Xd65M9w', '풀오버 주변의 덤벨 - 집중 변형', 'https://static.exercisedb.dev/media/Xd65M9w.gif', '가슴근육', '가슴', '덤벨', '삼두근,광배근', 'Step:1 벤치에 누워 머리는 한쪽 끝에 두고 발은 바닥에 단단히 둔다.,Step:2 양손으로 덤벨을 잡고 가슴 위로 팔을 곧게 뻗는다. 강한 집중 강도로 수행한다.,Step:3 팔을 곧게 유지한 채 아치 형태로 덤벨을 머리 뒤쪽으로 천천히 내린다.,Step:4 아래에서 잠깐 멈춘 뒤 덤벨을 시작 자세로 들어 올린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('AwAIlSo', '스퀘어 리버스 그립 머신 랫 풀다운', 'https://static.exercisedb.dev/media/AwAIlSo.gif', '광배근', '등', '레버리지 머신', '이두근,전완근', 'Step:1 좌석 높이와 자세를 조절하고 무릎을 패드 아래에 넣은 채 발을 바닥에 둔다.,Step:2 언더핸드 그립으로 손잡이를 잡되 어깨너비보다 약간 넓게 잡는다.,Step:3 가슴을 내밀고 어깨를 뒤로 두며, 허리는 약간 아치를 만들고 상체를 세운다.,Step:4 손잡이를 가슴 쪽으로 당기며 견갑골을 모아 조인다. 전 과정에서 스퀘어 자세를 유지한다.,Step:5 아래에서 잠깐 멈춘 뒤 손잡이를 천천히 풀어 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('DICPHtq', '타겟 스타일 싱글 레그 종아리 들어올리기(덤벨 위에서)', 'https://static.exercisedb.dev/media/DICPHtq.gif', '종아리근', '종아리', '덤벨', '발목,피트', 'Step:1 발을 골반 너비로 벌리고 서서 한 손에 덤벨을 든다.,Step:2 한쪽 발을 들어 올리고 다른 쪽 발로 균형을 잡는다.,Step:3 종아리 근육을 사용해 뒤꿈치를 가능한 높이 들어 올린다. 타겟 컨트롤을 강조한다.,Step:4 위에서 잠깐 멈춘 뒤 뒤꿈치를 천천히 내린다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 다리를 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('iDGtjyi', '가슴과 어깨 앞쪽의 마이크로 스트레치', 'https://static.exercisedb.dev/media/iDGtjyi.gif', '가슴근육', '가슴', '맨몸', '삼각근', 'Step:1 발을 어깨너비로 벌리고 바르게 선다.,Step:2 팔을 어깨 높이로 앞으로 곧게 뻗는다.,Step:3 팔을 몸 앞에서 교차하되 오른팔이 왼팔 위로 오게 한다.,Step:4 손가락을 깍지 끼고 손바닥을 맞댄다.,Step:5 견갑골을 부드럽게 모으고 손을 앞으로 밀어 가슴과 어깨 앞쪽이 늘어나는 느낌을 만든다.,Step:6 (마이크로 변형) 20-30초간 유지한 뒤 풀어 준다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('89HVjEp', '케틀벨 시티드 프레스 위드 하이', 'https://static.exercisedb.dev/media/89HVjEp.gif', '삼각근', '어깨', '케틀벨', '삼두근,코어', 'Step:1 벤치에 앉아 등을 곧게 펴고 발을 바닥에 고정한다.,Step:2 양손에 케틀벨을 어깨 높이로 들고 손바닥이 정면을 보게 한다.,Step:3 케틀벨을 머리 위로 밀어 올려 팔을 완전히 편다. 높은 동작에 집중한다.,Step:4 케틀벨을 어깨 높이로 다시 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('echClj7', '바벨 스쿼트(무릎 위) - 순수', 'https://static.exercisedb.dev/media/echClj7.gif', '대퇴사두근', '허벅지', '바벨', '둔근,햄스트링,종아리근', 'Step:1 바닥에 무릎을 꿇고 시작하되 무릎 간격은 골반 너비로 하고 발끝은 정면을 향하게 한다.,Step:2 바벨을 어깨 위에 올리고 오버핸드 그립으로 잡되 손 간격은 어깨너비보다 약간 넓게 한다.,Step:3 코어에 힘을 주고 가슴을 든 채 무릎을 굽혀 몸을 천천히 내리되 등은 곧게 유지한다. 순수 강도로 수행한다.,Step:4 허벅지가 바닥과 평행이 될 때까지, 또는 가능한 범위까지 내려간다.,Step:5 아래에서 잠깐 멈춘 뒤 뒤꿈치 방향으로 힘을 써 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('myJeTAe', '터프 케이블 원 암 레터럴 레이즈', 'https://static.exercisedb.dev/media/myJeTAe.gif', '삼각근', '어깨', '케이블', '승모근,삼두근', 'Step:1 케이블 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:2 한 손으로 케이블 손잡이를 잡고 손바닥은 아래를 향하게 한 뒤, 케이블에 장력이 생기도록 적당히 떨어져 선다.,Step:3 팔을 곧게 유지한 채 옆으로 들어 올려 바닥과 평행이 될 때까지 올린다.,Step:4 위에서 잠깐 멈춘 뒤 팔을 천천히 시작 자세로 내린다. 터프한 동작에 집중한다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 반대쪽으로 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('znf7t8E', '트리플로 근육 키우기', 'https://static.exercisedb.dev/media/znf7t8E.gif', '광배근', '등', '맨몸', '이두근,삼두근,어깨,코어', 'Step:1 오버핸드 그립으로 풀업 바에 매달리되 손은 어깨너비보다 약간 넓게 잡는다.,Step:2 코어에 힘을 주고 스윙 동작으로 탄성을 만들어 모멘텀을 만든다.,Step:3 앞으로 스윙할 때 가슴을 바 쪽으로 끌어올리며 광배근과 이두근으로 동작을 시작한다. 트리플 컨트롤을 강조한다.,Step:4 가슴이 바에 닿을 때까지 올라간 뒤, 바를 아래로 눌러 팔을 펴 딥 자세로 전환한다.,Step:5 팔을 굽히며 하강을 컨트롤해 시작 자세로 돌아간다.,Step:6 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('tuIZFDt', '중급형 무릎 플랭크 탭 숄더(남성)', 'https://static.exercisedb.dev/media/tuIZFDt.gif', '복근', '허리', '맨몸', '어깨,삼두근', 'Step:1 무릎을 대고 손을 어깨너비로 바닥에 둔 자세에서 시작한다.,Step:2 다리를 뒤로 뻗어 발끝으로 지지하고 플랭크 자세를 만든다.,Step:3 (중급자 변형) 코어에 힘을 주고 골반이 흔들리지 않게 유지한 채 한 손을 들어 반대쪽 어깨를 톡 친다.,Step:4 손을 다시 바닥에 두고 반대쪽도 반복한다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('o80Xu9C', '강화 스타일 케틀벨 익스텐션 범위 원암 바닥 프레스', 'https://static.exercisedb.dev/media/o80Xu9C.gif', '가슴근육', '가슴', '케틀벨', '삼두근,어깨', 'Step:1 등을 대고 바닥에 누워 무릎을 굽히고 발을 바닥에 둔다.,Step:2 한 손에 케틀벨을 들고 손바닥이 발 쪽을 향하게 한다.,Step:3 팔을 천장 쪽으로 곧게 펴되 팔꿈치를 잠그고 손목은 곧게 유지한다.,Step:4 케틀벨을 천천히 내려 시작 자세로 돌아간다. 전 과정에서 동작을 컨트롤한다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다. 강화된 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('7R4NIjL', '수평 보조 스탠딩 삼두근 익스텐션(수건 포함)', 'https://static.exercisedb.dev/media/7R4NIjL.gif', '삼두근', '상완이두근', '도움을 준', '어깨', 'Step:1 발을 어깨너비로 벌리고 서서 수건을 양손으로 잡아 머리 뒤로 둔다.,Step:2 팔꿈치를 귀 옆에 붙이고 상완을 고정한다.,Step:3 (수평 변형) 전완을 천천히 위로 펴며 상단에서 삼두근을 조인다.,Step:4 잠깐 멈춘 뒤 수건을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('W7yh3Yo', '벽에 대고 원암 짐 볼 프렌치 프레스', 'https://static.exercisedb.dev/media/W7yh3Yo.gif', '삼두근', '상완이두근', '덤벨', '어깨', 'Step:1 짐 볼 위에 앉아 발을 바닥에 두고 등을 곧게 편다.,Step:2 한 손에 덤벨을 들고 손바닥이 위를 향하게 하며 팔꿈치를 90도로 굽힌다. 벽 동작에 집중한다.,Step:3 팔꿈치를 고정한 채 덤벨을 천장 쪽으로 곧게 펴 올린다.,Step:4 덤벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한 뒤 팔을 바꾼다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('VsopqcV', '매크로 스타일 클로즈 그립 푸쉬업', 'https://static.exercisedb.dev/media/VsopqcV.gif', '삼두근', '상완이두근', '맨몸', '가슴,어깨', 'Step:1 하이 플랭크 자세에서 손을 가깝게 모아 어깨 바로 아래에 둔다.,Step:2 코어에 힘을 주고 팔꿈치를 몸 옆에 붙인 채 몸을 바닥 쪽으로 내린다.,Step:3 손바닥으로 밀어 팔을 펴며 시작 자세로 돌아간다. 전 과정에서 매크로 자세를 유지한다.,Step:4 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('4QqYaJW', '스태빌리티 볼 소프트 트위스트', 'https://static.exercisedb.dev/media/4QqYaJW.gif', '복근', '허리', '스태빌리티 볼', '복사근,허리', 'Step:1 스태빌리티 볼 위에 엎드려 눕고 발을 어깨너비로 벌려 발끝을 바닥에 둔다.,Step:2 손을 머리 뒤에 두거나 가슴 앞에서 교차한다.,Step:3 코어에 힘을 주고 상체를 천천히 들어 올리되 등은 곧게 유지한다.,Step:4 상체를 한쪽으로 회전해 어깨가 엉덩이 쪽으로 가게 한다. 동작 내내 엉덩이와 다리는 안정적으로 유지한다.,Step:5 잠깐 멈춘 뒤 시작 자세로 돌아간다.,Step:6 (부드러운 변형) 반대쪽으로도 회전을 반복한다.,Step:7 원하는 반복 횟수만큼 좌우를 번갈아 계속한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('vNPJbDA', '케이블 로프 인클라인 트라이셉스 익스텐션 - 역변형', 'https://static.exercisedb.dev/media/vNPJbDA.gif', '삼두근', '상완이두근', '케이블', '어깨', 'Step:1 하이 풀리에 로프를 연결하고 인클라인 벤치 각도를 편한 수준으로 조절한다.,Step:2 풀리를 등지고 서서 발을 어깨너비로 벌린다.,Step:3 오버핸드 그립으로 로프를 잡고 팔을 머리 위로 곧게 편다.,Step:4 (역변형) 팔꿈치를 머리 가까이에 두고 상완을 고정한 채 수행한다.,Step:5 팔꿈치를 굽혀 로프를 머리 뒤로 내려 전완이 이두근에 닿을 때까지 내린다.,Step:6 잠깐 멈춘 뒤 팔을 펴 시작 자세로 돌아간다.,Step:7 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('Y8dOJlH', '케이블 스쿼트 로우(로프 부착 포함) 헤비', 'https://static.exercisedb.dev/media/Y8dOJlH.gif', '광배근', '등', '케이블', '이두근,능형근,후면 삼각근', 'Step:1 허리 높이에 케이블 머신에 로프를 연결한다.,Step:2 머신을 마주 보고 서서 발을 어깨너비로 벌린다.,Step:3 (헤비 변형) 무릎을 굽혀 스쿼트 자세로 내려가되 등은 곧게, 가슴은 들어 올린다.,Step:4 오버핸드 그립으로 로프를 잡되 손 간격은 어깨너비로 한다.,Step:5 코어에 힘을 주고 로프를 몸 쪽으로 당겨 견갑골을 모아 조인다.,Step:6 팔꿈치를 몸에 붙인 채 계속 당겨 손이 가슴에 닿을 때까지 당긴다.,Step:7 위에서 잠깐 멈춘 뒤 로프를 천천히 풀며 팔을 펴 시작 자세로 돌아간다.,Step:8 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('kLiIFdB', '밴드 수직 팔로프 프레스 - 시트 변형', 'https://static.exercisedb.dev/media/kLiIFdB.gif', '복근', '허리', '밴드', '복사근,둔근', 'Step:1 가슴 높이에 단단한 물체에 밴드를 감아 고정한다.,Step:2 밴드를 양손으로 잡고 고정 지점에서 멀어져 밴드에 장력을 만든다.,Step:3 밴드에 몸 옆면이 향하도록 서서 몸을 고정한다.,Step:4 팔을 가슴 높이에서 앞으로 곧게 뻗는다.,Step:5 코어에 힘을 주고 밴드를 가슴에서 멀리 밀어 팔을 완전히 편다.,Step:6 몇 초간 유지한 뒤 밴드를 천천히 가슴 쪽으로 되돌린다.,Step:7 원하는 반복 횟수만큼 반복한 뒤 반대쪽도 수행한다. 시트 강도로 수행한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('YA2HKGz', '바벨 리버스 리스트 컬 - 엎드린 변형', 'https://static.exercisedb.dev/media/YA2HKGz.gif', '전완근', '팔 아래', '바벨', '이두근,상완근', 'Step:1 벤치에 앉아 오버핸드 그립으로 바벨을 잡고 손바닥은 아래를 향하게 한다.,Step:2 전완을 허벅지 위에 올려 손목이 가장자리 밖으로 나오게 한다.,Step:3 손목을 천천히 위로 말아 바벨을 몸 쪽으로 끌어올린다. 엎드린 컨트롤을 강조한다.,Step:4 위에서 잠깐 멈춘 뒤 바벨을 천천히 시작 자세로 내린다.,Step:5 원하는 반복 횟수만큼 반복한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('lFBTISi', '펌 스타일 행잉 사이드 레그레이즈', 'https://static.exercisedb.dev/media/lFBTISi.gif', '복근', '허리', '맨몸', '복사근', 'Step:1 풀업 바에 매달려 팔을 완전히 펴고 손바닥은 바깥쪽을 향하게 한다.,Step:2 코어에 힘을 주고 무릎을 가슴 쪽으로 들어 올리며 상체를 한쪽으로 비튼다.,Step:3 위에서 잠깐 멈춘 뒤 다리를 천천히 시작 자세로 내린다.,Step:4 반대쪽으로도 동일하게 수행한다.,Step:5 원하는 반복 횟수만큼 좌우를 번갈아 계속한다. 단단한 컨트롤을 강조한다.');
INSERT INTO `exerciseCategory` (`external_id`, `name`, `image_url`, `target_muscle`, `body_part`, `equipment`, `secondary_muscles`, `instructions`) VALUES ('gWcZD4q', '수평 덤벨 스탠딩 대체 오버헤드 프레스', 'https://static.exercisedb.dev/media/gWcZD4q.gif', '삼각근', '어깨', '덤벨', '삼두근,코어', 'Step:1 발을 어깨너비로 벌리고 서서 양손에 덤벨을 어깨 높이로 들고 손바닥이 정면을 보게 한다.,Step:2 (수평 변형) 한쪽 덤벨을 머리 위로 밀어 올려 팔을 완전히 편다.,Step:3 덤벨을 어깨 높이로 내린다.,Step:4 반대쪽 팔로 반복한다.,Step:5 원하는 반복 횟수만큼 팔을 번갈아 계속한다.');